window.QUESTIONS = {"version": "BAMF Gesamtfragenkatalog Stand 07.05.2025", "source": "BAMF Gesamtfragenkatalog (text/images) + oet.bamf.de Berlin (answers)", "counts": {"general": 300, "berlin": 10, "total": 310}, "questions": [{"id": 1, "id_str": "1", "category": "general", "exam_pool": "general", "question_de": "In Deutschland dürfen Menschen offen etwas gegen die Regierung sagen, weil …", "question_image": null, "image_kind": null, "options": [{"text_de": "hier Religionsfreiheit gilt.", "correct": false, "text_en": "freedom of religion applies here."}, {"text_de": "die Menschen Steuern zahlen.", "correct": false, "text_en": "people pay taxes."}, {"text_de": "die Menschen das Wahlrecht haben.", "correct": false, "text_en": "people have the right to vote."}, {"text_de": "hier Meinungsfreiheit gilt.", "correct": true, "text_en": "freedom of opinion (freedom of expression) applies here."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-001.png"}, "question_en": "In Germany, people are allowed to openly say something against the government because …", "asking_note": "Tests which specific freedom protects criticising the government. Several options sound like genuine rights (religious freedom, the right to vote), but the reason you can speak out against those in power specifically is freedom of expression.", "answer_explanation": "Freedom of opinion (Meinungsfreiheit) is guaranteed by Article 5 of the Grundgesetz. It gives everyone the right to freely express and spread their opinion in speech, writing and images, including criticism of those in power. That is exactly what lets people speak out against the government without fear of punishment.", "distractor_notes": ["Religious freedom (Article 4) protects belief and worship, not political criticism of the government.", "Paying taxes is a civic duty; it has nothing to do with the right to criticise the government.", "The right to vote lets you choose representatives, but it is not what protects your speech against the government.", ""]}, {"id": 2, "id_str": "2", "category": "general", "exam_pool": "general", "question_de": "In Deutschland können Eltern bis zum 14. Lebensjahr ihres Kindes entscheiden, ob es in der Schule am …", "question_image": null, "image_kind": null, "options": [{"text_de": "Geschichtsunterricht teilnimmt.", "correct": false, "text_en": "history lessons."}, {"text_de": "Religionsunterricht teilnimmt.", "correct": true, "text_en": "religious education (religion classes)."}, {"text_de": "Politikunterricht teilnimmt.", "correct": false, "text_en": "civics/politics lessons."}, {"text_de": "Sprachunterricht teilnimmt.", "correct": false, "text_en": "language lessons."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-002.png"}, "question_en": "In Germany, parents can decide until their child turns 14 whether it takes part in ... at school.", "asking_note": "Tests which school subject is optional on grounds of belief. The confusable options are all school subjects; only religious education can be opted into or out of.", "answer_explanation": "Under Article 7 of the Grundgesetz, religious education is a regular subject in state schools, but because Germany guarantees freedom of belief, parents decide on their child's religious instruction until the child reaches religious majority at 14 (Religionsmuendigkeit), after which the young person decides. Other subjects are part of the compulsory curriculum and cannot be opted out of on belief grounds.", "distractor_notes": ["History is a compulsory subject; parents cannot opt their child out of it.", "", "Civics/politics is part of the standard curriculum and is not optional.", "Language lessons are compulsory and not subject to a parental opt-out."]}, {"id": 3, "id_str": "3", "category": "general", "exam_pool": "general", "question_de": "Deutschland ist ein Rechtsstaat. Was ist damit gemeint?", "question_image": null, "image_kind": null, "options": [{"text_de": "Alle Einwohnerinnen/Einwohner und der Staat müssen sich an die Gesetze halten.", "correct": true, "text_en": "All residents and the state itself must obey the laws."}, {"text_de": "Der Staat muss sich nicht an die Gesetze halten.", "correct": false, "text_en": "The state does not have to obey the laws."}, {"text_de": "Nur Deutsche müssen die Gesetze befolgen.", "correct": false, "text_en": "Only Germans have to obey the laws."}, {"text_de": "Die Gerichte machen die Gesetze.", "correct": false, "text_en": "The courts make the laws."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-003.png"}, "question_en": "Germany is a state governed by the rule of law (Rechtsstaat). What is meant by that?", "asking_note": "Tests the meaning of Rechtsstaat. The key trap: the state itself is also bound by the law, not just citizens. Watch the distractors that exempt the state or limit the law to Germans only.", "answer_explanation": "In a Rechtsstaat, state power is bound by law and the constitution: the government, administration and even the legislature are subject to the law, exactly like ordinary residents. This principle flows from Article 20 of the Grundgesetz and protects people from arbitrary state action.", "distractor_notes": ["", "The opposite of the rule of law: in a Rechtsstaat the state is precisely the body that must obey the law.", "The law binds everyone in Germany, residents and citizens alike, not only Germans.", "Courts apply and interpret laws; laws are made by the legislature (Bundestag and Bundesrat), not the courts."]}, {"id": 4, "id_str": "4", "category": "general", "exam_pool": "general", "question_de": "Welches Recht gehört zu den Grundrechten in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Waffenbesitz", "correct": false, "text_en": "possession of weapons"}, {"text_de": "Faustrecht", "correct": false, "text_en": "the right of the fist / might makes right (Faustrecht)"}, {"text_de": "Meinungsfreiheit", "correct": true, "text_en": "freedom of opinion / expression"}, {"text_de": "Selbstjustiz", "correct": false, "text_en": "vigilante justice (taking the law into your own hands)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-004.png"}, "question_en": "Which right is one of the basic rights (Grundrechte) in Germany?", "asking_note": "Tests recognition of a genuine constitutional basic right versus things that are actually illegal. The distractors (owning weapons, might-makes-right, vigilante justice) are not rights at all.", "answer_explanation": "Freedom of opinion is a basic right guaranteed by Article 5 of the Grundgesetz. The Grundrechte (Articles 1 to 19) protect individuals against the state and include free expression, freedom of belief, assembly and equality before the law.", "distractor_notes": ["Owning weapons is heavily regulated by law, not a constitutional basic right.", "'Faustrecht' means settling disputes by force, the opposite of the rule of law, not a right.", "", "Taking the law into your own hands (Selbstjustiz) is forbidden; the state holds the monopoly on the use of force."]}, {"id": 5, "id_str": "5", "category": "general", "exam_pool": "general", "question_de": "Wahlen in Deutschland sind frei. Was bedeutet das?", "question_image": null, "image_kind": null, "options": [{"text_de": "Man darf Geld annehmen, wenn man dafür eine bestimmte Kandidatin/einen bestimmten Kandidaten wählt.", "correct": false, "text_en": "You may accept money for voting for a particular candidate."}, {"text_de": "Nur Personen, die noch nie im Gefängnis waren, dürfen wählen.", "correct": false, "text_en": "Only people who have never been in prison are allowed to vote."}, {"text_de": "Die Wählerin/der Wähler darf bei der Wahl weder beeinflusst noch zu einer bestimmten Stimmabgabe gezwungen werden und keine Nachteile durch die Wahl haben.", "correct": true, "text_en": "Voters may be neither influenced nor forced into a particular vote, and must suffer no disadvantage because of their vote."}, {"text_de": "Alle wahlberechtigten Personen müssen wählen.", "correct": false, "text_en": "All eligible voters are required to vote."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 0.956, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-005.png"}, "question_en": "Elections in Germany are free. What does that mean?", "asking_note": "Tests the meaning of the 'free' election principle specifically (not secret, not universal, not compulsory). The trap about compulsory voting sounds plausible, but 'free' actually means no one may be pressured or forced in how they vote.", "answer_explanation": "German elections must be universal, direct, free, equal and secret (Article 38 of the Grundgesetz). 'Free' specifically means voters cast their ballot without pressure, coercion or fear of disadvantage. That is why there is no compulsory voting and why vote-buying is illegal.", "distractor_notes": ["Buying or selling votes is a crime; accepting money to vote a certain way is illegal, not part of free elections.", "The right to vote is not generally denied to former prisoners; this is not what 'free' means.", "", "Germany has no compulsory voting; being forced to vote would contradict the 'free' principle."]}, {"id": 6, "id_str": "6", "category": "general", "exam_pool": "general", "question_de": "Wie heißt die deutsche Verfassung?", "question_image": null, "image_kind": null, "options": [{"text_de": "Volksgesetz", "correct": false, "text_en": "People's Law (Volksgesetz)"}, {"text_de": "Bundesgesetz", "correct": false, "text_en": "Federal Law (Bundesgesetz)"}, {"text_de": "Deutsches Gesetz", "correct": false, "text_en": "German Law (Deutsches Gesetz)"}, {"text_de": "Grundgesetz", "correct": true, "text_en": "Basic Law (Grundgesetz)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-006.png"}, "question_en": "What is the German constitution called?", "asking_note": "Straightforward recall of the name of Germany's constitution. The distractors are plausible-sounding invented names.", "answer_explanation": "Germany's constitution is the Grundgesetz (Basic Law), in force since 23 May 1949. It was called 'Basic Law' rather than 'constitution' to signal its provisional character during the division of Germany, but it became the permanent constitution of the reunified country in 1990.", "distractor_notes": ["'Volksgesetz' is not a real term for the German constitution.", "A 'Bundesgesetz' is any ordinary federal statute, not the constitution itself.", "'Deutsches Gesetz' is not the name of the constitution.", ""]}, {"id": 7, "id_str": "7", "category": "general", "exam_pool": "general", "question_de": "Welches Recht gehört zu den Grundrechten, die nach der deutschen Verfassung garantiert werden? Das Recht auf …", "question_image": null, "image_kind": null, "options": [{"text_de": "Glaubens- und Gewissensfreiheit", "correct": true, "text_en": "freedom of faith and conscience"}, {"text_de": "Unterhaltung", "correct": false, "text_en": "entertainment"}, {"text_de": "Arbeit", "correct": false, "text_en": "work"}, {"text_de": "Wohnung", "correct": false, "text_en": "housing"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-007.png"}, "question_en": "Which right is one of the basic rights guaranteed by the German constitution? The right to …", "asking_note": "Tests distinguishing a genuine Grundrecht from desirable things that are NOT guaranteed as basic rights (work, housing, entertainment). Freedom of faith and conscience is the real constitutional right.", "answer_explanation": "Freedom of faith, conscience and religious or ideological belief is guaranteed by Article 4 of the Grundgesetz. Unlike a job or a home, which the state may support through policy but does not guarantee as an enforceable basic right, freedom of belief is an inviolable individual right against the state.", "distractor_notes": ["", "There is no constitutional 'right to entertainment.'", "There is no enforceable basic right to a job; the state promotes employment but does not guarantee it.", "There is no basic right to be given housing; it is a matter of social policy, not a Grundrecht."]}, {"id": 8, "id_str": "8", "category": "general", "exam_pool": "general", "question_de": "Was steht nicht im Grundgesetz von Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Die Würde des Menschen ist unantastbar.", "correct": false, "text_en": "Human dignity is inviolable."}, {"text_de": "Alle sollen gleich viel Geld haben.", "correct": true, "text_en": "Everyone should have the same amount of money."}, {"text_de": "Jeder Mensch darf seine Meinung sagen.", "correct": false, "text_en": "Everyone may express their opinion."}, {"text_de": "Alle sind vor dem Gesetz gleich.", "correct": false, "text_en": "All are equal before the law."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-008.png"}, "question_en": "Which of the following is NOT stated in Germany's Basic Law (Grundgesetz)?", "asking_note": "Negative framing: you must pick the statement that is NOT in the constitution. Three options are genuine constitutional guarantees; the odd one out is the false claim that everyone should have equal amounts of money.", "answer_explanation": "The Grundgesetz guarantees human dignity (Art. 1), freedom of expression (Art. 5) and equality before the law (Art. 3), but it never promises material or financial equality. Germany is a social state that aims to cushion hardship, not one that mandates equal wealth for all.", "distractor_notes": ["This is Article 1 of the Grundgesetz, so it IS in the constitution and is not the answer to this negative question.", "", "Freedom of expression is guaranteed by Article 5, genuinely in the constitution.", "Equality before the law is Article 3, genuinely in the constitution."]}, {"id": 9, "id_str": "9", "category": "general", "exam_pool": "general", "question_de": "Welches Grundrecht gilt in Deutschland nur für Ausländerinnen/Ausländer? Das Grundrecht auf …", "question_image": null, "image_kind": null, "options": [{"text_de": "Schutz der Familie", "correct": false, "text_en": "protection of the family"}, {"text_de": "Menschenwürde", "correct": false, "text_en": "human dignity"}, {"text_de": "Asyl", "correct": true, "text_en": "asylum"}, {"text_de": "Meinungsfreiheit", "correct": false, "text_en": "freedom of opinion"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-009.png"}, "question_en": "Which basic right in Germany applies only to foreign nationals? The basic right to …", "asking_note": "Tests which right is specific to non-citizens. Most basic rights apply to everyone; the right to asylum by definition only concerns foreigners (the politically persecuted).", "answer_explanation": "The right to asylum for the politically persecuted is guaranteed by Article 16a of the Grundgesetz and, by its nature, applies only to foreign nationals. Rights such as human dignity, family protection and free expression are human rights that apply to citizens and foreigners alike.", "distractor_notes": ["Protection of the family (Art. 6) applies to everyone, not only foreigners.", "Human dignity (Art. 1) is a universal right for all people.", "", "Freedom of opinion (Art. 5) applies to everyone in Germany, not just foreigners."]}, {"id": 10, "id_str": "10", "category": "general", "exam_pool": "general", "question_de": "Was ist mit dem deutschen Grundgesetz vereinbar?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Prügelstrafe", "correct": false, "text_en": "corporal punishment (beating)"}, {"text_de": "die Folter", "correct": false, "text_en": "torture"}, {"text_de": "die Todesstrafe", "correct": false, "text_en": "the death penalty"}, {"text_de": "die Geldstrafe", "correct": true, "text_en": "a monetary fine (Geldstrafe)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-010.png"}, "question_en": "Which of the following is compatible with the German Basic Law?", "asking_note": "Tests which punishment is constitutionally permitted. The trap is that three options (corporal punishment, torture, the death penalty) are all prohibited; only a monetary fine is lawful.", "answer_explanation": "A monetary fine is a normal, constitutionally lawful criminal penalty. The death penalty is explicitly abolished by Article 102 of the Grundgesetz, while torture and corporal punishment violate the inviolable human dignity of Article 1 and the right to physical integrity in Article 2.", "distractor_notes": ["Corporal punishment violates human dignity and physical integrity; it is unconstitutional.", "Torture is absolutely prohibited under the guarantee of human dignity.", "The death penalty is abolished in Germany by Article 102 of the Grundgesetz.", ""]}, {"id": 11, "id_str": "11", "category": "general", "exam_pool": "general", "question_de": "Wie wird die Verfassung der Bundesrepublik Deutschland genannt?", "question_image": null, "image_kind": null, "options": [{"text_de": "Grundgesetz", "correct": true, "text_en": "Basic Law (Grundgesetz)"}, {"text_de": "Bundesverfassung", "correct": false, "text_en": "Federal Constitution (Bundesverfassung)"}, {"text_de": "Gesetzbuch", "correct": false, "text_en": "Code of Law (Gesetzbuch)"}, {"text_de": "Verfassungsvertrag", "correct": false, "text_en": "Constitutional Treaty (Verfassungsvertrag)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-011.png"}, "question_en": "What is the constitution of the Federal Republic of Germany called?", "asking_note": "Recall of the constitution's name (a variant of question 6). The distractors are plausible legal-sounding names.", "answer_explanation": "The constitution is officially the Grundgesetz (Basic Law), adopted in 1949. 'Bundesverfassung' is the term used in Switzerland and Austria, and a 'Gesetzbuch' is a code of ordinary laws (like the Civil Code), not the constitution.", "distractor_notes": ["", "'Bundesverfassung' is what Switzerland and Austria call their constitutions, not Germany.", "A 'Gesetzbuch' is a code of ordinary law (e.g. the Civil Code), not the constitution.", "'Verfassungsvertrag' is not the name of Germany's constitution."]}, {"id": 12, "id_str": "12", "category": "general", "exam_pool": "general", "question_de": "Eine Partei im Deutschen Bundestag will die Pressefreiheit abschaffen. Ist das möglich?", "question_image": null, "image_kind": null, "options": [{"text_de": "Ja, wenn mehr als die Hälfte der Abgeordneten im Bundestag dafür sind.", "correct": false, "text_en": "Yes, if more than half of the members of the Bundestag are in favour."}, {"text_de": "Ja, aber dazu müssen zwei Drittel der Abgeordneten im Bundestag dafür sein.", "correct": false, "text_en": "Yes, but two-thirds of the members of the Bundestag must be in favour."}, {"text_de": "Nein, denn die Pressefreiheit ist ein Grundrecht. Sie kann nicht abgeschafft werden.", "correct": true, "text_en": "No, because freedom of the press is a basic right. It cannot be abolished."}, {"text_de": "Nein, denn nur der Bundesrat kann die Pressefreiheit abschaffen.", "correct": false, "text_en": "No, because only the Bundesrat can abolish freedom of the press."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-012.png"}, "question_en": "A party in the German Bundestag wants to abolish freedom of the press. Is that possible?", "asking_note": "Tests whether a basic right can simply be voted away. The trap answers offer specific majorities (half, two-thirds) that sound official; the point is that press freedom is a protected basic right and cannot be abolished.", "answer_explanation": "Freedom of the press is part of freedom of expression, a basic right under Article 5 of the Grundgesetz. Basic rights bind all state power (Art. 1(3)) and cannot simply be voted away by a parliamentary majority; the free democratic basic order is additionally shielded by the 'eternity clause' (Art. 79(3)). So neither a simple nor a two-thirds majority in the Bundestag can abolish press freedom, which is why the answer is no.", "distractor_notes": ["A simple majority cannot abolish a basic right; core constitutional guarantees are shielded from ordinary legislation.", "Even a two-thirds majority cannot abolish the essence of press freedom; it is a protected basic right.", "", "The Bundesrat cannot abolish press freedom either; no state body has that power."]}, {"id": 13, "id_str": "13", "category": "general", "exam_pool": "general", "question_de": "Im Parlament steht der Begriff \"Opposition\" für …", "question_image": null, "image_kind": null, "options": [{"text_de": "die regierenden Parteien.", "correct": false, "text_en": "the governing parties."}, {"text_de": "die Fraktion mit den meisten Abgeordneten.", "correct": false, "text_en": "the parliamentary group with the most members."}, {"text_de": "alle Parteien, die bei der letzten Wahl die 5%-Hürde erreichen konnten.", "correct": false, "text_en": "all parties that cleared the 5% threshold at the last election."}, {"text_de": "alle Abgeordneten, die nicht zu der Regierungspartei/den Regierungsparteien gehören.", "correct": true, "text_en": "all members of parliament who do not belong to the governing party or parties."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-013.png"}, "question_en": "In parliament, the term 'opposition' refers to …", "asking_note": "Tests the definition of parliamentary opposition. Trap: it is defined against the governing parties, so any answer describing the ruling parties or simply the largest faction is wrong.", "answer_explanation": "The opposition consists of the members and parties in parliament that are not part of the government. Its role is to scrutinise and check the governing majority, offer alternatives and hold the government accountable, which is a core feature of a functioning democracy.", "distractor_notes": ["The governing parties form the government, the opposite of the opposition.", "The largest group is usually a governing party; size does not define the opposition.", "Clearing the 5% threshold gets a party into parliament, but governing parties also clear it, so this does not define the opposition.", ""]}, {"id": 14, "id_str": "14", "category": "general", "exam_pool": "general", "question_de": "Meinungsfreiheit in Deutschland heißt, dass ich …", "question_image": null, "image_kind": null, "options": [{"text_de": "Passanten auf der Straße beschimpfen darf.", "correct": false, "text_en": "may insult passers-by on the street."}, {"text_de": "meine Meinung im Internet äußern kann.", "correct": true, "text_en": "can express my opinion on the internet."}, {"text_de": "Nazi-, Hamas- oder Islamischer Staat-Symbole öffentlich tragen darf.", "correct": false, "text_en": "may publicly display Nazi, Hamas or Islamic State symbols."}, {"text_de": "meine Meinung nur dann äußern darf, solange ich der Regierung nicht widerspreche.", "correct": false, "text_en": "may only express my opinion as long as I do not contradict the government."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-014.png"}, "question_en": "Freedom of expression in Germany means that I …", "asking_note": "Tests the limits of free expression. Three options describe things that are NOT protected (insulting passers-by, displaying banned extremist symbols, self-censoring toward the government). Only expressing your opinion online is protected.", "answer_explanation": "Freedom of opinion (Article 5 Grundgesetz) protects expressing your views in any medium, including online, and explicitly includes disagreeing with the government. It does not cover insults, nor displaying symbols of banned unconstitutional or terrorist organisations, which are criminal offences.", "distractor_notes": ["Insulting people (Beleidigung) is a criminal offence and not protected by free expression.", "", "Displaying symbols of banned organisations (Nazi, Hamas, IS) is a crime under the Criminal Code, not free speech.", "Free expression specifically includes the right to contradict the government; self-censorship is not required."]}, {"id": 15, "id_str": "15", "category": "general", "exam_pool": "general", "question_de": "Was verbietet das deutsche Grundgesetz?", "question_image": null, "image_kind": null, "options": [{"text_de": "Militärdienst", "correct": false, "text_en": "military service"}, {"text_de": "Zwangsarbeit", "correct": true, "text_en": "forced labour"}, {"text_de": "freie Berufswahl", "correct": false, "text_en": "free choice of profession"}, {"text_de": "Arbeit im Ausland", "correct": false, "text_en": "working abroad"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-015.png"}, "question_en": "What does the German Basic Law prohibit?", "asking_note": "Tests which of the four is forbidden by the constitution. Three are actually permitted or protected (military service, free choice of profession, working abroad); forced labour is the prohibited one.", "answer_explanation": "Article 12 of the Grundgesetz guarantees free choice of occupation and prohibits forced labour (apart from certain court-ordered detention). Compelling someone to work against their will contradicts personal freedom and human dignity.", "distractor_notes": ["Military or compulsory service is constitutionally permitted (Art. 12a), not prohibited.", "", "Free choice of profession is guaranteed (Art. 12), not prohibited.", "Working abroad is allowed and not restricted by the Basic Law."]}, {"id": 16, "id_str": "16", "category": "general", "exam_pool": "general", "question_de": "Wann ist die Meinungsfreiheit in Deutschland eingeschränkt?", "question_image": null, "image_kind": null, "options": [{"text_de": "bei der öffentlichen Verbreitung falscher Behauptungen über einzelne Personen", "correct": true, "text_en": "when false claims about specific individuals are spread publicly"}, {"text_de": "bei Meinungsäußerungen über die Bundesregierung", "correct": false, "text_en": "when expressing opinions about the federal government"}, {"text_de": "bei Diskussionen über Religionen", "correct": false, "text_en": "in discussions about religions"}, {"text_de": "bei Kritik am Staat", "correct": false, "text_en": "in criticism of the state"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-016.png"}, "question_en": "When is freedom of expression restricted in Germany?", "asking_note": "Tests the legitimate limits of free speech. Three options describe protected speech (criticising the government, discussing religion, criticising the state). The real limit is spreading false factual claims about individuals (defamation).", "answer_explanation": "Free expression has limits where it collides with others' rights, notably personal honour and reputation. Publicly spreading false factual assertions about a person can be defamation or slander (sections 185 to 187 of the Criminal Code) and is not protected. By contrast, criticising the government or the state is exactly what free expression is meant to protect.", "distractor_notes": ["", "Expressing opinions about the government is protected speech, not a restriction.", "Discussing religions is protected by free expression and freedom of belief.", "Criticising the state is a core protected use of free expression."]}, {"id": 17, "id_str": "17", "category": "general", "exam_pool": "general", "question_de": "Die deutschen Gesetze verbieten …", "question_image": null, "image_kind": null, "options": [{"text_de": "Meinungsfreiheit der Einwohnerinnen und Einwohner.", "correct": false, "text_en": "freedom of opinion of the residents."}, {"text_de": "Petitionen der Bürgerinnen und Bürger.", "correct": false, "text_en": "petitions by citizens."}, {"text_de": "Versammlungsfreiheit der Einwohnerinnen und Einwohner.", "correct": false, "text_en": "freedom of assembly of the residents."}, {"text_de": "Ungleichbehandlung der Bürgerinnen und Bürger durch den Staat.", "correct": true, "text_en": "unequal treatment of citizens by the state."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-017.png"}, "question_en": "German laws prohibit …", "asking_note": "Tests which of these the law forbids. Three options list protected freedoms (expression, petition, assembly) that the law guarantees, not bans. The forbidden thing is unequal treatment of citizens by the state.", "answer_explanation": "Article 3 of the Grundgesetz guarantees equality before the law and forbids the state from discriminating on grounds such as sex, descent, race, language, faith or political views. Freedom of opinion, petition and assembly are themselves guaranteed rights, so the law protects rather than bans them.", "distractor_notes": ["Freedom of opinion is guaranteed (Art. 5), not forbidden.", "The right to petition is guaranteed by Article 17; it is protected, not banned.", "Freedom of assembly is guaranteed by Article 8, not prohibited.", ""]}, {"id": 18, "id_str": "18", "category": "general", "exam_pool": "general", "question_de": "Welches Grundrecht ist in Artikel 1 des Grundgesetzes der Bundesrepublik Deutschland garantiert?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Unantastbarkeit der Menschenwürde", "correct": true, "text_en": "the inviolability of human dignity"}, {"text_de": "das Recht auf Leben", "correct": false, "text_en": "the right to life"}, {"text_de": "Religionsfreiheit", "correct": false, "text_en": "freedom of religion"}, {"text_de": "Meinungsfreiheit", "correct": false, "text_en": "freedom of opinion"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-018.png"}, "question_en": "Which basic right is guaranteed in Article 1 of the Basic Law of the Federal Republic of Germany?", "asking_note": "Tests specific knowledge that Article 1 equals human dignity. The distractors are all genuine basic rights but appear in later articles, so the trap is picking a real right that is nevertheless not Article 1.", "answer_explanation": "Article 1 of the Grundgesetz opens with 'Human dignity is inviolable', the supreme value of the constitution and the foundation from which all other basic rights flow. Its position first is deliberate, a direct response to the atrocities of the Nazi era.", "distractor_notes": ["", "The right to life is guaranteed, but in Article 2, not Article 1.", "Freedom of religion is in Article 4, not Article 1.", "Freedom of opinion is in Article 5, not Article 1."]}, {"id": 19, "id_str": "19", "category": "general", "exam_pool": "general", "question_de": "Was versteht man unter dem Recht der \"Freizügigkeit\" in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Man darf sich seinen Wohnort selbst aussuchen.", "correct": true, "text_en": "You may choose your place of residence yourself."}, {"text_de": "Man kann seinen Beruf wechseln.", "correct": false, "text_en": "You can change your profession."}, {"text_de": "Man darf sich für eine andere Religion entscheiden.", "correct": false, "text_en": "You may decide to follow a different religion."}, {"text_de": "Man darf sich in der Öffentlichkeit nur leicht bekleidet bewegen.", "correct": false, "text_en": "You may go around in public only lightly dressed."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-019.png"}, "question_en": "What is meant by the right of 'freedom of movement' (Freizuegigkeit) in Germany?", "asking_note": "Tests the meaning of 'Freizuegigkeit', a false friend: it means the freedom to choose where you live and move within the country, NOT changing jobs or religion, and nothing to do with clothing (a play on the everyday sense of 'freizuegig').", "answer_explanation": "Freizuegigkeit under Article 11 of the Grundgesetz is the right of all Germans to move and reside freely anywhere in the federal territory, that is, to choose where they live and travel within the country. It is not about clothing, profession or religion.", "distractor_notes": ["", "Changing your profession is covered by occupational freedom (Art. 12), not Freizuegigkeit.", "Choosing a religion is freedom of belief (Art. 4), not freedom of movement.", "This plays on the everyday sense of 'freizuegig' (revealing or permissive); it has nothing to do with the legal right."]}, {"id": 20, "id_str": "20", "category": "general", "exam_pool": "general", "question_de": "Eine Partei in Deutschland verfolgt das Ziel, eine Diktatur zu errichten. Sie ist dann …", "question_image": null, "image_kind": null, "options": [{"text_de": "tolerant.", "correct": false, "text_en": "tolerant."}, {"text_de": "rechtsstaatlich orientiert.", "correct": false, "text_en": "committed to the rule of law."}, {"text_de": "gesetzestreu.", "correct": false, "text_en": "law-abiding."}, {"text_de": "verfassungswidrig.", "correct": true, "text_en": "unconstitutional (verfassungswidrig)."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-020.png"}, "question_en": "A party in Germany pursues the goal of establishing a dictatorship. It is therefore …", "asking_note": "Tests the label for a party that opposes the democratic constitution. The distractors are positive-sounding terms; the correct answer is that such a party is unconstitutional (verfassungswidrig).", "answer_explanation": "A party seeking to abolish democracy and set up a dictatorship attacks the free democratic basic order and is therefore unconstitutional. Under Article 21 of the Grundgesetz such parties can be banned by the Federal Constitutional Court, part of Germany's concept of a 'defensive democracy' (wehrhafte Demokratie).", "distractor_notes": ["Aiming for dictatorship is the opposite of tolerant.", "Seeking to destroy the rule of law is not being oriented toward it.", "A party trying to overthrow the constitutional order is not law-abiding.", ""]}, {"id": 21, "id_str": "21", "category": "general", "exam_pool": "general", "question_de": "Welches ist das Wappen der Bundesrepublik Deutschland?", "question_image": null, "image_kind": "options", "options": [{"text_de": "Bild 1", "correct": true, "image": "assets/img/q021-opt1.png", "text_en": "Picture 1"}, {"text_de": "Bild 2", "correct": false, "image": "assets/img/q021-opt2.png", "text_en": "Picture 2"}, {"text_de": "Bild 3", "correct": false, "image": "assets/img/q021-opt3.png", "text_en": "Picture 3"}, {"text_de": "Bild 4", "correct": false, "image": "assets/img/q021-opt4.png", "text_en": "Picture 4"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "numeric", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-021.png"}, "question_en": "Which of these is the coat of arms of the Federal Republic of Germany?", "asking_note": "This is a picture-answer question: the four options are images (Picture 1 to 4). You must recognise the German federal coat of arms (Bundeswappen), a single black eagle on a golden-yellow shield. The answer is a picture choice.", "answer_explanation": "The federal coat of arms (Bundeswappen) shows a single black eagle (Bundesadler) with a red beak, red talons and open wings on a golden-yellow shield. This eagle is one of the oldest state symbols in Europe and has been Germany's official emblem since 1950. The other pictures show different, foreign or historical coats of arms.", "distractor_notes": ["", "Not the German federal coat of arms.", "Not the German federal coat of arms.", "Not the German federal coat of arms."]}, {"id": 22, "id_str": "22", "category": "general", "exam_pool": "general", "question_de": "Was für eine Staatsform hat Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Monarchie", "correct": false, "text_en": "monarchy"}, {"text_de": "Diktatur", "correct": false, "text_en": "dictatorship"}, {"text_de": "Republik", "correct": true, "text_en": "republic"}, {"text_de": "Fürstentum", "correct": false, "text_en": "principality"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-022.png"}, "question_en": "What form of state does Germany have?", "asking_note": "Tests Germany's form of state. The distractors are other forms (monarchy, dictatorship, principality). Germany is a republic.", "answer_explanation": "Germany is a republic: the head of state (the Federal President) is elected, not a hereditary monarch. Article 20 of the Grundgesetz defines Germany as a democratic and social federal state, and the republican principle is protected by the eternity clause.", "distractor_notes": ["Germany has no king or queen as head of state; it is not a monarchy.", "Germany is a democracy with free elections and separation of powers, not a dictatorship.", "", "A principality is ruled by a prince (like Liechtenstein); Germany is not one."]}, {"id": 23, "id_str": "23", "category": "general", "exam_pool": "general", "question_de": "In Deutschland sind die meisten Erwerbstätigen …", "question_image": null, "image_kind": null, "options": [{"text_de": "in kleinen Familienunternehmen beschäftigt.", "correct": false, "text_en": "employed in small family businesses."}, {"text_de": "ehrenamtlich für ein Bundesland tätig.", "correct": false, "text_en": "working on a voluntary/honorary basis for a federal state."}, {"text_de": "selbstständig mit einer eigenen Firma tätig.", "correct": false, "text_en": "self-employed with their own company."}, {"text_de": "bei einer Firma oder Behörde beschäftigt.", "correct": true, "text_en": "employed by a company or public authority."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-023.png"}, "question_en": "In Germany, most economically active people (Erwerbstaetige) are …", "asking_note": "Tests a factual point about the labour market: the large majority are employees working for a company or a public authority, not self-employed or in small family firms.", "answer_explanation": "The great majority of working people in Germany are dependent employees (Arbeitnehmer) who work for a company or a public authority in return for wages or salary. Only a minority are self-employed, and volunteering is unpaid and not a main occupation.", "distractor_notes": ["Only a small share work in small family businesses; it is not the majority.", "Honorary or voluntary work is unpaid and not how most people earn a living.", "The self-employed are a minority of the workforce.", ""]}, {"id": 24, "id_str": "24", "category": "general", "exam_pool": "general", "question_de": "Wie viele Bundesländer hat die Bundesrepublik Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "14", "correct": false, "text_en": "14"}, {"text_de": "15", "correct": false, "text_en": "15"}, {"text_de": "16", "correct": true, "text_en": "16"}, {"text_de": "17", "correct": false, "text_en": "17"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-024.png"}, "question_en": "How many federal states (Bundeslaender) does the Federal Republic of Germany have?", "asking_note": "Simple factual recall. Germany has 16 federal states.", "answer_explanation": "Germany is made up of 16 federal states (Bundeslaender), including three city-states (Berlin, Hamburg and Bremen). This number has stood since reunification in 1990, when the five re-established eastern states joined the former West Germany.", "distractor_notes": ["Incorrect count; Germany has 16 states.", "Incorrect count; the correct number is 16.", "", "Incorrect count; the correct number is 16."]}, {"id": 25, "id_str": "25", "category": "general", "exam_pool": "general", "question_de": "Was ist kein Bundesland der Bundesrepublik Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Elsass-Lothringen", "correct": true, "text_en": "Alsace-Lorraine (Elsass-Lothringen)"}, {"text_de": "Nordrhein-Westfalen", "correct": false, "text_en": "North Rhine-Westphalia"}, {"text_de": "Mecklenburg-Vorpommern", "correct": false, "text_en": "Mecklenburg-Western Pomerania"}, {"text_de": "Sachsen-Anhalt", "correct": false, "text_en": "Saxony-Anhalt"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-025.png"}, "question_en": "Which of these is NOT a federal state of the Federal Republic of Germany?", "asking_note": "Negative framing: pick the one that is NOT a German state. Alsace-Lorraine sounds German and was historically part of Germany, but it is now a region of France. The other three are real German states.", "answer_explanation": "Alsace-Lorraine is a region in eastern France; it belonged to the German Empire from 1871 to 1918 but is not one of the 16 present-day Bundeslaender. North Rhine-Westphalia, Mecklenburg-Western Pomerania and Saxony-Anhalt are all genuine German federal states.", "distractor_notes": ["", "North Rhine-Westphalia is Germany's most populous federal state, a real Bundesland.", "Mecklenburg-Western Pomerania is a real federal state in Germany's northeast.", "Saxony-Anhalt is a genuine federal state in eastern Germany."]}, {"id": 26, "id_str": "26", "category": "general", "exam_pool": "general", "question_de": "Deutschland ist …", "question_image": null, "image_kind": null, "options": [{"text_de": "eine kommunistische Republik.", "correct": false, "text_en": "a communist republic."}, {"text_de": "ein demokratischer und sozialer Bundesstaat.", "correct": true, "text_en": "a democratic and social federal state."}, {"text_de": "eine kapitalistische und soziale Monarchie.", "correct": false, "text_en": "a capitalist and social monarchy."}, {"text_de": "ein sozialer und sozialistischer Bundesstaat.", "correct": false, "text_en": "a social and socialist federal state."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-026.png"}, "question_en": "Germany is …", "asking_note": "Tests the constitutional self-definition of Germany. The correct wording matches Article 20; the distractors mix in wrong labels (communist, capitalist monarchy, socialist).", "answer_explanation": "Article 20 of the Grundgesetz defines Germany as a 'democratic and social federal state' (demokratischer und sozialer Bundesstaat). 'Democratic' means power comes from the people, 'social' commits the state to social justice, and 'federal' means power is shared between the Bund and the Laender.", "distractor_notes": ["Germany is not communist; it is a democracy with a market economy.", "", "Germany is a republic, not a monarchy.", "Germany is a 'social' state but not a 'socialist' one; the constitutional term is democratic and social."]}, {"id": 27, "id_str": "27", "category": "general", "exam_pool": "general", "question_de": "Deutschland ist …", "question_image": null, "image_kind": null, "options": [{"text_de": "ein sozialistischer Staat.", "correct": false, "text_en": "a socialist state."}, {"text_de": "ein Bundesstaat.", "correct": true, "text_en": "a federal state (Bundesstaat)."}, {"text_de": "eine Diktatur.", "correct": false, "text_en": "a dictatorship."}, {"text_de": "eine Monarchie.", "correct": false, "text_en": "a monarchy."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-027.png"}, "question_en": "Germany is …", "asking_note": "Tests recognition that Germany is a federal state. The distractors are wrong systems (socialist state, dictatorship, monarchy).", "answer_explanation": "Germany is a Bundesstaat (federal state): sovereignty is divided between the central federation (Bund) and the 16 states (Laender), each with its own government and parliament. This federal structure is anchored in Article 20 and protected against abolition by the eternity clause.", "distractor_notes": ["Germany is not a socialist state; it has a social market economy and a democratic order.", "", "Germany is a democracy with free elections and separation of powers, not a dictatorship.", "Germany has no monarch; the head of state is the elected Federal President."]}, {"id": 28, "id_str": "28", "category": "general", "exam_pool": "general", "question_de": "Wer wählt in Deutschland die Abgeordneten zum Bundestag?", "question_image": null, "image_kind": null, "options": [{"text_de": "das Militär", "correct": false, "text_en": "the military"}, {"text_de": "die Wirtschaft", "correct": false, "text_en": "the economy / business"}, {"text_de": "das wahlberechtigte Volk", "correct": true, "text_en": "the people who are eligible to vote"}, {"text_de": "die Verwaltung", "correct": false, "text_en": "the administration"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-028.png"}, "question_en": "Who elects the members of the Bundestag in Germany?", "asking_note": "Tests the principle of popular sovereignty: the eligible people (voters), not the military, the economy or the administration, elect the Bundestag.", "answer_explanation": "Members of the Bundestag are elected directly by the eligible voters, German citizens aged 18 and over. This follows from Article 20, under which all state authority derives from the people, and Article 38, which sets out universal, direct, free, equal and secret elections.", "distractor_notes": ["The military does not elect parliament; in a democracy the armed forces stay out of elections.", "Business or the economy does not elect the Bundestag; that would contradict democracy.", "", "The public administration implements decisions; it does not elect the Bundestag."]}, {"id": 29, "id_str": "29", "category": "general", "exam_pool": "general", "question_de": "Welches Tier ist das Wappentier der Bundesrepublik Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Löwe", "correct": false, "text_en": "lion"}, {"text_de": "Adler", "correct": true, "text_en": "eagle"}, {"text_de": "Bär", "correct": false, "text_en": "bear"}, {"text_de": "Pferd", "correct": false, "text_en": "horse"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-029.png"}, "question_en": "Which animal is the heraldic animal of the Federal Republic of Germany?", "asking_note": "Simple recall of the national heraldic animal, the eagle.", "answer_explanation": "The heraldic animal of Germany is the eagle (Adler), shown as the black Bundesadler on the federal coat of arms. The eagle has symbolised German statehood since the Holy Roman Empire and remains the emblem of the modern republic.", "distractor_notes": ["The lion appears in some regional coats of arms (e.g. Baden-Wuerttemberg, Hesse) but is not the national animal.", "", "The bear is the symbol of Berlin, not of Germany as a whole.", "The horse features in Lower Saxony's coat of arms, not the federal emblem."]}, {"id": 30, "id_str": "30", "category": "general", "exam_pool": "general", "question_de": "Was ist kein Merkmal unserer Demokratie?", "question_image": null, "image_kind": null, "options": [{"text_de": "regelmäßige Wahlen", "correct": false, "text_en": "regular elections"}, {"text_de": "Pressezensur", "correct": true, "text_en": "press censorship"}, {"text_de": "Meinungsfreiheit", "correct": false, "text_en": "freedom of opinion"}, {"text_de": "verschiedene Parteien", "correct": false, "text_en": "various (competing) political parties"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-030.png"}, "question_en": "Which of the following is NOT a feature of our democracy?", "asking_note": "Negative framing: pick what does NOT belong to democracy. Three options are genuine democratic features; press censorship is the odd one out and is in fact forbidden.", "answer_explanation": "Censorship of the press is explicitly prohibited by Article 5 of the Grundgesetz ('Eine Zensur findet nicht statt') and is a hallmark of dictatorships, not democracies. Regular elections, free expression and a plurality of competing parties are all core features of German democracy.", "distractor_notes": ["Regular free elections are a core feature of democracy.", "", "Freedom of opinion is a defining democratic feature, guaranteed by Article 5.", "Having several competing parties (pluralism) is essential to democracy."]}, {"id": 31, "id_str": "31", "category": "general", "exam_pool": "general", "question_de": "Die Zusammenarbeit von Parteien zur Bildung einer Regierung nennt man in Deutschland …", "question_image": null, "image_kind": null, "options": [{"text_de": "Einheit.", "correct": false, "text_en": "unity (Einheit)."}, {"text_de": "Koalition.", "correct": true, "text_en": "coalition (Koalition)."}, {"text_de": "Ministerium.", "correct": false, "text_en": "ministry (Ministerium)."}, {"text_de": "Fraktion.", "correct": false, "text_en": "parliamentary group (Fraktion)."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-031.png"}, "question_en": "In Germany, the cooperation of parties to form a government is called a …", "asking_note": "Tests the term for parties joining to form a government. Trap: 'Fraktion' (a parliamentary group) is a related but different concept; the answer is 'Koalition'.", "answer_explanation": "When no single party wins an outright majority, parties join forces in a coalition (Koalition) to command a governing majority in the Bundestag. Because German elections rarely give one party a majority, coalition governments are the norm.", "distractor_notes": ["'Einheit' means unity; it is not the term for parties forming a government.", "", "A 'Ministerium' is a government department (ministry), not the alliance of parties.", "A 'Fraktion' is a single party's group of members in parliament, not an alliance of parties to govern."]}, {"id": 32, "id_str": "32", "category": "general", "exam_pool": "general", "question_de": "Was ist keine staatliche Gewalt in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Gesetzgebung", "correct": false, "text_en": "Legislation (law-making)"}, {"text_de": "Regierung", "correct": false, "text_en": "The government (executive)"}, {"text_de": "Presse", "correct": true, "text_en": "The press"}, {"text_de": "Rechtsprechung", "correct": false, "text_en": "The judiciary (courts)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-032.png"}, "question_en": "Which of these is NOT a branch of state power (Gewalt) in Germany?", "asking_note": "Negatively framed 'odd one out'. Three of the options are the classic branches of government; you must pick the one that is not part of the state's power structure.", "answer_explanation": "Germany's state power is split into three branches: the legislature (Gesetzgebung), the executive (Regierung), and the judiciary (Rechtsprechung) - the separation of powers set out in Art. 20 of the Grundgesetz. The press is often called the 'fourth estate', but it is deliberately independent of the state and is NOT one of the official branches of government.", "distractor_notes": ["Gesetzgebung is the legislative branch - a genuine state power.", "The Regierung is the executive branch - a genuine state power.", "", "Rechtsprechung is the judicial branch - a genuine state power."]}, {"id": 33, "id_str": "33", "category": "general", "exam_pool": "general", "question_de": "Welche Aussage ist richtig? In Deutschland …", "question_image": null, "image_kind": null, "options": [{"text_de": "sind Staat und Religionsgemeinschaften voneinander getrennt.", "correct": true, "text_en": "state and religious communities are separate from one another."}, {"text_de": "bilden die Religionsgemeinschaften den Staat.", "correct": false, "text_en": "the religious communities form the state."}, {"text_de": "ist der Staat abhängig von den Religionsgemeinschaften.", "correct": false, "text_en": "the state is dependent on the religious communities."}, {"text_de": "bilden Staat und Religionsgemeinschaften eine Einheit.", "correct": false, "text_en": "state and religious communities form a single unit."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-033.png"}, "question_en": "Which statement is correct? In Germany ...", "asking_note": "Tests the relationship between the state and religion. Only one option describes the actual constitutional arrangement.", "answer_explanation": "Germany is a secular state: Art. 4 of the Grundgesetz guarantees freedom of belief, and there is no state church. The Grundgesetz (via the incorporated Weimar constitution articles) separates the state from religious communities, even though the two cooperate in areas like church tax and religious education. Germany is not a theocracy and does not depend on any religion.", "distractor_notes": ["", "Wrong - religious communities do not form or constitute the German state.", "Wrong - the state is not dependent on religious communities; it is neutral toward them.", "Wrong - describes a theocracy, the opposite of Germany's secular arrangement."]}, {"id": 34, "id_str": "34", "category": "general", "exam_pool": "general", "question_de": "Was ist Deutschland nicht?", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Demokratie", "correct": false, "text_en": "a democracy"}, {"text_de": "ein Rechtsstaat", "correct": false, "text_en": "a state under the rule of law (Rechtsstaat)"}, {"text_de": "eine Monarchie", "correct": true, "text_en": "a monarchy"}, {"text_de": "ein Sozialstaat", "correct": false, "text_en": "a welfare/social state (Sozialstaat)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-034.png"}, "question_en": "What is Germany NOT?", "asking_note": "Negatively framed. Three options are constitutional descriptions of Germany from the Grundgesetz; pick the form of government Germany explicitly is NOT.", "answer_explanation": "Art. 20 of the Grundgesetz defines Germany as a democratic and social federal state, and its structure makes it a Rechtsstaat (rule of law). Germany is a republic with an elected head of state, so it is NOT a monarchy - there is no king or queen holding state power.", "distractor_notes": ["Germany is a democracy - power comes from the people.", "Germany is a Rechtsstaat - the state is bound by law.", "", "Germany is a Sozialstaat - it provides social security and welfare."]}, {"id": 35, "id_str": "35", "category": "general", "exam_pool": "general", "question_de": "Womit finanziert der deutsche Staat die Sozialversicherung?", "question_image": null, "image_kind": null, "options": [{"text_de": "Kirchensteuer", "correct": false, "text_en": "church tax"}, {"text_de": "Sozialabgaben", "correct": true, "text_en": "social insurance contributions"}, {"text_de": "Spendengeldern", "correct": false, "text_en": "donations"}, {"text_de": "Vereinsbeiträgen", "correct": false, "text_en": "membership fees for clubs/associations"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-035.png"}, "question_en": "How does the German state finance social insurance (Sozialversicherung)?", "asking_note": "Tests where the money for the social insurance system comes from. Do not confuse general funding sources with the specific payroll-based contributions.", "answer_explanation": "The statutory social insurance system (health, pension, unemployment, accident and long-term care insurance) is funded mainly through Sozialabgaben - compulsory contributions deducted from wages and shared between employees and employers. These earmarked contributions, not general taxes or voluntary money, are the core financing.", "distractor_notes": ["Church tax (Kirchensteuer) funds religious communities, not the social insurance system.", "", "Donations are voluntary gifts and do not fund statutory social insurance.", "Club membership fees fund private associations, not social insurance."]}, {"id": 36, "id_str": "36", "category": "general", "exam_pool": "general", "question_de": "Welche Maßnahme schafft in Deutschland soziale Sicherheit?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Krankenversicherung", "correct": true, "text_en": "health insurance"}, {"text_de": "die Autoversicherung", "correct": false, "text_en": "car insurance"}, {"text_de": "die Gebäudeversicherung", "correct": false, "text_en": "buildings insurance"}, {"text_de": "die Haftpflichtversicherung", "correct": false, "text_en": "personal liability insurance"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-036.png"}, "question_en": "Which measure creates social security (soziale Sicherheit) in Germany?", "asking_note": "Distinguishes the statutory social-insurance branches from ordinary private property/liability insurances. Only one of these is part of the Sozialversicherung.", "answer_explanation": "Health insurance (Krankenversicherung) is one of the five pillars of the statutory social insurance system, which is what provides social security - protecting people against the financial risk of illness. The other options are private insurances that protect property or cover damage claims, not part of the social safety net.", "distractor_notes": ["", "Car insurance covers vehicle-related damage; it is a private insurance, not social security.", "Buildings insurance protects property against damage; not part of social security.", "Liability insurance covers damage you cause to others; a private insurance, not social security."]}, {"id": 37, "id_str": "37", "category": "general", "exam_pool": "general", "question_de": "Wie werden die Regierungschefinnen/Regierungschefs der meisten Bundesländer in Deutschland genannt?", "question_image": null, "image_kind": null, "options": [{"text_de": "Erste Ministerin/Erster Minister", "correct": false, "text_en": "First Minister"}, {"text_de": "Premierministerin/Premierminister", "correct": false, "text_en": "Prime Minister (Premierminister)"}, {"text_de": "Senatorin/Senator", "correct": false, "text_en": "Senator"}, {"text_de": "Ministerpräsidentin/Ministerpräsident", "correct": true, "text_en": "Minister-President (Ministerpräsident/in)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-037.png"}, "question_en": "What are the heads of government of most German federal states (Bundesländer) called?", "asking_note": "Watch the word 'most' (meisten): the city-states use different titles, and 'Senator' is the trap that points to them. Pick the standard title.", "answer_explanation": "The head of government of most Bundesländer holds the title Ministerpräsident/in. The exceptions are the three city-states: Berlin has a Regierender Bürgermeister, Hamburg a Erster Bürgermeister, and Bremen a Bürgermeister/Präsident des Senats - which is why 'Senator' appears as a distractor.", "distractor_notes": ["'First Minister' is a British/Scottish title, not used for German states.", "'Premierminister' is used in other countries (e.g. France, UK), not for German Länder.", "'Senator' refers to ministers in the city-state senates (e.g. Berlin, Hamburg, Bremen), not the general title.", ""]}, {"id": 38, "id_str": "38", "category": "general", "exam_pool": "general", "question_de": "Die Bundesrepublik Deutschland ist ein demokratischer und sozialer …", "question_image": null, "image_kind": null, "options": [{"text_de": "Staatenverbund.", "correct": false, "text_en": "association of states (Staatenverbund)."}, {"text_de": "Bundesstaat.", "correct": true, "text_en": "federal state (Bundesstaat)."}, {"text_de": "Staatenbund.", "correct": false, "text_en": "confederation of states (Staatenbund)."}, {"text_de": "Zentralstaat.", "correct": false, "text_en": "centralised (unitary) state (Zentralstaat)."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-038.png"}, "question_en": "The Federal Republic of Germany is a democratic and social ...", "asking_note": "Tests the exact wording of Art. 20 Grundgesetz. The distractors are similar-sounding terms describing looser unions of states - pick the one meaning a true federal state.", "answer_explanation": "Art. 20(1) of the Grundgesetz states verbatim: 'Die Bundesrepublik Deutschland ist ein demokratischer und sozialer Bundesstaat.' A Bundesstaat is a federal state where sovereignty is shared between the federation (Bund) and the member states (Länder), each with its own government.", "distractor_notes": ["'Staatenverbund' (association of states) is the term often used for the EU, not for Germany itself.", "", "A 'Staatenbund' (confederation) is a looser alliance of independent states - weaker than Germany's federal bond.", "A 'Zentralstaat' concentrates all power centrally, the opposite of Germany's federal structure."]}, {"id": 39, "id_str": "39", "category": "general", "exam_pool": "general", "question_de": "Was hat jedes deutsche Bundesland?", "question_image": null, "image_kind": null, "options": [{"text_de": "eine eigene Außenministerin/einen eigenen Außenminister", "correct": false, "text_en": "its own foreign minister"}, {"text_de": "eine eigene Währung", "correct": false, "text_en": "its own currency"}, {"text_de": "eine eigene Armee", "correct": false, "text_en": "its own army"}, {"text_de": "eine eigene Regierung", "correct": true, "text_en": "its own government"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-039.png"}, "question_en": "What does every German federal state (Bundesland) have?", "asking_note": "Tests which powers belong to the states versus the federal level. Foreign policy, currency and defence are federal matters - pick what genuinely exists at state level.", "answer_explanation": "Under Germany's federal system each Bundesland has its own government, its own parliament (Landtag) and its own constitution, and legislates in areas like education and policing. Foreign affairs, the currency (the euro) and the armed forces are all matters reserved to the federal level, so no state has its own.", "distractor_notes": ["Foreign policy is a federal competence; states do not have their own foreign ministers.", "Germany has a single currency (the euro), managed federally/at EU level.", "Defence is federal; the Bundeswehr is the single national army.", ""]}, {"id": 40, "id_str": "40", "category": "general", "exam_pool": "general", "question_de": "Mit welchen Worten beginnt die deutsche Nationalhymne?", "question_image": null, "image_kind": null, "options": [{"text_de": "Völker, hört die Signale …", "correct": false, "text_en": "'Peoples, hear the signals ...' (Voelker, hoert die Signale ...)"}, {"text_de": "Einigkeit und Recht und Freiheit …", "correct": true, "text_en": "'Unity and justice and freedom ...' (Einigkeit und Recht und Freiheit ...)"}, {"text_de": "Freude schöner Götterfunken …", "correct": false, "text_en": "'Joy, beautiful spark of the gods ...' (Freude schoener Goetterfunken ...)"}, {"text_de": "Deutschland einig Vaterland …", "correct": false, "text_en": "'Germany, united fatherland ...' (Deutschland einig Vaterland ...)"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-040.png"}, "question_en": "With which words does the German national anthem begin?", "asking_note": "Classic mix-up question: three distractors are the opening lines of other well-known songs/anthems. Pick the line from the Deutschlandlied.", "answer_explanation": "The German national anthem is the third verse of the Deutschlandlied (Hoffmann von Fallersleben, melody by Haydn), which begins 'Einigkeit und Recht und Freiheit'. Only this third stanza is the official anthem of the Federal Republic.", "distractor_notes": ["This is the refrain of 'The Internationale', the socialist/workers' anthem.", "", "This is Schiller's 'Ode to Joy' (Beethoven's Ninth), the anthem of the European Union.", "This is a line from 'Auferstanden aus Ruinen', the former national anthem of East Germany (GDR)."]}, {"id": 41, "id_str": "41", "category": "general", "exam_pool": "general", "question_de": "Warum gibt es in einer Demokratie mehr als eine Partei?", "question_image": null, "image_kind": null, "options": [{"text_de": "weil dadurch die unterschiedlichen Meinungen der Bürgerinnen und Bürger vertreten werden", "correct": true, "text_en": "because it allows the different opinions of citizens to be represented"}, {"text_de": "damit Bestechung in der Politik begrenzt wird", "correct": false, "text_en": "so that bribery in politics is limited"}, {"text_de": "um politische Demonstrationen zu verhindern", "correct": false, "text_en": "in order to prevent political demonstrations"}, {"text_de": "um wirtschaftlichen Wettbewerb anzuregen", "correct": false, "text_en": "in order to stimulate economic competition"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-041.png"}, "question_en": "Why is there more than one party in a democracy?", "asking_note": "Tests the purpose of a multi-party system (pluralism). The distractors offer plausible-sounding but incorrect economic/procedural reasons.", "answer_explanation": "A democracy rests on pluralism: society holds many different views and interests, and multiple parties exist so that these diverse opinions can be represented and compete for majorities in free elections. Art. 21 of the Grundgesetz recognises parties as instruments of forming the political will of the people.", "distractor_notes": ["", "Multiple parties are not primarily an anti-corruption mechanism.", "Wrong and backwards - democracies protect, not prevent, peaceful demonstrations.", "Economic competition concerns markets and businesses, not the reason for political parties."]}, {"id": 42, "id_str": "42", "category": "general", "exam_pool": "general", "question_de": "Wer beschließt in Deutschland ein neues Gesetz?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Regierung", "correct": false, "text_en": "the government"}, {"text_de": "das Parlament", "correct": true, "text_en": "the parliament"}, {"text_de": "die Gerichte", "correct": false, "text_en": "the courts"}, {"text_de": "die Polizei", "correct": false, "text_en": "the police"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-042.png"}, "question_en": "Who passes a new law in Germany?", "asking_note": "Tests the separation of powers: which branch actually enacts laws. The government proposes and the courts apply laws, but a different body passes them.", "answer_explanation": "Law-making is the job of the legislature. In Germany the Bundestag (parliament) debates and passes federal laws, with the Bundesrat participating for laws affecting the states. The government may draft and propose bills, but it does not itself pass them.", "distractor_notes": ["The government (executive) proposes and implements laws but does not pass them.", "", "Courts (the judiciary) interpret and apply laws, they do not make them.", "The police enforce the law; they have no legislative role."]}, {"id": 43, "id_str": "43", "category": "general", "exam_pool": "general", "question_de": "Wann kann in Deutschland eine Partei verboten werden?", "question_image": null, "image_kind": null, "options": [{"text_de": "wenn ihr Wahlkampf zu teuer ist", "correct": false, "text_en": "if its election campaign is too expensive"}, {"text_de": "wenn sie gegen die Verfassung kämpft", "correct": true, "text_en": "if it fights against the constitution"}, {"text_de": "wenn sie Kritik am Staatsoberhaupt äußert", "correct": false, "text_en": "if it voices criticism of the head of state"}, {"text_de": "wenn ihr Programm eine neue Richtung vorschlägt", "correct": false, "text_en": "if its programme proposes a new direction"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-043.png"}, "question_en": "When can a political party be banned in Germany?", "asking_note": "Tests the constitutional threshold for a party ban. Note that legitimate political activity - new ideas, criticism, expensive campaigns - can never be grounds for a ban.", "answer_explanation": "Under Art. 21(2) of the Grundgesetz, a party may be banned only if it seeks to undermine or abolish the free democratic basic order (die freiheitliche demokratische Grundordnung) - in other words, if it fights against the constitution. Only the Bundesverfassungsgericht (Federal Constitutional Court) can order such a ban.", "distractor_notes": ["Campaign cost is not a ground for banning a party.", "", "Criticising the head of state is protected free speech, not grounds for a ban.", "Proposing new political directions is normal democratic activity, never a reason for a ban."]}, {"id": 44, "id_str": "44", "category": "general", "exam_pool": "general", "question_de": "Wen kann man als Bürgerin/Bürger in Deutschland nicht direkt wählen?", "question_image": null, "image_kind": null, "options": [{"text_de": "Abgeordnete des EU-Parlaments", "correct": false, "text_en": "Members of the EU Parliament"}, {"text_de": "Die Bundespräsidentin/den Bundespräsidenten", "correct": true, "text_en": "The Federal President (Bundespraesident)"}, {"text_de": "Landtagsabgeordnete", "correct": false, "text_en": "State parliament (Landtag) members"}, {"text_de": "Bundestagsabgeordnete", "correct": false, "text_en": "Members of the Bundestag"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-044.png"}, "question_en": "Whom can citizens in Germany NOT elect directly?", "asking_note": "Negatively framed. Three offices are filled by direct popular vote; one is chosen indirectly by a special assembly. Pick the indirectly elected office.", "answer_explanation": "The Federal President is elected indirectly by the Bundesversammlung (Federal Convention) - made up of all Bundestag members plus an equal number of delegates chosen by the state parliaments - not by the general public. Citizens directly elect MEPs, Landtag members and Bundestag members.", "distractor_notes": ["MEPs are directly elected by citizens in European elections.", "", "Landtag members are directly elected in state elections.", "Bundestag members are directly elected in federal elections."]}, {"id": 45, "id_str": "45", "category": "general", "exam_pool": "general", "question_de": "Zu welcher Versicherung gehört die Pflegeversicherung?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sozialversicherung", "correct": true, "text_en": "social insurance (Sozialversicherung)"}, {"text_de": "Unfallversicherung", "correct": false, "text_en": "accident insurance"}, {"text_de": "Hausratsversicherung", "correct": false, "text_en": "household contents insurance"}, {"text_de": "Haftpflicht- und Feuerversicherung", "correct": false, "text_en": "liability and fire insurance"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-045.png"}, "question_en": "To which type of insurance does long-term care insurance (Pflegeversicherung) belong?", "asking_note": "Tests knowledge of the statutory social-insurance branches. Distractors are private insurances; pick the umbrella category Pflegeversicherung sits under.", "answer_explanation": "Long-term care insurance (Pflegeversicherung) is one of the five pillars of the statutory Sozialversicherung, alongside health, pension, unemployment and accident insurance. It was introduced in 1995 to cover the costs of care for people who need it.", "distractor_notes": ["", "Accident insurance is itself a separate branch; note the question asks for the overarching category, which is social insurance.", "Household contents insurance is a private property insurance, not part of the social system.", "Liability and fire insurance are private insurances, not the category Pflegeversicherung belongs to."]}, {"id": 46, "id_str": "46", "category": "general", "exam_pool": "general", "question_de": "Der deutsche Staat hat viele Aufgaben. Welche Aufgabe gehört dazu?", "question_image": null, "image_kind": null, "options": [{"text_de": "Er baut Straßen und Schulen.", "correct": true, "text_en": "It builds roads and schools."}, {"text_de": "Er verkauft Lebensmittel und Kleidung.", "correct": false, "text_en": "It sells food and clothing."}, {"text_de": "Er versorgt alle Einwohnerinnen und Einwohner kostenlos mit Zeitungen.", "correct": false, "text_en": "It supplies all inhabitants with free newspapers."}, {"text_de": "Er produziert Autos und Busse.", "correct": false, "text_en": "It produces cars and buses."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-046.png"}, "question_en": "The German state has many tasks. Which task is one of them?", "asking_note": "Tests what genuinely counts as a state responsibility versus what is left to the private market economy. Pick the public-infrastructure task.", "answer_explanation": "Providing public infrastructure - roads, schools, hospitals and other public services - is a core task of the state. In Germany's social market economy, producing and selling goods like food, clothing and vehicles is left to private businesses, not the state.", "distractor_notes": ["", "Selling food and clothing is done by private businesses, not the state.", "The state does not supply free newspapers; a free press is privately run.", "Manufacturing cars and buses is private-sector activity, not a state task."]}, {"id": 47, "id_str": "47", "category": "general", "exam_pool": "general", "question_de": "Der deutsche Staat hat viele Aufgaben. Welche Aufgabe gehört nicht dazu?", "question_image": null, "image_kind": null, "options": [{"text_de": "Er bezahlt für alle Staatsangehörigen Urlaubsreisen.", "correct": true, "text_en": "It pays for holiday trips for all citizens."}, {"text_de": "Er zahlt Kindergeld.", "correct": false, "text_en": "It pays child benefit (Kindergeld)."}, {"text_de": "Er unterstützt Museen.", "correct": false, "text_en": "It supports museums."}, {"text_de": "Er fördert Sportlerinnen und Sportler.", "correct": false, "text_en": "It promotes/funds athletes."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-047.png"}, "question_en": "The German state has many tasks. Which task is NOT one of them?", "asking_note": "Negatively framed - pick the thing the state does NOT do. Three options are real state benefits/support; one is an absurd personal perk the state never pays for.", "answer_explanation": "The state does not pay for private holidays. It does provide real public support such as child benefit (Kindergeld), funding for culture (museums, theatres) and support for sport and athletes. Paying for everyone's vacations is not a state task.", "distractor_notes": ["", "Kindergeld is a genuine state benefit paid to families.", "The state does fund and support museums and culture.", "The state does promote and fund athletes and sport."]}, {"id": 48, "id_str": "48", "category": "general", "exam_pool": "general", "question_de": "Welches Organ gehört nicht zu den Verfassungsorganen Deutschlands?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Bundesrat", "correct": false, "text_en": "the Bundesrat"}, {"text_de": "die Bundespräsidentin/der Bundespräsident", "correct": false, "text_en": "the Federal President (Bundespraesident)"}, {"text_de": "die Bürgerversammlung", "correct": true, "text_en": "the citizens' assembly (Buergerversammlung)"}, {"text_de": "die Regierung", "correct": false, "text_en": "the government (Bundesregierung)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-048.png"}, "question_en": "Which body is NOT one of Germany's constitutional bodies (Verfassungsorgane)?", "asking_note": "Negatively framed. Three options are among the five official constitutional organs; one is an invented/local-sounding body. Pick the one that is not a Verfassungsorgan.", "answer_explanation": "Germany's constitutional bodies are the Bundestag, the Bundesrat, the Federal President, the Federal Government (Bundesregierung) and the Federal Constitutional Court (plus the Bundesversammlung for electing the President). A 'Buergerversammlung' (citizens' assembly) is not among them - it is not defined as a constitutional organ in the Grundgesetz.", "distractor_notes": ["The Bundesrat (chamber of the states) is a constitutional body.", "The Federal President is a constitutional body.", "", "The Bundesregierung (government) is a constitutional body."]}, {"id": 49, "id_str": "49", "category": "general", "exam_pool": "general", "question_de": "Wer bestimmt in Deutschland die Schulpolitik?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Lehrer und Lehrerinnen", "correct": false, "text_en": "the teachers"}, {"text_de": "die Bundesländer", "correct": true, "text_en": "the federal states (Bundeslaender)"}, {"text_de": "das Familienministerium", "correct": false, "text_en": "the family ministry"}, {"text_de": "die Universitäten", "correct": false, "text_en": "the universities"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-049.png"}, "question_en": "Who determines school (education) policy in Germany?", "asking_note": "Tests federalism: education is a state, not federal, competence. The distractors point to actors involved in schooling but who do not set policy.", "answer_explanation": "Education is governed by the principle of Kulturhoheit der Laender - cultural/educational sovereignty of the states. Each Bundesland runs its own school system and sets its own curricula and school policy, which is why school systems differ from state to state.", "distractor_notes": ["Teachers deliver lessons but do not set school policy.", "", "The family ministry is a federal body; education policy is not set at federal level.", "Universities are part of higher education and do not determine school policy."]}, {"id": 50, "id_str": "50", "category": "general", "exam_pool": "general", "question_de": "Die Wirtschaftsform in Deutschland nennt man …", "question_image": null, "image_kind": null, "options": [{"text_de": "freie Zentralwirtschaft.", "correct": false, "text_en": "free central economy."}, {"text_de": "soziale Marktwirtschaft.", "correct": true, "text_en": "social market economy (soziale Marktwirtschaft)."}, {"text_de": "gelenkte Zentralwirtschaft.", "correct": false, "text_en": "directed central economy."}, {"text_de": "Planwirtschaft.", "correct": false, "text_en": "planned economy."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-050.png"}, "question_en": "Germany's economic system is called ...", "asking_note": "Distractors describe centrally planned/command economies (associated with the former GDR/socialist states). Pick the term for Germany's market-plus-welfare model.", "answer_explanation": "Germany's economic model is the soziale Marktwirtschaft (social market economy): a free-market economy combined with social safeguards and state regulation to balance economic freedom with social fairness. It was shaped in post-war West Germany, associated with Ludwig Erhard.", "distractor_notes": ["A 'free central economy' is a contradictory/centrally controlled model, not Germany's.", "", "A 'directed central economy' means state-controlled central planning - not Germany's system.", "A planned economy (state sets production centrally) described the former GDR, not the Federal Republic."]}, {"id": 51, "id_str": "51", "category": "general", "exam_pool": "general", "question_de": "Zu einem demokratischen Rechtsstaat gehört es nicht, dass …", "question_image": null, "image_kind": null, "options": [{"text_de": "Menschen sich kritisch über die Regierung äußern können.", "correct": false, "text_en": "People can express criticism of the government."}, {"text_de": "Bürger friedlich demonstrieren gehen dürfen.", "correct": false, "text_en": "Citizens are allowed to demonstrate peacefully."}, {"text_de": "Menschen von einer Privatpolizei ohne Grund verhaftet werden.", "correct": true, "text_en": "People are arrested without reason by a private police force."}, {"text_de": "jemand ein Verbrechen begeht und deshalb verhaftet wird.", "correct": false, "text_en": "Someone commits a crime and is therefore arrested."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-051.png"}, "question_en": "Which of the following does NOT belong to a democratic state under the rule of law (Rechtsstaat)?", "asking_note": "Negatively framed - pick the thing that violates the rule of law. Three options are legitimate features of a Rechtsstaat; one describes arbitrary, lawless action.", "answer_explanation": "In a Rechtsstaat, state power is bound by law and only the state (not private forces) may use legitimate force, always with legal justification. Arbitrary arrest without cause by a 'private police' contradicts the rule of law. Free criticism, peaceful protest and lawful arrest for actual crimes are all consistent with it.", "distractor_notes": ["Criticising the government is protected free speech - a hallmark of the rule of law.", "Peaceful demonstration is a protected freedom of assembly - part of the rule of law.", "", "Arresting someone who has actually committed a crime is lawful and proper - it belongs to the rule of law."]}, {"id": 52, "id_str": "52", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet \"Volkssouveränität\"? Alle Staatsgewalt geht vom ...", "question_image": null, "image_kind": null, "options": [{"text_de": "Volke aus.", "correct": true, "text_en": "people."}, {"text_de": "Bundestag aus.", "correct": false, "text_en": "Bundestag."}, {"text_de": "preußischen König aus.", "correct": false, "text_en": "Prussian king."}, {"text_de": "Bundesverfassungsgericht aus.", "correct": false, "text_en": "Federal Constitutional Court."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-052.png"}, "question_en": "What does 'popular sovereignty' (Volkssouveraenitaet) mean? All state power emanates from the ...", "asking_note": "Tests the exact principle of Art. 20(2) Grundgesetz. Complete the sentence with the source of all state authority - the distractors name institutions, but power flows from one source.", "answer_explanation": "Art. 20(2) of the Grundgesetz states: 'Alle Staatsgewalt geht vom Volke aus' - all state authority emanates from the people. This is the principle of popular sovereignty: the people are the ultimate source of legitimate power, exercised through elections and votes and via the state's organs.", "distractor_notes": ["", "The Bundestag exercises power on behalf of the people, but power originates with the people, not the parliament.", "A king is the opposite of popular sovereignty - monarchy, not democracy.", "The Constitutional Court applies the constitution; it is not the source of state power."]}, {"id": 53, "id_str": "53", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet \"Rechtsstaat\" in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Der Staat hat Recht.", "correct": false, "text_en": "The state is right/in the right."}, {"text_de": "Es gibt nur rechte Parteien.", "correct": false, "text_en": "There are only right-wing parties."}, {"text_de": "Die Bürgerinnen und Bürger entscheiden über Gesetze.", "correct": false, "text_en": "The citizens decide on the laws."}, {"text_de": "Der Staat muss die Gesetze einhalten.", "correct": true, "text_en": "The state must obey the laws."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-053.png"}, "question_en": "What does 'Rechtsstaat' (state under the rule of law) mean in Germany?", "asking_note": "A wordplay trap: 'Recht' can mean 'law', 'right' or (as 'rechts') 'right-wing'. Two distractors exploit these meanings. Pick the definition about the state being bound by law.", "answer_explanation": "A Rechtsstaat means that all state power is bound by law and the constitution - the state itself must obey the laws, and citizens are protected against arbitrary state action. Independent courts can review whether the state acts lawfully.", "distractor_notes": ["Wrong - a play on 'Recht'; it does not mean the state is always right.", "Wrong - a play on 'rechts' (right-wing); it has nothing to do with party politics.", "This describes direct democracy, not the rule of law; in Germany parliament makes laws.", ""]}, {"id": 54, "id_str": "54", "category": "general", "exam_pool": "general", "question_de": "Was ist keine staatliche Gewalt in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Legislative", "correct": false, "text_en": "Legislative (legislature)"}, {"text_de": "Judikative", "correct": false, "text_en": "Judikative (judiciary)"}, {"text_de": "Exekutive", "correct": false, "text_en": "Exekutive (executive)"}, {"text_de": "Direktive", "correct": true, "text_en": "Direktive (directive)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-054.png"}, "question_en": "Which of these is NOT a branch of state power (Gewalt) in Germany?", "asking_note": "Negatively framed and uses the Latin-derived names of the three branches. One option is a made-up-sounding word that is not a branch of government - pick it.", "answer_explanation": "The three branches of state power under the separation of powers (Art. 20 Grundgesetz) are the Legislative (law-making), the Exekutive (executive/government) and the Judikative (judiciary/courts). 'Direktive' simply means an instruction or directive and is not a branch of government.", "distractor_notes": ["The Legislative is the law-making branch - a genuine state power.", "The Judikative is the judicial branch - a genuine state power.", "The Exekutive is the executive branch - a genuine state power.", ""]}, {"id": 55, "id_str": "55", "category": "general", "exam_pool": "general", "question_de": "Was zeigt dieses Bild?", "question_image": "assets/img/q055-stem.png", "image_kind": "stem", "options": [{"text_de": "den Bundestagssitz in Berlin", "correct": true, "text_en": "the seat of the Bundestag in Berlin"}, {"text_de": "das Bundesverfassungsgericht in Karlsruhe", "correct": false, "text_en": "the Federal Constitutional Court in Karlsruhe"}, {"text_de": "das Bundesratsgebäude in Berlin", "correct": false, "text_en": "the Bundesrat building in Berlin"}, {"text_de": "das Bundeskanzleramt in Berlin", "correct": false, "text_en": "the Federal Chancellery in Berlin"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-055.png"}, "question_en": "What does this picture show?", "asking_note": "This question shows an image (the stem is a photo of a building). You must identify which German institution's building it is; the four answers are text descriptions of different buildings/cities.", "answer_explanation": "The image shows the Reichstag building in Berlin - recognisable by its neoclassical facade and the large glass dome added in the 1990s - which is the seat of the Bundestag, the German federal parliament. The other options name real but different institutions and buildings.", "distractor_notes": ["", "The Federal Constitutional Court sits in Karlsruhe in a modern building, not the pictured one.", "The Bundesrat has its own building (the former Prussian House of Lords) in Berlin, not the Reichstag.", "The Federal Chancellery (Kanzleramt) is a separate modern building in Berlin."]}, {"id": 56, "id_str": "56", "category": "general", "exam_pool": "general", "question_de": "Welches Amt gehört in Deutschland zur Gemeindeverwaltung?", "question_image": null, "image_kind": null, "options": [{"text_de": "Pfarramt", "correct": false, "text_en": "parish office (Pfarramt)"}, {"text_de": "Ordnungsamt", "correct": true, "text_en": "public order office (Ordnungsamt)"}, {"text_de": "Finanzamt", "correct": false, "text_en": "tax office (Finanzamt)"}, {"text_de": "Auswärtiges Amt", "correct": false, "text_en": "Foreign Office (Auswaertiges Amt)"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-056.png"}, "question_en": "Which office (Amt) belongs to municipal (local) administration in Germany?", "asking_note": "Tests which level of government an office sits at. Distractors are a church office, a state office and a federal office - pick the local/municipal one.", "answer_explanation": "The Ordnungsamt (public order office) is part of the municipal (Gemeinde/local) administration, handling local matters such as public order, registration and permits. The others sit at different levels or outside the state entirely.", "distractor_notes": ["A Pfarramt is a church (parish) office, not part of state/municipal administration.", "", "The Finanzamt (tax office) is a state-level (Land) authority, not municipal.", "The Auswaertiges Amt (Foreign Office) is a federal ministry, not municipal."]}, {"id": 57, "id_str": "57", "category": "general", "exam_pool": "general", "question_de": "Wer wird meistens zur Präsidentin/zum Präsidenten des Deutschen Bundestages gewählt?", "question_image": null, "image_kind": null, "options": [{"text_de": "die/der älteste Abgeordnete im Parlament", "correct": false, "text_en": "the oldest member of parliament"}, {"text_de": "die Ministerpräsidentin/der Ministerpräsident des größten Bundeslandes", "correct": false, "text_en": "the minister-president of the largest federal state"}, {"text_de": "eine ehemalige Bundeskanzlerin/ein ehemaliger Bundeskanzler", "correct": false, "text_en": "a former Federal Chancellor"}, {"text_de": "eine Abgeordnete/ein Abgeordneter der stärksten Fraktion", "correct": true, "text_en": "a member of the strongest parliamentary group (Fraktion)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-057.png"}, "question_en": "Who is usually elected President of the German Bundestag?", "asking_note": "Tests parliamentary convention. The distractors are plausible-sounding rules (oldest member, ex-chancellor) - pick the actual customary practice.", "answer_explanation": "By long-standing convention, the President of the Bundestag is chosen from the ranks of the strongest parliamentary group (staerkste Fraktion). The office ranks protocol-wise just below the Federal President and is elected by the Bundestag at its first sitting.", "distractor_notes": ["The oldest member traditionally could open the first session (Alterspraesident), but is not made Bundestag President.", "A state minister-president heads a Land government and is not, by that role, Bundestag President.", "Being a former chancellor is not the basis for becoming Bundestag President.", ""]}, {"id": 58, "id_str": "58", "category": "general", "exam_pool": "general", "question_de": "Wer ernennt in Deutschland die Ministerinnen/die Minister der Bundesregierung?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Präsidentin/der Präsident des Bundesverfassungsgerichtes", "correct": false, "text_en": "the President of the Federal Constitutional Court"}, {"text_de": "die Bundespräsidentin/der Bundespräsident", "correct": true, "text_en": "the Federal President (Bundespraesident)"}, {"text_de": "die Bundesratspräsidentin/der Bundesratspräsident", "correct": false, "text_en": "the President of the Bundesrat"}, {"text_de": "die Bundestagspräsidentin/der Bundestagspräsident", "correct": false, "text_en": "the President of the Bundestag"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-058.png"}, "question_en": "Who appoints the ministers of the federal government in Germany?", "asking_note": "Tests the formal appointment procedure. All four options are 'presidents' of different bodies - pick the one who formally appoints ministers.", "answer_explanation": "Under Art. 64 of the Grundgesetz, federal ministers are appointed and dismissed by the Federal President (Bundespraesident) on the proposal of the Federal Chancellor. The President formally makes the appointment; the Chancellor selects who is proposed.", "distractor_notes": ["The President of the Constitutional Court leads the court, with no role in appointing ministers.", "", "The President of the Bundesrat chairs the chamber of the states; they do not appoint federal ministers (though they deputise for the Federal President).", "The President of the Bundestag leads parliament; they do not appoint ministers."]}, {"id": 59, "id_str": "59", "category": "general", "exam_pool": "general", "question_de": "Vor wie vielen Jahren gab es erstmals eine jüdische Gemeinde auf dem Gebiet des heutigen Deutschlands?", "question_image": null, "image_kind": null, "options": [{"text_de": "vor etwa 300 Jahren", "correct": false, "text_en": "about 300 years ago"}, {"text_de": "vor etwa 700 Jahren", "correct": false, "text_en": "about 700 years ago"}, {"text_de": "vor etwa 1150 Jahren", "correct": false, "text_en": "about 1,150 years ago"}, {"text_de": "vor etwa 1700 Jahren", "correct": true, "text_en": "about 1,700 years ago"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": ["ambiguous_answer_match"]}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-059.png"}, "question_en": "How many years ago did the first Jewish community exist on the territory of present-day Germany?", "asking_note": "A historical-fact question - pick the correct time span. The figures are far apart, so it tests whether you know Jewish presence in Germany goes back to Roman times.", "answer_explanation": "There has been a Jewish presence on German soil for roughly 1,700 years. The earliest documented Jewish community was in Cologne, referenced in a decree of the Roman Emperor Constantine dated 321 CE - which is why the 1700-year figure is correct.", "distractor_notes": ["Far too recent - Jewish communities in Germany long predate the 18th century.", "Too recent - Jewish presence in Germany goes back far beyond the medieval period alone.", "Too recent - understates the history by several centuries.", ""]}, {"id": 60, "id_str": "60", "category": "general", "exam_pool": "general", "question_de": "In Deutschland gehören der Bundestag und der Bundesrat zur …", "question_image": null, "image_kind": null, "options": [{"text_de": "Exekutive.", "correct": false, "text_en": "executive (Exekutive)."}, {"text_de": "Legislative.", "correct": true, "text_en": "legislature (Legislative)."}, {"text_de": "Direktive.", "correct": false, "text_en": "directive (Direktive)."}, {"text_de": "Judikative.", "correct": false, "text_en": "judiciary (Judikative)."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-060.png"}, "question_en": "In Germany, the Bundestag and the Bundesrat belong to the ...", "asking_note": "Tests which branch of the separation of powers these two chambers form. Both make/shape laws - match them to the correct branch using the Latin term.", "answer_explanation": "The Bundestag (federal parliament) and the Bundesrat (chamber representing the states) together make up the legislative branch (Legislative) - the bodies that pass federal laws. The Bundestag adopts laws and the Bundesrat participates, especially where state interests are affected.", "distractor_notes": ["The Exekutive is the government/administration that implements laws, not these two chambers.", "", "'Direktive' is not a branch of government at all.", "The Judikative is the courts, which apply the law - not the Bundestag and Bundesrat."]}, {"id": 61, "id_str": "61", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet \"Volkssouveränität\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "Die Königin/der König herrscht über das Volk.", "correct": false, "text_en": "The king/queen rules over the people."}, {"text_de": "Das Bundesverfassungsgericht steht über der Verfassung.", "correct": false, "text_en": "The Federal Constitutional Court stands above the constitution."}, {"text_de": "Die Interessenverbände üben die Souveränität zusammen mit der Regierung aus.", "correct": false, "text_en": "Interest groups exercise sovereignty together with the government."}, {"text_de": "Die Staatsgewalt geht vom Volke aus.", "correct": true, "text_en": "State power emanates from the people."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-061.png"}, "question_en": "What does 'popular sovereignty' (Volkssouveraenitaet) mean?", "asking_note": "Same principle as an earlier question, but here as full statements. Pick the option that says power comes from the people; the distractors describe monarchy or rule by other bodies.", "answer_explanation": "Popular sovereignty means that the people are the source of all state authority, as set out in Art. 20(2) of the Grundgesetz ('Alle Staatsgewalt geht vom Volke aus'). Power is legitimated by and derived from the people, exercised through elections and the constitutional organs.", "distractor_notes": ["This describes a monarchy - the opposite of popular sovereignty.", "Wrong - the Constitutional Court is bound by the constitution, not above it.", "Wrong - sovereignty rests with the people, not with interest groups and the government.", ""]}, {"id": 62, "id_str": "62", "category": "general", "exam_pool": "general", "question_de": "Wenn das Parlament eines deutschen Bundeslandes gewählt wird, nennt man das …", "question_image": null, "image_kind": null, "options": [{"text_de": "Kommunalwahl", "correct": false, "text_en": "local/municipal election (Kommunalwahl)"}, {"text_de": "Landtagswahl", "correct": true, "text_en": "state parliament election (Landtagswahl)"}, {"text_de": "Europawahl", "correct": false, "text_en": "European election (Europawahl)"}, {"text_de": "Bundestagswahl", "correct": false, "text_en": "federal election (Bundestagswahl)"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-062.png"}, "question_en": "When the parliament of a German federal state (Bundesland) is elected, what is this called?", "asking_note": "Tests the names of the different election types by level of government. Distractors cover the local, EU and federal levels - pick the one for a state parliament.", "answer_explanation": "Electing the parliament (Landtag) of a Bundesland is called a Landtagswahl. Each level of government has its own election type, and the Landtag is the state-level parliament.", "distractor_notes": ["A Kommunalwahl elects local councils and mayors at the municipal level, not the state parliament.", "", "A Europawahl elects members of the European Parliament, not a state parliament.", "A Bundestagswahl elects the federal parliament (Bundestag), not a state parliament."]}, {"id": 63, "id_str": "63", "category": "general", "exam_pool": "general", "question_de": "Was gehört in Deutschland nicht zur Exekutive?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Polizei", "correct": false, "text_en": "the police"}, {"text_de": "die Gerichte", "correct": true, "text_en": "the courts"}, {"text_de": "das Finanzamt", "correct": false, "text_en": "the tax office (Finanzamt)"}, {"text_de": "die Ministerien", "correct": false, "text_en": "the ministries"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-063.png"}, "question_en": "Which of these does NOT belong to the executive branch in Germany?", "asking_note": "Negative framing: you must pick the ONE thing that is NOT part of the executive (Exekutive). This tests the separation of powers (Gewaltenteilung). Three options are executive/administrative bodies; the odd one out belongs to a different branch.", "answer_explanation": "Germany's separation of powers (Article 20 of the Grundgesetz) splits the state into three branches: legislature (Bundestag/Bundesrat), executive (Exekutive), and judiciary (Judikative). The courts (Gerichte) are the judiciary, whose job is to apply and interpret the law independently. Because they are not part of the executive, they are the correct 'does not belong' answer.", "distractor_notes": ["The police enforce the law and are part of the executive.", "", "The tax office (Finanzamt) is a state administrative body and part of the executive.", "The ministries carry out government policy and are part of the executive."]}, {"id": 64, "id_str": "64", "category": "general", "exam_pool": "general", "question_de": "Die Bundesrepublik Deutschland ist heute gegliedert in …", "question_image": null, "image_kind": null, "options": [{"text_de": "vier Besatzungszonen.", "correct": false, "text_en": "four occupation zones."}, {"text_de": "einen Oststaat und einen Weststaat.", "correct": false, "text_en": "one Eastern state and one Western state."}, {"text_de": "16 Kantone.", "correct": false, "text_en": "16 cantons."}, {"text_de": "Bund, Länder und Kommunen.", "correct": true, "text_en": "federation, states and municipalities."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-064.png"}, "question_en": "The Federal Republic of Germany today is structured into …", "asking_note": "Straightforward factual recall of Germany's federal structure. The three wrong answers are historical or foreign structures designed to catch you if you confuse eras or countries.", "answer_explanation": "Germany is a federal state (Bundesstaat) organized on three levels: the federation (Bund), the 16 states (Länder), and the municipalities (Kommunen/Gemeinden). This layered structure is anchored in the Grundgesetz (Articles 20 and 28) and distributes power between national, regional and local government.", "distractor_notes": ["Four occupation zones existed only right after WWII (1945), when the Allies divided Germany.", "One Eastern and one Western state describes the divided Germany (FRG and GDR) before reunification in 1990.", "Cantons are the units of Switzerland, not Germany.", ""]}, {"id": 65, "id_str": "65", "category": "general", "exam_pool": "general", "question_de": "Es gehört nicht zu den Aufgaben des Deutschen Bundestages, …", "question_image": null, "image_kind": null, "options": [{"text_de": "Gesetze zu entwerfen.", "correct": false, "text_en": "to draft laws."}, {"text_de": "die Bundesregierung zu kontrollieren.", "correct": false, "text_en": "to oversee the federal government."}, {"text_de": "die Bundeskanzlerin/den Bundeskanzler zu wählen.", "correct": false, "text_en": "to elect the Federal Chancellor."}, {"text_de": "das Bundeskabinett zu bilden.", "correct": true, "text_en": "to form the federal cabinet."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-065.png"}, "question_en": "Which of the following is NOT a task of the German Bundestag?", "asking_note": "Negative framing ('gehört nicht zu den Aufgaben' = 'is NOT among the tasks'). Three options are genuine Bundestag duties; pick the one that is done by someone else. Watch the confusion between electing the Chancellor (Bundestag does this) and forming the cabinet (the Chancellor does this).", "answer_explanation": "The Bundestag drafts and passes laws, scrutinizes the government, and elects the Chancellor (Article 63 of the Grundgesetz). It does NOT form the cabinet: the Chancellor selects the ministers, who are then appointed and dismissed by the Federal President (Article 64). Forming the Bundeskabinett is therefore not a Bundestag task.", "distractor_notes": ["Drafting and passing legislation is a core Bundestag function.", "Controlling the government is a core parliamentary function.", "The Bundestag elects the Chancellor under Article 63.", ""]}, {"id": 66, "id_str": "66", "category": "general", "exam_pool": "general", "question_de": "Welche Städte haben die größten jüdischen Gemeinden in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Berlin und München", "correct": true, "text_en": "Berlin and Munich"}, {"text_de": "Hamburg und Essen", "correct": false, "text_en": "Hamburg and Essen"}, {"text_de": "Nürnberg und Stuttgart", "correct": false, "text_en": "Nuremberg and Stuttgart"}, {"text_de": "Worms und Speyer", "correct": false, "text_en": "Worms and Speyer"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-066.png"}, "question_en": "Which cities have the largest Jewish communities in Germany?", "asking_note": "Factual recall about present-day Jewish community size, not historical significance. The trap is Worms and Speyer, which are historically famous but not the largest communities today.", "answer_explanation": "Berlin and Munich have the largest Jewish congregations in modern Germany. Berlin's community is the biggest in the country, and Munich's is among the largest, reflecting the postwar and especially post-1990 growth of Jewish life (many members arrived from the former Soviet Union).", "distractor_notes": ["", "Hamburg and Essen have Jewish communities but not the largest.", "Nuremberg and Stuttgart are not the largest Jewish communities.", "Worms and Speyer were major centers of medieval Jewish life (the 'ShUM' cities) but are small communities today."]}, {"id": 67, "id_str": "67", "category": "general", "exam_pool": "general", "question_de": "Was ist in Deutschland vor allem eine Aufgabe der Bundesländer?", "question_image": null, "image_kind": null, "options": [{"text_de": "Verteidigungspolitik", "correct": false, "text_en": "defense policy"}, {"text_de": "Außenpolitik", "correct": false, "text_en": "foreign policy"}, {"text_de": "Wirtschaftspolitik", "correct": false, "text_en": "economic policy"}, {"text_de": "Schulpolitik", "correct": true, "text_en": "education policy"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-067.png"}, "question_en": "In Germany, which of these is above all a responsibility of the individual states (Bundesländer)?", "asking_note": "Tests the division of powers between the federation and the states. The trap is knowing which policy areas belong to the Länder rather than the Bund. Only one listed area is primarily a state matter.", "answer_explanation": "Education is the classic domain of the states (the 'Kulturhoheit der Länder'). Each Bundesland runs its own schools, curricula and school laws, which is why school systems differ from state to state. Defense and foreign policy, by contrast, are federal responsibilities.", "distractor_notes": ["Defense policy is a federal (Bund) responsibility.", "Foreign policy is a federal responsibility.", "Economic policy is largely shaped at the federal level.", ""]}, {"id": 68, "id_str": "68", "category": "general", "exam_pool": "general", "question_de": "Warum kontrolliert der Staat in Deutschland das Schulwesen?", "question_image": null, "image_kind": null, "options": [{"text_de": "weil es in Deutschland nur staatliche Schulen gibt", "correct": false, "text_en": "because there are only state schools in Germany"}, {"text_de": "weil alle Schülerinnen und Schüler einen Schulabschluss haben müssen", "correct": false, "text_en": "because all pupils must obtain a school-leaving qualification"}, {"text_de": "weil es in den Bundesländern verschiedene Schulen gibt", "correct": false, "text_en": "because there are different schools in the states"}, {"text_de": "weil es nach dem Grundgesetz seine Aufgabe ist", "correct": true, "text_en": "because it is the state's task under the Grundgesetz"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-068.png"}, "question_en": "Why does the state supervise the school system in Germany?", "asking_note": "This asks for the legal basis for state oversight of schools. The three wrong answers give plausible-sounding but incorrect reasons; the right one points to the constitution.", "answer_explanation": "Article 7 of the Grundgesetz states that the entire school system is under the supervision of the state ('Das gesamte Schulwesen steht unter der Aufsicht des Staates'). Supervising schools is therefore a constitutional duty, which is the correct reason.", "distractor_notes": ["Wrong: Germany also has private and church-run schools, not only state schools.", "Wrong: this is a policy aim, not the reason the state supervises schools.", "Wrong: the existence of different schools does not itself explain state oversight.", ""]}, {"id": 69, "id_str": "69", "category": "general", "exam_pool": "general", "question_de": "Die Bundesrepublik Deutschland hat einen dreistufigen Verwaltungsaufbau. Wie heißt die unterste politische Stufe?", "question_image": null, "image_kind": null, "options": [{"text_de": "Stadträte", "correct": false, "text_en": "city councils"}, {"text_de": "Landräte", "correct": false, "text_en": "district administrators (Landräte)"}, {"text_de": "Gemeinden", "correct": true, "text_en": "municipalities (Gemeinden)"}, {"text_de": "Bezirksämter", "correct": false, "text_en": "borough offices (Bezirksämter)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-069.png"}, "question_en": "The Federal Republic of Germany has a three-tier administrative structure. What is the lowest political level called?", "asking_note": "Recall of the bottom rung of the Bund–Länder–Gemeinden hierarchy. The distractors are real bodies (councils, district administrators, borough offices) that sound local but are not the answer to 'lowest level'.", "answer_explanation": "Germany's administration runs Bund (federation) → Länder (states) → Gemeinden (municipalities). The municipality is the lowest political and administrative level, closest to citizens, and is guaranteed self-government under Article 28 of the Grundgesetz.", "distractor_notes": ["City councils are municipal bodies, not the level itself.", "Landräte head districts (Kreise), which sit above the municipal level.", "", "Bezirksämter are borough administrations within certain large cities, not the general lowest tier."]}, {"id": 70, "id_str": "70", "category": "general", "exam_pool": "general", "question_de": "Der deutsche Bundespräsident Gustav Heinemann gibt Helmut Schmidt 1974 die Ernennungsurkunde zum deutschen Bundeskanzler. Was gehört zu den Aufgaben der deutschen Bundespräsidentin/des deutschen Bundespräsidenten?", "question_image": "assets/img/q070-stem.png", "image_kind": "stem", "options": [{"text_de": "Sie/Er führt die Regierungsgeschäfte.", "correct": false, "text_en": "He/she runs the affairs of government."}, {"text_de": "Sie/Er kontrolliert die Regierungspartei.", "correct": false, "text_en": "He/she supervises the governing party."}, {"text_de": "Sie/Er wählt die Ministerinnen/Minister aus.", "correct": false, "text_en": "He/she selects the ministers."}, {"text_de": "Sie/Er schlägt die Kanzlerin/den Kanzler zur Wahl vor.", "correct": true, "text_en": "He/she proposes the Chancellor for election."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-070.png"}, "question_en": "(Refers to a photo of Federal President Gustav Heinemann handing Helmut Schmidt his certificate of appointment as Federal Chancellor in 1974.) What is one of the tasks of the German Federal President?", "asking_note": "The question stem references a historical photo, but the answer is text. It tests what the largely ceremonial Federal President actually does, versus the Chancellor's job. Do not confuse proposing the Chancellor (President) with governing (Chancellor).", "answer_explanation": "Under Article 63 of the Grundgesetz, the Federal President proposes a candidate for Chancellor, whom the Bundestag then elects. The presidency is a mostly representative office; proposing the candidate and then formally appointing the elected Chancellor (the certificate of appointment shown in the photo) is one of its genuine functions.", "distractor_notes": ["Running the government is the Chancellor's job, not the President's.", "The President does not oversee any political party; the office is meant to be non-partisan.", "The Chancellor selects the ministers; the President only formally appoints them.", ""]}, {"id": 71, "id_str": "71", "category": "general", "exam_pool": "general", "question_de": "Wo hält sich die deutsche Bundeskanzlerin/der deutsche Bundeskanzler am häufigsten auf? Am häufigsten ist sie/er …", "question_image": null, "image_kind": null, "options": [{"text_de": "in Bonn, weil sich dort das Bundeskanzleramt und der Bundestag befinden.", "correct": false, "text_en": "In Bonn, because the Chancellery and the Bundestag are located there."}, {"text_de": "auf Schloss Meseberg, dem Gästehaus der Bundesregierung, um Staatsgäste zu empfangen.", "correct": false, "text_en": "At Schloss Meseberg, the federal government's guest house, to receive state guests."}, {"text_de": "auf Schloss Bellevue, dem Amtssitz der Bundespräsidentin/des Bundespräsidenten, um Staatsgäste zu empfangen.", "correct": false, "text_en": "At Schloss Bellevue, the official residence of the Federal President, to receive state guests."}, {"text_de": "in Berlin, weil sich dort das Bundeskanzleramt und der Bundestag befinden.", "correct": true, "text_en": "In Berlin, because the Chancellery and the Bundestag are located there."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": ["ambiguous_answer_match"]}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-071.png"}, "question_en": "Where is the German Federal Chancellor most often located?", "asking_note": "Tests knowledge that Berlin is the seat of government. The distractors pair a real place with a plausible-but-wrong reason: Bonn is the former capital, and the two palaces belong to other functions/offices.", "answer_explanation": "Berlin has been Germany's capital and seat of government since reunification (the Bundestag moved there in 1999). The Federal Chancellery (Bundeskanzleramt) and the Bundestag are in Berlin, so that is where the Chancellor spends most of their working time.", "distractor_notes": ["Bonn was the capital of West Germany until 1990/1999; the government has since moved to Berlin.", "Schloss Meseberg is the government's guest house, used occasionally, not the Chancellor's usual location.", "Schloss Bellevue is the Federal President's residence, not the Chancellor's.", ""]}, {"id": 72, "id_str": "72", "category": "general", "exam_pool": "general", "question_de": "Wie heißt die jetzige Bundeskanzlerin/der jetzige Bundeskanzler von Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Gerhard Schröder", "correct": false, "text_en": "Gerhard Schröder"}, {"text_de": "Angela Merkel", "correct": false, "text_en": "Angela Merkel"}, {"text_de": "Ursula von der Leyen", "correct": false, "text_en": "Ursula von der Leyen"}, {"text_de": "Friedrich Merz", "correct": true, "text_en": "Friedrich Merz"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-072.png"}, "question_en": "What is the name of the current Federal Chancellor of Germany?", "asking_note": "Current-affairs recall. The answer changes over time; the distractors are former chancellors and a well-known politician who holds a different office. As of this exam, the sitting Chancellor is the correct choice.", "answer_explanation": "Friedrich Merz (CDU) became Federal Chancellor in May 2025 after the February 2025 Bundestag election, leading a CDU/CSU-SPD coalition. He is the current head of government.", "distractor_notes": ["Gerhard Schröder (SPD) was Chancellor from 1998 to 2005.", "Angela Merkel (CDU) was Chancellor from 2005 to 2021.", "Ursula von der Leyen is President of the European Commission, not the German Chancellor.", ""]}, {"id": 73, "id_str": "73", "category": "general", "exam_pool": "general", "question_de": "Die beiden größten Fraktionen im Deutschen Bundestag heißen zurzeit …", "question_image": null, "image_kind": null, "options": [{"text_de": "CDU/CSU und AfD.", "correct": true, "text_en": "CDU/CSU and AfD."}, {"text_de": "Die Linke und Bündnis 90/Die Grünen.", "correct": false, "text_en": "Die Linke and Alliance 90/The Greens."}, {"text_de": "Bündnis 90/Die Grünen und SPD.", "correct": false, "text_en": "Alliance 90/The Greens and SPD."}, {"text_de": "Die Linke und CDU/CSU.", "correct": false, "text_en": "Die Linke and CDU/CSU."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-073.png"}, "question_en": "The two largest parliamentary groups (Fraktionen) in the German Bundestag are currently …", "asking_note": "Current-affairs recall about the two biggest Fraktionen after the most recent election. Reflects the 2025 Bundestag composition; the distractors pair smaller parties.", "answer_explanation": "After the February 2025 federal election, the CDU/CSU became the largest parliamentary group and the AfD the second largest. Together they form the two biggest Fraktionen in the current Bundestag; the CDU/CSU governs in coalition with the SPD, while the AfD is the largest opposition group.", "distractor_notes": ["", "Die Linke and the Greens are smaller groups, not the two largest.", "The Greens and SPD are not the two largest groups.", "Die Linke is not among the two largest groups."]}, {"id": 74, "id_str": "74", "category": "general", "exam_pool": "general", "question_de": "Wie heißt das Parlament für ganz Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Bundesversammlung", "correct": false, "text_en": "Federal Convention (Bundesversammlung)"}, {"text_de": "Volkskammer", "correct": false, "text_en": "People's Chamber (Volkskammer)"}, {"text_de": "Bundestag", "correct": true, "text_en": "Bundestag"}, {"text_de": "Bundesgerichtshof", "correct": false, "text_en": "Federal Court of Justice (Bundesgerichtshof)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-074.png"}, "question_en": "What is the name of the parliament for all of Germany?", "asking_note": "Recall of the name of the national parliament. Distractors are other federal bodies and a historical/judicial body that sound similar but are not the parliament.", "answer_explanation": "The Bundestag is the directly elected national parliament of Germany. It passes federal laws, elects the Chancellor and oversees the government, making it the country's central legislative body.", "distractor_notes": ["The Bundesversammlung is a special assembly that meets only to elect the Federal President.", "The Volkskammer was the parliament of the former East Germany (GDR), which no longer exists.", "", "The Bundesgerichtshof is Germany's highest court for civil and criminal cases, not a parliament."]}, {"id": 75, "id_str": "75", "category": "general", "exam_pool": "general", "question_de": "Wie heißt Deutschlands heutiges Staatsoberhaupt?", "question_image": null, "image_kind": null, "options": [{"text_de": "Frank-Walter Steinmeier", "correct": true, "text_en": "Frank-Walter Steinmeier"}, {"text_de": "Bärbel Bas", "correct": false, "text_en": "Bärbel Bas"}, {"text_de": "Bodo Ramelow", "correct": false, "text_en": "Bodo Ramelow"}, {"text_de": "Joachim Gauck", "correct": false, "text_en": "Joachim Gauck"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-075.png"}, "question_en": "What is the name of Germany's current head of state?", "asking_note": "Current-affairs recall: the head of state is the Federal President, not the Chancellor. Distractors are other prominent politicians and a former President.", "answer_explanation": "Frank-Walter Steinmeier (SPD) has been Germany's Federal President since 2017 and was re-elected in 2022. As Bundespräsident he is the head of state, a largely representative role above day-to-day politics.", "distractor_notes": ["", "Bärbel Bas is an SPD politician (former Bundestag President, later a federal minister), not the head of state.", "Bodo Ramelow (Die Linke) was Minister-President of Thuringia, not the head of state.", "Joachim Gauck was Federal President before Steinmeier, from 2012 to 2017."]}, {"id": 76, "id_str": "76", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet die Abkürzung CDU in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Christliche Deutsche Union", "correct": false, "text_en": "Christian German Union (Christliche Deutsche Union)"}, {"text_de": "Club Deutscher Unternehmer", "correct": false, "text_en": "Club of German Entrepreneurs (Club Deutscher Unternehmer)"}, {"text_de": "Christlicher Deutscher Umweltschutz", "correct": false, "text_en": "Christian German Environmental Protection (Christlicher Deutscher Umweltschutz)"}, {"text_de": "Christlich Demokratische Union", "correct": true, "text_en": "Christian Democratic Union (Christlich Demokratische Union)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-076.png"}, "question_en": "What does the abbreviation CDU stand for in Germany?", "asking_note": "Tests the exact expansion of a major party's name. The distractors are near-miss wordings that swap in wrong words (e.g. 'Deutsche' instead of 'Demokratische').", "answer_explanation": "CDU stands for Christlich Demokratische Union (Christian Democratic Union), a center-right party founded after World War II. It is one of Germany's two traditional major parties (Volksparteien) and currently leads the federal government.", "distractor_notes": ["Wrong wording: it is 'Demokratische', not 'Deutsche'.", "Invented organization; not what CDU means.", "Invented environmental group; not what CDU means.", ""]}, {"id": 77, "id_str": "77", "category": "general", "exam_pool": "general", "question_de": "Was ist die Bundeswehr?", "question_image": null, "image_kind": null, "options": [{"text_de": "die deutsche Polizei", "correct": false, "text_en": "the German police"}, {"text_de": "ein deutscher Hafen", "correct": false, "text_en": "a German port"}, {"text_de": "eine deutsche Bürgerinitiative", "correct": false, "text_en": "a German citizens' initiative"}, {"text_de": "die deutsche Armee", "correct": true, "text_en": "the German army"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-077.png"}, "question_en": "What is the Bundeswehr?", "asking_note": "Simple vocabulary/institution recall. Only one option names the armed forces; the others are unrelated types of organizations.", "answer_explanation": "The Bundeswehr is Germany's armed forces, established in 1955. It comprises the army, air force and navy and is under civilian control (the Minister of Defence in peacetime, the Chancellor in a state of defence).", "distractor_notes": ["The police (Polizei) handle domestic law enforcement, separate from the military.", "A port (Hafen) is a harbor, unrelated to the Bundeswehr.", "A citizens' initiative (Bürgerinitiative) is a grassroots civic group, not the military.", ""]}, {"id": 78, "id_str": "78", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet die Abkürzung SPD?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sozialistische Partei Deutschlands", "correct": false, "text_en": "Socialist Party of Germany (Sozialistische Partei Deutschlands)"}, {"text_de": "Sozialpolitische Partei Deutschlands", "correct": false, "text_en": "Social-Policy Party of Germany (Sozialpolitische Partei Deutschlands)"}, {"text_de": "Sozialdemokratische Partei Deutschlands", "correct": true, "text_en": "Social Democratic Party of Germany (Sozialdemokratische Partei Deutschlands)"}, {"text_de": "Sozialgerechte Partei Deutschlands", "correct": false, "text_en": "Socially-Just Party of Germany (Sozialgerechte Partei Deutschlands)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-078.png"}, "question_en": "What does the abbreviation SPD stand for?", "asking_note": "Exact party-name expansion. All options start with 'Sozial-'; the trap is picking the wrong second word. 'Sozialistische' is deliberately close to but different from 'Sozialdemokratische'.", "answer_explanation": "SPD stands for Sozialdemokratische Partei Deutschlands (Social Democratic Party of Germany). Founded in 1863, it is Germany's oldest party and one of the two large traditional parties, positioned on the center-left.", "distractor_notes": ["Wrong: 'Sozialistische' (Socialist) is not the SPD's name.", "Invented wording; not what SPD means.", "", "Invented wording; not what SPD means."]}, {"id": 79, "id_str": "79", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet die Abkürzung FDP in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Friedliche Demonstrative Partei", "correct": false, "text_en": "Peaceful Demonstrative Party (Friedliche Demonstrative Partei)"}, {"text_de": "Freie Deutschland Partei", "correct": false, "text_en": "Free Germany Party (Freie Deutschland Partei)"}, {"text_de": "Führende Demokratische Partei", "correct": false, "text_en": "Leading Democratic Party (Führende Demokratische Partei)"}, {"text_de": "Freie Demokratische Partei", "correct": true, "text_en": "Free Democratic Party (Freie Demokratische Partei)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-079.png"}, "question_en": "What does the abbreviation FDP stand for in Germany?", "asking_note": "Exact party-name expansion. The distractors mix in plausible-sounding but wrong words; only one is the real liberal party's name.", "answer_explanation": "FDP stands for Freie Demokratische Partei (Free Democratic Party), Germany's classic liberal party. It emphasizes civil liberties, free-market economics and a smaller state, and has often been a junior coalition partner in federal governments.", "distractor_notes": ["Invented wording; not what FDP means.", "Wrong wording: it is 'Demokratische', not 'Deutschland'.", "Invented wording; not what FDP means.", ""]}, {"id": 80, "id_str": "80", "category": "general", "exam_pool": "general", "question_de": "Welches Gericht in Deutschland ist zuständig für die Auslegung des Grundgesetzes?", "question_image": null, "image_kind": null, "options": [{"text_de": "Oberlandesgericht", "correct": false, "text_en": "Higher Regional Court (Oberlandesgericht)"}, {"text_de": "Amtsgericht", "correct": false, "text_en": "Local Court (Amtsgericht)"}, {"text_de": "Bundesverfassungsgericht", "correct": true, "text_en": "Federal Constitutional Court (Bundesverfassungsgericht)"}, {"text_de": "Verwaltungsgericht", "correct": false, "text_en": "Administrative Court (Verwaltungsgericht)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-080.png"}, "question_en": "Which court in Germany is responsible for interpreting the Grundgesetz (Basic Law)?", "asking_note": "Tests which court is the guardian of the constitution. The distractors are real German courts that handle other matters; only one has jurisdiction over the constitution.", "answer_explanation": "The Bundesverfassungsgericht (Federal Constitutional Court, based in Karlsruhe) is the guardian of the Grundgesetz. It interprets the constitution, rules on constitutional complaints, and can strike down laws that violate the Basic Law.", "distractor_notes": ["The Oberlandesgericht is an appellate court for civil and criminal cases, not constitutional questions.", "The Amtsgericht is a local court for everyday civil and minor criminal matters.", "", "The Verwaltungsgericht handles disputes between citizens and public authorities, not the constitution."]}, {"id": 81, "id_str": "81", "category": "general", "exam_pool": "general", "question_de": "Wer wählt die Bundeskanzlerin/den Bundeskanzler in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Bundesrat", "correct": false, "text_en": "the Bundesrat"}, {"text_de": "die Bundesversammlung", "correct": false, "text_en": "the Federal Convention (Bundesversammlung)"}, {"text_de": "das Volk", "correct": false, "text_en": "the people"}, {"text_de": "der Bundestag", "correct": true, "text_en": "the Bundestag"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-081.png"}, "question_en": "Who elects the Federal Chancellor in Germany?", "asking_note": "Tests the constitutional route to the chancellorship. A common trap is thinking the people or the Federal President elect the Chancellor; in fact it is parliament. (Note: id 83 asks the same thing.)", "answer_explanation": "Under Article 63 of the Grundgesetz, the Bundestag elects the Chancellor, on the proposal of the Federal President. Citizens do not vote for the Chancellor directly; they elect the Bundestag, which then chooses the head of government.", "distractor_notes": ["The Bundesrat represents the states and does not elect the Chancellor.", "The Bundesversammlung only elects the Federal President.", "The people elect the Bundestag, not the Chancellor directly.", ""]}, {"id": 82, "id_str": "82", "category": "general", "exam_pool": "general", "question_de": "Wer leitet das deutsche Bundeskabinett?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Bundestagspräsidentin/der Bundestagspräsident", "correct": false, "text_en": "the President of the Bundestag"}, {"text_de": "die Bundespräsidentin/der Bundespräsident", "correct": false, "text_en": "the Federal President"}, {"text_de": "die Bundesratspräsidentin/der Bundesratspräsident", "correct": false, "text_en": "the President of the Bundesrat"}, {"text_de": "die Bundeskanzlerin/der Bundeskanzler", "correct": true, "text_en": "the Federal Chancellor"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-082.png"}, "question_en": "Who leads the German federal cabinet (Bundeskabinett)?", "asking_note": "Tests who heads the government. The distractors are the presiding officers of other bodies (Bundestag, Bundesrat) and the head of state, all of whom sound authoritative but do not run the cabinet.", "answer_explanation": "The Federal Chancellor chairs and leads the federal cabinet. Under Article 65 of the Grundgesetz, the Chancellor sets the general policy guidelines (Richtlinienkompetenz), making them the head of government.", "distractor_notes": ["The President of the Bundestag presides over parliament, not the cabinet.", "The Federal President is head of state and does not lead the cabinet.", "The President of the Bundesrat chairs the states' chamber, not the cabinet.", ""]}, {"id": 83, "id_str": "83", "category": "general", "exam_pool": "general", "question_de": "Wer wählt die deutsche Bundeskanzlerin/den deutschen Bundeskanzler?", "question_image": null, "image_kind": null, "options": [{"text_de": "das Volk", "correct": false, "text_en": "the people"}, {"text_de": "die Bundesversammlung", "correct": false, "text_en": "the Federal Convention (Bundesversammlung)"}, {"text_de": "der Bundestag", "correct": true, "text_en": "the Bundestag"}, {"text_de": "die Bundesregierung", "correct": false, "text_en": "the federal government"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-083.png"}, "question_en": "Who elects the German Federal Chancellor?", "asking_note": "Same core fact as id 81. The Chancellor is elected by parliament, not by the people or the President. Note the order of options differs from id 81.", "answer_explanation": "The Bundestag elects the Chancellor under Article 63 of the Grundgesetz, following a nomination by the Federal President. The Chancellor needs the support of a majority of the members of the Bundestag.", "distractor_notes": ["The people elect the Bundestag, not the Chancellor directly.", "The Bundesversammlung elects only the Federal President.", "", "The federal government is led by the Chancellor; it does not elect them."]}, {"id": 84, "id_str": "84", "category": "general", "exam_pool": "general", "question_de": "Welche Hauptaufgabe hat die deutsche Bundespräsidentin/der deutsche Bundespräsident? Sie/Er …", "question_image": null, "image_kind": null, "options": [{"text_de": "regiert das Land.", "correct": false, "text_en": "governs the country."}, {"text_de": "entwirft die Gesetze.", "correct": false, "text_en": "drafts the laws."}, {"text_de": "repräsentiert das Land.", "correct": true, "text_en": "represents the country."}, {"text_de": "überwacht die Einhaltung der Gesetze.", "correct": false, "text_en": "monitors compliance with the laws."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-084.png"}, "question_en": "What is the main task of the German Federal President?", "asking_note": "Tests the ceremonial nature of the presidency. The distractors describe jobs of the Chancellor, parliament, or the courts. The President 'represents' rather than 'governs'.", "answer_explanation": "The Federal President is Germany's head of state and mainly represents the country at home and abroad. The office is largely ceremonial and non-partisan: the President signs laws and appoints officials but does not govern day to day.", "distractor_notes": ["Governing is the Chancellor's and the government's role.", "Drafting laws is done by the government and parliament.", "", "Monitoring compliance with the law is the job of the courts and administration, not the President."]}, {"id": 85, "id_str": "85", "category": "general", "exam_pool": "general", "question_de": "Wer bildet den deutschen Bundesrat?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Abgeordneten des Bundestages", "correct": false, "text_en": "the members of the Bundestag"}, {"text_de": "die Ministerinnen und Minister der Bundesregierung", "correct": false, "text_en": "the ministers of the federal government"}, {"text_de": "die Regierungsvertreter der Bundesländer", "correct": true, "text_en": "the government representatives of the states (Länder)"}, {"text_de": "die Parteimitglieder", "correct": false, "text_en": "the party members"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-085.png"}, "question_en": "Who makes up the German Bundesrat?", "asking_note": "Tests the composition of the second chamber. The trap is confusing the Bundesrat (state governments) with the Bundestag (elected MPs) or with the federal ministers.", "answer_explanation": "The Bundesrat is made up of members of the state governments (Article 51 of the Grundgesetz). Each Bundesland sends representatives from its cabinet, so the Bundesrat is how the Länder participate in federal legislation and administration.", "distractor_notes": ["Members of the Bundestag sit in parliament, not the Bundesrat.", "Federal ministers form the federal government, not the Bundesrat.", "", "Ordinary party members do not form the Bundesrat."]}, {"id": 86, "id_str": "86", "category": "general", "exam_pool": "general", "question_de": "Wer wählt in Deutschland die Bundespräsidentin/den Bundespräsidenten?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Bundesversammlung", "correct": true, "text_en": "the Federal Convention (Bundesversammlung)"}, {"text_de": "der Bundesrat", "correct": false, "text_en": "the Bundesrat"}, {"text_de": "das Bundesparlament", "correct": false, "text_en": "the federal parliament (Bundesparlament)"}, {"text_de": "das Bundesverfassungsgericht", "correct": false, "text_en": "the Federal Constitutional Court"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-086.png"}, "question_en": "Who elects the Federal President in Germany?", "asking_note": "Tests the specific body that chooses the head of state. The distractor 'Bundesparlament' is a made-up-sounding name, and the Bundesrat/Constitutional Court are real bodies with other roles.", "answer_explanation": "The Federal President is elected by the Bundesversammlung (Federal Convention), a special body that meets only for this purpose (Article 54 of the Grundgesetz). It consists of all Bundestag members plus an equal number of delegates chosen by the state parliaments.", "distractor_notes": ["", "The Bundesrat represents the state governments and does not elect the President.", "There is no body officially called the 'Bundesparlament'; the national parliament is the Bundestag.", "The Federal Constitutional Court is a court, not an electoral body."]}, {"id": 87, "id_str": "87", "category": "general", "exam_pool": "general", "question_de": "Wer ist das Staatsoberhaupt der Bundesrepublik Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Bundeskanzlerin/der Bundeskanzler", "correct": false, "text_en": "the Federal Chancellor"}, {"text_de": "die Bundespräsidentin/der Bundespräsident", "correct": true, "text_en": "the Federal President"}, {"text_de": "die Bundesratspräsidentin/der Bundesratspräsident", "correct": false, "text_en": "the President of the Bundesrat"}, {"text_de": "die Bundestagspräsidentin/der Bundestagspräsident", "correct": false, "text_en": "the President of the Bundestag"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-087.png"}, "question_en": "Who is the head of state of the Federal Republic of Germany?", "asking_note": "Tests the distinction between head of state (President) and head of government (Chancellor). All four options are presiding figures, but only one is the head of state.", "answer_explanation": "The Federal President (Bundespräsident) is the head of state of the Federal Republic of Germany. The Chancellor is head of government; the two roles are deliberately separated so that the head of state stands above party politics.", "distractor_notes": ["The Chancellor is head of government, not head of state.", "", "The President of the Bundesrat chairs the states' chamber and only deputizes for the President when needed.", "The President of the Bundestag presides over parliament, not the state."]}, {"id": 88, "id_str": "88", "category": "general", "exam_pool": "general", "question_de": "Die parlamentarische Opposition im Deutschen Bundestag …", "question_image": null, "image_kind": null, "options": [{"text_de": "kontrolliert die Regierung.", "correct": true, "text_en": "monitors/controls the government."}, {"text_de": "entscheidet, wer Bundesministerin/Bundesminister wird.", "correct": false, "text_en": "decides who becomes a federal minister."}, {"text_de": "bestimmt, wer im Bundesrat sitzt.", "correct": false, "text_en": "determines who sits in the Bundesrat."}, {"text_de": "schlägt die Regierungschefinnen/Regierungschefs der Länder vor.", "correct": false, "text_en": "proposes the heads of government of the states."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-088.png"}, "question_en": "The parliamentary opposition in the German Bundestag …", "asking_note": "Tests the role of the opposition. The distractors describe powers the opposition does NOT have (choosing ministers, deciding Bundesrat seats, nominating state premiers). Its real job is scrutiny.", "answer_explanation": "A central function of the parliamentary opposition is to check and scrutinize the government: questioning ministers, criticizing policy, and offering alternatives. This control function is essential to democracy, ensuring the majority is held accountable.", "distractor_notes": ["", "Ministers are chosen by the Chancellor, not the opposition.", "The Bundesrat is made up of state government representatives, decided by the states, not the opposition.", "State premiers are elected by the respective state parliaments, not proposed by the federal opposition."]}, {"id": 89, "id_str": "89", "category": "general", "exam_pool": "general", "question_de": "Wie nennt man in Deutschland die Vereinigung von Abgeordneten einer Partei im Parlament?", "question_image": null, "image_kind": null, "options": [{"text_de": "Verband", "correct": false, "text_en": "association (Verband)"}, {"text_de": "Ältestenrat", "correct": false, "text_en": "Council of Elders (Ältestenrat)"}, {"text_de": "Fraktion", "correct": true, "text_en": "parliamentary group (Fraktion)"}, {"text_de": "Opposition", "correct": false, "text_en": "opposition"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-089.png"}, "question_en": "In Germany, what do you call the association of members of parliament belonging to one party?", "asking_note": "Vocabulary recall for a specific parliamentary term. The distractors are other real parliamentary or organizational terms; only 'Fraktion' means a party's group of MPs.", "answer_explanation": "The group of members of parliament from the same party (or allied parties) is called a Fraktion. Fraktionen organize parliamentary work, coordinate voting, and gain rights and speaking time in the Bundestag according to their size.", "distractor_notes": ["A Verband is a general association or interest group, not a parliamentary group.", "The Ältestenrat is a steering committee that organizes the Bundestag's schedule, not a party's group of MPs.", "", "The opposition is made up of the parties not in government; it is not the general term for a party's group of MPs."]}, {"id": 90, "id_str": "90", "category": "general", "exam_pool": "general", "question_de": "Die deutschen Bundesländer wirken an der Gesetzgebung des Bundes mit durch …", "question_image": null, "image_kind": null, "options": [{"text_de": "den Bundesrat.", "correct": true, "text_en": "the Bundesrat."}, {"text_de": "die Bundesversammlung.", "correct": false, "text_en": "the Federal Convention (Bundesversammlung)."}, {"text_de": "den Bundestag.", "correct": false, "text_en": "the Bundestag."}, {"text_de": "die Bundesregierung.", "correct": false, "text_en": "the federal government."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-090.png"}, "question_en": "The German states (Bundesländer) take part in federal legislation through …", "asking_note": "Tests which institution channels state influence into federal law-making. The trap is confusing the Bundesrat (states' chamber) with the Bundestag or Bundesversammlung.", "answer_explanation": "Through the Bundesrat, the states participate in the legislation and administration of the federation (Article 50 of the Grundgesetz). Many federal laws require the Bundesrat's approval, giving the Länder a direct voice in national law-making.", "distractor_notes": ["", "The Bundesversammlung only elects the Federal President and has no legislative role.", "The Bundestag is the directly elected federal parliament, not the states' body.", "The federal government proposes laws but is not how the states participate in legislation."]}, {"id": 91, "id_str": "91", "category": "general", "exam_pool": "general", "question_de": "In Deutschland kann ein Regierungswechsel in einem Bundesland Auswirkungen auf die Bundespolitik haben. Das Regieren wird …", "question_image": null, "image_kind": null, "options": [{"text_de": "schwieriger, wenn sich dadurch die Mehrheit im Bundestag ändert.", "correct": false, "text_en": "harder, if this changes the majority in the Bundestag."}, {"text_de": "leichter, wenn dadurch neue Parteien in den Bundesrat kommen.", "correct": false, "text_en": "easier, if this brings new parties into the Bundesrat."}, {"text_de": "schwieriger, wenn dadurch die Mehrheit im Bundesrat verändert wird.", "correct": true, "text_en": "harder, if this changes the majority in the Bundesrat."}, {"text_de": "leichter, wenn es sich um ein reiches Bundesland handelt.", "correct": false, "text_en": "easier, if it is a wealthy state."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-091.png"}, "question_en": "In Germany, a change of government in a state (Bundesland) can affect federal politics. Governing becomes …", "asking_note": "Tests understanding of how state elections feed into the Bundesrat and thus into federal law-making. The distractors offer wrong cause-effect pairs (Bundestag majority, 'new parties', 'rich state'). The key link is the Bundesrat majority.", "answer_explanation": "State governments send representatives to the Bundesrat, so a change of government in a Bundesland can shift the majority there. If the federal government loses its majority in the Bundesrat, laws that need Bundesrat approval become harder to pass, so governing gets more difficult.", "distractor_notes": ["Wrong body: a state election does not directly change the majority in the Bundestag (which is elected federally).", "Wrong: new parties entering the Bundesrat does not make governing easier for the federal government.", "", "Wrong: a state's wealth does not make federal governing easier."]}, {"id": 92, "id_str": "92", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet die Abkürzung CSU in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Christlich Sichere Union", "correct": false, "text_en": "Christian Secure Union (Christlich Sichere Union)"}, {"text_de": "Christlich Süddeutsche Union", "correct": false, "text_en": "Christian South-German Union (Christlich Süddeutsche Union)"}, {"text_de": "Christlich Sozialer Unternehmerverband", "correct": false, "text_en": "Christian Social Employers' Association (Christlich Sozialer Unternehmerverband)"}, {"text_de": "Christlich Soziale Union", "correct": true, "text_en": "Christian Social Union (Christlich Soziale Union)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-092.png"}, "question_en": "What does the abbreviation CSU stand for in Germany?", "asking_note": "Exact party-name expansion. All options start with 'Christlich'; the trap is picking the wrong following words. Only one is the real Bavarian sister party of the CDU.", "answer_explanation": "CSU stands for Christlich Soziale Union (Christian Social Union), the center-right party that operates only in Bavaria. It is the sister party of the CDU, and the two form a single joint parliamentary group (CDU/CSU) in the Bundestag.", "distractor_notes": ["Invented wording; not what CSU means.", "Invented wording; not what CSU means, though the CSU is indeed Bavarian.", "Invented organization; not what CSU means.", ""]}, {"id": 93, "id_str": "93", "category": "general", "exam_pool": "general", "question_de": "Je mehr \"Zweitstimmen\" eine Partei bei einer Bundestagswahl bekommt, desto …", "question_image": null, "image_kind": null, "options": [{"text_de": "weniger Erststimmen kann sie haben.", "correct": false, "text_en": "fewer first votes it can have."}, {"text_de": "mehr Direktkandidaten der Partei ziehen ins Parlament ein.", "correct": false, "text_en": "more of the party's direct candidates enter parliament."}, {"text_de": "größer ist das Risiko, eine Koalition bilden zu müssen.", "correct": false, "text_en": "greater the risk of having to form a coalition."}, {"text_de": "mehr Sitze erhält die Partei im Parlament.", "correct": true, "text_en": "more seats the party receives in parliament."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-093.png"}, "question_en": "The more 'second votes' (Zweitstimmen) a party receives in a Bundestag election, the …", "asking_note": "Tests understanding of Germany's two-vote electoral system. The Zweitstimme is the decisive vote for a party's overall share of seats. The distractors misdescribe how first votes, direct candidates and coalitions work.", "answer_explanation": "In German federal elections voters cast two votes; the Zweitstimme (second vote) is for a party list and determines each party's overall share of seats in the Bundestag. So the more second votes a party wins, the more seats it holds in parliament.", "distractor_notes": ["Wrong: the two votes are independent; more second votes does not reduce first votes.", "Wrong: direct candidates are decided by the first vote (Erststimme), not the second vote.", "Wrong: needing a coalition depends on whether any party wins an overall majority, not simply on winning more second votes.", ""]}, {"id": 94, "id_str": "94", "category": "general", "exam_pool": "general", "question_de": "Ab welchem Alter darf man in Deutschland an der Wahl zum Deutschen Bundestag teilnehmen?", "question_image": null, "image_kind": null, "options": [{"text_de": "16", "correct": false, "text_en": "16"}, {"text_de": "18", "correct": true, "text_en": "18"}, {"text_de": "21", "correct": false, "text_en": "21"}, {"text_de": "23", "correct": false, "text_en": "23"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-094.png"}, "question_en": "At what age are you allowed to vote in elections to the German Bundestag (federal parliament)?", "asking_note": "A straightforward fact-check on the federal voting age. The four numbers are the trap: some elections in Germany allow 16, but the Bundestag has its own age.", "answer_explanation": "The right to vote (aktives Wahlrecht) in Bundestag elections is granted at age 18, as set out in Art. 38 of the Grundgesetz. Turning 18 is the standard threshold for full political participation at the federal level.", "distractor_notes": ["16 is the minimum age in some Land/local elections and for European Parliament elections, but not for the Bundestag.", "", "21 was historically a voting age in Germany but no longer applies.", "23 has never been the general voting age."]}, {"id": 95, "id_str": "95", "category": "general", "exam_pool": "general", "question_de": "Was gilt für die meisten Kinder in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Wahlpflicht", "correct": false, "text_en": "Compulsory voting"}, {"text_de": "Schulpflicht", "correct": true, "text_en": "Compulsory schooling"}, {"text_de": "Schweigepflicht", "correct": false, "text_en": "Duty of confidentiality"}, {"text_de": "Religionspflicht", "correct": false, "text_en": "Compulsory religion"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-095.png"}, "question_en": "What applies to most children in Germany?", "asking_note": "A vocabulary test that hinges on telling apart four German '-pflicht' (duty/obligation) words. The answer is compulsory schooling.", "answer_explanation": "Germany has Schulpflicht, a legal obligation for children to attend school (generally around nine years, regulated by each Land). It ensures every child receives an education regardless of the parents' wishes.", "distractor_notes": ["Wahlpflicht (compulsory voting) does not exist in Germany; voting is a right, not a duty.", "", "Schweigepflicht (duty of confidentiality) applies to professionals like doctors and lawyers, not to children generally.", "Religionspflicht does not exist; the Grundgesetz guarantees freedom of religion."]}, {"id": 96, "id_str": "96", "category": "general", "exam_pool": "general", "question_de": "Wie kann jemand, der den Holocaust leugnet, bestraft werden?", "question_image": null, "image_kind": null, "options": [{"text_de": "Kürzung sozialer Leistungen", "correct": false, "text_en": "Reduction of social benefits"}, {"text_de": "bis zu 100 Sozialstunden", "correct": false, "text_en": "Up to 100 hours of community service"}, {"text_de": "gar nicht, Holocaustleugnung ist erlaubt", "correct": false, "text_en": "Not at all, Holocaust denial is permitted"}, {"text_de": "mit Freiheitsstrafe bis zu fünf Jahren oder mit Geldstrafe", "correct": true, "text_en": "Imprisonment of up to five years or a fine"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-096.png"}, "question_en": "How can someone who denies the Holocaust be punished in Germany?", "asking_note": "Tests the fact that Holocaust denial is a criminal offence in Germany. Watch option 3, which falsely claims it is permitted — it is a trap.", "answer_explanation": "Denying the Holocaust is prosecuted as Volksverhetzung (incitement to hatred) under §130 of the Strafgesetzbuch, punishable by up to five years' imprisonment or a fine. This reflects Germany's legal reckoning with its Nazi past.", "distractor_notes": ["Cutting social benefits is not a criminal penalty and is unrelated to this offence.", "Community service is not the prescribed penalty here.", "False — Holocaust denial is explicitly a criminal act, not permitted speech.", ""]}, {"id": 97, "id_str": "97", "category": "general", "exam_pool": "general", "question_de": "Was bezahlt man in Deutschland automatisch, wenn man fest angestellt ist?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sozialversicherung", "correct": true, "text_en": "Social insurance (contributions)"}, {"text_de": "Sozialhilfe", "correct": false, "text_en": "Social assistance"}, {"text_de": "Kindergeld", "correct": false, "text_en": "Child benefit"}, {"text_de": "Wohngeld", "correct": false, "text_en": "Housing benefit"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-097.png"}, "question_en": "What do you pay automatically in Germany when you are in permanent (regular) employment?", "asking_note": "The key is to separate a payment you make from benefits you receive. Only one option is something an employee pays into.", "answer_explanation": "Employees automatically pay statutory social insurance contributions — covering health, pension, unemployment and long-term care insurance — deducted directly from gross pay. These contributions are mandatory for regular employment.", "distractor_notes": ["", "Sozialhilfe is a benefit the state pays to people in need, not something you pay.", "Kindergeld is a benefit paid out to parents, not a contribution.", "Wohngeld is a housing subsidy received from the state, not a payment made."]}, {"id": 98, "id_str": "98", "category": "general", "exam_pool": "general", "question_de": "Wenn Abgeordnete im Deutschen Bundestag ihre Fraktion wechseln, …", "question_image": null, "image_kind": null, "options": [{"text_de": "dürfen sie nicht mehr an den Sitzungen des Parlaments teilnehmen.", "correct": false, "text_en": "they may no longer take part in sittings of parliament."}, {"text_de": "kann die Regierung ihre Mehrheit verlieren.", "correct": true, "text_en": "the government can lose its majority."}, {"text_de": "muss die Bundespräsidentin/der Bundespräsident zuvor ihr/sein Einverständnis geben.", "correct": false, "text_en": "the Federal President must give consent beforehand."}, {"text_de": "dürfen die Wählerinnen/Wähler dieser Abgeordneten noch einmal wählen.", "correct": false, "text_en": "the voters of these members are allowed to vote again."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-098.png"}, "question_en": "When members of the Bundestag switch their parliamentary group (Fraktion), ...", "asking_note": "Tests the free mandate and how governing majorities work. Members keep their seat when they switch; the real consequence is arithmetic in parliament.", "answer_explanation": "Members hold a free mandate under Art. 38 of the Grundgesetz and keep their seat even if they leave or switch their Fraktion. Because a governing coalition depends on holding a majority of seats, enough defections can cost the government its majority.", "distractor_notes": ["False — members retain their seat and full right to participate.", "", "False — no consent from the Federal President is required.", "False — switching groups does not trigger a re-run of the election."]}, {"id": 99, "id_str": "99", "category": "general", "exam_pool": "general", "question_de": "Wer bezahlt in Deutschland die Sozialversicherungen?", "question_image": null, "image_kind": null, "options": [{"text_de": "Arbeitgeberinnen/Arbeitgeber und Arbeitnehmerinnen/Arbeitnehmer", "correct": true, "text_en": "Employers and employees"}, {"text_de": "nur Arbeitnehmerinnen/Arbeitnehmer", "correct": false, "text_en": "only employees"}, {"text_de": "alle Staatsangehörigen", "correct": false, "text_en": "all citizens"}, {"text_de": "nur Arbeitgeberinnen/Arbeitgeber", "correct": false, "text_en": "only employers"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-099.png"}, "question_en": "Who pays for social insurance in Germany?", "asking_note": "Tests the shared-financing (parity) principle of the social insurance system — the cost is split, not carried by one side.", "answer_explanation": "Social insurance contributions are shared, roughly half and half, between employer and employee (the Paritätsprinzip). Both sides fund the health, pension, unemployment and care systems together.", "distractor_notes": ["", "Employees do not bear the cost alone; the employer pays an equal share.", "It is not funded by all citizens generally, but by those in employment (and certain other insured groups).", "Employers do not carry the full cost alone; employees pay their share too."]}, {"id": 100, "id_str": "100", "category": "general", "exam_pool": "general", "question_de": "Was gehört nicht zur gesetzlichen Sozialversicherung?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Lebensversicherung", "correct": true, "text_en": "Life insurance"}, {"text_de": "die gesetzliche Rentenversicherung", "correct": false, "text_en": "Statutory pension insurance"}, {"text_de": "die Arbeitslosenversicherung", "correct": false, "text_en": "Unemployment insurance"}, {"text_de": "die Pflegeversicherung", "correct": false, "text_en": "Long-term care insurance"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-100.png"}, "question_en": "Which of the following is NOT part of the statutory social insurance system in Germany?", "asking_note": "Negative framing — pick the odd one out. Three options are genuine branches of the statutory system; one is a private product.", "answer_explanation": "The statutory social insurance has five branches: health, pension, unemployment, long-term care and accident insurance. Life insurance (Lebensversicherung) is a private, voluntary product and is not part of it.", "distractor_notes": ["", "Statutory pension insurance is one of the five core branches of social insurance.", "Unemployment insurance is a genuine branch of the statutory system.", "Long-term care insurance (Pflegeversicherung) is a genuine branch of the statutory system."]}, {"id": 101, "id_str": "101", "category": "general", "exam_pool": "general", "question_de": "Gewerkschaften sind Interessenverbände der …", "question_image": null, "image_kind": null, "options": [{"text_de": "Jugendlichen.", "correct": false, "text_en": "young people."}, {"text_de": "Arbeitnehmerinnen und Arbeitnehmer.", "correct": true, "text_en": "employees / workers."}, {"text_de": "Rentnerinnen und Rentner.", "correct": false, "text_en": "pensioners."}, {"text_de": "Arbeitgeberinnen und Arbeitgeber.", "correct": false, "text_en": "employers."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-101.png"}, "question_en": "Trade unions (Gewerkschaften) in Germany are interest groups representing ...", "asking_note": "Tests who unions represent. The natural trap is the last option — employers, who are actually the counterpart to unions.", "answer_explanation": "Trade unions represent the interests of employees, negotiating wages and working conditions with employers. This is grounded in the freedom of association (Koalitionsfreiheit) protected by Art. 9 of the Grundgesetz.", "distractor_notes": ["Youth interests are represented by youth organisations, not trade unions.", "", "Pensioners are represented by separate pensioners' associations.", "Employers are represented by employers' associations (Arbeitgeberverbände) — the counterpart to unions, not unions themselves."]}, {"id": 102, "id_str": "102", "category": "general", "exam_pool": "general", "question_de": "Womit kann man in der Bundesrepublik Deutschland geehrt werden, wenn man auf politischem, wirtschaftlichem, kulturellem, geistigem oder sozialem Gebiet eine besondere Leistung erbracht hat? Mit dem …", "question_image": null, "image_kind": null, "options": [{"text_de": "Bundesverdienstkreuz", "correct": true, "text_en": "Federal Cross of Merit (Bundesverdienstkreuz)"}, {"text_de": "Bundesadler", "correct": false, "text_en": "Federal Eagle (Bundesadler)"}, {"text_de": "Vaterländischen Verdienstorden", "correct": false, "text_en": "Patriotic Order of Merit"}, {"text_de": "Ehrentitel \"Held der Deutschen Demokratischen Republik\"", "correct": false, "text_en": "Honorary title 'Hero of the German Democratic Republic'"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-102.png"}, "question_en": "With what can a person be honoured in the Federal Republic of Germany for a special achievement in the political, economic, cultural, intellectual or social field? With the ...", "asking_note": "Tests the highest German civilian honour. The distractors are decoys drawn from the former GDR and from the national emblem.", "answer_explanation": "The Bundesverdienstkreuz (Order of Merit of the Federal Republic of Germany), created in 1951, is the country's highest civilian honour, awarded for outstanding achievements benefiting society. It is the only order of merit awarded by the Federal Republic.", "distractor_notes": ["", "The Bundesadler is the federal eagle — Germany's coat of arms/emblem, not an award.", "The Vaterländischer Verdienstorden was a decoration of the former East Germany (GDR).", "'Held der DDR' was an honorary title of the former East German state, not of the Federal Republic."]}, {"id": 103, "id_str": "103", "category": "general", "exam_pool": "general", "question_de": "Was wird in Deutschland als \"Ampelkoalition\" bezeichnet? Die Zusammenarbeit …", "question_image": null, "image_kind": null, "options": [{"text_de": "der Bundestagsfraktionen von CDU und CSU", "correct": false, "text_en": "of the CDU and CSU parliamentary groups"}, {"text_de": "von SPD, FDP und Bündnis 90/Die Grünen in einer Regierung", "correct": true, "text_en": "of SPD, FDP and Alliance 90/The Greens in a government"}, {"text_de": "von CSU, Die LINKE und Bündnis 90/Die Grünen in einer Regierung", "correct": false, "text_en": "of CSU, The Left and Alliance 90/The Greens in a government"}, {"text_de": "der Bundestagsfraktionen von CDU und SPD", "correct": false, "text_en": "of the CDU and SPD parliamentary groups"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-103.png"}, "question_en": "What is referred to in Germany as an 'Ampelkoalition' (traffic-light coalition)? The cooperation ...", "asking_note": "Tests coalition colour-coding. 'Ampel' points to the party colours red (SPD), yellow (FDP) and green (Greens); the trap options list other party combinations.", "answer_explanation": "An 'Ampelkoalition' is named after the traffic-light colours of its partners: red for the SPD, yellow for the FDP and green for the Greens. Germany's federal government from 2021 to 2024 was exactly this three-party coalition.", "distractor_notes": ["CDU and CSU form the 'Union' sister-party bloc, not a traffic-light coalition.", "", "This party combination does not correspond to the traffic-light colours.", "A CDU–SPD pairing is called a 'grand coalition' (Große Koalition), not an Ampelkoalition."]}, {"id": 104, "id_str": "104", "category": "general", "exam_pool": "general", "question_de": "Eine Frau in Deutschland verliert ihre Arbeit. Was darf nicht der Grund für diese Entlassung sein?", "question_image": null, "image_kind": null, "options": [{"text_de": "Die Frau ist lange krank und arbeitsunfähig.", "correct": false, "text_en": "The woman has been ill for a long time and unable to work."}, {"text_de": "Die Frau kam oft zu spät zur Arbeit.", "correct": false, "text_en": "The woman was often late for work."}, {"text_de": "Die Frau erledigt private Sachen während der Arbeitszeit.", "correct": false, "text_en": "The woman does private things during working hours."}, {"text_de": "Die Frau bekommt ein Kind und ihr Chef weiß das.", "correct": true, "text_en": "The woman is having a baby and her boss knows about it."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-104.png"}, "question_en": "A woman in Germany loses her job. What is NOT allowed to be the reason for this dismissal?", "asking_note": "Negative framing — identify the one reason that is legally prohibited. Pregnancy/maternity is a specially protected status.", "answer_explanation": "Pregnant employees enjoy special protection under the Mutterschutzgesetz, which bans dismissal on the grounds of pregnancy or impending motherhood. This also flows from the prohibition of discrimination based on sex in Art. 3 of the Grundgesetz.", "distractor_notes": ["Long-term inability to work can, in principle, be a lawful ground for dismissal.", "Persistent lateness can be a legitimate performance-related ground for dismissal.", "Handling private matters during working hours can be a legitimate ground for dismissal.", ""]}, {"id": 105, "id_str": "105", "category": "general", "exam_pool": "general", "question_de": "Was ist eine Aufgabe von Wahlhelferinnen/Wahlhelfern in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sie helfen alten Menschen bei der Stimmabgabe in der Wahlkabine.", "correct": false, "text_en": "They help elderly people cast their vote inside the voting booth."}, {"text_de": "Sie schreiben die Wahlbenachrichtigungen vor der Wahl.", "correct": false, "text_en": "They write the voter notifications before the election."}, {"text_de": "Sie geben Zwischenergebnisse an die Medien weiter.", "correct": false, "text_en": "They pass interim results to the media."}, {"text_de": "Sie zählen die Stimmen nach dem Ende der Wahl.", "correct": true, "text_en": "They count the votes after the election closes."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-105.png"}, "question_en": "What is a task of election helpers (Wahlhelfer) in Germany?", "asking_note": "Tests the role of volunteer poll workers. Their job is counting the ballots after polls close; they do not influence how people vote or leak results.", "answer_explanation": "Election helpers volunteer at polling stations, oversee the orderly and lawful conduct of the vote, and publicly count the ballots once polling closes. This public counting safeguards the transparency and integrity of the election.", "distractor_notes": ["No one may accompany a voter into the booth — that would breach the secret ballot.", "Voter notifications are sent out by the municipality/registration office, not by election helpers.", "Leaking interim results is not their task and would undermine the fairness of the vote.", ""]}, {"id": 106, "id_str": "106", "category": "general", "exam_pool": "general", "question_de": "In Deutschland helfen ehrenamtliche Wahlhelferinnen und Wahlhelfer bei den Wahlen. Was ist eine Aufgabe von Wahlhelferinnen/Wahlhelfern?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sie helfen Kindern und alten Menschen beim Wählen.", "correct": false, "text_en": "They help children and elderly people to vote."}, {"text_de": "Sie schreiben Karten und Briefe mit der Angabe des Wahllokals.", "correct": false, "text_en": "They write cards and letters stating the polling station."}, {"text_de": "Sie geben Zwischenergebnisse an Journalisten weiter.", "correct": false, "text_en": "They pass interim results to journalists."}, {"text_de": "Sie zählen die Stimmen nach dem Ende der Wahl.", "correct": true, "text_en": "They count the votes after the election closes."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-106.png"}, "question_en": "In Germany, volunteer election helpers assist with elections. What is a task of election helpers?", "asking_note": "Same underlying fact as the previous question — poll workers count the votes after the close. The near-identical distractors are meant to tempt you.", "answer_explanation": "The core duty of volunteer election helpers is to run the polling station and, once voting ends, to count the ballots publicly. This open counting is a key guarantee of a transparent, verifiable election.", "distractor_notes": ["Helpers do not assist people inside the booth; the vote must be cast without influence.", "Notifications naming the polling station are sent by the municipality, not written by helpers.", "Passing interim results to journalists is not their role and would compromise the vote.", ""]}, {"id": 107, "id_str": "107", "category": "general", "exam_pool": "general", "question_de": "Für wie viele Jahre wird der Bundestag in Deutschland gewählt?", "question_image": null, "image_kind": null, "options": [{"text_de": "2 Jahre", "correct": false, "text_en": "2 years"}, {"text_de": "4 Jahre", "correct": true, "text_en": "4 years"}, {"text_de": "6 Jahre", "correct": false, "text_en": "6 years"}, {"text_de": "8 Jahre", "correct": false, "text_en": "8 years"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-107.png"}, "question_en": "For how many years is the Bundestag elected in Germany?", "asking_note": "Tests the length of the legislative term (Wahlperiode). It is four years.", "answer_explanation": "The Bundestag is elected for a four-year term under Art. 39 of the Grundgesetz. Federal elections therefore normally take place every four years.", "distractor_notes": ["The term is not two years.", "", "The term is not six years.", "The term is not eight years."]}, {"id": 108, "id_str": "108", "category": "general", "exam_pool": "general", "question_de": "Bei einer Bundestagswahl in Deutschland darf jede/jeder wählen, die/der …", "question_image": null, "image_kind": null, "options": [{"text_de": "in der Bundesrepublik Deutschland wohnt und wählen möchte.", "correct": false, "text_en": "lives in the Federal Republic of Germany and wants to vote."}, {"text_de": "Bürgerin/Bürger der Bundesrepublik Deutschland ist und mindestens 18 Jahre alt ist.", "correct": true, "text_en": "is a citizen of the Federal Republic of Germany and is at least 18 years old."}, {"text_de": "seit mindestens 3 Jahren in der Bundesrepublik Deutschland lebt.", "correct": false, "text_en": "has lived in the Federal Republic of Germany for at least 3 years."}, {"text_de": "Bürgerin/Bürger der Bundesrepublik Deutschland ist und mindestens 21 Jahre alt ist.", "correct": false, "text_en": "is a citizen of the Federal Republic of Germany and is at least 21 years old."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": ["ambiguous_answer_match"]}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-108.png"}, "question_en": "In a German federal election (Bundestagswahl), who is allowed to vote? Anyone who ...", "asking_note": "Tests the two requirements together: German citizenship AND being at least 18. Traps offer residence alone or the wrong minimum age.", "answer_explanation": "Voting in Bundestag elections requires German citizenship and a minimum age of 18, as set out in Art. 38 of the Grundgesetz. Living in Germany without citizenship does not confer the right to vote in federal elections.", "distractor_notes": ["Mere residence, without German citizenship, does not grant the right to vote.", "", "Length of residence is irrelevant — citizenship is required, not years lived in the country.", "Correct on citizenship, but the minimum age is 18, not 21."]}, {"id": 109, "id_str": "109", "category": "general", "exam_pool": "general", "question_de": "Wie oft gibt es normalerweise Bundestagswahlen in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "alle drei Jahre", "correct": false, "text_en": "every three years"}, {"text_de": "alle vier Jahre", "correct": true, "text_en": "every four years"}, {"text_de": "alle fünf Jahre", "correct": false, "text_en": "every five years"}, {"text_de": "alle sechs Jahre", "correct": false, "text_en": "every six years"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-109.png"}, "question_en": "How often are federal elections (Bundestagswahlen) normally held in Germany?", "asking_note": "Same fact as the term-length questions — every four years. Watch the neighbouring numbers.", "answer_explanation": "Federal elections take place roughly every four years, matching the Bundestag's four-year legislative term under Art. 39 of the Grundgesetz.", "distractor_notes": ["Elections are not held every three years.", "", "Five years applies to some Land parliaments and the European Parliament, not the Bundestag.", "Elections are not held every six years."]}, {"id": 110, "id_str": "110", "category": "general", "exam_pool": "general", "question_de": "Für wie viele Jahre wird der Bundestag in Deutschland gewählt?", "question_image": null, "image_kind": null, "options": [{"text_de": "2 Jahre", "correct": false, "text_en": "2 years"}, {"text_de": "3 Jahre", "correct": false, "text_en": "3 years"}, {"text_de": "4 Jahre", "correct": true, "text_en": "4 years"}, {"text_de": "5 Jahre", "correct": false, "text_en": "5 years"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-110.png"}, "question_en": "For how many years is the Bundestag elected in Germany?", "asking_note": "Same four-year fact as question 107, but here the answer sits in the third position and the options are 2/3/4/5 years.", "answer_explanation": "The Bundestag's legislative term is four years under Art. 39 of the Grundgesetz, so it is elected for four years at a time.", "distractor_notes": ["The term is not two years.", "The term is not three years.", "", "Five years applies to some state parliaments and the European Parliament, not the Bundestag."]}, {"id": 111, "id_str": "111", "category": "general", "exam_pool": "general", "question_de": "Welche Handlungen mit Bezug auf den Staat Israel sind in Deutschland verboten?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Politik Israels öffentlich kritisieren", "correct": false, "text_en": "publicly criticising Israel's policies"}, {"text_de": "das Aufhängen einer israelischen Flagge auf dem Privatgrundstück", "correct": false, "text_en": "hanging an Israeli flag on private property"}, {"text_de": "eine Diskussion über die Politik Israels", "correct": false, "text_en": "holding a discussion about Israel's policies"}, {"text_de": "der öffentliche Aufruf zur Vernichtung Israels", "correct": true, "text_en": "publicly calling for the destruction of Israel"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-111.png"}, "question_en": "Which actions relating to the State of Israel are prohibited in Germany?", "asking_note": "Distinguishes protected free speech (criticism, debate, flying a flag) from criminal incitement. The prohibited act is publicly calling for Israel's destruction.", "answer_explanation": "Publicly calling for the destruction of a state is criminal incitement (covered by offences such as Volksverhetzung, §130 StGB, and incitement to crimes, §111 StGB). By contrast, criticising or debating a government's policies is protected by freedom of expression under Art. 5 of the Grundgesetz.", "distractor_notes": ["Publicly criticising Israel's policies is lawful, protected free speech.", "Displaying an Israeli flag on one's own property is lawful.", "Discussing Israel's policies is lawful free expression.", ""]}, {"id": 112, "id_str": "112", "category": "general", "exam_pool": "general", "question_de": "Die Wahlen in Deutschland sind …", "question_image": null, "image_kind": null, "options": [{"text_de": "speziell.", "correct": false, "text_en": "special."}, {"text_de": "geheim.", "correct": true, "text_en": "secret."}, {"text_de": "berufsbezogen.", "correct": false, "text_en": "occupation-based."}, {"text_de": "geschlechtsabhängig.", "correct": false, "text_en": "gender-dependent."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-112.png"}, "question_en": "Elections in Germany are ...", "asking_note": "Tests one of the five constitutional electoral principles. The correct term is 'secret'; the other options are invented and undemocratic.", "answer_explanation": "Under Art. 38 of the Grundgesetz, elections must be general, direct, free, equal and secret. 'Secret' means no one may find out how an individual voted.", "distractor_notes": ["'Special' is not an electoral principle.", "", "Elections are not tied to a person's occupation — that would violate equal suffrage.", "Elections do not depend on gender; suffrage is equal for all."]}, {"id": 113, "id_str": "113", "category": "general", "exam_pool": "general", "question_de": "Wahlen in Deutschland gewinnt die Partei, die …", "question_image": null, "image_kind": null, "options": [{"text_de": "die meisten Stimmen bekommt.", "correct": true, "text_en": "gets the most votes."}, {"text_de": "die meisten Männer mehrheitlich gewählt haben.", "correct": false, "text_en": "was chosen by a majority of the most men."}, {"text_de": "die meisten Stimmen bei den Arbeiterinnen/Arbeitern bekommen hat.", "correct": false, "text_en": "got the most votes among workers."}, {"text_de": "die meisten Erststimmen für ihre Kanzlerkandidatin/ihren Kanzlerkandidaten erhalten hat.", "correct": false, "text_en": "received the most first votes (Erststimmen) for its candidate for Chancellor."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-113.png"}, "question_en": "In German elections, the party that wins is the one that ...", "asking_note": "Tests the majority principle and equal suffrage — every vote counts the same, so the most votes wins. Distractors slice the electorate by group or invent a direct Chancellor vote.", "answer_explanation": "The party with the most votes wins, because under equal suffrage (Art. 38 GG) every vote carries the same weight regardless of the voter's sex, occupation or income. There is no separate class of decisive voters.", "distractor_notes": ["", "A single demographic group such as men does not decide the outcome; all votes count equally.", "Workers' votes carry no more weight than anyone else's.", "There is no direct 'first vote' for Chancellor — the Chancellor is elected by the Bundestag, not by voters directly."]}, {"id": 114, "id_str": "114", "category": "general", "exam_pool": "general", "question_de": "An demokratischen Wahlen in Deutschland teilzunehmen ist …", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Pflicht.", "correct": false, "text_en": "a duty."}, {"text_de": "ein Recht.", "correct": true, "text_en": "a right."}, {"text_de": "ein Zwang.", "correct": false, "text_en": "coercion / compulsion."}, {"text_de": "eine Last.", "correct": false, "text_en": "a burden."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-114.png"}, "question_en": "Taking part in democratic elections in Germany is ...", "asking_note": "Tests that voting is a right, not a legal obligation — Germany has no compulsory voting.", "answer_explanation": "Voting is a democratic right, not a legal obligation — Germany does not have compulsory voting (Wahlpflicht). Citizens freely decide whether to take part.", "distractor_notes": ["It is not a legal duty; there is no Wahlpflicht in Germany.", "", "Voting cannot be coerced — free elections forbid any compulsion.", "'Burden' is a value judgement, not the legal character of voting."]}, {"id": 115, "id_str": "115", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet \"aktives Wahlrecht\" in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Man kann gewählt werden.", "correct": false, "text_en": "You can be elected."}, {"text_de": "Man muss wählen gehen.", "correct": false, "text_en": "You must go and vote."}, {"text_de": "Man kann wählen.", "correct": true, "text_en": "You can vote."}, {"text_de": "Man muss zur Auszählung der Stimmen gehen.", "correct": false, "text_en": "You must attend the counting of the votes."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-115.png"}, "question_en": "What does 'aktives Wahlrecht' (active suffrage) mean in Germany?", "asking_note": "Easily confused with 'passives Wahlrecht' (the right to be elected). Active suffrage is the right to cast a vote.", "answer_explanation": "'Aktives Wahlrecht' is the right to cast a vote in an election. It stands in contrast to 'passives Wahlrecht', which is the right to stand as a candidate and be elected.", "distractor_notes": ["Being able to be elected is 'passives Wahlrecht', not active suffrage.", "There is no obligation to vote; active suffrage is a right, not a duty.", "", "Attending the vote count is not part of active suffrage."]}, {"id": 116, "id_str": "116", "category": "general", "exam_pool": "general", "question_de": "Wenn Sie bei einer Bundestagswahl in Deutschland wählen dürfen, heißt das …", "question_image": null, "image_kind": null, "options": [{"text_de": "aktive Wahlkampagne.", "correct": false, "text_en": "active election campaign."}, {"text_de": "aktives Wahlverfahren.", "correct": false, "text_en": "active electoral procedure."}, {"text_de": "aktiver Wahlkampf.", "correct": false, "text_en": "active campaigning."}, {"text_de": "aktives Wahlrecht.", "correct": true, "text_en": "active suffrage (aktives Wahlrecht)."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-116.png"}, "question_en": "If you are allowed to vote in a German federal election, this is called ...", "asking_note": "A vocabulary question: the entitlement to vote is 'aktives Wahlrecht'. The distractors are all campaign- or procedure-related terms.", "answer_explanation": "Being entitled to cast a vote is the 'aktives Wahlrecht' (active right to vote). It describes the legal entitlement to participate as a voter.", "distractor_notes": ["'Wahlkampagne' refers to a campaign, not the right to vote.", "'Wahlverfahren' means the voting procedure, not the entitlement to vote.", "'Wahlkampf' means election campaigning, not the right to vote.", ""]}, {"id": 117, "id_str": "117", "category": "general", "exam_pool": "general", "question_de": "Wie viel Prozent der Zweitstimmen müssen Parteien mindestens bekommen, um in den Deutschen Bundestag gewählt zu werden?", "question_image": null, "image_kind": null, "options": [{"text_de": "3%", "correct": false, "text_en": "3%"}, {"text_de": "4%", "correct": false, "text_en": "4%"}, {"text_de": "5%", "correct": true, "text_en": "5%"}, {"text_de": "6%", "correct": false, "text_en": "6%"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-117.png"}, "question_en": "What minimum percentage of second votes (Zweitstimmen) must parties receive to be elected into the German Bundestag?", "asking_note": "Tests the electoral threshold (Sperrklausel). The neighbouring percentages are the trap; the figure is five percent.", "answer_explanation": "A party must win at least 5% of the second votes (or three direct constituency seats) to enter the Bundestag — the so-called '5%-Hürde'. This threshold keeps very small parties out and helps produce a workable parliament.", "distractor_notes": ["The threshold is not 3%.", "The threshold is not 4%.", "", "The threshold is not 6%."]}, {"id": 118, "id_str": "118", "category": "general", "exam_pool": "general", "question_de": "Wer darf bei den rund 40 jüdischen Makkabi-Sportvereinen Mitglied werden?", "question_image": null, "image_kind": null, "options": [{"text_de": "nur Deutsche", "correct": false, "text_en": "only Germans"}, {"text_de": "nur Israelis", "correct": false, "text_en": "only Israelis"}, {"text_de": "nur religiöse Menschen", "correct": false, "text_en": "only religious people"}, {"text_de": "alle Menschen", "correct": true, "text_en": "everyone / all people"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-118.png"}, "question_en": "Who may become a member of the roughly 40 Jewish Makkabi sports clubs?", "asking_note": "Tests the principle of openness and non-discrimination. The clubs are Jewish in origin but open to everyone — the restrictive options are traps.", "answer_explanation": "The Jewish Makkabi sports clubs are open to everyone, regardless of religion or nationality. This openness reflects Germany's principles of non-discrimination and integration through shared sporting life.", "distractor_notes": ["Membership is not limited to Germans.", "Membership is not limited to Israelis.", "Membership is not limited to religious people.", ""]}, {"id": 119, "id_str": "119", "category": "general", "exam_pool": "general", "question_de": "Wahlen in Deutschland sind frei. Was bedeutet das?", "question_image": null, "image_kind": null, "options": [{"text_de": "Alle verurteilten Straftäterinnen/Straftäter dürfen nicht wählen.", "correct": false, "text_en": "All convicted criminals are not allowed to vote."}, {"text_de": "Wenn ich wählen gehen möchte, muss meine Arbeitgeberin/mein Arbeitgeber mir frei geben.", "correct": false, "text_en": "If I want to vote, my employer must give me time off."}, {"text_de": "Jede Person kann ohne Zwang entscheiden, ob sie wählen möchte und wen sie wählen möchte.", "correct": true, "text_en": "Every person can decide, without any coercion, whether they want to vote and whom they want to vote for."}, {"text_de": "Ich kann frei entscheiden, wo ich wählen gehen möchte.", "correct": false, "text_en": "I can freely decide where I want to go to vote."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-119.png"}, "question_en": "Elections in Germany are free. What does that mean?", "asking_note": "Tests the meaning of a 'free' election — no coercion over whether and for whom you vote. The distractors mix in unrelated rules about criminals, employers and polling location.", "answer_explanation": "A 'free' election (Art. 38 GG) means no one may pressure or coerce a voter over whether to vote or for whom. The decision is entirely the voter's own, made without intimidation or influence.", "distractor_notes": ["This is false and unrelated to what 'free' means; not all convicted people lose the vote.", "Time off from an employer is not what the principle of a free election refers to.", "", "You vote at your assigned polling station, so 'free' does not mean choosing any location."]}, {"id": 120, "id_str": "120", "category": "general", "exam_pool": "general", "question_de": "Das Wahlsystem in Deutschland ist ein …", "question_image": null, "image_kind": null, "options": [{"text_de": "Zensuswahlrecht.", "correct": false, "text_en": "census suffrage (votes weighted by wealth/tax)."}, {"text_de": "Dreiklassenwahlrecht.", "correct": false, "text_en": "three-class franchise."}, {"text_de": "Mehrheits- und Verhältniswahlrecht.", "correct": true, "text_en": "combined majority and proportional representation."}, {"text_de": "allgemeines Männerwahlrecht.", "correct": false, "text_en": "general male-only suffrage."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-120.png"}, "question_en": "The electoral system in Germany is a ...", "asking_note": "Tests that Germany combines a majority element (direct seats) with proportional representation (party lists). The distractors are historical, discriminatory voting systems.", "answer_explanation": "Germany uses a 'personalised proportional representation' (personalisierte Verhältniswahl): the first vote elects direct candidates (a majority element), while the second vote for party lists determines each party's overall share of seats (the proportional element). The Zweitstimme is ultimately decisive for the composition of parliament.", "distractor_notes": ["Zensuswahlrecht tied voting power to wealth or tax paid — an abolished, undemocratic system.", "The Prussian Dreiklassenwahlrecht weighted votes by tax bracket — historical and discriminatory.", "", "Male-only suffrage is historical; suffrage in Germany is universal and equal for all adults."]}, {"id": 121, "id_str": "121", "category": "general", "exam_pool": "general", "question_de": "Eine Partei möchte in den Deutschen Bundestag. Sie muss aber einen Mindestanteil an Wählerstimmen haben. Das heißt …", "question_image": null, "image_kind": null, "options": [{"text_de": "5%-Hürde.", "correct": true, "text_en": "5% hurdle (5%-Hürde)."}, {"text_de": "Zulassungsgrenze.", "correct": false, "text_en": "admission limit."}, {"text_de": "Basiswert.", "correct": false, "text_en": "base value."}, {"text_de": "Richtlinie.", "correct": false, "text_en": "guideline."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-121.png"}, "question_en": "A party wants to enter the German Bundestag, but it must obtain a minimum share of voters' votes. This is called the ...", "asking_note": "A vocabulary question for the electoral threshold. The correct term is the '5%-Hürde'; the other options are made-up terms.", "answer_explanation": "The minimum share of votes (5%) a party needs to win seats in the Bundestag is called the '5%-Hürde' (five-percent threshold, or Sperrklausel). It prevents the parliament from splintering into many tiny parties.", "distractor_notes": ["", "'Zulassungsgrenze' is not the term used for the electoral threshold.", "'Basiswert' is not a real term for the threshold.", "'Richtlinie' (guideline) is not the term for the electoral threshold."]}, {"id": 122, "id_str": "122", "category": "general", "exam_pool": "general", "question_de": "Welchem Grundsatz unterliegen Wahlen in Deutschland? Wahlen in Deutschland sind …", "question_image": null, "image_kind": null, "options": [{"text_de": "frei, gleich, geheim.", "correct": true, "text_en": "free, equal, secret."}, {"text_de": "offen, sicher, frei.", "correct": false, "text_en": "open, safe, free."}, {"text_de": "geschlossen, gleich, sicher.", "correct": false, "text_en": "closed, equal, safe."}, {"text_de": "sicher, offen, freiwillig.", "correct": false, "text_en": "safe, open, voluntary."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-122.png"}, "question_en": "Which principles do elections in Germany follow? Elections in Germany are ...", "asking_note": "Tests the electoral principles from Art. 38 of the Grundgesetz. Only one set of three words is correct; the rest mix in invalid terms.", "answer_explanation": "Art. 38 of the Grundgesetz states that elections are general, direct, free, equal and secret. Of the choices offered, only 'free, equal, secret' names genuine constitutional electoral principles.", "distractor_notes": ["", "'Open' and 'safe/secure' are not electoral principles — a ballot must be secret, not open.", "'Closed' and 'safe' are not electoral principles.", "'Safe', 'open' and 'voluntary' are not the constitutional electoral principles."]}, {"id": 123, "id_str": "123", "category": "general", "exam_pool": "general", "question_de": "Was ist in Deutschland die \"5%-Hürde\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "Abstimmungsregelung im Bundestag für kleine Parteien", "correct": false, "text_en": "A voting rule inside the Bundestag for small parties"}, {"text_de": "Anwesenheitskontrolle im Bundestag für Abstimmungen", "correct": false, "text_en": "An attendance check in the Bundestag before votes"}, {"text_de": "Mindestanteil an Wählerstimmen, um ins Parlament zu kommen", "correct": true, "text_en": "The minimum share of voters' votes needed to enter parliament"}, {"text_de": "Anwesenheitskontrolle im Bundesrat für Abstimmungen", "correct": false, "text_en": "An attendance check in the Bundesrat before votes"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-123.png"}, "question_en": "What is the '5%-Hürde' (five-percent hurdle) in Germany?", "asking_note": "Tests the definition of the threshold: a minimum vote share to enter parliament — not a rule about voting or attendance inside the Bundestag or Bundesrat.", "answer_explanation": "The '5%-Hürde' is the minimum share of second votes (5%) that a party must reach to win seats in the Bundestag. Its purpose is to prevent parliament from fragmenting into many very small parties.", "distractor_notes": ["It is not a voting rule inside parliament for small parties.", "It is not an attendance check for votes in the Bundestag.", "", "It is not an attendance check for votes in the Bundesrat."]}, {"id": 124, "id_str": "124", "category": "general", "exam_pool": "general", "question_de": "Die Bundestagswahl in Deutschland ist die Wahl …", "question_image": null, "image_kind": null, "options": [{"text_de": "der Bundeskanzlerin/des Bundeskanzlers.", "correct": false, "text_en": "the Federal Chancellor."}, {"text_de": "der Parlamente der Länder.", "correct": false, "text_en": "the parliaments of the Länder (states)."}, {"text_de": "des Parlaments für Deutschland.", "correct": true, "text_en": "the parliament for Germany."}, {"text_de": "der Bundespräsidentin/des Bundespräsidenten.", "correct": false, "text_en": "the Federal President."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-124.png"}, "question_en": "The federal election (Bundestagswahl) in Germany is the election of ...", "asking_note": "Tests what the Bundestagswahl actually elects — the federal parliament — not the Chancellor or President, who are chosen indirectly.", "answer_explanation": "The Bundestagswahl elects the Bundestag, Germany's federal parliament. Voters do not directly elect the Chancellor or the President — the Bundestag then elects the Chancellor, and a special Federal Convention (Bundesversammlung) elects the President.", "distractor_notes": ["The Chancellor is not elected directly by voters but by the Bundestag.", "The Länder parliaments are chosen in separate state elections (Landtagswahlen).", "", "The Federal President is elected by the Bundesversammlung, not in the Bundestagswahl."]}, {"id": 125, "id_str": "125", "category": "general", "exam_pool": "general", "question_de": "In einer Demokratie ist eine Funktion von regelmäßigen Wahlen, …", "question_image": null, "image_kind": null, "options": [{"text_de": "die Bürgerinnen und Bürger zu zwingen, ihre Stimme abzugeben.", "correct": false, "text_en": "to force citizens to cast their vote."}, {"text_de": "nach dem Willen der Wählermehrheit den Wechsel der Regierung zu ermöglichen.", "correct": true, "text_en": "to make a change of government possible according to the will of the majority of voters."}, {"text_de": "im Land bestehende Gesetze beizubehalten.", "correct": false, "text_en": "to keep the country's existing laws unchanged."}, {"text_de": "den Armen mehr Macht zu geben.", "correct": false, "text_en": "to give the poor more power."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-125.png"}, "question_en": "In a democracy, one function of regular elections is …", "asking_note": "Tests what elections are actually FOR. The trap answers dress up authoritarian or populist ideas (forcing people to vote, freezing laws, favouring one group) as if they were democratic functions. Pick the one about peaceful, majority-driven change of power.", "answer_explanation": "The core purpose of regular elections in a democracy is to let the electorate confer and withdraw power peacefully: the majority decides who governs, and a losing government must step aside. This is the mechanism that makes government accountable and allows a bloodless change of power, unlike in a dictatorship.", "distractor_notes": ["Voting in Germany is a right, not a legal duty — there is no compulsory voting, so elections do not 'force' anyone to vote.", "", "Elections are precisely the tool for changing course, including changing or repealing laws — not for freezing them.", "Elections give every eligible voter one equal vote regardless of wealth; they do not hand extra power to any single group."]}, {"id": 126, "id_str": "126", "category": "general", "exam_pool": "general", "question_de": "Was bekommen wahlberechtigte Bürgerinnen und Bürger in Deutschland vor einer Wahl?", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Wahlbenachrichtigung von der Gemeinde", "correct": true, "text_en": "a polling-card notification from the municipality"}, {"text_de": "eine Wahlerlaubnis von der Bundespräsidentin/von dem Bundespräsidenten", "correct": false, "text_en": "a voting permit from the Federal President"}, {"text_de": "eine Benachrichtigung von der Bundesversammlung", "correct": false, "text_en": "a notification from the Federal Convention (Bundesversammlung)"}, {"text_de": "eine Benachrichtigung vom Pfarramt", "correct": false, "text_en": "a notification from the parish/church office"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-126.png"}, "question_en": "What do citizens entitled to vote in Germany receive before an election?", "asking_note": "A practical, procedural question: who notifies you and how. Three distractors name plausible-sounding but wrong institutions (President, Federal Convention, church office). The correct sender is your local municipality.", "answer_explanation": "Before an election, eligible voters are sent a Wahlbenachrichtigung (polling notification card) by their Gemeinde (municipality/local authority), which keeps the electoral register. It tells you where and when to vote and how to request a postal ballot. No 'permission' to vote is needed — the right to vote follows automatically from being registered and eligible.", "distractor_notes": ["", "The Federal President has no role in individual voter notification and cannot issue a 'permit' to vote.", "The Bundesversammlung (Federal Convention) meets only to elect the Federal President; it has nothing to do with ordinary voter notifications.", "The Pfarramt (parish office) is a church body with no electoral function in a state that separates church and state administration."]}, {"id": 127, "id_str": "127", "category": "general", "exam_pool": "general", "question_de": "Warum gibt es die 5%-Hürde im Wahlgesetz der Bundesrepublik Deutschland? Es gibt sie, weil …", "question_image": null, "image_kind": null, "options": [{"text_de": "die Programme von vielen kleinen Parteien viele Gemeinsamkeiten haben.", "correct": false, "text_en": "the programmes of many small parties have much in common."}, {"text_de": "die Bürgerinnen und Bürger bei vielen kleinen Parteien die Orientierung verlieren können.", "correct": false, "text_en": "citizens can lose their bearings when there are many small parties."}, {"text_de": "viele kleine Parteien die Regierungsbildung erschweren.", "correct": true, "text_en": "many small parties make it harder to form a government."}, {"text_de": "die kleinen Parteien nicht so viel Geld haben, um die Politikerinnen und Politiker zu bezahlen.", "correct": false, "text_en": "small parties do not have as much money to pay politicians."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-127.png"}, "question_en": "Why does the electoral law of the Federal Republic of Germany contain the 5% threshold (5%-Hürde)? It exists because …", "asking_note": "Tests the RATIONALE behind the five-percent clause, not just its existence. The trap answers give superficial or cynical reasons (parties are all alike, voters get confused, small parties are poor). The real reason is about keeping parliament governable.", "answer_explanation": "A party generally needs at least 5% of the votes to enter the Bundestag. The clause is designed to prevent parliament from splintering into many tiny factions, which would make it very difficult to build stable governing majorities and coalitions. The historical lesson is the Weimar Republic, whose fragmented Reichstag contributed to political instability.", "distractor_notes": ["Whether small parties' programmes overlap is irrelevant to the threshold's purpose, which is about parliamentary workability, not policy content.", "Voter confusion is not the legal justification for the clause; the aim is a functioning, majority-capable parliament.", "", "The threshold has nothing to do with party finances or paying politicians; it is about representation in parliament."]}, {"id": 128, "id_str": "128", "category": "general", "exam_pool": "general", "question_de": "Parlamentsmitglieder, die von den Bürgerinnen und Bürgern gewählt werden, nennt man …", "question_image": null, "image_kind": null, "options": [{"text_de": "Abgeordnete.", "correct": true, "text_en": "deputies / members of parliament (Abgeordnete)."}, {"text_de": "Kanzlerinnen/Kanzler.", "correct": false, "text_en": "chancellors."}, {"text_de": "Botschafterinnen/Botschafter.", "correct": false, "text_en": "ambassadors."}, {"text_de": "Ministerpräsidentinnen/Ministerpräsidenten.", "correct": false, "text_en": "minister-presidents."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-128.png"}, "question_en": "Members of parliament who are elected by the citizens are called …?", "asking_note": "A vocabulary/role question. It contrasts an elected legislator with three other titles that are either appointed, head of government, or executive posts. 'Abgeordnete' is the term for an elected member of parliament.", "answer_explanation": "An Abgeordnete(r) is a directly or list-elected representative who sits in a parliament (the Bundestag at federal level, or a Landtag in a federal state). They are elected by citizens and represent the whole people, bound only by their conscience under Article 38 of the Basic Law.", "distractor_notes": ["", "The Chancellor heads the federal government and is elected by the Bundestag, not directly by citizens.", "Ambassadors are appointed diplomats representing Germany abroad, not elected parliamentarians.", "A Ministerpräsident heads a federal state's government and is chosen by that state's parliament, not the term for an ordinary elected member."]}, {"id": 129, "id_str": "129", "category": "general", "exam_pool": "general", "question_de": "Vom Volk gewählt wird in Deutschland …", "question_image": null, "image_kind": null, "options": [{"text_de": "die Bundeskanzlerin/der Bundeskanzler.", "correct": false, "text_en": "the Federal Chancellor."}, {"text_de": "die Ministerpräsidentin/der Ministerpräsident eines Bundeslandes.", "correct": false, "text_en": "the minister-president of a federal state."}, {"text_de": "der Bundestag.", "correct": true, "text_en": "the Bundestag (federal parliament)."}, {"text_de": "die Bundespräsidentin/der Bundespräsident.", "correct": false, "text_en": "the Federal President."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-129.png"}, "question_en": "In Germany, who/what is elected directly by the people?", "asking_note": "A classic 'who is directly elected' trap. Chancellor, minister-presidents and the Federal President are all chosen indirectly by other bodies. Only the parliament (Bundestag) is elected directly by voters.", "answer_explanation": "Citizens vote directly only for the Bundestag (and, at other levels, for state and local parliaments). The Bundestag in turn elects the Chancellor; each state parliament elects its minister-president; and a special Federal Convention (Bundesversammlung) elects the Federal President. This is Germany's system of representative, indirect democracy for its top offices.", "distractor_notes": ["The Chancellor is elected by the members of the Bundestag, not by the people directly.", "A state's minister-president is elected by that state's parliament (Landtag), not directly by voters.", "", "The Federal President is elected by the Bundesversammlung (Federal Convention), not by direct popular vote."]}, {"id": 130, "id_str": "130", "category": "general", "exam_pool": "general", "question_de": "Welcher Stimmzettel wäre bei einer Bundestagswahl gültig?", "question_image": "assets/img/q130-stem.png", "image_kind": "stem", "options": [{"text_de": "1", "correct": true, "text_en": "Ballot 1"}, {"text_de": "2", "correct": false, "text_en": "Ballot 2"}, {"text_de": "3", "correct": false, "text_en": "Ballot 3"}, {"text_de": "4", "correct": false, "text_en": "Ballot 4"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "numeric", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-130.png"}, "question_en": "Which ballot paper would be valid in a federal (Bundestag) election?", "asking_note": "This is a picture-based question: the stem shows four sample ballot papers and you must judge which is correctly marked. A valid ballot follows the marking rules (typically one clear cross per vote in the intended box); the invalid ones show extra marks, comments, or wrong marking. The answer is a picture choice (ballot 1).", "answer_explanation": "A ballot paper is valid only when the voter's intention is unambiguous and marked according to the rules — normally a single clear cross (or comparable mark) in the designated box, with no additions, conditions, or identifying remarks. Ballot 1 is the one marked correctly; the others are spoiled (e.g. multiple crosses, written comments, or marks outside the boxes), which makes a vote invalid.", "distractor_notes": ["", "Marked in a way that breaches the ballot rules (e.g. ambiguous or extra marks), making it invalid.", "Marked in a way that breaches the ballot rules, making it invalid.", "Marked in a way that breaches the ballot rules, making it invalid."]}, {"id": 131, "id_str": "131", "category": "general", "exam_pool": "general", "question_de": "In Deutschland ist eine Bürgermeisterin/ein Bürgermeister …", "question_image": null, "image_kind": null, "options": [{"text_de": "die Leiterin/der Leiter einer Schule.", "correct": false, "text_en": "the head of a school."}, {"text_de": "die Chefin/der Chef einer Bank.", "correct": false, "text_en": "the boss of a bank."}, {"text_de": "das Oberhaupt einer Gemeinde.", "correct": true, "text_en": "the head of a municipality (Gemeinde)."}, {"text_de": "die/der Vorsitzende einer Partei.", "correct": false, "text_en": "the chair of a party."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-131.png"}, "question_en": "In Germany, a mayor (Bürgermeister/in) is …?", "asking_note": "A role-definition question. The distractors swap the mayor for other 'head of something' figures (school head, bank boss, party chair). A mayor heads a municipality/local community.", "answer_explanation": "A Bürgermeister/in is the head of a Gemeinde (municipality or local community) — the top of local self-government. Depending on the state, mayors are elected directly by residents or by the municipal council, and they lead the local administration.", "distractor_notes": ["The head of a school is a Schulleiter/in, an education post, not a mayor.", "A bank's boss is a private-sector manager, unrelated to municipal government.", "", "A party chair (Parteivorsitzende/r) leads a political party, not a town or municipality."]}, {"id": 132, "id_str": "132", "category": "general", "exam_pool": "general", "question_de": "Viele Menschen in Deutschland arbeiten in ihrer Freizeit ehrenamtlich. Was bedeutet das?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sie arbeiten als Soldatinnen/Soldaten.", "correct": false, "text_en": "They work as soldiers."}, {"text_de": "Sie arbeiten freiwillig und unbezahlt in Vereinen und Verbänden.", "correct": true, "text_en": "They work voluntarily and unpaid in clubs and associations."}, {"text_de": "Sie arbeiten in der Bundesregierung.", "correct": false, "text_en": "They work in the federal government."}, {"text_de": "Sie arbeiten in einem Krankenhaus und verdienen dabei Geld.", "correct": false, "text_en": "They work in a hospital and earn money doing so."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-132.png"}, "question_en": "Many people in Germany do voluntary/honorary work (ehrenamtlich) in their free time. What does that mean?", "asking_note": "Tests the meaning of 'ehrenamtlich'. The key features are FREELY chosen and UNPAID. Watch the last distractor, which sounds like helping in a hospital but explicitly says the person earns money — the opposite of honorary work.", "answer_explanation": "'Ehrenamtlich' means honorary or voluntary work done freely and without pay, typically in Vereine (clubs) and Verbände (associations) — sports clubs, welfare organisations, volunteer fire brigades, and the like. Such civic engagement is widespread in Germany and is considered an important part of community life.", "distractor_notes": ["Soldiers are paid professionals or conscripts; that is a paid state role, not honorary volunteering.", "", "Working in the federal government is paid public employment, not voluntary unpaid work.", "Earning money for hospital work is paid employment — the explicit mention of pay contradicts the meaning of 'ehrenamtlich'."]}, {"id": 133, "id_str": "133", "category": "general", "exam_pool": "general", "question_de": "Was ist bei Bundestags- und Landtagswahlen in Deutschland erlaubt?", "question_image": null, "image_kind": null, "options": [{"text_de": "Der Ehemann wählt für seine Frau mit.", "correct": false, "text_en": "The husband votes on behalf of his wife as well."}, {"text_de": "Man kann durch Briefwahl seine Stimme abgeben.", "correct": true, "text_en": "You can cast your vote by postal ballot (Briefwahl)."}, {"text_de": "Man kann am Wahltag telefonisch seine Stimme abgeben.", "correct": false, "text_en": "You can cast your vote by telephone on election day."}, {"text_de": "Kinder ab dem Alter von 14 Jahren dürfen wählen.", "correct": false, "text_en": "Children from the age of 14 are allowed to vote."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-133.png"}, "question_en": "What is permitted in Bundestag and Landtag elections in Germany?", "asking_note": "Tests knowledge of voting rules. Three distractors describe things that are forbidden (voting on someone else's behalf, voting by phone, letting 14-year-olds vote). The permitted method is postal voting.", "answer_explanation": "Voters who cannot or do not wish to attend a polling station may apply for Briefwahl (postal voting) and send in their ballot by mail. German elections follow the principle that the vote is personal, secret, direct and equal — so voting must be done by the voter themselves; postal voting is the legitimate alternative to in-person voting.", "distractor_notes": ["Each person must cast their own vote; voting is personal — no one may vote in place of a spouse.", "", "There is no telephone voting; the vote must be cast in person at a polling station or by postal ballot.", "The voting age for Bundestag elections is 18 (16 for some state and European/local elections), never 14."]}, {"id": 134, "id_str": "134", "category": "general", "exam_pool": "general", "question_de": "Man will die Buslinie abschaffen, mit der Sie immer zur Arbeit fahren. Was können Sie machen, um die Buslinie zu erhalten?", "question_image": null, "image_kind": null, "options": [{"text_de": "Ich beteilige mich an einer Bürgerinitiative für die Erhaltung der Buslinie oder gründe selber eine Initiative.", "correct": true, "text_en": "I take part in a citizens' initiative to preserve the bus line, or I start such an initiative myself."}, {"text_de": "Ich werde Mitglied in einem Sportverein und trainiere Radfahren.", "correct": false, "text_en": "I join a sports club and train cycling."}, {"text_de": "Ich wende mich an das Finanzamt, weil ich als Steuerzahlerin/Steuerzahler ein Recht auf die Buslinie habe.", "correct": false, "text_en": "I turn to the tax office because, as a taxpayer, I have a right to the bus line."}, {"text_de": "Ich schreibe einen Brief an das Forstamt der Gemeinde.", "correct": false, "text_en": "I write a letter to the municipality's forestry office (Forstamt)."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-134.png"}, "question_en": "The bus line you always take to work is going to be scrapped. What can you do to keep the bus line?", "asking_note": "Tests understanding of legitimate civic participation. Only one option is a real democratic tool for influencing a local decision; the others are irrelevant (join a sports club), based on a false claim of entitlement (tax office), or address the wrong authority (forestry office).", "answer_explanation": "A Bürgerinitiative (citizens' initiative) is a recognised, grassroots form of political participation in which residents organise, gather support and press decision-makers on a specific local issue. Joining or founding one is exactly how citizens can lawfully influence a decision like keeping a bus route — this kind of engagement is a normal part of local democracy.", "distractor_notes": ["", "Joining a sports club to cycle does nothing to influence the transport decision — it is a private leisure choice, not civic action.", "Paying taxes gives no individual legal 'right' to a specific bus line, and the tax office (Finanzamt) has no say over transport routes.", "The Forstamt manages forests, not public transport, so it is the wrong authority to address."]}, {"id": 135, "id_str": "135", "category": "general", "exam_pool": "general", "question_de": "Wen vertreten die Gewerkschaften in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "große Unternehmen", "correct": false, "text_en": "large companies"}, {"text_de": "kleine Unternehmen", "correct": false, "text_en": "small companies"}, {"text_de": "Selbstständige", "correct": false, "text_en": "the self-employed"}, {"text_de": "Arbeitnehmerinnen und Arbeitnehmer", "correct": true, "text_en": "employees (Arbeitnehmerinnen und Arbeitnehmer)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-135.png"}, "question_en": "Whom do trade unions (Gewerkschaften) represent in Germany?", "asking_note": "A straightforward interest-group question. The distractors all name the employer/business side or the self-employed. Unions represent employees (workers/wage-earners).", "answer_explanation": "Gewerkschaften are organisations that represent the interests of Arbeitnehmer (employees/workers). They negotiate collective wage agreements (Tarifverträge) with employers, campaign for better pay and working conditions, and can call strikes. Employers, by contrast, are organised in their own associations (Arbeitgeberverbände).", "distractor_notes": ["Large companies are on the employer side and are represented by employers' associations, not unions.", "Small companies are also employers, whose interests are represented by business/employer associations.", "The self-employed are not employees and are typically represented by professional or trade bodies, not unions.", ""]}, {"id": 136, "id_str": "136", "category": "general", "exam_pool": "general", "question_de": "Sie gehen in Deutschland zum Arbeitsgericht bei …", "question_image": null, "image_kind": null, "options": [{"text_de": "falscher Nebenkostenabrechnung.", "correct": false, "text_en": "an incorrect utility/service-charge statement (Nebenkostenabrechnung)."}, {"text_de": "ungerechtfertigter Kündigung durch Ihre Chefin/Ihren Chef.", "correct": true, "text_en": "an unjustified dismissal by your boss."}, {"text_de": "Problemen mit den Nachbarinnen/Nachbarn.", "correct": false, "text_en": "problems with the neighbours."}, {"text_de": "Schwierigkeiten nach einem Verkehrsunfall.", "correct": false, "text_en": "difficulties after a traffic accident."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-136.png"}, "question_en": "In Germany, you go to the labour court (Arbeitsgericht) in the case of …?", "asking_note": "Tests which disputes belong to the labour court. Three distractors are matters for other courts (rental/civil, neighbour/civil, traffic-accident/civil or criminal). Only the employment dismissal belongs to the labour court.", "answer_explanation": "The Arbeitsgericht (labour court) has jurisdiction over disputes arising from the employment relationship — above all dismissals, wages, and other conflicts between employees and employers. An unfair or unjustified dismissal is the textbook case for this specialised branch of the German court system.", "distractor_notes": ["A disputed utility-cost statement is a tenancy/civil-law matter, handled by the ordinary civil courts (Amtsgericht/Landgericht).", "", "Neighbour disputes are civil-law matters for the ordinary courts, not the labour court.", "A traffic accident is a civil (and possibly criminal) matter, dealt with by the ordinary courts, not the labour court."]}, {"id": 137, "id_str": "137", "category": "general", "exam_pool": "general", "question_de": "Welches Gericht ist in Deutschland bei Konflikten in der Arbeitswelt zuständig?", "question_image": null, "image_kind": null, "options": [{"text_de": "das Familiengericht", "correct": false, "text_en": "the family court"}, {"text_de": "das Strafgericht", "correct": false, "text_en": "the criminal court"}, {"text_de": "das Arbeitsgericht", "correct": true, "text_en": "the labour court (Arbeitsgericht)"}, {"text_de": "das Amtsgericht", "correct": false, "text_en": "the local/district court (Amtsgericht)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-137.png"}, "question_en": "Which court is responsible in Germany for conflicts in the world of work (the workplace)?", "asking_note": "The same topic as the previous question, asked as a court-name recall. Distractors name other branches of the court system (family, criminal, local/district). The workplace court is the labour court.", "answer_explanation": "Germany has separate specialised court branches. The Arbeitsgericht is the one dedicated to employment/labour disputes — conflicts between employees and employers over dismissals, pay and working conditions. This specialisation is a distinctive feature of the German judiciary.", "distractor_notes": ["The Familiengericht (a division of the Amtsgericht) deals with divorce, custody and other family matters, not workplace disputes.", "The Strafgericht handles criminal offences and punishment, not employment conflicts.", "", "The Amtsgericht is the general local court for smaller civil and criminal cases; workplace disputes go to the specialised Arbeitsgericht instead."]}, {"id": 138, "id_str": "138", "category": "general", "exam_pool": "general", "question_de": "Was kann ich in Deutschland machen, wenn mir meine Arbeitgeberin/mein Arbeitgeber zu Unrecht gekündigt hat?", "question_image": null, "image_kind": null, "options": [{"text_de": "weiterarbeiten und freundlich zur Chefin/zum Chef sein", "correct": false, "text_en": "keep working and be friendly to the boss"}, {"text_de": "ein Mahnverfahren gegen die Arbeitgeberin/den Arbeitgeber führen", "correct": false, "text_en": "bring a dunning procedure (Mahnverfahren) against the employer"}, {"text_de": "Kündigungsschutzklage erheben", "correct": true, "text_en": "file an action against unfair dismissal (Kündigungsschutzklage)"}, {"text_de": "die Arbeitgeberin/den Arbeitgeber bei der Polizei anzeigen", "correct": false, "text_en": "report the employer to the police"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-138.png"}, "question_en": "What can I do in Germany if my employer has dismissed me unlawfully (without justification)?", "asking_note": "Tests the correct legal remedy for wrongful dismissal. The distractors are either passive (keep working nicely), the wrong legal tool (a Mahnverfahren is for unpaid debts), or a misuse of the police. The right answer is the specific dismissal-protection lawsuit.", "answer_explanation": "The proper remedy is a Kündigungsschutzklage — an unfair-dismissal claim filed at the labour court, normally within three weeks of receiving the notice. It asks the court to rule that the dismissal is invalid. German dismissal-protection law (Kündigungsschutzgesetz) gives many employees protection against dismissals that lack a valid social, personal or conduct-related reason.", "distractor_notes": ["Doing nothing forfeits your rights; you must act (and within a short deadline) to challenge the dismissal.", "A Mahnverfahren is a simplified procedure to collect an undisputed monetary debt, not a way to contest a dismissal.", "", "A dismissal is not a criminal offence, so the police are not the right avenue; the labour court is."]}, {"id": 139, "id_str": "139", "category": "general", "exam_pool": "general", "question_de": "Wann kommt es in Deutschland zu einem Prozess vor Gericht? Wenn jemand …", "question_image": null, "image_kind": null, "options": [{"text_de": "zu einer anderen Religion übertritt.", "correct": false, "text_en": "converts to another religion."}, {"text_de": "eine Straftat begangen hat und angeklagt wird.", "correct": true, "text_en": "has committed a criminal offence and is charged (indicted)."}, {"text_de": "eine andere Meinung als die der Regierung vertritt.", "correct": false, "text_en": "holds a different opinion from the government."}, {"text_de": "sein Auto falsch geparkt hat und es abgeschleppt wird.", "correct": false, "text_en": "has parked the car wrongly and it gets towed."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-139.png"}, "question_en": "When does a court trial take place in Germany? When someone …?", "asking_note": "Tests what actually leads to a criminal trial. Three distractors describe things that are legal and protected (changing religion, disagreeing with the government) or a minor administrative matter (a towed car). A trial follows being charged with a crime.", "answer_explanation": "A criminal court trial (Prozess) takes place when the public prosecutor charges someone with a Straftat (criminal offence) and the court opens proceedings. The accused is presumed innocent until proven guilty and is tried before an independent court — a basic guarantee of the rule of law (Rechtsstaat).", "distractor_notes": ["Freedom of religion is a fundamental right (Article 4 of the Basic Law); changing religion is legal and never a matter for a court.", "", "Freedom of opinion is protected (Article 5); disagreeing with the government is legal and cannot lead to a criminal trial.", "A wrongly parked, towed car is a minor administrative/traffic matter handled by fines, not a court trial."]}, {"id": 140, "id_str": "140", "category": "general", "exam_pool": "general", "question_de": "Was macht eine Schöffin/ein Schöffe in Deutschland? Sie/Er …", "question_image": null, "image_kind": null, "options": [{"text_de": "entscheidet mit Richterinnen/Richtern über Schuld und Strafe.", "correct": true, "text_en": "decides, together with professional judges, on guilt and punishment."}, {"text_de": "gibt Bürgerinnen/Bürgern rechtlichen Rat.", "correct": false, "text_en": "gives citizens legal advice."}, {"text_de": "stellt Urkunden aus.", "correct": false, "text_en": "issues official documents/deeds."}, {"text_de": "verteidigt die Angeklagte/den Angeklagten.", "correct": false, "text_en": "defends the accused."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-140.png"}, "question_en": "What does a lay judge (Schöffe/Schöffin) do in Germany? He/She …?", "asking_note": "Tests the role of the lay judge. Distractors confuse the Schöffe with a lawyer (gives legal advice / defends the accused) or a notary (issues documents). The Schöffe sits alongside professional judges and helps decide guilt and sentence.", "answer_explanation": "A Schöffe is a lay (honorary) judge — an ordinary citizen who sits on the bench in criminal cases and, together with the professional judge(s), decides on the defendant's guilt and the sentence. Their vote carries the same weight as a professional judge's, bringing citizens' participation directly into the administration of justice.", "distractor_notes": ["", "Giving legal advice is the job of a lawyer (Rechtsanwalt), not a lay judge.", "Issuing deeds and official documents is the role of a notary (Notar) or public authority, not a Schöffe.", "Defending the accused is the task of the defence lawyer (Verteidiger), whereas the Schöffe is a neutral decision-maker."]}, {"id": 141, "id_str": "141", "category": "general", "exam_pool": "general", "question_de": "Wer berät in Deutschland Personen bei Rechtsfragen und vertritt sie vor Gericht?", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Rechtsanwältin/ein Rechtsanwalt", "correct": true, "text_en": "a lawyer (Rechtsanwalt/Rechtsanwältin)"}, {"text_de": "eine Richterin/ein Richter", "correct": false, "text_en": "a judge (Richter/in)"}, {"text_de": "eine Schöffin/ein Schöffe", "correct": false, "text_en": "a lay judge (Schöffe/Schöffin)"}, {"text_de": "eine Staatsanwältin/ein Staatsanwalt", "correct": false, "text_en": "a public prosecutor (Staatsanwalt/Staatsanwältin)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-141.png"}, "question_en": "Who, in Germany, advises people on legal questions and represents them in court?", "asking_note": "Tests the distinct courtroom roles. All four options are legal actors, so you must know who advises and represents a client — versus who judges (Richter), decides as a layperson (Schöffe), or prosecutes (Staatsanwalt). The answer is the lawyer.", "answer_explanation": "A Rechtsanwalt (lawyer/attorney) advises clients on legal matters and represents their interests in and out of court. Lawyers are an independent part of the justice system whose job is to act for their client — distinct from the judge who decides the case and the prosecutor who represents the state.", "distractor_notes": ["", "A judge decides the case impartially; a judge does not advise or represent one party.", "A lay judge helps decide guilt and sentence on the bench, but does not advise or represent individuals.", "A public prosecutor represents the state and brings charges; they do not act for or advise the defendant."]}, {"id": 142, "id_str": "142", "category": "general", "exam_pool": "general", "question_de": "Was ist die Hauptaufgabe einer Richterin/eines Richters in Deutschland? Eine Richterin/ein Richter …", "question_image": null, "image_kind": null, "options": [{"text_de": "vertritt Bürgerinnen und Bürger vor einem Gericht.", "correct": false, "text_en": "represents citizens before a court."}, {"text_de": "arbeitet an einem Gericht und spricht Urteile.", "correct": true, "text_en": "works at a court and pronounces judgments (Urteile)."}, {"text_de": "ändert Gesetze.", "correct": false, "text_en": "changes laws."}, {"text_de": "betreut Jugendliche vor Gericht.", "correct": false, "text_en": "looks after young people in court."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-142.png"}, "question_en": "What is the main task of a judge (Richter/in) in Germany? A judge …?", "asking_note": "Tests the judge's core function against confusable roles. Distractors describe a lawyer (represents citizens), the legislature (changes laws), and a youth-court social worker. A judge works at a court and delivers judgments.", "answer_explanation": "A judge works at a court and hands down judgments (Urteile) — deciding cases by applying the law to the facts. Judges are independent and bound only by law and justice (Article 97 of the Basic Law), which is a cornerstone of the separation of powers and the rule of law.", "distractor_notes": ["Representing citizens in court is the lawyer's role, not the judge's.", "", "Changing or making laws is the task of the legislature (parliament), not of judges, who apply the law.", "Caring for/supervising juveniles is a role for youth-court assistance (Jugendgerichtshilfe) or social workers, not the judge."]}, {"id": 143, "id_str": "143", "category": "general", "exam_pool": "general", "question_de": "Eine Richterin/ein Richter in Deutschland gehört zur …", "question_image": null, "image_kind": null, "options": [{"text_de": "Judikative.", "correct": true, "text_en": "judiciary (Judikative)."}, {"text_de": "Exekutive.", "correct": false, "text_en": "executive (Exekutive)."}, {"text_de": "Operative.", "correct": false, "text_en": "'operative' branch (Operative)."}, {"text_de": "Legislative.", "correct": false, "text_en": "legislature (Legislative)."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-143.png"}, "question_en": "In Germany, a judge (Richter/in) belongs to the …?", "asking_note": "Tests the separation of powers using Latin-derived branch names. Note the fake option 'Operative', which is not a branch of state at all. Judges belong to the Judikative (judiciary).", "answer_explanation": "Under the separation of powers (Gewaltenteilung), state authority is divided into the legislature (Legislative), the executive (Exekutive) and the judiciary (Judikative). Judges belong to the Judikative — the branch that administers justice, kept independent from the law-making and governing branches.", "distractor_notes": ["", "The Exekutive (government and administration) enforces and carries out the law; judges are not part of it.", "'Operative' is not one of the three state powers — it is a made-up distractor.", "The Legislative (parliament) makes the laws; judges apply them, so they are not part of the legislature."]}, {"id": 144, "id_str": "144", "category": "general", "exam_pool": "general", "question_de": "Eine Richterin/ein Richter gehört in Deutschland zur …", "question_image": null, "image_kind": null, "options": [{"text_de": "vollziehenden Gewalt.", "correct": false, "text_en": "executive power (vollziehende Gewalt)."}, {"text_de": "rechtsprechenden Gewalt.", "correct": true, "text_en": "judicial power (rechtsprechende Gewalt)."}, {"text_de": "planenden Gewalt.", "correct": false, "text_en": "'planning power' (planende Gewalt)."}, {"text_de": "gesetzgebenden Gewalt.", "correct": false, "text_en": "legislative power (gesetzgebende Gewalt)."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-144.png"}, "question_en": "In Germany, a judge (Richter/in) belongs to the …?", "asking_note": "The same separation-of-powers point as the previous question, but using the German descriptive names for the branches instead of the Latin ones. 'Rechtsprechende Gewalt' (the power that administers justice) is the judiciary. Watch out for 'planende Gewalt', which is invented.", "answer_explanation": "'Rechtsprechende Gewalt' is the German term for the judiciary — the power that speaks/administers the law by deciding cases. It is the same branch as the Judikative, one of the three separated powers alongside the vollziehende (executive) and gesetzgebende (legislative) powers.", "distractor_notes": ["The vollziehende Gewalt (executive) governs and enforces the law; it is not the branch judges belong to.", "", "'Planende Gewalt' (planning power) is not a real branch of state — it is a made-up distractor.", "The gesetzgebende Gewalt (legislature) makes laws; judges apply them, so this is wrong."]}, {"id": 145, "id_str": "145", "category": "general", "exam_pool": "general", "question_de": "In Deutschland wird die Staatsgewalt geteilt. Für welche Staatsgewalt arbeitet eine Richterin/ein Richter? Für die …", "question_image": null, "image_kind": null, "options": [{"text_de": "Judikative", "correct": true, "text_en": "judiciary (Judikative)"}, {"text_de": "Exekutive", "correct": false, "text_en": "executive (Exekutive)"}, {"text_de": "Presse", "correct": false, "text_en": "press (Presse)"}, {"text_de": "Legislative", "correct": false, "text_en": "legislature (Legislative)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-145.png"}, "question_en": "In Germany, state power is divided (separated). For which branch of state power does a judge work? For the …?", "asking_note": "Yet another phrasing of the separation-of-powers point. This time the odd distractor is 'Presse' (the press) — sometimes loosely called the 'fourth estate', but NOT one of the three official state powers. Judges work for the Judikative.", "answer_explanation": "State power (Staatsgewalt) is split into three branches: the legislature makes law, the executive governs and enforces, and the judiciary (Judikative) administers justice. A judge works for the Judikative, deciding legal disputes independently.", "distractor_notes": ["", "The Exekutive is the governing/enforcing branch (government, administration, police); judges are not part of it.", "The press is often called the 'fourth estate' but is not one of the three constitutional state powers; it is a private/free institution, not where judges work.", "The Legislative makes the laws; judges apply them, so this is wrong."]}, {"id": 146, "id_str": "146", "category": "general", "exam_pool": "general", "question_de": "Wie nennt man in Deutschland ein Verfahren vor einem Gericht?", "question_image": null, "image_kind": null, "options": [{"text_de": "Programm", "correct": false, "text_en": "programme (Programm)"}, {"text_de": "Prozedur", "correct": false, "text_en": "procedure (Prozedur)"}, {"text_de": "Protokoll", "correct": false, "text_en": "protocol/record (Protokoll)"}, {"text_de": "Prozess", "correct": true, "text_en": "trial (Prozess)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-146.png"}, "question_en": "What is a proceeding before a court called in Germany?", "asking_note": "A vocabulary question with three near-homophones (Programm, Prozedur, Protokoll) chosen to confuse. The word for a court proceeding is 'Prozess' (trial/process).", "answer_explanation": "A court proceeding in Germany is called a Prozess (a trial or legal proceedings). The court hears the case and reaches a judgment; conducting a Prozess before an independent court is central to the rule of law.", "distractor_notes": ["A 'Programm' is a plan or schedule of activities, not a court proceeding.", "'Prozedur' means a procedure or routine in general and is not the German legal term for a court case.", "A 'Protokoll' is the written record/minutes of proceedings, not the proceeding itself.", ""]}, {"id": 147, "id_str": "147", "category": "general", "exam_pool": "general", "question_de": "Was ist die Arbeit einer Richterin/eines Richters in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Deutschland regieren", "correct": false, "text_en": "to govern Germany"}, {"text_de": "Recht sprechen", "correct": true, "text_en": "to administer justice (Recht sprechen)"}, {"text_de": "Pläne erstellen", "correct": false, "text_en": "to draw up plans"}, {"text_de": "Gesetze erlassen", "correct": false, "text_en": "to enact laws"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-147.png"}, "question_en": "What is the work of a judge (Richter/in) in Germany?", "asking_note": "A compact version of the judge's-role question. Distractors assign the judge the tasks of the government (govern), a planner (make plans), and the legislature (enact laws). The judge's work is 'Recht sprechen' — to administer justice.", "answer_explanation": "A judge's work is 'Recht sprechen' — to administer/pronounce justice by deciding cases according to the law. Judges are independent and subject only to the law, which keeps the judiciary separate from the branches that govern and legislate.", "distractor_notes": ["Governing the country is the task of the government (executive), not the judiciary.", "", "Drawing up plans is not a judicial function; judges decide legal disputes.", "Enacting laws is the job of the legislature (parliament); judges apply laws, they do not make them."]}, {"id": 148, "id_str": "148", "category": "general", "exam_pool": "general", "question_de": "Was ist eine Aufgabe der Polizei in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "das Land zu verteidigen", "correct": false, "text_en": "to defend the country"}, {"text_de": "die Bürgerinnen und Bürger abzuhören", "correct": false, "text_en": "to wiretap/eavesdrop on citizens"}, {"text_de": "die Gesetze zu beschließen", "correct": false, "text_en": "to pass laws"}, {"text_de": "die Einhaltung von Gesetzen zu überwachen", "correct": true, "text_en": "to monitor compliance with the laws"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-148.png"}, "question_en": "What is one task of the police in Germany?", "asking_note": "Tests what the police legitimately do. Distractors assign the police the military's job (defend the country), an unconstitutional activity (spying on citizens), and the legislature's job (passing laws). The police enforce/monitor compliance with the law.", "answer_explanation": "A core task of the police is to uphold public safety and order and to monitor and enforce compliance with the law — preventing and investigating offences and protecting citizens. The police act within the law and under judicial oversight, which distinguishes a Rechtsstaat from a police state.", "distractor_notes": ["Defending the country against external threats is the job of the armed forces (Bundeswehr), not the police.", "Blanket eavesdropping on citizens would violate basic rights; the police may not simply spy on the population.", "Passing laws is the role of parliament (the legislature), not the police.", ""]}, {"id": 149, "id_str": "149", "category": "general", "exam_pool": "general", "question_de": "Was ist ein Beispiel für antisemitisches Verhalten?", "question_image": null, "image_kind": null, "options": [{"text_de": "ein jüdisches Fest besuchen", "correct": false, "text_en": "attending a Jewish festival"}, {"text_de": "die israelische Regierung kritisieren", "correct": false, "text_en": "criticising the Israeli government"}, {"text_de": "den Holocaust leugnen", "correct": true, "text_en": "denying the Holocaust"}, {"text_de": "gegen Juden Fußball spielen.", "correct": false, "text_en": "playing football against Jews"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-149.png"}, "question_en": "What is an example of antisemitic behaviour?", "asking_note": "Tests the boundary between protected free expression and antisemitism. Attending a Jewish festival is respectful; criticising the Israeli government is legitimate political speech; the football option is nonsensical filler. Denying the Holocaust is antisemitic — and a crime in Germany.", "answer_explanation": "Denying the Holocaust — the systematic murder of about six million Jews by the Nazi regime — is a clear form of antisemitism and is a criminal offence in Germany (incitement to hatred / Volksverhetzung, §130 of the Criminal Code). Germany's confrontation with its Nazi past makes rejecting antisemitism a central civic value.", "distractor_notes": ["Attending a Jewish festival is a normal, respectful act — the opposite of antisemitism.", "Criticising the policies of the Israeli government is legitimate political opinion and is not, in itself, antisemitic.", "", "Simply playing football against Jewish people is an ordinary sporting activity with no antisemitic content; the option is a nonsensical distractor."]}, {"id": 150, "id_str": "150", "category": "general", "exam_pool": "general", "question_de": "Eine Gerichtsschöffin/ein Gerichtsschöffe in Deutschland ist …", "question_image": null, "image_kind": null, "options": [{"text_de": "die Stellvertreterin/der Stellvertreter des Stadtoberhaupts.", "correct": false, "text_en": "the deputy of the town's head (mayor)."}, {"text_de": "eine ehrenamtliche Richterin/ein ehrenamtlicher Richter.", "correct": true, "text_en": "an honorary (volunteer) judge."}, {"text_de": "ein Mitglied eines Gemeinderats.", "correct": false, "text_en": "a member of a municipal council."}, {"text_de": "eine Person, die Jura studiert hat.", "correct": false, "text_en": "a person who has studied law."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-150.png"}, "question_en": "A court lay judge (Gerichtsschöffe/-schöffin) in Germany is …?", "asking_note": "Tests the definition of a Schöffe. The key point is 'ehrenamtlich' (honorary/volunteer) and that they need NO legal training. Distractors confuse them with a deputy mayor, a council member, or someone who studied law.", "answer_explanation": "A Schöffe is an ehrenamtliche(r) Richter/in — a lay (honorary) judge. Ordinary citizens are appointed for a fixed term to sit alongside professional judges in criminal cases and help decide on guilt and sentence. They are expressly not required to have any legal training, which is the point: it brings the community's judgement into the courtroom.", "distractor_notes": ["A deputy mayor is a local-government post, unrelated to serving as a lay judge.", "", "A member of a municipal council is a local political representative, not a lay judge.", "Schöffen specifically do not need to have studied law — legal expertise is provided by the professional judge."]}, {"id": 151, "id_str": "151", "category": "general", "exam_pool": "general", "question_de": "Wer baute die Mauer in Berlin?", "question_image": null, "image_kind": null, "options": [{"text_de": "Großbritannien", "correct": false, "text_en": "Great Britain"}, {"text_de": "die DDR", "correct": true, "text_en": "the GDR (East Germany)"}, {"text_de": "die Bundesrepublik Deutschland", "correct": false, "text_en": "the Federal Republic of Germany (West Germany)"}, {"text_de": "die USA", "correct": false, "text_en": "the USA"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-151.png"}, "question_en": "Who built the Wall in Berlin?", "asking_note": "A history/date-of-division question. The Allied powers (Britain, USA) and the West German Federal Republic are distractors. The Berlin Wall was built by the GDR (East Germany).", "answer_explanation": "The Berlin Wall was built starting on 13 August 1961 by the GDR (Deutsche Demokratische Republik / East Germany) to stop the mass flight of its citizens to the West. It became the most visible symbol of the division of Germany and of the Cold War until it fell on 9 November 1989.", "distractor_notes": ["Great Britain was a Western occupying power in West Berlin; it did not build the Wall — the Wall was built against the West.", "", "The Federal Republic (West Germany) was on the western side and opposed the Wall; it did not build it.", "The USA was a Western occupying power protecting West Berlin, not the builder of the Wall."]}, {"id": 152, "id_str": "152", "category": "general", "exam_pool": "general", "question_de": "Wann waren die Nationalsozialisten mit Adolf Hitler in Deutschland an der Macht?", "question_image": null, "image_kind": null, "options": [{"text_de": "1918 bis 1923", "correct": false, "text_en": "1918 to 1923"}, {"text_de": "1932 bis 1950", "correct": false, "text_en": "1932 to 1950"}, {"text_de": "1933 bis 1945", "correct": true, "text_en": "1933 to 1945"}, {"text_de": "1945 bis 1989", "correct": false, "text_en": "1945 to 1989"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-152.png"}, "question_en": "When were the National Socialists, under Adolf Hitler, in power in Germany?", "asking_note": "A key date-range question. The distractors bracket other eras (post-WWI unrest; a stretched date; the whole postwar division period). The Nazi dictatorship lasted 1933 to 1945.", "answer_explanation": "The National Socialists were in power from 1933, when Hitler was appointed Chancellor (30 January 1933), until 1945, when Nazi Germany was defeated at the end of the Second World War in Europe. This twelve-year dictatorship carried out the Holocaust and started a world war — a period at the heart of Germany's historical responsibility.", "distractor_notes": ["1918–1923 covers the turbulent early years of the Weimar Republic after WWI, before the Nazis held power.", "1932–1950 is inaccurate at both ends: Hitler took power in 1933, and Nazi rule ended in 1945.", "", "1945–1989 is the era of a divided Germany (postwar occupation to the fall of the Wall), long after the Nazi regime had ended."]}, {"id": 153, "id_str": "153", "category": "general", "exam_pool": "general", "question_de": "Was war am 8. Mai 1945?", "question_image": null, "image_kind": null, "options": [{"text_de": "Tod Adolf Hitlers", "correct": false, "text_en": "the death of Adolf Hitler"}, {"text_de": "Beginn des Berliner Mauerbaus", "correct": false, "text_en": "the beginning of the building of the Berlin Wall"}, {"text_de": "Wahl von Konrad Adenauer zum Bundeskanzler", "correct": false, "text_en": "the election of Konrad Adenauer as Federal Chancellor"}, {"text_de": "Ende des Zweiten Weltkriegs in Europa", "correct": true, "text_en": "the end of the Second World War in Europe"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-153.png"}, "question_en": "What happened on 8 May 1945?", "asking_note": "Tests recognition of a specific historic date. The distractors are all real events but from other dates (Hitler's death 30 Apr 1945; Wall 1961; Adenauer elected 1949). 8 May 1945 is the end of WWII in Europe.", "answer_explanation": "On 8 May 1945 the war in Europe ended with the unconditional surrender of Nazi Germany. The date is remembered as the day of liberation from National Socialism and the end of the Second World War in Europe (VE Day).", "distractor_notes": ["Adolf Hitler died by suicide on 30 April 1945, not on 8 May.", "Construction of the Berlin Wall began on 13 August 1961, sixteen years later.", "Konrad Adenauer was first elected Federal Chancellor in 1949, when the Federal Republic was founded.", ""]}, {"id": 154, "id_str": "154", "category": "general", "exam_pool": "general", "question_de": "Wann war der Zweite Weltkrieg zu Ende?", "question_image": null, "image_kind": null, "options": [{"text_de": "1933", "correct": false, "text_en": "1933"}, {"text_de": "1945", "correct": true, "text_en": "1945"}, {"text_de": "1949", "correct": false, "text_en": "1949"}, {"text_de": "1961", "correct": false, "text_en": "1961"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-154.png"}, "question_en": "When did the Second World War end?", "asking_note": "A single-year recall question. The distractors mark other landmark years (1933 Nazi takeover; 1949 founding of the two German states; 1961 the Berlin Wall). The war ended in 1945.", "answer_explanation": "The Second World War ended in 1945 — in Europe with Germany's unconditional surrender on 8 May 1945, and globally later that year. It brought the Nazi dictatorship to an end and led to the occupation and later division of Germany.", "distractor_notes": ["1933 is when the Nazis came to power, the start of the dictatorship, not the end of the war.", "", "1949 is the year the Federal Republic (West) and the GDR (East) were founded, after the war had already ended.", "1961 is the year the Berlin Wall was built, well after the war."]}, {"id": 155, "id_str": "155", "category": "general", "exam_pool": "general", "question_de": "Wann waren die Nationalsozialisten in Deutschland an der Macht?", "question_image": null, "image_kind": null, "options": [{"text_de": "1888 bis 1918", "correct": false, "text_en": "1888 to 1918"}, {"text_de": "1921 bis 1934", "correct": false, "text_en": "1921 to 1934"}, {"text_de": "1933 bis 1945", "correct": true, "text_en": "1933 to 1945"}, {"text_de": "1949 bis 1963", "correct": false, "text_en": "1949 to 1963"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-155.png"}, "question_en": "When were the National Socialists in power in Germany?", "asking_note": "The same key date range as question 152, with different wrong brackets. The distractors point to the Kaiserreich era, the 1920s, and the early Federal Republic. The Nazi regime lasted 1933 to 1945.", "answer_explanation": "The National Socialist regime lasted from 1933, when Hitler was appointed Chancellor, to 1945, when Nazi Germany was defeated at the end of the Second World War. These twelve years of dictatorship — with the Holocaust and a world war — are central to how Germany understands its historical responsibility today.", "distractor_notes": ["1888–1918 is roughly the reign of Kaiser Wilhelm II in the German Empire, decades before the Nazis.", "1921–1934 misplaces the regime: the Nazis took power only in 1933 and ruled until 1945, not from 1921.", "", "1949–1963 is the early Federal Republic (the Adenauer era), after the Nazi regime had ended."]}, {"id": 156, "id_str": "156", "category": "general", "exam_pool": "general", "question_de": "In welchem Jahr wurde Hitler Reichskanzler?", "question_image": null, "image_kind": null, "options": [{"text_de": "1923", "correct": false, "text_en": "1923"}, {"text_de": "1927", "correct": false, "text_en": "1927"}, {"text_de": "1933", "correct": true, "text_en": "1933"}, {"text_de": "1936", "correct": false, "text_en": "1936"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-156.png"}, "question_en": "In what year did Hitler become Reich Chancellor (Reichskanzler)?", "asking_note": "A pure date-recall question. The trap is confusing this with other Nazi-era dates: 1923 (Hitler's failed Munich putsch) and 1936 (Berlin Olympics). Anchor on 1933 as the year the Nazis took power.", "answer_explanation": "On 30 January 1933, Reich President Paul von Hindenburg appointed Adolf Hitler as Reich Chancellor. This is the pivotal 'Machtergreifung' (seizure of power) that let the Nazis dismantle the Weimar democracy within months. 1933 is one of the most-tested dates in the whole exam.", "distractor_notes": ["1923 is the year of Hitler's failed Beer Hall Putsch (Hitlerputsch) in Munich, which landed him in prison, not in power.", "1927 has no significant Nazi milestone; it is a filler distractor.", "", "1936 is the year of the Berlin Summer Olympics, which the regime used for propaganda; it is not when Hitler took office."]}, {"id": 157, "id_str": "157", "category": "general", "exam_pool": "general", "question_de": "Die Nationalsozialisten mit Adolf Hitler errichteten 1933 in Deutschland …", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Diktatur.", "correct": true, "text_en": "dictatorship."}, {"text_de": "einen demokratischen Staat.", "correct": false, "text_en": "democratic state."}, {"text_de": "eine Monarchie.", "correct": false, "text_en": "monarchy."}, {"text_de": "ein Fürstentum.", "correct": false, "text_en": "principality."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-157.png"}, "question_en": "In 1933 the National Socialists under Adolf Hitler established in Germany a …", "asking_note": "Tests that you know the Nazi regime was a dictatorship, not any form of legitimate or shared government. All three wrong answers name systems that respect some rule or power-sharing.", "answer_explanation": "After 1933 the Nazis abolished free elections, banned other parties, suppressed the press and concentrated all power in Hitler as 'Führer'. That is the definition of a dictatorship: rule by one party/leader without checks, elections or civil liberties.", "distractor_notes": ["", "A democratic state is the opposite of what the Nazis built; they destroyed the Weimar democracy.", "A monarchy is rule by a king or emperor; Germany's monarchy ended in 1918 with the abdication of the Kaiser.", "A principality (Fürstentum) is a small state ruled by a prince; irrelevant to 1930s Germany."]}, {"id": 158, "id_str": "158", "category": "general", "exam_pool": "general", "question_de": "Das \"Dritte Reich\" war eine …", "question_image": null, "image_kind": null, "options": [{"text_de": "Diktatur.", "correct": true, "text_en": "dictatorship."}, {"text_de": "Demokratie.", "correct": false, "text_en": "democracy."}, {"text_de": "Monarchie.", "correct": false, "text_en": "monarchy."}, {"text_de": "Räterepublik.", "correct": false, "text_en": "council republic (Räterepublik)."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-158.png"}, "question_en": "The 'Third Reich' was a …", "asking_note": "Nearly identical to the previous question, just phrased with the term 'Drittes Reich' (the Nazis' name for their state). Watch the fourth option 'Räterepublik' (council republic), a Soviet-style workers' council system, which is a new distractor here.", "answer_explanation": "'Third Reich' (1933-1945) was the Nazi regime's self-designation. It was a totalitarian dictatorship: one party, no free elections, a state-controlled press and terror against opponents and minorities.", "distractor_notes": ["", "A democracy rests on free elections and civil rights, which the Nazi state eliminated.", "A monarchy is hereditary rule by a king/emperor; Germany had none after 1918.", "A Räterepublik is a socialist system governed by workers' and soldiers' councils (as briefly attempted in Munich in 1919); not what the Nazis created."]}, {"id": 159, "id_str": "159", "category": "general", "exam_pool": "general", "question_de": "Was gab es in Deutschland nicht während der Zeit des Nationalsozialismus?", "question_image": null, "image_kind": null, "options": [{"text_de": "freie Wahlen", "correct": true, "text_en": "free elections"}, {"text_de": "Pressezensur", "correct": false, "text_en": "press censorship"}, {"text_de": "willkürliche Verhaftungen", "correct": false, "text_en": "arbitrary arrests"}, {"text_de": "Verfolgung von Juden", "correct": false, "text_en": "persecution of Jews"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-159.png"}, "question_en": "Which of the following did NOT exist in Germany during the era of National Socialism?", "asking_note": "NEGATIVE framing: you must pick the thing that was absent under the Nazis, not something they did. Three options describe real features of the regime; the correct answer is the freedom they abolished.", "answer_explanation": "Free elections did NOT exist under the Nazi dictatorship. The regime banned rival parties in 1933 and held only sham single-list votes. Everything else listed was a real, defining feature of the era.", "distractor_notes": ["", "Press censorship was pervasive; the regime controlled all newspapers and media through propaganda ministry (Goebbels).", "Arbitrary arrests of opponents were routine, especially into concentration camps, without trial or legal recourse.", "The persecution of Jews was central Nazi policy, escalating from exclusion to the Holocaust."]}, {"id": 160, "id_str": "160", "category": "general", "exam_pool": "general", "question_de": "Welcher Krieg dauerte von 1939 bis 1945?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Erste Weltkrieg", "correct": false, "text_en": "the First World War"}, {"text_de": "der Zweite Weltkrieg", "correct": true, "text_en": "the Second World War"}, {"text_de": "der Vietnamkrieg", "correct": false, "text_en": "the Vietnam War"}, {"text_de": "der Golfkrieg", "correct": false, "text_en": "the Gulf War"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-160.png"}, "question_en": "Which war lasted from 1939 to 1945?", "asking_note": "Straight date-recall. The trap is the First World War (1914-1918); don't let 'World War' pull you to the wrong one. The Vietnam War and Gulf War are far later and not German.", "answer_explanation": "The Second World War ran from 1939 to 1945, beginning with Nazi Germany's invasion of Poland on 1 September 1939 and ending in Europe with Germany's unconditional surrender in May 1945.", "distractor_notes": ["The First World War was 1914-1918, a generation earlier.", "", "The Vietnam War (roughly 1955-1975) was fought in Southeast Asia, not involving Germany.", "The Gulf War (1990-1991) was in the Middle East, decades later."]}, {"id": 161, "id_str": "161", "category": "general", "exam_pool": "general", "question_de": "Was kennzeichnete den NS-Staat? Eine Politik …", "question_image": null, "image_kind": null, "options": [{"text_de": "des staatlichen Rassismus", "correct": true, "text_en": "state racism"}, {"text_de": "der Meinungsfreiheit", "correct": false, "text_en": "freedom of opinion"}, {"text_de": "der allgemeinen Religionsfreiheit", "correct": false, "text_en": "general freedom of religion"}, {"text_de": "der Entwicklung der Demokratie", "correct": false, "text_en": "the development of democracy"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-161.png"}, "question_en": "What characterised the Nazi state (NS-Staat)? A policy of …", "asking_note": "You need the trait that defined the regime. Three options describe democratic freedoms the Nazis suppressed; only one names the racist ideology at the core of the state.", "answer_explanation": "The Nazi state was built on state-organised racism: a racial ideology that declared an 'Aryan' master race and legally persecuted Jews, Sinti and Roma, and others, culminating in the Holocaust. Racism was official government policy, not a fringe view.", "distractor_notes": ["", "Freedom of opinion was abolished; dissent was punished and the press was censored.", "General freedom of religion did not apply; the regime persecuted Jews and pressured the churches.", "The Nazis destroyed democracy rather than developing it."]}, {"id": 162, "id_str": "162", "category": "general", "exam_pool": "general", "question_de": "Claus Schenk Graf von Stauffenberg wurde bekannt durch …", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Goldmedaille bei den Olympischen Spielen 1936.", "correct": false, "text_en": "a gold medal at the 1936 Olympic Games."}, {"text_de": "den Bau des Reichstagsgebäudes.", "correct": false, "text_en": "building the Reichstag building."}, {"text_de": "den Aufbau der Wehrmacht.", "correct": false, "text_en": "the build-up of the Wehrmacht (armed forces)."}, {"text_de": "das Attentat auf Hitler am 20. Juli 1944.", "correct": true, "text_en": "the assassination attempt on Hitler on 20 July 1944."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-162.png"}, "question_en": "Claus Schenk Graf von Stauffenberg became known for …", "asking_note": "Tests knowledge of German resistance to Hitler. Stauffenberg is the face of the military resistance. The distractors attach him to unrelated 1930s-40s events (Olympics, Reichstag building, army buildup).", "answer_explanation": "Colonel Claus Schenk Graf von Stauffenberg led the failed assassination attempt on Hitler on 20 July 1944 ('Operation Valkyrie'), planting a bomb at Hitler's headquarters. He was executed the same night and is honoured as a symbol of German resistance against the Nazi dictatorship.", "distractor_notes": ["No Olympic connection; a distractor tying him to the 1936 Berlin Games.", "The Reichstag building was completed in 1894, long before his time; unrelated.", "He did not lead the build-up of the Wehrmacht; he was an officer within it who turned against Hitler.", ""]}, {"id": 163, "id_str": "163", "category": "general", "exam_pool": "general", "question_de": "In welchem Jahr zerstörten die Nationalsozialisten Synagogen und jüdische Geschäfte in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "1925", "correct": false, "text_en": "1925"}, {"text_de": "1930", "correct": false, "text_en": "1930"}, {"text_de": "1938", "correct": true, "text_en": "1938"}, {"text_de": "1945", "correct": false, "text_en": "1945"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-163.png"}, "question_en": "In what year did the National Socialists destroy synagogues and Jewish businesses in Germany?", "asking_note": "Date-recall for the Reichspogromnacht ('Kristallnacht'). Fix 1938 in memory. 1945 (war's end) and the earlier dates are traps.", "answer_explanation": "In the night of 9-10 November 1938, the Nazi pogrom later called Reichspogromnacht (or 'Kristallnacht') saw synagogues burned and Jewish shops, homes and cemeteries destroyed across Germany. It marked a violent escalation toward the Holocaust.", "distractor_notes": ["1925 predates the Nazi takeover; no such state-organised pogrom occurred.", "1930 is still during the Weimar Republic, before the Nazis held power.", "", "1945 is the end of the war; the pogrom was seven years earlier."]}, {"id": 164, "id_str": "164", "category": "general", "exam_pool": "general", "question_de": "Was passierte am 9. November 1938 in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Mit dem Angriff auf Polen beginnt der Zweite Weltkrieg.", "correct": false, "text_en": "The attack on Poland begins the Second World War."}, {"text_de": "Die Nationalsozialisten verlieren eine Wahl und lösen den Reichstag auf.", "correct": false, "text_en": "The National Socialists lose an election and dissolve the Reichstag."}, {"text_de": "Jüdische Geschäfte und Synagogen werden durch Nationalsozialisten und ihre Anhänger zerstört.", "correct": true, "text_en": "Jewish businesses and synagogues are destroyed by National Socialists and their followers."}, {"text_de": "Hitler wird Reichspräsident und lässt alle Parteien verbieten.", "correct": false, "text_en": "Hitler becomes Reich President and has all parties banned."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-164.png"}, "question_en": "What happened on 9 November 1938 in Germany?", "asking_note": "9 November is a loaded date in German history (also 1918, 1923, 1989). This question pins it to 1938 specifically. Read each option for its year; only one matches the Reichspogromnacht.", "answer_explanation": "9 November 1938 was the Reichspogromnacht: Nazis and their supporters destroyed Jewish shops and synagogues across the country. It is the key event tied to this date in 1938. (Note: 9 November also marks 1918's revolution and the 1989 fall of the Wall, but this question specifies 1938.)", "distractor_notes": ["The invasion of Poland was 1 September 1939, not this date.", "The Nazis did not lose an election in 1938; they had already abolished multi-party politics.", "", "Hitler merged the chancellor and presidency into 'Führer' in 1934, not 1938; parties were banned in 1933."]}, {"id": 165, "id_str": "165", "category": "general", "exam_pool": "general", "question_de": "Wie hieß der erste Bundeskanzler der Bundesrepublik Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Konrad Adenauer", "correct": true, "text_en": "Konrad Adenauer"}, {"text_de": "Kurt Georg Kiesinger", "correct": false, "text_en": "Kurt Georg Kiesinger"}, {"text_de": "Helmut Schmidt", "correct": false, "text_en": "Helmut Schmidt"}, {"text_de": "Willy Brandt", "correct": false, "text_en": "Willy Brandt"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-165.png"}, "question_en": "What was the name of the first Federal Chancellor (Bundeskanzler) of the Federal Republic of Germany?", "asking_note": "Recall of the first postwar West German chancellor. All four names are real chancellors, so you must know the order: Adenauer came first (1949).", "answer_explanation": "Konrad Adenauer (CDU) was the first Federal Chancellor of the Federal Republic of Germany, serving 1949-1963. He anchored West Germany in the Western alliance and oversaw the start of the postwar economic recovery.", "distractor_notes": ["", "Kurt Georg Kiesinger was chancellor 1966-1969, the third holder of the office.", "Helmut Schmidt (SPD) was chancellor 1974-1982, much later.", "Willy Brandt (SPD) was chancellor 1969-1974, known for reconciliation with the East; not the first."]}, {"id": 166, "id_str": "166", "category": "general", "exam_pool": "general", "question_de": "Bei welchen Demonstrationen in Deutschland riefen die Menschen \"Wir sind das Volk\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "beim Arbeiteraufstand 1953 in der DDR", "correct": false, "text_en": "at the workers' uprising of 1953 in the DDR"}, {"text_de": "bei den Demonstrationen 1968 in der Bundesrepublik Deutschland", "correct": false, "text_en": "at the 1968 demonstrations in the Federal Republic of Germany"}, {"text_de": "bei den Anti-Atomkraft-Demonstrationen 1985 in der Bundesrepublik Deutschland", "correct": false, "text_en": "at the anti-nuclear demonstrations of 1985 in the Federal Republic of Germany"}, {"text_de": "bei den Montagsdemonstrationen 1989 in der DDR", "correct": true, "text_en": "at the Monday demonstrations of 1989 in the DDR"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-166.png"}, "question_en": "At which demonstrations in Germany did people chant 'We are the people' ('Wir sind das Volk')?", "asking_note": "Ties a famous slogan to the right protest movement. The distractors list other real German protests (1953 uprising, 1968, anti-nuclear); the slogan belongs to the 1989 Monday demonstrations that helped bring down the DDR.", "answer_explanation": "'Wir sind das Volk' was the rallying cry of the Monday demonstrations (Montagsdemonstrationen) in Leipzig and other East German cities in autumn 1989. These peaceful mass protests were decisive in the collapse of the DDR regime and the fall of the Berlin Wall on 9 November 1989.", "distractor_notes": ["The 1953 uprising in the DDR was a workers' revolt against the regime, but it used different demands and was crushed by Soviet tanks.", "The 1968 protests in West Germany were a student movement with different slogans.", "The 1985 anti-nuclear protests were about energy/weapons policy, not this chant.", ""]}, {"id": 167, "id_str": "167", "category": "general", "exam_pool": "general", "question_de": "Welche Länder wurden nach dem Zweiten Weltkrieg in Deutschland als \"Alliierte Besatzungsmächte\" bezeichnet?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sowjetunion, Großbritannien, Polen, Schweden", "correct": false, "text_en": "Soviet Union, Great Britain, Poland, Sweden"}, {"text_de": "Frankreich, Sowjetunion, Italien, Japan", "correct": false, "text_en": "France, Soviet Union, Italy, Japan"}, {"text_de": "USA, Sowjetunion, Spanien, Portugal", "correct": false, "text_en": "USA, Soviet Union, Spain, Portugal"}, {"text_de": "USA, Sowjetunion, Großbritannien, Frankreich", "correct": true, "text_en": "USA, Soviet Union, Great Britain, France"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-167.png"}, "question_en": "Which countries were designated the 'Allied occupying powers' (Alliierte Besatzungsmächte) in Germany after the Second World War?", "asking_note": "You must recognise the exact set of four occupying powers. Each wrong option swaps in a country (Poland, Sweden, Italy, Japan, Spain, Portugal) that was NOT an occupier. Only one lists all four correctly.", "answer_explanation": "After 1945 Germany was divided into four occupation zones controlled by the USA, the Soviet Union, Great Britain and France, the main victorious Allies. These four powers jointly governed Germany (and Berlin) through the Allied Control Council.", "distractor_notes": ["Poland and Sweden were not occupying powers; Poland was itself occupied and later Soviet-aligned.", "Italy and Japan were Axis powers defeated in the war, not occupiers of Germany.", "Spain and Portugal were neutral dictatorships and had no occupation zone.", ""]}, {"id": 168, "id_str": "168", "category": "general", "exam_pool": "general", "question_de": "Welches Land war keine \"Alliierte Besatzungsmacht\" in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "USA", "correct": false, "text_en": "USA"}, {"text_de": "Sowjetunion", "correct": false, "text_en": "Soviet Union"}, {"text_de": "Frankreich", "correct": false, "text_en": "France"}, {"text_de": "Japan", "correct": true, "text_en": "Japan"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-168.png"}, "question_en": "Which country was NOT an 'Allied occupying power' in Germany?", "asking_note": "NEGATIVE framing: pick the country that did NOT occupy Germany. Three are the real occupiers; the odd one out is Japan, a defeated Axis power.", "answer_explanation": "Japan was NOT an occupying power in Germany. It was an Axis ally of Nazi Germany and was itself defeated and occupied (mainly by the USA) in 1945. The four occupiers of Germany were the USA, Soviet Union, Great Britain and France.", "distractor_notes": ["The USA was one of the four occupying powers, holding a zone in the south.", "The Soviet Union occupied the eastern zone, where the DDR later formed.", "France occupied a zone in the southwest.", ""]}, {"id": 169, "id_str": "169", "category": "general", "exam_pool": "general", "question_de": "Wann wurde die Bundesrepublik Deutschland gegründet?", "question_image": null, "image_kind": null, "options": [{"text_de": "1939", "correct": false, "text_en": "1939"}, {"text_de": "1945", "correct": false, "text_en": "1945"}, {"text_de": "1949", "correct": true, "text_en": "1949"}, {"text_de": "1951", "correct": false, "text_en": "1951"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-169.png"}, "question_en": "When was the Federal Republic of Germany (Bundesrepublik Deutschland) founded?", "asking_note": "Date-recall for the founding of West Germany. Note the year is the same as the DDR's founding (1949), which the exam also tests separately. Don't confuse 1945 (war's end) with 1949 (state founding).", "answer_explanation": "The Federal Republic of Germany was founded in 1949, when the Grundgesetz (Basic Law) came into force on 23 May 1949 in the three western occupation zones. The DDR was founded in the Soviet zone later the same year (October 1949).", "distractor_notes": ["1939 is the start of the Second World War, ten years too early.", "1945 is when the war ended and occupation began, but the state was not yet founded.", "", "1951 has no founding significance; a filler distractor."]}, {"id": 170, "id_str": "170", "category": "general", "exam_pool": "general", "question_de": "Was gab es während der Zeit des Nationalsozialismus in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "das Verbot von Parteien", "correct": true, "text_en": "the banning of parties"}, {"text_de": "das Recht zur freien Entfaltung der Persönlichkeit", "correct": false, "text_en": "the right to free development of one's personality"}, {"text_de": "Pressefreiheit", "correct": false, "text_en": "freedom of the press"}, {"text_de": "den Schutz der Menschenwürde", "correct": false, "text_en": "the protection of human dignity"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-170.png"}, "question_en": "What existed in Germany during the era of National Socialism?", "asking_note": "The mirror of the 'what did NOT exist' questions. Here you pick the repressive measure that DID exist. Three options are democratic rights/protections the Nazis abolished; only the ban on parties is a real feature of the regime.", "answer_explanation": "Under the Nazi regime, political parties were banned: after 1933 the NSDAP was the only legal party and all others were dissolved or prohibited. The other three options are fundamental rights guaranteed by today's Grundgesetz, none of which existed under the dictatorship.", "distractor_notes": ["", "The right to free development of the personality (Art. 2 Grundgesetz) is a modern constitutional right, not something the Nazi state allowed.", "Freedom of the press was abolished; media were controlled and censored.", "Protection of human dignity (Art. 1 Grundgesetz) is the founding value of today's constitution, systematically violated by the Nazis."]}, {"id": 171, "id_str": "171", "category": "general", "exam_pool": "general", "question_de": "Soziale Marktwirtschaft bedeutet, die Wirtschaft …", "question_image": null, "image_kind": null, "options": [{"text_de": "steuert sich allein nach Angebot und Nachfrage.", "correct": false, "text_en": "is steered solely by supply and demand."}, {"text_de": "wird vom Staat geplant und gesteuert, Angebot und Nachfrage werden nicht berücksichtigt.", "correct": false, "text_en": "is planned and controlled by the state, with supply and demand ignored."}, {"text_de": "richtet sich nach der Nachfrage im Ausland.", "correct": false, "text_en": "is oriented to demand abroad."}, {"text_de": "richtet sich nach Angebot und Nachfrage, aber der Staat sorgt für einen sozialen Ausgleich.", "correct": true, "text_en": "follows supply and demand, but the state ensures a social balance."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-171.png"}, "question_en": "The social market economy (soziale Marktwirtschaft) means the economy …", "asking_note": "Tests understanding of Germany's economic model. The trap is the two extremes: pure free market (option 1) and full state planning (option 2). The correct answer combines market forces WITH a state-guaranteed social balance.", "answer_explanation": "The social market economy, Germany's economic system since the 1950s, combines a free market based on supply and demand with a social safety net: the state intervenes to ensure fairness through social insurance, labour protections and support for those in need. It is a middle path between pure capitalism and a planned economy.", "distractor_notes": ["An economy steered solely by supply and demand describes a pure free market with no social component, the opposite of 'social'.", "A state-planned economy ignoring supply and demand describes a socialist command economy (as in the DDR), not the Federal Republic's model.", "Orienting the economy to foreign demand is not the meaning of 'social market economy'.", ""]}, {"id": 172, "id_str": "172", "category": "general", "exam_pool": "general", "question_de": "In welcher Besatzungszone wurde die DDR gegründet? In der …", "question_image": null, "image_kind": null, "options": [{"text_de": "amerikanischen Besatzungszone", "correct": false, "text_en": "American occupation zone"}, {"text_de": "französischen Besatzungszone", "correct": false, "text_en": "French occupation zone"}, {"text_de": "britischen Besatzungszone", "correct": false, "text_en": "British occupation zone"}, {"text_de": "sowjetischen Besatzungszone", "correct": true, "text_en": "Soviet occupation zone"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-172.png"}, "question_en": "In which occupation zone was the DDR founded? In the …", "asking_note": "You must match the DDR (East Germany) to the correct occupying power's zone. Three options name the Western zones; the DDR arose in the Soviet zone.", "answer_explanation": "The German Democratic Republic (DDR) was founded in October 1949 in the Soviet occupation zone. It became a socialist one-party state aligned with the Soviet Union, while the three Western zones merged into the Federal Republic.", "distractor_notes": ["The American zone was in southern Germany and became part of the Federal Republic.", "The French zone was in the southwest and became part of the Federal Republic.", "The British zone was in the northwest and became part of the Federal Republic.", ""]}, {"id": 173, "id_str": "173", "category": "general", "exam_pool": "general", "question_de": "Die Bundesrepublik Deutschland ist ein Gründungsmitglied …", "question_image": null, "image_kind": null, "options": [{"text_de": "des Nordatlantikpakts (NATO).", "correct": false, "text_en": "the North Atlantic Treaty Organization (NATO)."}, {"text_de": "der Vereinten Nationen (VN).", "correct": false, "text_en": "the United Nations (UN)."}, {"text_de": "der Europäischen Union (EU).", "correct": true, "text_en": "the European Union (EU)."}, {"text_de": "des Warschauer Pakts.", "correct": false, "text_en": "the Warsaw Pact."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-173.png"}, "question_en": "The Federal Republic of Germany is a founding member of …", "asking_note": "Tests which international organisation Germany co-founded. Careful: Germany joined NATO in 1955 and the UN in 1973 (not founding), and was never in the Warsaw Pact (that was the Eastern bloc). It was a founding member of the EU (and its predecessor communities).", "answer_explanation": "The Federal Republic of Germany was a founding member of the European Union and its predecessor European Communities (starting with the 1957 Treaties of Rome). European integration has been a cornerstone of West German and later German policy since the 1950s.", "distractor_notes": ["NATO was founded in 1949; West Germany only joined in 1955, so it was not a founding member.", "The UN was founded in 1945; West and East Germany joined only in 1973.", "", "The Warsaw Pact was the Soviet-led military alliance of the Eastern bloc; West Germany was never a member (the DDR was)."]}, {"id": 174, "id_str": "174", "category": "general", "exam_pool": "general", "question_de": "Wann wurde die DDR gegründet?", "question_image": null, "image_kind": null, "options": [{"text_de": "1947", "correct": false, "text_en": "1947"}, {"text_de": "1949", "correct": true, "text_en": "1949"}, {"text_de": "1953", "correct": false, "text_en": "1953"}, {"text_de": "1956", "correct": false, "text_en": "1956"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-174.png"}, "question_en": "When was the DDR founded?", "asking_note": "Date-recall for East Germany. It shares 1949 with the Federal Republic; the DDR came a few months after. The 1953 distractor tempts by matching the year of the East German uprising.", "answer_explanation": "The German Democratic Republic (DDR) was founded on 7 October 1949 in the Soviet occupation zone, a few months after the Federal Republic was established in the west. Both German states thus date from 1949.", "distractor_notes": ["1947 predates both German states.", "", "1953 is the year of the workers' uprising in the DDR (17 June), not its founding.", "1956 has no founding significance for the DDR."]}, {"id": 175, "id_str": "175", "category": "general", "exam_pool": "general", "question_de": "Wie viele Besatzungszonen gab es in Deutschland nach dem Zweiten Weltkrieg?", "question_image": null, "image_kind": null, "options": [{"text_de": "3", "correct": false, "text_en": "3"}, {"text_de": "4", "correct": true, "text_en": "4"}, {"text_de": "5", "correct": false, "text_en": "5"}, {"text_de": "6", "correct": false, "text_en": "6"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-175.png"}, "question_en": "How many occupation zones were there in Germany after the Second World War?", "asking_note": "Simple count question. The answer is four, matching the four Allied occupying powers (USA, Soviet Union, Britain, France). Don't confuse with the four SECTORS of Berlin (a separate question).", "answer_explanation": "Germany was divided into four occupation zones after 1945, one each for the USA, the Soviet Union, Great Britain and France. Berlin, though inside the Soviet zone, was likewise split into four sectors.", "distractor_notes": ["Three would omit one of the four occupying powers.", "", "Five is too many; there were only four Allied powers.", "Six is too many; a filler distractor."]}, {"id": 176, "id_str": "176", "category": "general", "exam_pool": "general", "question_de": "Wie waren die Besatzungszonen Deutschlands nach 1945 verteilt?", "question_image": "assets/img/q176-stem.png", "image_kind": "stem", "options": [{"text_de": "1=Großbritannien, 2=Sowjetunion, 3=Frankreich, 4=USA", "correct": false, "text_en": "1=Great Britain, 2=Soviet Union, 3=France, 4=USA"}, {"text_de": "1=Sowjetunion, 2=Großbritannien, 3=USA, 4=Frankreich", "correct": false, "text_en": "1=Soviet Union, 2=Great Britain, 3=USA, 4=France"}, {"text_de": "1=Großbritannien, 2=Sowjetunion, 3=USA, 4=Frankreich", "correct": true, "text_en": "1=Great Britain, 2=Soviet Union, 3=USA, 4=France"}, {"text_de": "1=Großbritannien, 2=USA, 3=Sowjetunion, 4=Frankreich", "correct": false, "text_en": "1=Great Britain, 2=USA, 3=Soviet Union, 4=France"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-176.png"}, "question_en": "How were Germany's occupation zones distributed after 1945? (map question)", "asking_note": "This question refers to a MAP (image in the stem): a map of postwar Germany with the four zones numbered 1-4, and you match numbers to countries. The correct answer places Great Britain in the north (1), the Soviet Union in the east (2), the USA in the south (3) and France in the southwest (4). Learn the geography: Britain north, Soviets east, USA south, France southwest.", "answer_explanation": "On the standard map, Great Britain occupied the northwest (1), the Soviet Union the east (2, which became the DDR), the USA the south (3), and France the southwest (4). This west-east and north-south layout matches the historical division that led to West and East Germany.", "distractor_notes": ["Wrong: it puts France in the south and the USA in the southwest, swapping their real positions.", "Wrong: it labels the northern zone as Soviet and the eastern as British, reversing the actual geography.", "", "Wrong: it swaps the USA (should be south, position 3) with the Soviet Union (should be east, position 2)."]}, {"id": 177, "id_str": "177", "category": "general", "exam_pool": "general", "question_de": "Welche deutsche Stadt wurde nach dem Zweiten Weltkrieg in vier Sektoren aufgeteilt?", "question_image": null, "image_kind": null, "options": [{"text_de": "München", "correct": false, "text_en": "Munich"}, {"text_de": "Berlin", "correct": true, "text_en": "Berlin"}, {"text_de": "Dresden", "correct": false, "text_en": "Dresden"}, {"text_de": "Frankfurt/Oder", "correct": false, "text_en": "Frankfurt/Oder"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-177.png"}, "question_en": "Which German city was divided into four sectors after the Second World War?", "asking_note": "Tests that you know Berlin, though deep in the Soviet zone, was itself split four ways. The distractors are other German cities with no four-power sector division.", "answer_explanation": "Berlin, the former capital lying inside the Soviet occupation zone, was itself divided into four sectors governed by the USA, Soviet Union, Great Britain and France. This split later produced West Berlin and East Berlin, symbolised by the Berlin Wall from 1961.", "distractor_notes": ["Munich lay entirely in the American zone and was not sectored.", "", "Dresden lay in the Soviet zone and was not divided into sectors.", "Frankfurt/Oder is a border town on the Polish frontier, not divided into four sectors."]}, {"id": 178, "id_str": "178", "category": "general", "exam_pool": "general", "question_de": "Vom Juni 1948 bis zum Mai 1949 wurden die Bürgerinnen und Bürger von West-Berlin durch eine Luftbrücke versorgt. Welcher Umstand war dafür verantwortlich?", "question_image": null, "image_kind": null, "options": [{"text_de": "Für Frankreich war eine Versorgung der West-Berliner Bevölkerung mit dem Flugzeug kostengünstiger.", "correct": false, "text_en": "For France, supplying the West Berlin population by aircraft was cheaper."}, {"text_de": "Die amerikanischen Soldatinnen und Soldaten hatten beim Landtransport Angst vor Überfällen.", "correct": false, "text_en": "The American soldiers feared ambushes during land transport."}, {"text_de": "Für Großbritannien war die Versorgung über die Luftbrücke schneller.", "correct": false, "text_en": "For Great Britain, supply via the airlift was faster."}, {"text_de": "Die Sowjetunion unterbrach den gesamten Verkehr auf dem Landwege.", "correct": true, "text_en": "The Soviet Union cut off all traffic by land."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-178.png"}, "question_en": "From June 1948 to May 1949 the citizens of West Berlin were supplied via an airlift (Luftbrücke). What circumstance was responsible for this?", "asking_note": "Tests the cause of the Berlin Airlift. Three options give false, plausible-sounding logistical reasons (cost, fear, speed). The real cause was the Soviet land blockade of West Berlin.", "answer_explanation": "In June 1948 the Soviet Union blockaded all road, rail and canal routes into West Berlin (the Berlin Blockade), trying to force the Western powers out. The USA and Britain responded with the Berlin Airlift ('Luftbrücke'), flying in food and fuel for nearly a year until the Soviets lifted the blockade in May 1949.", "distractor_notes": ["Cost was not the reason; the airlift was hugely expensive, undertaken out of necessity, not to save money.", "Fear of ambush was not the cause; the land routes were physically blocked by the Soviets.", "Speed was not the reason; an airlift is far harder than land transport and was a forced improvisation.", ""]}, {"id": 179, "id_str": "179", "category": "general", "exam_pool": "general", "question_de": "Wie endete der Zweite Weltkrieg in Europa offiziell?", "question_image": null, "image_kind": null, "options": [{"text_de": "mit dem Tod Adolf Hitlers", "correct": false, "text_en": "with the death of Adolf Hitler"}, {"text_de": "durch die bedingungslose Kapitulation Deutschlands", "correct": true, "text_en": "through the unconditional surrender of Germany"}, {"text_de": "mit dem Rückzug der Deutschen aus den besetzten Gebieten", "correct": false, "text_en": "with the German withdrawal from the occupied territories"}, {"text_de": "durch eine Revolution in Deutschland", "correct": false, "text_en": "through a revolution in Germany"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-179.png"}, "question_en": "How did the Second World War in Europe officially end?", "asking_note": "Tests the formal end of the war in Europe. Hitler's death (30 April 1945) came days before, but the war ended OFFICIALLY through Germany's unconditional surrender, not by any single event listed in the distractors.", "answer_explanation": "The Second World War in Europe officially ended with Germany's unconditional surrender, signed on 7-8 May 1945 (8 May is commemorated as the day of liberation / end of the war in Europe). Unconditional surrender meant the German military laid down arms with no negotiated terms.", "distractor_notes": ["Hitler's suicide on 30 April 1945 preceded the surrender but was not the official end of the war.", "", "There was no orderly negotiated withdrawal; German forces were defeated and surrendered.", "There was no revolution in 1945; the regime was defeated militarily by the Allies."]}, {"id": 180, "id_str": "180", "category": "general", "exam_pool": "general", "question_de": "Der erste Bundeskanzler der Bundesrepublik Deutschland war …", "question_image": null, "image_kind": null, "options": [{"text_de": "Ludwig Erhard.", "correct": false, "text_en": "Ludwig Erhard."}, {"text_de": "Willy Brandt.", "correct": false, "text_en": "Willy Brandt."}, {"text_de": "Konrad Adenauer.", "correct": true, "text_en": "Konrad Adenauer."}, {"text_de": "Gerhard Schröder.", "correct": false, "text_en": "Gerhard Schröder."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-180.png"}, "question_en": "The first Federal Chancellor of the Federal Republic of Germany was …", "asking_note": "Same fact as question 165, reworded. All four are genuine chancellors, so you must know Adenauer was first (1949). Erhard, Brandt and Schröder all came later.", "answer_explanation": "Konrad Adenauer (CDU) was the first Federal Chancellor, in office 1949-1963. He led West Germany's integration into the West and reconciliation with former enemies such as France.", "distractor_notes": ["Ludwig Erhard, the 'father of the economic miracle', was the second chancellor (1963-1966), succeeding Adenauer.", "Willy Brandt (SPD) was chancellor 1969-1974.", "", "Gerhard Schröder (SPD) was chancellor 1998-2005, decades later."]}, {"id": 181, "id_str": "181", "category": "general", "exam_pool": "general", "question_de": "Was wollte Willy Brandt mit seinem Kniefall 1970 im ehemaligen jüdischen Ghetto in Warschau ausdrücken?", "question_image": "assets/img/q181-stem.png", "image_kind": "stem", "options": [{"text_de": "Er hat sich den ehemaligen Alliierten unterworfen.", "correct": false, "text_en": "He submitted himself to the former Allies."}, {"text_de": "Er bat Polen und die polnischen Juden um Vergebung.", "correct": true, "text_en": "He asked Poland and the Polish Jews for forgiveness."}, {"text_de": "Er zeigte seine Demut vor dem Warschauer Pakt.", "correct": false, "text_en": "He showed his humility before the Warsaw Pact."}, {"text_de": "Er sprach ein Gebet am Grab des Unbekannten Soldaten.", "correct": false, "text_en": "He said a prayer at the grave of the Unknown Soldier."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-181.png"}, "question_en": "What did Willy Brandt want to express with his 'genuflection' (Kniefall) in 1970 at the former Jewish ghetto in Warsaw? (image question)", "asking_note": "This question shows a PHOTO in the stem (Brandt kneeling in Warsaw). It tests the meaning of the gesture: an act of humility and a plea for forgiveness for Nazi crimes. The distractors twist it into submission to allies, deference to the Warsaw Pact, or a prayer.", "answer_explanation": "In December 1970, on a visit to Warsaw, Chancellor Willy Brandt spontaneously knelt at the memorial to the 1943 Warsaw Ghetto Uprising ('Warschauer Kniefall'). The gesture was understood worldwide as a humble plea for forgiveness for the crimes of Nazi Germany against Poland and the Jewish people, and a landmark of West German reconciliation policy (Ostpolitik).", "distractor_notes": ["It was not submission to the Allies; it was a moral gesture of atonement, not a political capitulation.", "", "It was not deference to the Warsaw Pact military alliance; it addressed Nazi crimes, not Cold War politics.", "It was not a prayer at a soldier's grave; the site was the memorial to the Jewish ghetto uprising."]}, {"id": 182, "id_str": "182", "category": "general", "exam_pool": "general", "question_de": "Wie heißt das jüdische Gebetshaus?", "question_image": null, "image_kind": null, "options": [{"text_de": "Basilika", "correct": false, "text_en": "basilica"}, {"text_de": "Moschee", "correct": false, "text_en": "mosque"}, {"text_de": "Synagoge", "correct": true, "text_en": "synagogue"}, {"text_de": "Kirche", "correct": false, "text_en": "church"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-182.png"}, "question_en": "What is the Jewish house of prayer called?", "asking_note": "Basic religious-vocabulary question. Match each faith to its place of worship: the Jewish one is the synagogue. The distractors are the Christian and Muslim (and a Catholic-style) houses of worship.", "answer_explanation": "A synagogue is the Jewish house of prayer and communal worship. Recognising the main religions' places of worship is basic civic knowledge in Germany, whose constitution guarantees freedom of religion.", "distractor_notes": ["A basilica is a type of large Christian (often Catholic) church building.", "A mosque (Moschee) is the Muslim house of prayer.", "", "A church (Kirche) is the Christian house of worship."]}, {"id": 183, "id_str": "183", "category": "general", "exam_pool": "general", "question_de": "Wann war in der Bundesrepublik Deutschland das \"Wirtschaftswunder\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "40er Jahre", "correct": false, "text_en": "1940s"}, {"text_de": "50er Jahre", "correct": true, "text_en": "1950s"}, {"text_de": "70er Jahre", "correct": false, "text_en": "1970s"}, {"text_de": "80er Jahre", "correct": false, "text_en": "1980s"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-183.png"}, "question_en": "When was the 'economic miracle' (Wirtschaftswunder) in the Federal Republic of Germany?", "asking_note": "Date-recall for West Germany's postwar boom. The answer is the 1950s. The 1940s (war and immediate ruin) and later decades are traps.", "answer_explanation": "The 'Wirtschaftswunder' was the rapid economic recovery and boom of West Germany in the 1950s, associated with economics minister Ludwig Erhard and the social market economy. Rebuilding, full employment and rising prosperity transformed the country within a decade of the war's end.", "distractor_notes": ["The 1940s were the years of war and postwar devastation, before recovery.", "", "The 1970s brought oil crises and slower growth, not the boom.", "The 1980s were well after the miracle years."]}, {"id": 184, "id_str": "184", "category": "general", "exam_pool": "general", "question_de": "Auf welcher rechtlichen Grundlage wurde der Staat Israel gegründet?", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Resolution der Vereinten Nationen", "correct": true, "text_en": "a resolution of the United Nations"}, {"text_de": "ein Beschluss des Zionistenkongresses", "correct": false, "text_en": "a decision of the Zionist Congress"}, {"text_de": "ein Vorschlag der Bundesregierung", "correct": false, "text_en": "a proposal of the German federal government"}, {"text_de": "ein Vorschlag der UdSSR", "correct": false, "text_en": "a proposal of the USSR"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-184.png"}, "question_en": "On what legal basis was the State of Israel founded?", "asking_note": "Tests knowledge that Israel's founding rested on a United Nations resolution. The distractors substitute other bodies (Zionist Congress, German federal government, USSR) that did not provide the legal basis.", "answer_explanation": "The State of Israel was founded in 1948 on the basis of the United Nations partition plan for Palestine (UN General Assembly Resolution 181 of 1947), which provided for separate Jewish and Arab states. This UN resolution is the internationally recognised legal basis for Israel's creation.", "distractor_notes": ["", "The Zionist Congress promoted the idea of a Jewish state but had no legal authority to found one internationally.", "The German federal government had no role in founding Israel.", "The USSR voted for the UN partition plan but did not itself create the legal basis; the UN resolution did."]}, {"id": 185, "id_str": "185", "category": "general", "exam_pool": "general", "question_de": "Wofür stand der Ausdruck \"Eiserner Vorhang\"? Für die Abschottung …", "question_image": null, "image_kind": null, "options": [{"text_de": "des Warschauer Pakts gegen den Westen", "correct": true, "text_en": "of the Warsaw Pact against the West"}, {"text_de": "Norddeutschlands gegen Süddeutschland", "correct": false, "text_en": "of northern Germany against southern Germany"}, {"text_de": "Nazi-Deutschlands gegen die Alliierten", "correct": false, "text_en": "of Nazi Germany against the Allies"}, {"text_de": "Europas gegen die USA", "correct": false, "text_en": "of Europe against the USA"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-185.png"}, "question_en": "What did the expression 'Iron Curtain' (Eiserner Vorhang) stand for? For the sealing-off …", "asking_note": "Tests the meaning of a Cold War term. The 'Iron Curtain' described the divide sealing the Soviet-led Eastern bloc (Warsaw Pact) off from the democratic West. Distractors mislocate it inside Germany, in the Nazi era, or between Europe and the USA.", "answer_explanation": "The 'Iron Curtain' was the symbolic and physical line dividing Europe during the Cold War, sealing off the Soviet-controlled Eastern bloc (the Warsaw Pact states) from the democratic, capitalist West. The Berlin Wall and the fortified inner-German border were its most visible parts.", "distractor_notes": ["", "It did not divide northern from southern Germany; the divide was east-west, between the two blocs.", "It was a Cold War (post-1945) concept, not a Nazi-era one against the Allies.", "It did not separate Europe from the USA, which were allied in the Western bloc."]}, {"id": 186, "id_str": "186", "category": "general", "exam_pool": "general", "question_de": "Im Jahr 1953 gab es in der DDR einen Aufstand, an den lange Zeit in der Bundesrepublik Deutschland ein Feiertag erinnerte. Wann war das?", "question_image": null, "image_kind": null, "options": [{"text_de": "1. Mai", "correct": false, "text_en": "1 May"}, {"text_de": "17. Juni", "correct": true, "text_en": "17 June"}, {"text_de": "20. Juli", "correct": false, "text_en": "20 July"}, {"text_de": "9. November", "correct": false, "text_en": "9 November"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-186.png"}, "question_en": "In 1953 there was an uprising in the DDR that a public holiday in the Federal Republic of Germany commemorated for a long time. When was it?", "asking_note": "Date-recall tied to the 1953 East German uprising. The answer is 17 June. The distractors are other loaded German dates: 1 May (Labour Day), 20 July (Stauffenberg plot), 9 November (Wall/Kristallnacht).", "answer_explanation": "On 17 June 1953 workers across the DDR rose up against the communist regime; the revolt was crushed by Soviet tanks. In West Germany, 17 June was observed as a national holiday, the 'Day of German Unity', until reunification in 1990 moved that holiday to 3 October.", "distractor_notes": ["1 May is International Workers' Day, a public holiday but unrelated to the 1953 uprising.", "", "20 July marks the 1944 Stauffenberg assassination attempt on Hitler, not the DDR uprising.", "9 November is linked to 1918, 1938 (Kristallnacht) and 1989 (fall of the Wall), not 1953."]}, {"id": 187, "id_str": "187", "category": "general", "exam_pool": "general", "question_de": "Welcher deutsche Staat hatte eine schwarz-rot-goldene Flagge mit Hammer, Zirkel und Ährenkranz?", "question_image": "assets/img/q187-stem.png", "image_kind": "stem", "options": [{"text_de": "Preußen", "correct": false, "text_en": "Prussia"}, {"text_de": "Bundesrepublik Deutschland", "correct": false, "text_en": "Federal Republic of Germany"}, {"text_de": "\"Drittes Reich\"", "correct": false, "text_en": "\"Third Reich\""}, {"text_de": "DDR", "correct": true, "text_en": "GDR (East Germany)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-187.png"}, "question_en": "Which German state had a black-red-gold flag bearing a hammer, a compass and a ring of grain (ears of wheat)?", "asking_note": "The question refers to a flag image. It is testing whether you can identify the East German (DDR) state emblem. The trap is that all four options used or could use black-red-gold; the distinguishing feature is the added hammer, compass and wreath of grain.", "answer_explanation": "The German Democratic Republic (DDR) used the same black-red-gold tricolour as West Germany but added its state emblem (Staatswappen) in the centre: a hammer (workers), a compass (intelligentsia/technicians) and a ring of grain (farmers), symbolising the socialist 'workers' and peasants' state'. This emblem was added to the DDR flag in 1959 to distinguish it from the Federal Republic's plain tricolour.", "distractor_notes": ["Prussia was a historic kingdom/state whose flag was black and white with the Prussian eagle, not black-red-gold with a hammer and compass.", "The Federal Republic (West Germany, and today's unified Germany) uses a plain black-red-gold tricolour with no emblem on the flag itself.", "The Nazi 'Third Reich' used a red flag with a black swastika in a white circle, not black-red-gold.", ""]}, {"id": 188, "id_str": "188", "category": "general", "exam_pool": "general", "question_de": "In welchem Jahr wurde die Mauer in Berlin gebaut?", "question_image": null, "image_kind": null, "options": [{"text_de": "1953", "correct": false, "text_en": "1953"}, {"text_de": "1956", "correct": false, "text_en": "1956"}, {"text_de": "1959", "correct": false, "text_en": "1959"}, {"text_de": "1961", "correct": true, "text_en": "1961"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-188.png"}, "question_en": "In which year was the Berlin Wall built?", "asking_note": "A straightforward date-recall question. The trap is the cluster of plausible 1950s dates; you must know the exact year the Wall went up.", "answer_explanation": "The Berlin Wall was built starting on 13 August 1961. The East German (DDR) government erected it to stop the mass exodus of its citizens to the West via West Berlin, which was the last open crossing point between the two German states. It divided the city for 28 years.", "distractor_notes": ["1953 was the year of the popular uprising in the DDR (17 June 1953), not the Wall.", "1956 was the Hungarian uprising; nothing about the Berlin Wall.", "1959 was the year the DDR added its emblem to its flag, but the Wall did not yet exist.", ""]}, {"id": 189, "id_str": "189", "category": "general", "exam_pool": "general", "question_de": "Wann baute die DDR die Mauer in Berlin?", "question_image": null, "image_kind": null, "options": [{"text_de": "1919", "correct": false, "text_en": "1919"}, {"text_de": "1933", "correct": false, "text_en": "1933"}, {"text_de": "1961", "correct": true, "text_en": "1961"}, {"text_de": "1990", "correct": false, "text_en": "1990"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-189.png"}, "question_en": "When did the GDR (DDR) build the Wall in Berlin?", "asking_note": "Same fact as the previous question (Wall built in 1961), but the wrong answers here are widely spaced historical dates. Do not confuse 1961 (Wall built) with 1990 (reunification).", "answer_explanation": "The DDR began building the Berlin Wall on 13 August 1961 to halt the flight of its population to the West. The Wall stood until 1989 and was a defining symbol of the Cold War division of Germany and Europe.", "distractor_notes": ["1919 was the founding year of the Weimar Republic after World War I.", "1933 was the year Hitler and the Nazis came to power.", "", "1990 was the year of German reunification, when the DDR ceased to exist — not when the Wall was built."]}, {"id": 190, "id_str": "190", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet die Abkürzung DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "Dritter Deutscher Rundfunk", "correct": false, "text_en": "Third German Broadcasting"}, {"text_de": "Die Deutsche Republik", "correct": false, "text_en": "The German Republic"}, {"text_de": "Dritte Deutsche Republik", "correct": false, "text_en": "Third German Republic"}, {"text_de": "Deutsche Demokratische Republik", "correct": true, "text_en": "German Democratic Republic"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-190.png"}, "question_en": "What does the abbreviation 'DDR' stand for?", "asking_note": "Vocabulary/acronym recall. The distractors are invented expansions that all start with 'D'; only one is the real name of the East German state.", "answer_explanation": "DDR stands for 'Deutsche Demokratische Republik' — the German Democratic Republic, the socialist state that existed in eastern Germany from 1949 to 1990. Despite 'democratic' in its name, it was a one-party dictatorship led by the SED.", "distractor_notes": ["'Dritter Deutscher Rundfunk' is a made-up broadcasting name, not what DDR means.", "'Die Deutsche Republik' was never the name of the East German state. Its initials do spell D-D-R, which is exactly why it is a tempting distractor, but the real state was the Deutsche Demokratische Republik.", "'Dritte Deutsche Republik' is a fabricated term, not the name of any German state.", ""]}, {"id": 191, "id_str": "191", "category": "general", "exam_pool": "general", "question_de": "Wann wurde die Mauer in Berlin für alle geöffnet?", "question_image": null, "image_kind": null, "options": [{"text_de": "1987", "correct": false, "text_en": "1987"}, {"text_de": "1989", "correct": true, "text_en": "1989"}, {"text_de": "1992", "correct": false, "text_en": "1992"}, {"text_de": "1995", "correct": false, "text_en": "1995"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-191.png"}, "question_en": "When was the Berlin Wall opened for everyone?", "asking_note": "Date-recall for the fall of the Wall. Do not confuse the opening of the Wall (1989) with formal reunification (1990). All options are late-1980s/1990s years.", "answer_explanation": "The Berlin Wall was opened on 9 November 1989, after peaceful protests across the DDR and a confused announcement of new travel rules led crowds to the border crossings. Its opening marked the effective end of the division of Germany and paved the way for reunification in 1990.", "distractor_notes": ["1987 is when US President Reagan gave his 'tear down this wall' speech in Berlin, but the Wall was still standing.", "", "1992 is after both the fall of the Wall and reunification.", "1995 is well after reunification; irrelevant to the Wall's opening."]}, {"id": 192, "id_str": "192", "category": "general", "exam_pool": "general", "question_de": "Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "Brandenburg", "correct": true, "text_en": "Brandenburg"}, {"text_de": "Bayern", "correct": false, "text_en": "Bavaria"}, {"text_de": "Saarland", "correct": false, "text_en": "Saarland"}, {"text_de": "Hessen", "correct": false, "text_en": "Hesse"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-192.png"}, "question_en": "Which of today's German federal states was formerly part of the territory of the GDR (DDR)?", "asking_note": "Geography/history recall of the five 'new' eastern states. The trap: only one option is an eastern state; the others are all western states. Brandenburg surrounds Berlin.", "answer_explanation": "Brandenburg was part of the DDR and is one of the five 'new federal states' (neue Bundesländer) created when the DDR joined the Federal Republic in 1990. It surrounds the city-state of Berlin. The five eastern states are Brandenburg, Mecklenburg-Vorpommern, Saxony, Saxony-Anhalt and Thuringia.", "distractor_notes": ["", "Bavaria (Bayern) is in the south and was always part of West Germany.", "Saarland is in the far west, bordering France; it was part of West Germany.", "Hesse (Hessen) is a central-western state that belonged to West Germany."]}, {"id": 193, "id_str": "193", "category": "general", "exam_pool": "general", "question_de": "Von 1961 bis 1989 war Berlin …", "question_image": null, "image_kind": null, "options": [{"text_de": "ohne Bürgermeister.", "correct": false, "text_en": "without a mayor."}, {"text_de": "ein eigener Staat.", "correct": false, "text_en": "an independent state."}, {"text_de": "durch eine Mauer geteilt.", "correct": true, "text_en": "divided by a wall."}, {"text_de": "nur mit dem Flugzeug erreichbar.", "correct": false, "text_en": "reachable only by aeroplane."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-193.png"}, "question_en": "From 1961 to 1989, Berlin was ...", "asking_note": "Tests understanding of Berlin's Cold War status. The correct answer describes the physical division by the Wall; the distractors describe conditions that were never true of the city.", "answer_explanation": "Between 1961 (when the Wall went up) and 1989 (when it fell), Berlin was physically divided by the Berlin Wall into East Berlin (capital of the DDR) and West Berlin. The Wall cut through the middle of the city, separating families and neighbourhoods for 28 years.", "distractor_notes": ["Berlin had governing mayors throughout this period (both East and West Berlin had their own administrations).", "Berlin was not a sovereign state; East Berlin was the DDR capital and West Berlin was tied to the Federal Republic.", "", "West Berlin was reachable by road, rail and canal transit routes through the DDR, not only by plane (the airlift was in 1948-49, earlier)."]}, {"id": 194, "id_str": "194", "category": "general", "exam_pool": "general", "question_de": "Am 3. Oktober feiert man in Deutschland den Tag der Deutschen …", "question_image": null, "image_kind": null, "options": [{"text_de": "Einheit.", "correct": true, "text_en": "Unity."}, {"text_de": "Nation.", "correct": false, "text_en": "Nation."}, {"text_de": "Bundesländer.", "correct": false, "text_en": "Federal states."}, {"text_de": "Städte.", "correct": false, "text_en": "Cities."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-194.png"}, "question_en": "On 3 October, Germany celebrates the Day of German ...", "asking_note": "Fill-in-the-blank for the name of the national holiday. Only one word correctly completes 'Tag der Deutschen ___'. The trap is other plausible-sounding nouns.", "answer_explanation": "3 October is the 'Tag der Deutschen Einheit' (Day of German Unity), Germany's national holiday. It commemorates 3 October 1990, the date on which the DDR formally acceded to the Federal Republic and Germany was reunified into one state.", "distractor_notes": ["", "'Tag der Deutschen Nation' is not a real holiday name.", "There is no 'Day of the German Federal States'.", "There is no 'Day of German Cities' as a national holiday."]}, {"id": 195, "id_str": "195", "category": "general", "exam_pool": "general", "question_de": "Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "Hessen", "correct": false, "text_en": "Hesse"}, {"text_de": "Sachsen-Anhalt", "correct": true, "text_en": "Saxony-Anhalt"}, {"text_de": "Nordrhein-Westfalen", "correct": false, "text_en": "North Rhine-Westphalia"}, {"text_de": "Saarland", "correct": false, "text_en": "Saarland"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-195.png"}, "question_en": "Which of today's German federal states was formerly part of the territory of the GDR (DDR)?", "asking_note": "Same recall task as Q192: pick the one eastern state among western ones. Here the answer is Saxony-Anhalt.", "answer_explanation": "Saxony-Anhalt (Sachsen-Anhalt) was part of the DDR and is one of the five 'new federal states' formed on reunification in 1990. The complete set of former DDR states is Brandenburg, Mecklenburg-Vorpommern, Saxony, Saxony-Anhalt and Thuringia.", "distractor_notes": ["Hesse (Hessen) was a western state, part of West Germany.", "", "North Rhine-Westphalia (Nordrhein-Westfalen) is Germany's most populous state and was in the west.", "Saarland is a small western state on the French border; it was part of West Germany."]}, {"id": 196, "id_str": "196", "category": "general", "exam_pool": "general", "question_de": "Warum nennt man die Zeit im Herbst 1989 in der DDR \"Die Wende\"? In dieser Zeit veränderte sich die DDR politisch …", "question_image": null, "image_kind": null, "options": [{"text_de": "von einer Diktatur zur Demokratie.", "correct": true, "text_en": "from a dictatorship to a democracy."}, {"text_de": "von einer liberalen Marktwirtschaft zum Sozialismus.", "correct": false, "text_en": "from a liberal market economy to socialism."}, {"text_de": "von einer Monarchie zur Sozialdemokratie.", "correct": false, "text_en": "from a monarchy to social democracy."}, {"text_de": "von einem religiösen Staat zu einem kommunistischen Staat.", "correct": false, "text_en": "from a religious state to a communist state."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-196.png"}, "question_en": "Why is the period in autumn 1989 in the DDR called 'Die Wende' (the turning point)? During this time the DDR changed politically ...", "asking_note": "Tests the meaning of 'die Wende'. The correct answer names the actual direction of change; the distractors invert it or describe transitions that never happened.", "answer_explanation": "'Die Wende' refers to the peaceful revolution of autumn 1989, when mass protests and the opening of the Wall transformed the DDR from a one-party socialist dictatorship into a democracy, leading to free elections in March 1990 and reunification. It was a change from dictatorship toward democracy and a market economy.", "distractor_notes": ["", "This reverses the actual direction — the DDR moved away from socialism, not toward it.", "The DDR was not a monarchy; this transition never occurred.", "The DDR was already a communist-led state and was not religiously governed; this option is false."]}, {"id": 197, "id_str": "197", "category": "general", "exam_pool": "general", "question_de": "Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "Thüringen", "correct": true, "text_en": "Thuringia"}, {"text_de": "Hessen", "correct": false, "text_en": "Hesse"}, {"text_de": "Bayern", "correct": false, "text_en": "Bavaria"}, {"text_de": "Bremen", "correct": false, "text_en": "Bremen"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-197.png"}, "question_en": "Which of today's German federal states was formerly part of the territory of the GDR (DDR)?", "asking_note": "Same recall task as Q192/195. Here the answer is Thuringia. The others are all western states.", "answer_explanation": "Thuringia (Thüringen), in central Germany, was part of the DDR and became one of the five 'new federal states' at reunification in 1990. The five former DDR states are Brandenburg, Mecklenburg-Vorpommern, Saxony, Saxony-Anhalt and Thuringia.", "distractor_notes": ["", "Hesse (Hessen) was part of West Germany.", "Bavaria (Bayern) is a southern state that was always in West Germany.", "Bremen is a small city-state in the northwest and belonged to West Germany."]}, {"id": 198, "id_str": "198", "category": "general", "exam_pool": "general", "question_de": "Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "Bayern", "correct": false, "text_en": "Bavaria"}, {"text_de": "Niedersachsen", "correct": false, "text_en": "Lower Saxony"}, {"text_de": "Sachsen", "correct": true, "text_en": "Saxony"}, {"text_de": "Baden-Württemberg", "correct": false, "text_en": "Baden-Württemberg"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-198.png"}, "question_en": "Which of today's German federal states was formerly part of the territory of the GDR (DDR)?", "asking_note": "Same recall task again. Here the answer is Saxony. The others are western states.", "answer_explanation": "Saxony (Sachsen), in the southeast bordering Poland and the Czech Republic, was part of the DDR and became one of the five 'new federal states' at reunification in 1990. Note the easily confused name: Saxony was in the DDR, but Lower Saxony (Niedersachsen) was in West Germany.", "distractor_notes": ["Bavaria (Bayern) was always part of West Germany.", "Lower Saxony (Niedersachsen) is a northwestern state and was in West Germany — do not confuse it with Saxony.", "", "Baden-Württemberg is a southwestern state that belonged to West Germany."]}, {"id": 199, "id_str": "199", "category": "general", "exam_pool": "general", "question_de": "Mit der Abkürzung \"Stasi\" meinte man in der DDR …", "question_image": null, "image_kind": null, "options": [{"text_de": "das Parlament.", "correct": false, "text_en": "the parliament."}, {"text_de": "das Ministerium für Staatssicherheit.", "correct": true, "text_en": "the Ministry for State Security."}, {"text_de": "eine regierende Partei.", "correct": false, "text_en": "a governing party."}, {"text_de": "das Ministerium für Volksbildung.", "correct": false, "text_en": "the Ministry for Public Education."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-199.png"}, "question_en": "In the DDR, the abbreviation 'Stasi' referred to ...", "asking_note": "Vocabulary/acronym recall for the DDR secret police. The distractors are other DDR institutions; pick the state security ministry.", "answer_explanation": "'Stasi' is short for 'Ministerium für Staatssicherheit' (Ministry for State Security), the DDR's secret police and intelligence service. It maintained a vast network of informants and surveilled, intimidated and persecuted citizens to protect the SED regime.", "distractor_notes": ["The DDR parliament was the Volkskammer, not the Stasi.", "", "The ruling party was the SED (Sozialistische Einheitspartei Deutschlands), not the Stasi.", "The Ministry for Public Education (Volksbildung) handled schooling, a separate body from the Stasi."]}, {"id": 200, "id_str": "200", "category": "general", "exam_pool": "general", "question_de": "Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "Hessen", "correct": false, "text_en": "Hesse"}, {"text_de": "Schleswig-Holstein", "correct": false, "text_en": "Schleswig-Holstein"}, {"text_de": "Mecklenburg-Vorpommern", "correct": true, "text_en": "Mecklenburg-Western Pomerania"}, {"text_de": "Saarland", "correct": false, "text_en": "Saarland"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-200.png"}, "question_en": "Which of today's German federal states was formerly part of the territory of the GDR (DDR)?", "asking_note": "Same recall task. Here the answer is Mecklenburg-Vorpommern, the northeastern coastal state. The others are western states.", "answer_explanation": "Mecklenburg-Vorpommern (Mecklenburg-Western Pomerania), on the Baltic coast in the northeast, was part of the DDR and became one of the five 'new federal states' at reunification in 1990. The trap here is Schleswig-Holstein, the other Baltic/North Sea state, which was in West Germany.", "distractor_notes": ["Hesse (Hessen) was part of West Germany.", "Schleswig-Holstein, Germany's northernmost state, was part of West Germany — do not confuse it with the eastern coastal state.", "", "Saarland is a western state on the French border and belonged to West Germany."]}, {"id": 201, "id_str": "201", "category": "general", "exam_pool": "general", "question_de": "Welche der folgenden Auflistungen enthält nur Bundesländer, die zum Gebiet der früheren DDR gehörten?", "question_image": null, "image_kind": null, "options": [{"text_de": "Niedersachsen, Nordrhein-Westfalen, Hessen, Schleswig-Holstein, Brandenburg", "correct": false, "text_en": "Lower Saxony, North Rhine-Westphalia, Hesse, Schleswig-Holstein, Brandenburg"}, {"text_de": "Mecklenburg-Vorpommern, Brandenburg, Sachsen, Sachsen-Anhalt, Thüringen", "correct": true, "text_en": "Mecklenburg-Western Pomerania, Brandenburg, Saxony, Saxony-Anhalt, Thuringia"}, {"text_de": "Bayern, Baden-Württemberg, Rheinland-Pfalz, Thüringen, Sachsen", "correct": false, "text_en": "Bavaria, Baden-Württemberg, Rhineland-Palatinate, Thuringia, Saxony"}, {"text_de": "Sachsen, Thüringen, Hessen, Niedersachen, Brandenburg", "correct": false, "text_en": "Saxony, Thuringia, Hesse, Lower Saxony, Brandenburg"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-201.png"}, "question_en": "Which of the following lists contains only federal states that belonged to the territory of the former DDR?", "asking_note": "This is the 'complete set' version of the DDR-states question, and it is a trap-heavy 'odd one out' test: three of the four lists mix in at least one western state (e.g. Hesse, Bavaria, Lower Saxony, North Rhine-Westphalia). You must find the list that is entirely eastern.", "answer_explanation": "The five federal states that made up the former DDR are exactly Mecklenburg-Vorpommern, Brandenburg, Saxony, Saxony-Anhalt and Thuringia — the complete and correct list. All were reconstituted in 1990 as the 'new federal states' when the DDR acceded to the Federal Republic.", "distractor_notes": ["This list is mostly western states (Lower Saxony, North Rhine-Westphalia, Hesse, Schleswig-Holstein); only Brandenburg was in the DDR.", "", "This mixes western states (Bavaria, Baden-Württemberg, Rhineland-Palatinate) with two eastern ones; it is not exclusively eastern.", "This includes the western states Hesse and Lower Saxony alongside eastern ones, so it is not exclusively eastern."]}, {"id": 202, "id_str": "202", "category": "general", "exam_pool": "general", "question_de": "Zu wem gehörte die DDR im \"Kalten Krieg\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "zu den Westmächten", "correct": false, "text_en": "to the Western powers"}, {"text_de": "zum Warschauer Pakt", "correct": true, "text_en": "to the Warsaw Pact"}, {"text_de": "zur NATO", "correct": false, "text_en": "to NATO"}, {"text_de": "zu den blockfreien Staaten", "correct": false, "text_en": "to the non-aligned states"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-202.png"}, "question_en": "To which side did the DDR belong during the Cold War?", "asking_note": "Tests Cold War alliances. The DDR was in the Soviet/Eastern bloc. The distractors are the Western alliances or the non-aligned group.", "answer_explanation": "The DDR was aligned with the Soviet Union and was a member of the Warsaw Pact, the military alliance of the communist Eastern bloc formed in 1955. West Germany, by contrast, belonged to NATO and the Western powers.", "distractor_notes": ["The Western powers (USA, UK, France) were the Cold War opponents of the Eastern bloc; the DDR did not belong to them.", "", "NATO was the Western military alliance; West Germany joined it, but the DDR did not.", "The non-aligned states were countries that took neither side; the DDR was firmly in the Soviet bloc, not neutral."]}, {"id": 203, "id_str": "203", "category": "general", "exam_pool": "general", "question_de": "Wie hieß das Wirtschaftssystem der DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "Marktwirtschaft", "correct": false, "text_en": "market economy"}, {"text_de": "Planwirtschaft", "correct": true, "text_en": "planned economy"}, {"text_de": "Angebot und Nachfrage", "correct": false, "text_en": "supply and demand"}, {"text_de": "Kapitalismus", "correct": false, "text_en": "capitalism"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-203.png"}, "question_en": "What was the DDR's economic system called?", "asking_note": "Tests the term for the DDR's centrally directed economy. The distractors are all features of a capitalist/market economy — the opposite of the DDR system.", "answer_explanation": "The DDR had a 'Planwirtschaft' (planned economy), in which the state owned the means of production and central authorities set output targets, prices and distribution rather than the market. This contrasts with the social market economy of West Germany.", "distractor_notes": ["A market economy is the system of West Germany, where prices and production respond to the market — the opposite of the DDR.", "", "'Supply and demand' describes how prices form in a market economy, not the DDR's centrally planned system.", "Capitalism is the Western economic system based on private ownership; the DDR was socialist."]}, {"id": 204, "id_str": "204", "category": "general", "exam_pool": "general", "question_de": "Wie wurden die Bundesrepublik Deutschland und die DDR zu einem Staat?", "question_image": null, "image_kind": null, "options": [{"text_de": "Die Bundesrepublik hat die DDR besetzt.", "correct": false, "text_en": "The Federal Republic occupied the DDR."}, {"text_de": "Die heutigen fünf östlichen Bundesländer sind der Bundesrepublik Deutschland beigetreten.", "correct": true, "text_en": "Today's five eastern federal states acceded to the Federal Republic of Germany."}, {"text_de": "Die westlichen Bundesländer sind der DDR beigetreten.", "correct": false, "text_en": "The western federal states acceded to the DDR."}, {"text_de": "Die DDR hat die Bundesrepublik Deutschland besetzt.", "correct": false, "text_en": "The DDR occupied the Federal Republic of Germany."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-204.png"}, "question_en": "How did the Federal Republic of Germany and the DDR become a single state?", "asking_note": "Tests how reunification actually happened — legally, the eastern states joined (acceded to) the existing Federal Republic. The distractors describe an occupation or the reverse direction, which are false.", "answer_explanation": "Reunification happened by accession: on 3 October 1990, the five re-established eastern states joined the Federal Republic under Article 23 of the Basic Law (as it then read). The Federal Republic and its Basic Law (Grundgesetz) continued to exist; the DDR ceased to exist. It was a voluntary, legal accession, not a military conquest.", "distractor_notes": ["There was no military occupation; reunification was a peaceful, legal process.", "", "The direction is reversed — the eastern states joined the Federal Republic, not the other way around.", "The DDR did not occupy the Federal Republic; this is the opposite of what happened."]}, {"id": 205, "id_str": "205", "category": "general", "exam_pool": "general", "question_de": "Mit dem Beitritt der DDR zur Bundesrepublik Deutschland gehören die neuen Bundesländer nun auch …", "question_image": null, "image_kind": null, "options": [{"text_de": "zur Europäischen Union.", "correct": true, "text_en": "the European Union."}, {"text_de": "zum Warschauer Pakt.", "correct": false, "text_en": "the Warsaw Pact."}, {"text_de": "zur OPEC.", "correct": false, "text_en": "OPEC."}, {"text_de": "zur Europäischen Verteidigungsgemeinschaft.", "correct": false, "text_en": "the European Defence Community."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-205.png"}, "question_en": "With the accession of the DDR to the Federal Republic of Germany, the new federal states now also belong to ...", "asking_note": "Tests a consequence of reunification: the eastern states automatically became part of what West Germany already belonged to. The trap is the Warsaw Pact (which the DDR was leaving) and other bodies Germany was never in as a member state.", "answer_explanation": "Because West Germany was a member of the European Community (now the European Union), the former DDR territory automatically became part of the EU upon reunification in 1990. The eastern states thereby joined the Western integration structures West Germany had built up since the 1950s.", "distractor_notes": ["", "The Warsaw Pact was the Eastern bloc alliance the DDR was leaving; the new states did not join it — it dissolved in 1991.", "OPEC is the organisation of oil-exporting countries; Germany is not a member.", "The European Defence Community was a 1950s project that was never realised, so no one 'belongs' to it."]}, {"id": 206, "id_str": "206", "category": "general", "exam_pool": "general", "question_de": "Woran erinnern die sogenannten „Stolpersteine“ in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "an berühmte deutsche Politikerinnen und Politiker", "correct": false, "text_en": "famous German politicians"}, {"text_de": "an die Opfer des Nationalsozialismus", "correct": true, "text_en": "the victims of National Socialism"}, {"text_de": "an Verkehrstote", "correct": false, "text_en": "road traffic deaths"}, {"text_de": "an bekannte jüdische Musiker", "correct": false, "text_en": "well-known Jewish musicians"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-206.png"}, "question_en": "What do the so-called 'Stolpersteine' (stumbling stones) in Germany commemorate?", "asking_note": "Tests knowledge of a specific form of memorial. The distractors are plausible-sounding but wrong; the stones are specifically about Nazi victims, not traffic deaths or musicians.", "answer_explanation": "'Stolpersteine' are small brass plaques set into the pavement in front of the last freely chosen homes of people persecuted and murdered by the Nazis. Created by artist Gunter Demnig, each stone bears a victim's name and dates, commemorating the victims of National Socialism (Jews, Sinti and Roma, political prisoners, and others).", "distractor_notes": ["The stones do not honour politicians; they name ordinary victims of Nazi persecution.", "", "They are not traffic-death markers, despite being set in the pavement.", "They commemorate all victims of Nazism, not specifically Jewish musicians."]}, {"id": 207, "id_str": "207", "category": "general", "exam_pool": "general", "question_de": "In welchem Militärbündnis war die DDR Mitglied?", "question_image": null, "image_kind": null, "options": [{"text_de": "in der NATO", "correct": false, "text_en": "in NATO"}, {"text_de": "im Rheinbund", "correct": false, "text_en": "in the Confederation of the Rhine"}, {"text_de": "im Warschauer Pakt", "correct": true, "text_en": "in the Warsaw Pact"}, {"text_de": "im Europabündnis", "correct": false, "text_en": "in the Europe Alliance"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-207.png"}, "question_en": "Of which military alliance was the DDR a member?", "asking_note": "Same fact as Q202 but framed as 'military alliance'. Pick the Warsaw Pact. NATO is the Western alliance; the other two options are fictional or historical non-military names.", "answer_explanation": "The DDR was a member of the Warsaw Pact, the military alliance of the Soviet Union and its Eastern European satellite states, founded in 1955 as the Eastern counterpart to NATO. Its members were the communist states behind the Iron Curtain.", "distractor_notes": ["NATO was the Western military alliance; West Germany joined it, the DDR did not.", "The Confederation of the Rhine (Rheinbund) was a Napoleonic-era grouping from 1806, not a Cold War alliance.", "", "There is no military alliance called the 'Europabündnis' (Europe Alliance); it is a made-up name."]}, {"id": 208, "id_str": "208", "category": "general", "exam_pool": "general", "question_de": "Was war die \"Stasi\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Geheimdienst im \"Dritten Reich\"", "correct": false, "text_en": "the secret service of the 'Third Reich'"}, {"text_de": "eine berühmte deutsche Gedenkstätte", "correct": false, "text_en": "a famous German memorial site"}, {"text_de": "der Geheimdienst der DDR", "correct": true, "text_en": "the secret service of the DDR"}, {"text_de": "ein deutscher Sportverein während des Zweiten Weltkrieges", "correct": false, "text_en": "a German sports club during the Second World War"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-208.png"}, "question_en": "What was the 'Stasi'?", "asking_note": "Same topic as Q199 but asking directly what the Stasi was. Correct answer: the DDR's secret service/secret police. Trap: the Nazi-era secret service (Gestapo) is a different thing.", "answer_explanation": "The Stasi (Ministerium für Staatssicherheit) was the secret police and intelligence service of the DDR. It surveilled the population through a huge network of informants and suppressed opposition to keep the SED regime in power.", "distractor_notes": ["The Nazi-era secret police was the Gestapo, a different organisation from a different era.", "The Stasi was a state security agency, not a memorial site.", "", "The Stasi had nothing to do with a sports club; this option is nonsensical."]}, {"id": 209, "id_str": "209", "category": "general", "exam_pool": "general", "question_de": "Welches war das Wappen der Deutschen Demokratischen Republik?", "question_image": null, "image_kind": "options", "options": [{"text_de": "Bild 1", "correct": false, "image": "assets/img/q209-opt1.png", "text_en": "Picture 1"}, {"text_de": "Bild 2", "correct": false, "image": "assets/img/q209-opt2.png", "text_en": "Picture 2"}, {"text_de": "Bild 3", "correct": false, "image": "assets/img/q209-opt3.png", "text_en": "Picture 3"}, {"text_de": "Bild 4", "correct": true, "image": "assets/img/q209-opt4.png", "text_en": "Picture 4"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "numeric", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-209.png"}, "question_en": "Which was the coat of arms (state emblem) of the German Democratic Republic (DDR)?", "asking_note": "The four options are pictures: you must pick the correct image, Picture 4. The DDR emblem is a hammer and compass surrounded by a ring of grain — distinguish it from the Federal eagle and other emblems.", "answer_explanation": "The DDR's state emblem (Staatswappen) was a hammer and a compass (or drafting compass) encircled by a wreath/ring of grain, bound with the black-red-gold ribbon. The hammer represented workers, the compass the intelligentsia, and the grain the farmers — symbolising the 'workers' and peasants' state'. The correct picture is the one showing this emblem.", "distractor_notes": ["A picture showing a different emblem (e.g. the Federal eagle) — not the DDR.", "A picture showing a different emblem — not the DDR.", "A picture showing a different emblem — not the DDR.", ""]}, {"id": 210, "id_str": "210", "category": "general", "exam_pool": "general", "question_de": "Was ereignete sich am 17. Juni 1953 in der DDR?", "question_image": null, "image_kind": null, "options": [{"text_de": "der feierliche Beitritt zum Warschauer Pakt", "correct": false, "text_en": "the ceremonial accession to the Warsaw Pact"}, {"text_de": "landesweite Streiks und ein Volksaufstand", "correct": true, "text_en": "nationwide strikes and a popular uprising"}, {"text_de": "der 1. SED-Parteitag", "correct": false, "text_en": "the 1st SED party congress"}, {"text_de": "der erste Besuch Fidel Castros", "correct": false, "text_en": "the first visit of Fidel Castro"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-210.png"}, "question_en": "What happened on 17 June 1953 in the DDR?", "asking_note": "Tests knowledge of the 1953 popular uprising. The distractors are other DDR-related events; pick the strikes and popular uprising that were violently crushed by Soviet tanks.", "answer_explanation": "On 17 June 1953, workers' strikes over raised production quotas escalated into a nationwide popular uprising (Volksaufstand) across the DDR. It was crushed by Soviet tanks, with deaths and arrests. In West Germany, 17 June was later observed for decades as a national day of remembrance.", "distractor_notes": ["The DDR joined the Warsaw Pact in 1955, not on this date, and not as the event of 17 June 1953.", "", "The SED's founding congress was in 1946; this is not what happened on 17 June 1953.", "Fidel Castro's DDR visit came much later (1972); it is unrelated to 1953."]}, {"id": 211, "id_str": "211", "category": "general", "exam_pool": "general", "question_de": "Welcher Politiker steht für die \"Ostverträge\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "Helmut Kohl", "correct": false, "text_en": "Helmut Kohl"}, {"text_de": "Willy Brandt", "correct": true, "text_en": "Willy Brandt"}, {"text_de": "Michail Gorbatschow", "correct": false, "text_en": "Mikhail Gorbachev"}, {"text_de": "Ludwig Erhard", "correct": false, "text_en": "Ludwig Erhard"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-211.png"}, "question_en": "Which politician is associated with the 'Ostverträge' (Eastern Treaties)?", "asking_note": "Tests which chancellor is linked to the détente policy toward the Eastern bloc ('Ostpolitik'). The distractors are other well-known chancellors from different eras/policies.", "answer_explanation": "Willy Brandt, Social Democratic chancellor of West Germany from 1969 to 1974, pursued 'Ostpolitik' — a policy of reconciliation with the Eastern bloc. His government signed the 'Ostverträge' (Eastern Treaties) with the Soviet Union and Poland in 1970, recognising post-war borders and easing tensions. He received the Nobel Peace Prize in 1971.", "distractor_notes": ["Helmut Kohl was the chancellor of reunification in 1990, a different era and policy.", "", "Mikhail Gorbachev was the Soviet leader in the 1980s, not a German politician behind the Eastern Treaties.", "Ludwig Erhard was the chancellor and economics minister known for West Germany's post-war 'economic miracle', not the Eastern Treaties."]}, {"id": 212, "id_str": "212", "category": "general", "exam_pool": "general", "question_de": "Wie heißt Deutschland mit vollem Namen?", "question_image": null, "image_kind": null, "options": [{"text_de": "Bundesstaat Deutschland", "correct": false, "text_en": "Federal State of Germany"}, {"text_de": "Bundesländer Deutschland", "correct": false, "text_en": "Federal States of Germany"}, {"text_de": "Bundesrepublik Deutschland", "correct": true, "text_en": "Federal Republic of Germany"}, {"text_de": "Bundesbezirk Deutschland", "correct": false, "text_en": "Federal District of Germany"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-212.png"}, "question_en": "What is Germany's full official name?", "asking_note": "Tests the official name of the state. The distractors substitute a wrong noun ('Bundesstaat', 'Bundesländer', 'Bundesbezirk') for 'Bundesrepublik'.", "answer_explanation": "Germany's full official name is the 'Bundesrepublik Deutschland' (Federal Republic of Germany). It is a federal (bund) republic (republik) made up of 16 federal states (Bundesländer), as established by the Basic Law (Grundgesetz).", "distractor_notes": ["'Bundesstaat Deutschland' is not the official name, although Germany is a federal state in structure.", "'Bundesländer Deutschland' is not a name; Bundesländer are the constituent states.", "", "'Bundesbezirk Deutschland' is invented; there is no such term for the country."]}, {"id": 213, "id_str": "213", "category": "general", "exam_pool": "general", "question_de": "Wie viele Einwohner hat Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "70 Millionen", "correct": false, "text_en": "70 million"}, {"text_de": "78 Millionen", "correct": false, "text_en": "78 million"}, {"text_de": "84 Millionen", "correct": true, "text_en": "84 million"}, {"text_de": "90 Millionen", "correct": false, "text_en": "90 million"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-213.png"}, "question_en": "How many inhabitants does Germany have?", "asking_note": "Tests approximate current population. The official test answer is about 84 million; pick the closest figure. The distractors are notably too low or too high.", "answer_explanation": "Germany has roughly 84 million inhabitants, making it the most populous country in the European Union. This is the figure used in the current citizenship-test answer key.", "distractor_notes": ["70 million is too low for Germany's current population.", "78 million is too low; it understates the actual figure.", "", "90 million overstates Germany's population."]}, {"id": 214, "id_str": "214", "category": "general", "exam_pool": "general", "question_de": "Welche Farben hat die deutsche Flagge?", "question_image": null, "image_kind": null, "options": [{"text_de": "schwarz-rot-gold", "correct": true, "text_en": "black-red-gold"}, {"text_de": "rot-weiß-schwarz", "correct": false, "text_en": "red-white-black"}, {"text_de": "schwarz-rot-grün", "correct": false, "text_en": "black-red-green"}, {"text_de": "schwarz-gelb-rot", "correct": false, "text_en": "black-yellow-red"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-214.png"}, "question_en": "What colours does the German flag have?", "asking_note": "Basic recall of the national colours. The distractors reorder or swap colours (e.g. black-yellow-red, or add green) to catch inattentive readers.", "answer_explanation": "The German flag is black-red-gold (schwarz-rot-gold), in three horizontal stripes. These colours date back to the 19th-century democratic movement and were adopted by the Federal Republic; they are enshrined in Article 22 of the Basic Law.", "distractor_notes": ["", "Red-white-black were the colours of the German Empire (1871–1918) and were later misused by the Nazis — not today's flag.", "Black-red-green is not the German flag; green is not one of the colours.", "Black-yellow-red is the wrong order and 'yellow' rather than 'gold'; the correct sequence is black-red-gold."]}, {"id": 215, "id_str": "215", "category": "general", "exam_pool": "general", "question_de": "Wer wird als \"Kanzler der Deutschen Einheit\" bezeichnet?", "question_image": null, "image_kind": null, "options": [{"text_de": "Gerhard Schröder", "correct": false, "text_en": "Gerhard Schröder"}, {"text_de": "Helmut Kohl", "correct": true, "text_en": "Helmut Kohl"}, {"text_de": "Konrad Adenauer", "correct": false, "text_en": "Konrad Adenauer"}, {"text_de": "Helmut Schmidt", "correct": false, "text_en": "Helmut Schmidt"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-215.png"}, "question_en": "Who is referred to as the 'Chancellor of German Unity'?", "asking_note": "Tests which chancellor oversaw reunification. The distractors are other chancellors from different eras; pick the one in office in 1990.", "answer_explanation": "Helmut Kohl, chancellor from 1982 to 1998, is called the 'Kanzler der Deutschen Einheit' (Chancellor of German Unity) because he led West Germany through the reunification process in 1989–90, negotiating the terms of unity and the international 'Two Plus Four' agreement.", "distractor_notes": ["Gerhard Schröder was chancellor from 1998 to 2005, after reunification.", "", "Konrad Adenauer was the first post-war chancellor (1949–1963), decades before reunification.", "Helmut Schmidt was chancellor in the 1970s–early 1980s, before reunification."]}, {"id": 216, "id_str": "216", "category": "general", "exam_pool": "general", "question_de": "Welches Symbol ist im Plenarsaal des Deutschen Bundestages zu sehen?", "question_image": "assets/img/q216-stem.png", "image_kind": "stem", "options": [{"text_de": "der Bundesadler", "correct": true, "text_en": "the Federal Eagle"}, {"text_de": "die Fahne der Stadt Berlin", "correct": false, "text_en": "the flag of the city of Berlin"}, {"text_de": "der Reichsadler", "correct": false, "text_en": "the Imperial Eagle"}, {"text_de": "die Reichskrone", "correct": false, "text_en": "the Imperial Crown"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-216.png"}, "question_en": "Which symbol can be seen in the plenary chamber of the German Bundestag?", "asking_note": "The question refers to an image of the parliament's chamber. It tests the difference between today's Federal Eagle and older imperial symbols. Trap: the historical 'Reichsadler' and 'Reichskrone' are wrong — they belong to the empire, not today's democracy.", "answer_explanation": "The large stylised eagle mounted in the plenary chamber of the Bundestag is the 'Bundesadler' (Federal Eagle), the coat of arms of the Federal Republic of Germany. The eagle is a centuries-old German symbol, but its modern federal form represents today's democratic state.", "distractor_notes": ["", "The flag of the city of Berlin (a bear) is a municipal symbol, not the emblem in the Bundestag chamber.", "The 'Reichsadler' (Imperial Eagle) belonged to earlier German empires/regimes, not today's Federal Republic.", "The 'Reichskrone' (Imperial Crown) is a historic monarchical regalia and is not displayed in the Bundestag."]}, {"id": 217, "id_str": "217", "category": "general", "exam_pool": "general", "question_de": "In welchem Zeitraum gab es die Deutsche Demokratische Republik (DDR)?", "question_image": null, "image_kind": null, "options": [{"text_de": "1919 bis 1927", "correct": false, "text_en": "1919 to 1927"}, {"text_de": "1933 bis 1945", "correct": false, "text_en": "1933 to 1945"}, {"text_de": "1945 bis 1961", "correct": false, "text_en": "1945 to 1961"}, {"text_de": "1949 bis 1990", "correct": true, "text_en": "1949 to 1990"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-217.png"}, "question_en": "During which period did the German Democratic Republic (DDR) exist?", "asking_note": "Tests the lifespan of the DDR. It was founded in 1949 and ceased to exist at reunification in 1990. The distractors are earlier German historical periods (Weimar, Nazi era, early post-war).", "answer_explanation": "The DDR existed from its founding on 7 October 1949 until it acceded to the Federal Republic on 3 October 1990. It was created in the Soviet occupation zone after World War II, in the same year the Federal Republic was founded in the western zones.", "distractor_notes": ["1919–1927 falls within the Weimar Republic; the DDR did not yet exist.", "1933–1945 was the Nazi era ('Third Reich'), before the DDR was founded.", "1945–1961 covers the post-war occupation and early divided Germany, but the DDR started in 1949 and lasted until 1990, not only to 1961.", ""]}, {"id": 218, "id_str": "218", "category": "general", "exam_pool": "general", "question_de": "Wie viele Bundesländer kamen bei der Wiedervereinigung 1990 zur Bundesrepublik Deutschland hinzu?", "question_image": null, "image_kind": null, "options": [{"text_de": "4", "correct": false, "text_en": "4"}, {"text_de": "5", "correct": true, "text_en": "5"}, {"text_de": "6", "correct": false, "text_en": "6"}, {"text_de": "7", "correct": false, "text_en": "7"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-218.png"}, "question_en": "How many federal states joined the Federal Republic of Germany when the country was reunified in 1990?", "asking_note": "Tests the fact that reunification added the five 'new' eastern states. The numbers 4, 6 and 7 are near-miss distractors, so recall the exact figure rather than guessing.", "answer_explanation": "On 3 October 1990 the territory of the former GDR joined the Federal Republic as five re-established states: Brandenburg, Mecklenburg-Vorpommern, Sachsen, Sachsen-Anhalt and Thüringen. These are collectively called the 'neue Länder' (new states), bringing Germany from 11 to 16 states in total (East and West Berlin were also merged into one city-state).", "distractor_notes": ["Too few — there were five new eastern states, not four.", "", "Too many — Germany went from 11 to 16 states, an increase of five, not six.", "Too many — the increase was five states, not seven."]}, {"id": 219, "id_str": "219", "category": "general", "exam_pool": "general", "question_de": "Die Bundesrepublik Deutschland hat die Grenzen von heute seit …", "question_image": null, "image_kind": null, "options": [{"text_de": "1933", "correct": false, "text_en": "1933"}, {"text_de": "1949", "correct": false, "text_en": "1949"}, {"text_de": "1971", "correct": false, "text_en": "1971"}, {"text_de": "1990", "correct": true, "text_en": "1990"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-219.png"}, "question_en": "The Federal Republic of Germany has had its present-day borders since …", "asking_note": "Tests when Germany's modern borders were finalised. The years offered map to Nazi seizure of power, the founding of West Germany and Cold War treaties, so distinguish reunification (1990) from those earlier dates.", "answer_explanation": "Germany's current borders date from reunification on 3 October 1990, when the GDR joined the Federal Republic. The accompanying Two-Plus-Four Treaty settled the country's external borders in international law, confirming the Oder-Neiße line with Poland and closing the 'German question' left open since 1945.", "distractor_notes": ["1933 was the year the Nazis took power, not a border settlement.", "1949 was the founding of the Federal Republic (West Germany), which had different borders and did not include the East.", "1971 falls in the Cold War; Germany was still divided and no border settlement occurred then.", ""]}, {"id": 220, "id_str": "220", "category": "general", "exam_pool": "general", "question_de": "Der 27. Januar ist in Deutschland ein offizieller Gedenktag. Woran erinnert dieser Tag?", "question_image": null, "image_kind": null, "options": [{"text_de": "an das Ende des Zweiten Weltkrieges", "correct": false, "text_en": "the end of the Second World War"}, {"text_de": "an die Verabschiedung des Grundgesetzes", "correct": false, "text_en": "the adoption of the Basic Law (Grundgesetz)"}, {"text_de": "an die Wiedervereinigung Deutschlands", "correct": false, "text_en": "the reunification of Germany"}, {"text_de": "an die Opfer des Nationalsozialismus (Tag der Befreiung des Vernichtungslagers Auschwitz)", "correct": true, "text_en": "the victims of National Socialism (day of the liberation of the Auschwitz extermination camp)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-220.png"}, "question_en": "The 27th of January is an official day of remembrance in Germany. What does this day commemorate?", "asking_note": "Tests knowledge of Germany's official Holocaust remembrance day. All four options are real historical milestones, so match the specific date (27 January) to the correct event rather than picking any plausible one.", "answer_explanation": "27 January is the national Day of Remembrance for the Victims of National Socialism, marking the day in 1945 that the Auschwitz-Birkenau extermination camp was liberated. It was established as an official memorial day by Federal President Roman Herzog in 1996, and the United Nations later adopted the same date as International Holocaust Remembrance Day.", "distractor_notes": ["The end of WWII in Europe was 8 May 1945 (Tag der Befreiung / Kriegsende), a different date.", "The Basic Law was adopted on 23 May 1949, not commemorated on 27 January.", "Reunification is commemorated on 3 October, the Tag der Deutschen Einheit.", ""]}, {"id": 221, "id_str": "221", "category": "general", "exam_pool": "general", "question_de": "Deutschland ist Mitglied des Schengener Abkommens. Was bedeutet das?", "question_image": null, "image_kind": null, "options": [{"text_de": "Deutsche können in viele Länder Europas ohne Passkontrolle reisen.", "correct": true, "text_en": "Germans can travel to many European countries without passport control."}, {"text_de": "Alle Menschen können ohne Personenkontrolle in Deutschland einreisen.", "correct": false, "text_en": "Anyone can enter Germany without any identity check."}, {"text_de": "Deutsche können ohne Passkontrolle in jedes Land reisen.", "correct": false, "text_en": "Germans can travel to every country in the world without passport control."}, {"text_de": "Deutsche können in jedem Land mit dem Euro bezahlen.", "correct": false, "text_en": "Germans can pay with the euro in every country."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-221.png"}, "question_en": "Germany is a member of the Schengen Agreement. What does that mean?", "asking_note": "Tests what Schengen actually guarantees — free movement without passport checks within the area. Watch the overreaching distractors: Schengen does not open the border to 'everyone', is not worldwide, and is not about currency (that is the Eurozone).", "answer_explanation": "The Schengen Agreement abolished systematic checks at the internal borders between participating states, so people can cross from one Schengen country to another without passport control. It covers most EU countries plus a few others (such as Switzerland and Norway), but not the entire world.", "distractor_notes": ["", "Wrong scope — Schengen only removes checks between member states; entry into the area is still controlled and not open to literally everyone.", "Too broad — Schengen applies only to member states, not to every country on earth.", "That describes the euro/Eurozone (a monetary matter), not the Schengen free-movement rules."]}, {"id": 222, "id_str": "222", "category": "general", "exam_pool": "general", "question_de": "Welches Land ist ein Nachbarland von Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Ungarn", "correct": false, "text_en": "Hungary"}, {"text_de": "Portugal", "correct": false, "text_en": "Portugal"}, {"text_de": "Spanien", "correct": false, "text_en": "Spain"}, {"text_de": "Schweiz", "correct": true, "text_en": "Switzerland"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-222.png"}, "question_en": "Which country is a neighbour of Germany?", "asking_note": "Tests the nine countries bordering Germany. The distractors are all European but not adjacent, so recall Germany's actual land neighbours.", "answer_explanation": "Switzerland borders Germany to the south, along Lake Constance and the High Rhine. Germany has nine neighbouring countries in total: Denmark, Poland, the Czech Republic, Austria, Switzerland, France, Luxembourg, Belgium and the Netherlands.", "distractor_notes": ["Hungary lies in Central-Eastern Europe and does not border Germany (Austria and others lie between).", "Portugal is on the Iberian Peninsula in the far west and does not border Germany.", "Spain is on the Iberian Peninsula and does not border Germany.", ""]}, {"id": 223, "id_str": "223", "category": "general", "exam_pool": "general", "question_de": "Welches Land ist ein Nachbarland von Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Rumänien", "correct": false, "text_en": "Romania"}, {"text_de": "Bulgarien", "correct": false, "text_en": "Bulgaria"}, {"text_de": "Polen", "correct": true, "text_en": "Poland"}, {"text_de": "Griechenland", "correct": false, "text_en": "Greece"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-223.png"}, "question_en": "Which country is a neighbour of Germany?", "asking_note": "Tests Germany's land borders again. The distractors are all south-eastern European countries; only one shares a border with Germany.", "answer_explanation": "Poland borders Germany to the east, along the Oder-Neiße line. It is one of Germany's nine neighbouring countries.", "distractor_notes": ["Romania is in south-eastern Europe and does not border Germany.", "Bulgaria is in south-eastern Europe (on the Black Sea) and does not border Germany.", "", "Greece is in south-eastern Europe and does not border Germany."]}, {"id": 224, "id_str": "224", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet die Abkürzung EU?", "question_image": null, "image_kind": null, "options": [{"text_de": "Europäische Unternehmen", "correct": false, "text_en": "European Enterprises (Europäische Unternehmen)"}, {"text_de": "Europäische Union", "correct": true, "text_en": "European Union (Europäische Union)"}, {"text_de": "Einheitliche Union", "correct": false, "text_en": "Unified Union (Einheitliche Union)"}, {"text_de": "Euro Union", "correct": false, "text_en": "Euro Union"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-224.png"}, "question_en": "What does the abbreviation 'EU' stand for?", "asking_note": "Simple vocabulary check on what 'EU' means. The distractors are invented look-alike phrases, so pick the real name.", "answer_explanation": "EU stands for 'Europäische Union' — the European Union, the political and economic union of European member states, established in its current form by the Maastricht Treaty in 1993. Germany has been a member since its founding.", "distractor_notes": ["Not a real term — 'EU' does not stand for European Enterprises.", "", "Invented phrase; not what the abbreviation means.", "Confuses the currency (euro) with the name of the union."]}, {"id": 225, "id_str": "225", "category": "general", "exam_pool": "general", "question_de": "In welchem anderen Land gibt es eine große deutschsprachige Bevölkerung?", "question_image": null, "image_kind": null, "options": [{"text_de": "Tschechien", "correct": false, "text_en": "Czech Republic"}, {"text_de": "Norwegen", "correct": false, "text_en": "Norway"}, {"text_de": "Spanien", "correct": false, "text_en": "Spain"}, {"text_de": "Österreich", "correct": true, "text_en": "Austria"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-225.png"}, "question_en": "In which other country is there a large German-speaking population?", "asking_note": "Tests where German is widely spoken outside Germany. Only one option is a majority German-speaking country; note it is not simply Germany's neighbour with a German minority.", "answer_explanation": "German is the official and majority language of Austria, Germany's southern neighbour. German is also official in Switzerland, Liechtenstein, and parts of Belgium, Luxembourg and Italy (South Tyrol), but of the options given, Austria is the German-speaking country.", "distractor_notes": ["Czech is the main language of the Czech Republic; German is not widely spoken there today.", "Norwegian is spoken in Norway; it is not a German-speaking country.", "Spanish is spoken in Spain; it is not a German-speaking country.", ""]}, {"id": 226, "id_str": "226", "category": "general", "exam_pool": "general", "question_de": "Welche ist die Flagge der Europäischen Union?", "question_image": null, "image_kind": "options", "options": [{"text_de": "Bild 1", "correct": false, "image": "assets/img/q226-opt1.png", "text_en": "Picture 1"}, {"text_de": "Bild 2", "correct": true, "image": "assets/img/q226-opt2.png", "text_en": "Picture 2"}, {"text_de": "Bild 3", "correct": false, "image": "assets/img/q226-opt3.png", "text_en": "Picture 3"}, {"text_de": "Bild 4", "correct": false, "image": "assets/img/q226-opt4.png", "text_en": "Picture 4"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "numeric", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-226.png"}, "question_en": "Which one is the flag of the European Union?", "asking_note": "This is a picture question — the four options are images (Picture 1-4), and you must identify the EU flag: a circle of twelve golden stars on a blue background. Do not confuse it with a national flag.", "answer_explanation": "The flag of the European Union is a ring of twelve golden five-pointed stars on a blue field. The twelve stars symbolise unity, completeness and perfection — the number is fixed and does not represent the number of member states.", "distractor_notes": ["", "", "", ""]}, {"id": 227, "id_str": "227", "category": "general", "exam_pool": "general", "question_de": "Welches Land ist ein Nachbarland von Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Finnland", "correct": false, "text_en": "Finland"}, {"text_de": "Dänemark", "correct": true, "text_en": "Denmark"}, {"text_de": "Norwegen", "correct": false, "text_en": "Norway"}, {"text_de": "Schweden", "correct": false, "text_en": "Sweden"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-227.png"}, "question_en": "Which country is a neighbour of Germany?", "asking_note": "Tests Germany's land borders. All distractors are Nordic countries that do not touch Germany; only Denmark shares Germany's northern land border.", "answer_explanation": "Denmark is Germany's only northern land neighbour, bordering the state of Schleswig-Holstein on the Jutland peninsula. It is one of Germany's nine neighbouring countries.", "distractor_notes": ["Finland is in northern Europe and does not border Germany.", "", "Norway is in Scandinavia and does not border Germany.", "Sweden is in Scandinavia (across the Baltic Sea) and does not share a land border with Germany."]}, {"id": 228, "id_str": "228", "category": "general", "exam_pool": "general", "question_de": "Wie wird der Beitritt der DDR zur Bundesrepublik Deutschland im Jahr 1990 allgemein genannt?", "question_image": null, "image_kind": null, "options": [{"text_de": "NATO-Osterweiterung", "correct": false, "text_en": "NATO eastward enlargement"}, {"text_de": "EU-Osterweiterung", "correct": false, "text_en": "EU eastward enlargement"}, {"text_de": "Deutsche Wiedervereinigung", "correct": true, "text_en": "German reunification"}, {"text_de": "Europäische Gemeinschaft", "correct": false, "text_en": "European Community"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-228.png"}, "question_en": "What is the 1990 accession of the GDR to the Federal Republic of Germany commonly called?", "asking_note": "Tests the standard term for the events of 1990. The distractors are real but unrelated political processes (NATO/EU enlargement, the European Community), so match the term to the German context.", "answer_explanation": "The GDR's accession to the Federal Republic on 3 October 1990 is known as the 'Deutsche Wiedervereinigung' (German reunification), when the two German states that had existed since 1949 were joined into one. The date is now the national holiday, the Tag der Deutschen Einheit.", "distractor_notes": ["NATO eastward enlargement refers to former Eastern Bloc countries joining NATO after 1999 — not the joining of the two German states.", "EU eastward enlargement refers to Central and Eastern European countries joining the EU (notably in 2004) — a different event.", "", "The European Community was a stage of European integration, unrelated to the merging of the two German states."]}, {"id": 229, "id_str": "229", "category": "general", "exam_pool": "general", "question_de": "Welches Land ist ein Nachbarland von Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Spanien", "correct": false, "text_en": "Spain"}, {"text_de": "Bulgarien", "correct": false, "text_en": "Bulgaria"}, {"text_de": "Norwegen", "correct": false, "text_en": "Norway"}, {"text_de": "Luxemburg", "correct": true, "text_en": "Luxembourg"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-229.png"}, "question_en": "Which country is a neighbour of Germany?", "asking_note": "Tests Germany's land borders. Only one option is adjacent; the others are distant European countries.", "answer_explanation": "Luxembourg borders Germany to the west, along the Moselle and Sauer rivers. This small country is one of Germany's nine neighbours and a founding member of the European Economic Community.", "distractor_notes": ["Spain is on the Iberian Peninsula in the far west and does not border Germany.", "Bulgaria is in south-eastern Europe and does not border Germany.", "Norway is in Scandinavia and does not border Germany.", ""]}, {"id": 230, "id_str": "230", "category": "general", "exam_pool": "general", "question_de": "Das Europäische Parlament wird regelmäßig gewählt, nämlich alle …", "question_image": null, "image_kind": null, "options": [{"text_de": "5 Jahre.", "correct": true, "text_en": "5 years."}, {"text_de": "6 Jahre.", "correct": false, "text_en": "6 years."}, {"text_de": "7 Jahre.", "correct": false, "text_en": "7 years."}, {"text_de": "8 Jahre.", "correct": false, "text_en": "8 years."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-230.png"}, "question_en": "The European Parliament is elected at regular intervals, namely every …", "asking_note": "Tests the length of the European Parliament's term. The distractors are all plausible round numbers, so recall the exact figure.", "answer_explanation": "The European Parliament is directly elected by EU citizens every five years. Germans have voted in these elections since the first direct election in 1979; the elections give citizens a direct say in EU-level lawmaking.", "distractor_notes": ["", "The term is five years, not six.", "The term is five years, not seven.", "The term is five years, not eight."]}, {"id": 231, "id_str": "231", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet der Begriff \"europäische Integration\"?", "question_image": null, "image_kind": null, "options": [{"text_de": "Damit sind amerikanische Einwanderinnen und Einwanderer in Europa gemeint.", "correct": false, "text_en": "It refers to American immigrants in Europe."}, {"text_de": "Der Begriff meint den Einwanderungsstopp nach Europa.", "correct": false, "text_en": "The term means a halt to immigration into Europe."}, {"text_de": "Damit sind europäische Auswanderinnen und Auswanderer in den USA gemeint.", "correct": false, "text_en": "It refers to European emigrants who moved to the USA."}, {"text_de": "Der Begriff meint den Zusammenschluss europäischer Staaten zur EU.", "correct": true, "text_en": "The term means the joining-together of European states into the EU."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-231.png"}, "question_en": "What does the term 'European integration' mean?", "asking_note": "Tests the meaning of European integration. The distractors deliberately twist it into a migration or emigration issue; the correct answer is about states joining together politically and economically.", "answer_explanation": "European integration describes the process by which European states have progressively joined together — economically and politically — into the European Union, pooling parts of their sovereignty to secure peace, prosperity and cooperation on the continent after the Second World War.", "distractor_notes": ["Integration here is about states uniting, not about American immigrants in Europe.", "Wrong — the term is not about stopping immigration.", "Wrong — it is not about Europeans emigrating to the USA.", ""]}, {"id": 232, "id_str": "232", "category": "general", "exam_pool": "general", "question_de": "Wer wird bei der Europawahl gewählt?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Europäische Kommission", "correct": false, "text_en": "the European Commission"}, {"text_de": "die Länder, die in die EU eintreten dürfen", "correct": false, "text_en": "the countries allowed to join the EU"}, {"text_de": "die Abgeordneten des Europäischen Parlaments", "correct": true, "text_en": "the members of the European Parliament"}, {"text_de": "die europäische Verfassung", "correct": false, "text_en": "the European constitution"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-232.png"}, "question_en": "Who is elected in the European election?", "asking_note": "Tests what citizens actually vote for in EU elections. Watch the trap: the Commission and the 'constitution' are not directly elected, and candidate countries are not voted on by citizens.", "answer_explanation": "In the European election, EU citizens directly elect the Members of the European Parliament (the Abgeordnete / MEPs). The Parliament then helps shape EU legislation and, together with the member states, influences the composition of the European Commission.", "distractor_notes": ["The Commission is not directly elected by citizens; its President is proposed by the member states and confirmed by Parliament.", "Which countries may join the EU is decided by the member states and EU institutions, not by a citizen election.", "", "A constitution or treaty is not something citizens elect."]}, {"id": 233, "id_str": "233", "category": "general", "exam_pool": "general", "question_de": "Welches Land ist ein Nachbarland von Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Tschechien", "correct": true, "text_en": "Czech Republic"}, {"text_de": "Bulgarien", "correct": false, "text_en": "Bulgaria"}, {"text_de": "Griechenland", "correct": false, "text_en": "Greece"}, {"text_de": "Portugal", "correct": false, "text_en": "Portugal"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-233.png"}, "question_en": "Which country is a neighbour of Germany?", "asking_note": "Tests Germany's land borders. All distractors are south-eastern or south-western European countries that are not adjacent; only one shares a border.", "answer_explanation": "The Czech Republic borders Germany to the south-east, along the states of Bavaria and Saxony. It is one of Germany's nine neighbouring countries.", "distractor_notes": ["", "Bulgaria is in south-eastern Europe and does not border Germany.", "Greece is in south-eastern Europe and does not border Germany.", "Portugal is on the Iberian Peninsula in the far west and does not border Germany."]}, {"id": 234, "id_str": "234", "category": "general", "exam_pool": "general", "question_de": "Wo ist ein Sitz des Europäischen Parlaments?", "question_image": null, "image_kind": null, "options": [{"text_de": "London", "correct": false, "text_en": "London"}, {"text_de": "Paris", "correct": false, "text_en": "Paris"}, {"text_de": "Berlin", "correct": false, "text_en": "Berlin"}, {"text_de": "Straßburg", "correct": true, "text_en": "Strasbourg"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-234.png"}, "question_en": "Where is one seat of the European Parliament?", "asking_note": "Tests knowledge of the Parliament's official seat. The distractors are major European capitals; note the official seat is a French city that is not Paris.", "answer_explanation": "Strasbourg (Straßburg), in France near the German border, is the official seat of the European Parliament, where the formal plenary sessions are held. The Parliament also works in Brussels and Luxembourg, but Strasbourg is its symbolic home, chosen to represent Franco-German reconciliation.", "distractor_notes": ["London is in the UK, which has left the EU; it never hosted the European Parliament.", "Paris is the French capital but not a seat of the European Parliament.", "Berlin is Germany's capital, the seat of the Bundestag — not the European Parliament.", ""]}, {"id": 235, "id_str": "235", "category": "general", "exam_pool": "general", "question_de": "Der damalige französische Staatspräsident François Mitterrand und der damalige deutsche Bundeskanzler Helmut Kohl gedenken in Verdun gemeinsam der Toten beider Weltkriege. Welches Ziel der Europäischen Union wird bei diesem Treffen deutlich?", "question_image": "assets/img/q235-stem.png", "image_kind": "stem", "options": [{"text_de": "Freundschaft zwischen England und Deutschland", "correct": false, "text_en": "friendship between England and Germany"}, {"text_de": "Reisefreiheit in alle Länder der EU", "correct": false, "text_en": "freedom to travel to all EU countries"}, {"text_de": "Frieden und Sicherheit in den Ländern der EU", "correct": true, "text_en": "peace and security in the countries of the EU"}, {"text_de": "einheitliche Feiertage in den Ländern der EU", "correct": false, "text_en": "uniform public holidays in the EU countries"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-235.png"}, "question_en": "The French President François Mitterrand and the German Chancellor Helmut Kohl of the time jointly commemorate the dead of both world wars at Verdun. Which goal of the European Union becomes clear at this meeting?", "asking_note": "This question refers to a well-known photo/scene (the two leaders holding hands at Verdun). It tests the core purpose of European unification. The correct answer is the founding goal — peace; the distractors describe lesser or unrelated aims.", "answer_explanation": "The 1984 gesture at Verdun — where hundreds of thousands died in the First World War — symbolised Franco-German reconciliation and the central purpose of European unification: to secure lasting peace and security so that former enemies never again go to war. Preserving peace among its members is the founding motive of the European project.", "distractor_notes": ["The meeting was between France and Germany, not England; and it symbolised more than a bilateral friendship.", "Freedom of travel is a benefit of the EU, but not the goal this reconciliation gesture illustrates.", "", "Public holidays are not harmonised across the EU and are unrelated to this commemoration."]}, {"id": 236, "id_str": "236", "category": "general", "exam_pool": "general", "question_de": "Wie viele Mitgliedstaaten hat die EU heute?", "question_image": null, "image_kind": null, "options": [{"text_de": "21", "correct": false, "text_en": "21"}, {"text_de": "23", "correct": false, "text_en": "23"}, {"text_de": "25", "correct": false, "text_en": "25"}, {"text_de": "27", "correct": true, "text_en": "27"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-236.png"}, "question_en": "How many member states does the EU have today?", "asking_note": "Tests the current number of EU members. Remember that this figure changed after the United Kingdom left (Brexit), which is why the answer is lower than some older materials state.", "answer_explanation": "The EU currently has 27 member states. The number fell from 28 to 27 when the United Kingdom left the EU on 31 January 2020 (Brexit). Croatia, which joined in 2013, was the most recent country to accede.", "distractor_notes": ["Too low — the EU has 27 members, not 21.", "Too low — the EU has 27 members, not 23.", "Too low — the EU has 27 members, not 25.", ""]}, {"id": 237, "id_str": "237", "category": "general", "exam_pool": "general", "question_de": "2007 wurde das 50-jährige Jubiläum der \"Römischen Verträge\" gefeiert. Was war der Inhalt der Verträge?", "question_image": null, "image_kind": null, "options": [{"text_de": "Beitritt Deutschlands zur NATO", "correct": false, "text_en": "Germany's accession to NATO"}, {"text_de": "Gründung der Europäischen Wirtschaftsgemeinschaft (EWG)", "correct": true, "text_en": "the founding of the European Economic Community (EEC)"}, {"text_de": "Verpflichtung Deutschlands zu Reparationsleistungen", "correct": false, "text_en": "Germany's obligation to pay reparations"}, {"text_de": "Festlegung der Oder-Neiße-Linie als Ostgrenze", "correct": false, "text_en": "the fixing of the Oder-Neiße line as the eastern border"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-237.png"}, "question_en": "In 2007 the 50th anniversary of the 'Treaties of Rome' was celebrated. What was the content of these treaties?", "asking_note": "Tests what the 1957 Treaties of Rome established. The distractors mix in unrelated post-war milestones (NATO, reparations, the Oder-Neiße border); the correct answer is the founding of the EEC.", "answer_explanation": "The Treaties of Rome, signed in 1957 (in force 1958), founded the European Economic Community (EEC) and Euratom. They created a common market among the six founding states — including West Germany — and are considered a cornerstone of today's European Union, which is why their 50th anniversary was celebrated in 2007.", "distractor_notes": ["Germany (West Germany) joined NATO in 1955, a separate matter from the Treaties of Rome.", "", "Reparations were governed by post-war agreements, not the Treaties of Rome.", "The Oder-Neiße line was addressed by post-war and later German-Polish treaties, not the Treaties of Rome."]}, {"id": 238, "id_str": "238", "category": "general", "exam_pool": "general", "question_de": "An welchen Orten arbeitet das Europäische Parlament?", "question_image": null, "image_kind": null, "options": [{"text_de": "Paris, London und Den Haag", "correct": false, "text_en": "Paris, London and The Hague"}, {"text_de": "Straßburg, Luxemburg und Brüssel", "correct": true, "text_en": "Strasbourg, Luxembourg and Brussels"}, {"text_de": "Rom, Bern und Wien", "correct": false, "text_en": "Rome, Bern and Vienna"}, {"text_de": "Bonn, Zürich und Mailand", "correct": false, "text_en": "Bonn, Zurich and Milan"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-238.png"}, "question_en": "In which places does the European Parliament work?", "asking_note": "Tests the three working locations of the European Parliament. Each option is a set of three cities — only one lists all three correct EU cities. Note Parliament works across multiple sites, not just one.", "answer_explanation": "The European Parliament operates from three locations: Strasbourg (its official seat, where plenary sessions are held), Brussels (where committees meet and additional sessions take place) and Luxembourg (home to the Parliament's administrative offices, the General Secretariat).", "distractor_notes": ["Paris, London and The Hague are not the Parliament's working seats; the UK has also left the EU.", "", "Rome, Bern and Vienna are not seats of the Parliament — and Bern is in non-EU Switzerland.", "Bonn, Zurich and Milan are not Parliament seats — Bonn is a former West German capital and Zurich is in non-EU Switzerland."]}, {"id": 239, "id_str": "239", "category": "general", "exam_pool": "general", "question_de": "Durch welche Verträge schloss sich die Bundesrepublik Deutschland mit anderen Staaten zur Europäischen Wirtschaftsgemeinschaft zusammen?", "question_image": null, "image_kind": null, "options": [{"text_de": "durch die \"Hamburger Verträge\"", "correct": false, "text_en": "through the 'Hamburg Treaties'"}, {"text_de": "durch die \"Römischen Verträge\"", "correct": true, "text_en": "through the 'Treaties of Rome'"}, {"text_de": "durch die \"Pariser Verträge\"", "correct": false, "text_en": "through the 'Paris Treaties'"}, {"text_de": "durch die \"Londoner Verträge\"", "correct": false, "text_en": "through the 'London Treaties'"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-239.png"}, "question_en": "Through which treaties did the Federal Republic of Germany join together with other states to form the European Economic Community?", "asking_note": "Tests the name of the founding EEC treaties. All options are named after cities; recall that the EEC was founded by the treaties signed in Rome.", "answer_explanation": "The European Economic Community was founded by the Treaties of Rome, signed in Rome in 1957 by West Germany, France, Italy and the three Benelux countries. They established a common market and set European integration on the path that led to today's EU.", "distractor_notes": ["There are no 'Hamburg Treaties' founding the EEC.", "", "The Treaty of Paris (1951) founded the earlier Coal and Steel Community, not the EEC.", "There are no 'London Treaties' that founded the EEC."]}, {"id": 240, "id_str": "240", "category": "general", "exam_pool": "general", "question_de": "Seit wann bezahlt man in Deutschland mit dem Euro in bar?", "question_image": null, "image_kind": null, "options": [{"text_de": "1995", "correct": false, "text_en": "1995"}, {"text_de": "1998", "correct": false, "text_en": "1998"}, {"text_de": "2002", "correct": true, "text_en": "2002"}, {"text_de": "2005", "correct": false, "text_en": "2005"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-240.png"}, "question_en": "Since when has one paid with the euro in cash in Germany?", "asking_note": "Tests the year euro banknotes and coins entered circulation. Note the trap: the euro existed as an accounting currency from 1999, but physical cash arrived later.", "answer_explanation": "Euro banknotes and coins entered circulation on 1 January 2002, replacing the Deutsche Mark in everyday cash transactions. The euro had already existed as book money since 1999, but 2002 is when Germans began paying with it in cash.", "distractor_notes": ["In 1995 Germany still used the Deutsche Mark; the euro did not yet exist.", "The euro as an accounting currency began in 1999, not 1998; cash came in 2002.", "", "By 2005 the euro was already in use — cash was introduced earlier, in 2002."]}, {"id": 241, "id_str": "241", "category": "general", "exam_pool": "general", "question_de": "Frau Seger bekommt ein Kind. Was muss sie tun, um Elterngeld zu erhalten?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sie muss an ihre Krankenkasse schreiben.", "correct": false, "text_en": "She must write to her health insurance fund."}, {"text_de": "Sie muss einen Antrag bei der Elterngeldstelle stellen.", "correct": true, "text_en": "She must submit an application to the parental allowance office (Elterngeldstelle)."}, {"text_de": "Sie muss nichts tun, denn sie bekommt automatisch Elterngeld.", "correct": false, "text_en": "She does not need to do anything, because she receives parental allowance automatically."}, {"text_de": "Sie muss das Arbeitsamt um Erlaubnis bitten.", "correct": false, "text_en": "She must ask the employment office (Arbeitsamt) for permission."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-241.png"}, "question_en": "Frau Seger is having a child. What must she do in order to receive parental allowance (Elterngeld)?", "asking_note": "Tests the practical procedure for getting Elterngeld. The trap is option 2 ('she does nothing, it comes automatically') — German benefits generally require an application to the correct office.", "answer_explanation": "Elterngeld must be actively applied for; it is not paid automatically. Parents submit a written application to the responsible Elterngeldstelle (parental allowance office), which in Germany is typically a state or local authority. The benefit partly replaces income for parents who care for their newborn.", "distractor_notes": ["The health insurance fund handles maternity benefits (Mutterschaftsgeld) and medical matters, not Elterngeld applications.", "", "Wrong — Elterngeld is never automatic; it must be applied for.", "The employment office does not grant permission for Elterngeld; and no permission to have a child is needed."]}, {"id": 242, "id_str": "242", "category": "general", "exam_pool": "general", "question_de": "Wer entscheidet, ob ein Kind in Deutschland in den Kindergarten geht?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Staat", "correct": false, "text_en": "the state"}, {"text_de": "die Bundesländer", "correct": false, "text_en": "the federal states (Bundesländer)"}, {"text_de": "die Eltern/die Erziehungsberechtigten", "correct": true, "text_en": "the parents / legal guardians"}, {"text_de": "die Schulen", "correct": false, "text_en": "the schools"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-242.png"}, "question_en": "Who decides whether a child in Germany attends kindergarten?", "asking_note": "Tests that kindergarten (unlike school) is voluntary and is the parents' decision. Contrast with compulsory schooling, which is a state matter — a common point of confusion.", "answer_explanation": "Attending kindergarten is voluntary in Germany, so the decision rests with the parents or legal guardians. This differs from school, which is compulsory (Schulpflicht). Children do have a legal entitlement to a daycare/kindergarten place, but whether to take it up is the family's choice.", "distractor_notes": ["The state sets rules and guarantees a place, but does not decide whether an individual child attends kindergarten.", "The Bundesländer regulate education, but the kindergarten decision belongs to the parents.", "", "Schools deal with compulsory schooling, not the voluntary decision about kindergarten."]}, {"id": 243, "id_str": "243", "category": "general", "exam_pool": "general", "question_de": "Maik und Sybille wollen mit Freunden an ihrem deutschen Wohnort eine Demonstration auf der Straße abhalten. Was müssen sie vorher tun?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sie müssen die Demonstration anmelden.", "correct": true, "text_en": "They must register the demonstration."}, {"text_de": "Sie müssen nichts tun. Man darf in Deutschland jederzeit überall demonstrieren.", "correct": false, "text_en": "They need do nothing. In Germany you may demonstrate anywhere at any time."}, {"text_de": "Sie können gar nichts tun, denn Demonstrationen sind in Deutschland grundsätzlich verboten.", "correct": false, "text_en": "They can do nothing, because demonstrations are generally forbidden in Germany."}, {"text_de": "Maik und Sybille müssen einen neuen Verein gründen, weil nur Vereine demonstrieren dürfen.", "correct": false, "text_en": "Maik and Sybille must found a new club (Verein), because only clubs are allowed to demonstrate."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-243.png"}, "question_en": "Maik and Sybille want to hold a demonstration in the street at their German place of residence together with friends. What must they do beforehand?", "asking_note": "Tests the rules on freedom of assembly. Traps at both extremes: demonstrations are neither entirely unrestricted nor generally banned — they must be registered in advance.", "answer_explanation": "Freedom of assembly is guaranteed by Article 8 of the Basic Law, but an open-air demonstration must be registered (angemeldet) with the authorities in advance, usually about 48 hours before. This is a notification requirement, not a request for permission — the authorities cannot simply refuse, but registration lets them ensure public safety and traffic management.", "distractor_notes": ["", "Wrong — outdoor demonstrations require prior registration; you cannot simply demonstrate anywhere at any time.", "Wrong — demonstrations are a protected constitutional right, not generally forbidden.", "Wrong — no club is needed; the right to assemble belongs to individuals."]}, {"id": 244, "id_str": "244", "category": "general", "exam_pool": "general", "question_de": "Welchen Schulabschluss braucht man normalerweise, um an einer Universität in Deutschland ein Studium zu beginnen?", "question_image": null, "image_kind": null, "options": [{"text_de": "das Abitur", "correct": true, "text_en": "the Abitur"}, {"text_de": "ein Diplom", "correct": false, "text_en": "a Diplom"}, {"text_de": "die Prokura", "correct": false, "text_en": "the Prokura"}, {"text_de": "eine Gesellenprüfung", "correct": false, "text_en": "a journeyman's certificate (Gesellenprüfung)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-244.png"}, "question_en": "Which school-leaving qualification do you normally need to begin a degree at a university in Germany?", "asking_note": "Tests the standard university entrance qualification. The distractors are unrelated credentials (a university/vocational diploma, a business power of attorney, a trade certificate), so identify the school-leaving certificate.", "answer_explanation": "The Abitur is the general higher-education entrance qualification (allgemeine Hochschulreife), earned at the end of upper secondary school (Gymnasium). It is the standard prerequisite for enrolling in a university degree programme in Germany.", "distractor_notes": ["", "A Diplom is an academic degree awarded after completing study, not the qualification needed to start it.", "The Prokura is a commercial power of attorney in business law — nothing to do with university entry.", "The Gesellenprüfung is the exam completing a vocational apprenticeship (a trade qualification), not university entrance."]}, {"id": 245, "id_str": "245", "category": "general", "exam_pool": "general", "question_de": "Wer darf in Deutschland nicht als Paar zusammenleben?", "question_image": null, "image_kind": null, "options": [{"text_de": "Hans (20 Jahre) und Marie (19 Jahre)", "correct": false, "text_en": "Hans (20 years) and Marie (19 years)"}, {"text_de": "Tom (20 Jahre) und Klaus (45 Jahre)", "correct": false, "text_en": "Tom (20 years) and Klaus (45 years)"}, {"text_de": "Sofie (35 Jahre) und Lisa (40 Jahre)", "correct": false, "text_en": "Sofie (35 years) and Lisa (40 years)"}, {"text_de": "Anne (13 Jahre) und Tim (25 Jahre)", "correct": true, "text_en": "Anne (13 years) and Tim (25 years)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-245.png"}, "question_en": "Who in Germany is NOT allowed to live together as a couple?", "asking_note": "Negative framing — you must find the one pairing that is NOT permitted, i.e. the illegal couple. The trap tests whether you know that same-sex and age-gap couples between adults are all legal; the disqualifier is a minor (a 13-year-old) paired with an adult.", "answer_explanation": "Anne is only 13 — a child well below the age of consent and of legal majority (18). An adult forming a couple with a 13-year-old is not permitted and is criminal under German law protecting minors. By contrast, the other pairings are all between consenting adults; large age gaps and same-sex relationships between adults are fully legal in Germany.", "distractor_notes": ["Both are adults (20 and 19); this couple is perfectly legal.", "Both are adults (20 and 45); a same-sex couple with an age gap between adults is legal.", "Both are adults (35 and 40); a same-sex couple between adults is legal.", ""]}, {"id": 246, "id_str": "246", "category": "general", "exam_pool": "general", "question_de": "Ab welchem Alter ist man in Deutschland volljährig?", "question_image": null, "image_kind": null, "options": [{"text_de": "16", "correct": false, "text_en": "16"}, {"text_de": "18", "correct": true, "text_en": "18"}, {"text_de": "19", "correct": false, "text_en": "19"}, {"text_de": "21", "correct": false, "text_en": "21"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-246.png"}, "question_en": "At what age does one reach the age of majority (become an adult) in Germany?", "asking_note": "Tests the legal age of majority. The distractors include 16 (some limited rights, e.g. certain voting) and 19/21, but full legal adulthood has a single specific age.", "answer_explanation": "In Germany one becomes of legal age (volljährig) at 18. From that age a person has full legal capacity — can enter contracts independently, vote in all elections, and bears full legal responsibility for their actions.", "distractor_notes": ["At 16 a person has only limited rights (such as voting in some elections); full majority comes at 18.", "", "Majority is reached at 18, not 19.", "Majority is reached at 18, not 21."]}, {"id": 247, "id_str": "247", "category": "general", "exam_pool": "general", "question_de": "Eine Frau ist schwanger. Sie ist kurz vor und nach der Geburt ihres Kindes vom Gesetz besonders beschützt. Wie heißt dieser Schutz?", "question_image": null, "image_kind": null, "options": [{"text_de": "Elternzeit", "correct": false, "text_en": "parental leave (Elternzeit)"}, {"text_de": "Mutterschutz", "correct": true, "text_en": "maternity protection (Mutterschutz)"}, {"text_de": "Geburtsvorbereitung", "correct": false, "text_en": "birth preparation (Geburtsvorbereitung)"}, {"text_de": "Wochenbett", "correct": false, "text_en": "postpartum period / lying-in (Wochenbett)"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-247.png"}, "question_en": "A woman is pregnant. She is specially protected by law shortly before and after the birth of her child. What is this protection called?", "asking_note": "Tests the legal term for protection around childbirth. The trap is 'Elternzeit' (parental leave), which is related but different — Mutterschutz specifically protects the mother in the weeks around the birth.", "answer_explanation": "Mutterschutz is the statutory maternity protection covering the mother in the weeks immediately before and after childbirth — normally six weeks before and eight weeks after the birth. During this period she is protected from dismissal, generally must not work, and receives maternity pay.", "distractor_notes": ["Elternzeit is unpaid parental leave that either parent can take to raise a child later — not the specific legal protection around the birth itself.", "", "Geburtsvorbereitung refers to antenatal/birth-preparation classes, not a legal protection.", "Wochenbett is the informal term for the recovery weeks after birth, not the name of the legal protection."]}, {"id": 248, "id_str": "248", "category": "general", "exam_pool": "general", "question_de": "Die Erziehung der Kinder ist in Deutschland vor allem Aufgabe …", "question_image": null, "image_kind": null, "options": [{"text_de": "des Staates.", "correct": false, "text_en": "the state."}, {"text_de": "der Eltern.", "correct": true, "text_en": "the parents."}, {"text_de": "der Großeltern.", "correct": false, "text_en": "the grandparents."}, {"text_de": "der Schulen.", "correct": false, "text_en": "the schools."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-248.png"}, "question_en": "In Germany, raising children is above all the task of …", "asking_note": "Tests the constitutional principle of who is primarily responsible for child-rearing. The distractors (state, grandparents, schools) all play supporting roles, but the Basic Law names one party as primarily responsible.", "answer_explanation": "Article 6 of the Basic Law states that the care and upbringing of children is the natural right of the parents and a duty primarily incumbent upon them ('das natürliche Recht der Eltern'). The state watches over how they carry this out, but the primary responsibility for raising children lies with the parents.", "distractor_notes": ["The state only oversees and supports; it does not hold the primary responsibility for raising children.", "", "Grandparents may help, but the law places primary responsibility on the parents, not the grandparents.", "Schools educate children academically but are not primarily responsible for their upbringing."]}, {"id": 249, "id_str": "249", "category": "general", "exam_pool": "general", "question_de": "Wer ist in Deutschland hauptsächlich verantwortlich für die Kindererziehung?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Staat", "correct": false, "text_en": "the state"}, {"text_de": "die Eltern", "correct": true, "text_en": "the parents"}, {"text_de": "die Verwandten", "correct": false, "text_en": "relatives"}, {"text_de": "die Schulen", "correct": false, "text_en": "the schools"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-249.png"}, "question_en": "In Germany, who is primarily responsible for raising children?", "asking_note": "Tests the German legal principle that child-rearing is first and foremost a parental right and duty, not the state's. The distractors offer other actors (state, relatives, schools) who only play a supporting role.", "answer_explanation": "Under Article 6(2) of the Grundgesetz, the care and upbringing of children is 'the natural right of parents and a duty primarily incumbent upon them.' The state only supervises and steps in when the child's welfare is endangered; parents hold the primary responsibility.", "distractor_notes": ["The state (via the Jugendamt) only supervises and intervenes in cases of endangerment (Art. 6(2) GG); it is not the primary carer.", "", "Relatives may help but have no primary legal responsibility for a child's upbringing.", "Schools educate and share responsibility, but the primary duty of upbringing rests with the parents."]}, {"id": 250, "id_str": "250", "category": "general", "exam_pool": "general", "question_de": "In Deutschland hat man die besten Chancen auf einen gut bezahlten Arbeitsplatz, wenn man …", "question_image": null, "image_kind": null, "options": [{"text_de": "katholisch ist.", "correct": false, "text_en": "are Catholic."}, {"text_de": "gut ausgebildet ist.", "correct": true, "text_en": "are well educated."}, {"text_de": "eine Frau ist.", "correct": false, "text_en": "are a woman."}, {"text_de": "Mitglied einer Partei ist.", "correct": false, "text_en": "are a member of a political party."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-250.png"}, "question_en": "In Germany, you have the best chances of a well-paid job if you …", "asking_note": "Tests the meritocratic principle: qualifications, not religion, gender, or party membership, determine job prospects. The distractors are all traits that must NOT legally influence hiring.", "answer_explanation": "Germany's labour market is built on qualification and training (the dual education system, vocational qualifications, degrees). A good education and relevant skills are what open well-paid positions; discrimination on grounds such as religion or gender is prohibited by the General Equal Treatment Act (AGG) and Article 3 of the Grundgesetz.", "distractor_notes": ["Religion must not determine job prospects; discrimination on religious grounds is banned (AGG, Art. 3 GG).", "", "Gender must not determine hiring; women and men are equal before the law (Art. 3 GG).", "Party membership does not and must not decide who gets a well-paid job in Germany."]}, {"id": 251, "id_str": "251", "category": "general", "exam_pool": "general", "question_de": "Wenn man in Deutschland ein Kind schlägt, …", "question_image": null, "image_kind": null, "options": [{"text_de": "geht das niemanden etwas an.", "correct": false, "text_en": "it is nobody's business."}, {"text_de": "geht das nur die Familie etwas an.", "correct": false, "text_en": "it is only the family's business."}, {"text_de": "kann man dafür nicht bestraft werden.", "correct": false, "text_en": "you cannot be punished for it."}, {"text_de": "kann man dafür bestraft werden.", "correct": true, "text_en": "you can be punished for it."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-251.png"}, "question_en": "In Germany, if you hit a child, …", "asking_note": "Tests that corporal punishment of children is illegal in Germany. The three wrong options all try to normalise or excuse hitting a child as a private matter; the correct one states plainly that it is punishable.", "answer_explanation": "Since 2000, § 1631(2) of the German Civil Code (BGB) gives children an explicit right to a non-violent upbringing; physical punishment, psychological harm and other degrading measures are forbidden. Hitting a child can be prosecuted as bodily harm (Körperverletzung, § 223 StGB), so it is a matter for the state, not a private family affair.", "distractor_notes": ["Wrong — violence against a child is a public/legal matter, not a private one; the state can intervene.", "Wrong — it is not merely a family matter; hitting a child is a criminal offence the state can prosecute.", "Wrong — you can indeed be punished; hitting a child can amount to bodily harm (§ 223 StGB).", ""]}, {"id": 252, "id_str": "252", "category": "general", "exam_pool": "general", "question_de": "In Deutschland …", "question_image": null, "image_kind": null, "options": [{"text_de": "darf man zur gleichen Zeit nur mit einer Partnerin/einem Partner verheiratet sein.", "correct": true, "text_en": "you may be married to only one partner at a time."}, {"text_de": "kann man mehrere Ehepartnerinnen/Ehepartner gleichzeitig haben.", "correct": false, "text_en": "you can have several spouses at the same time."}, {"text_de": "darf man nicht wieder heiraten, wenn man einmal verheiratet war.", "correct": false, "text_en": "you may not marry again once you have been married."}, {"text_de": "darf eine Frau nicht wieder heiraten, wenn ihr Mann gestorben ist.", "correct": false, "text_en": "a woman may not marry again if her husband has died."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-252.png"}, "question_en": "In Germany …", "asking_note": "Tests that German law permits only monogamous marriage. Watch the options: only one describes the actual rule (one spouse at a time); the others describe polygamy or invented bans on remarriage.", "answer_explanation": "German marriage law is strictly monogamous: a person may be married to only one spouse at any given time. Entering a second marriage while still married (bigamy) is a criminal offence under § 172 StGB. Remarriage after divorce or the death of a spouse is fully permitted.", "distractor_notes": ["", "Wrong — having multiple spouses simultaneously (polygamy/bigamy) is illegal (§ 172 StGB).", "Wrong — remarriage after divorce or widowhood is allowed; there is no such lifelong ban.", "Wrong — a widow (like a widower) is free to remarry; no such prohibition exists."]}, {"id": 253, "id_str": "253", "category": "general", "exam_pool": "general", "question_de": "Wo müssen Sie sich anmelden, wenn Sie in Deutschland umziehen?", "question_image": null, "image_kind": null, "options": [{"text_de": "beim Einwohnermeldeamt", "correct": true, "text_en": "at the residents' registration office (Einwohnermeldeamt)"}, {"text_de": "beim Standesamt", "correct": false, "text_en": "at the civil registry office (Standesamt)"}, {"text_de": "beim Ordnungsamt", "correct": false, "text_en": "at the public order office (Ordnungsamt)"}, {"text_de": "beim Gewerbeamt", "correct": false, "text_en": "at the trade office (Gewerbeamt)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-253.png"}, "question_en": "Where must you register when you move house within Germany?", "asking_note": "Tests knowledge of the registration duty (Meldepflicht) and which office handles it. The distractors are other local offices with different jobs — easy to confuse by name.", "answer_explanation": "Germany's Federal Registration Act (Bundesmeldegesetz) requires anyone who moves to register their new address, normally within two weeks, at the residents' registration office (Einwohnermeldeamt / Bürgeramt). This keeps the official population register up to date.", "distractor_notes": ["", "The Standesamt handles births, marriages and deaths — not address registration.", "The Ordnungsamt enforces public order and local regulations — not residence registration.", "The Gewerbeamt registers businesses and trades — not private moves."]}, {"id": 254, "id_str": "254", "category": "general", "exam_pool": "general", "question_de": "In Deutschland dürfen Ehepaare sich scheiden lassen. Meistens müssen sie dazu das \"Trennungsjahr\" einhalten. Was bedeutet das?", "question_image": null, "image_kind": null, "options": [{"text_de": "Der Scheidungsprozess dauert ein Jahr.", "correct": false, "text_en": "The divorce proceedings last one year."}, {"text_de": "Die Ehegatten sind ein Jahr verheiratet, dann ist die Scheidung möglich.", "correct": false, "text_en": "The spouses are married for one year, then divorce is possible."}, {"text_de": "Das Besuchsrecht für die Kinder gilt ein Jahr.", "correct": false, "text_en": "The right to visit the children lasts one year."}, {"text_de": "Die Ehegatten führen mindestens ein Jahr getrennt ihr eigenes Leben. Danach ist die Scheidung möglich.", "correct": true, "text_en": "The spouses live their own separate lives for at least one year. After that, divorce is possible."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-254.png"}, "question_en": "In Germany, married couples may divorce. Usually they must observe the 'year of separation' (Trennungsjahr) first. What does that mean?", "asking_note": "Tests the meaning of the Trennungsjahr. The trap options misread it as the length of the divorce proceedings, a minimum marriage length, or a rule about child visitation.", "answer_explanation": "German divorce law (§§ 1565–1566 BGB) presumes a marriage has failed once the spouses have lived apart for at least one year. This separation year — living separate lives, which can even be under one roof — is normally required before a court will grant the divorce.", "distractor_notes": ["Wrong — the Trennungsjahr is the required separation before filing, not the length of the court proceedings.", "Wrong — it is not about how long you have been married; it is about living apart for a year.", "Wrong — it has nothing to do with child visitation rights.", ""]}, {"id": 255, "id_str": "255", "category": "general", "exam_pool": "general", "question_de": "Bei Erziehungsproblemen können Eltern in Deutschland Hilfe erhalten vom …", "question_image": null, "image_kind": null, "options": [{"text_de": "Ordnungsamt.", "correct": false, "text_en": "public order office (Ordnungsamt)."}, {"text_de": "Schulamt.", "correct": false, "text_en": "school authority (Schulamt)."}, {"text_de": "Jugendamt.", "correct": true, "text_en": "youth welfare office (Jugendamt)."}, {"text_de": "Gesundheitsamt.", "correct": false, "text_en": "health department (Gesundheitsamt)."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-255.png"}, "question_en": "For parenting problems, parents in Germany can get help from the …", "asking_note": "Tests which authority supports families with child-rearing difficulties. The distractors are similarly named '-amt' offices with unrelated remits.", "answer_explanation": "The Jugendamt (youth welfare office) is the central agency for child and youth welfare under Book VIII of the Social Code (SGB VIII). It advises and supports parents facing difficulties with upbringing and offers family counselling and assistance.", "distractor_notes": ["The Ordnungsamt handles public order matters, not family or parenting support.", "The Schulamt administers schools, not general parenting help.", "", "The Gesundheitsamt deals with public health, not child-rearing support."]}, {"id": 256, "id_str": "256", "category": "general", "exam_pool": "general", "question_de": "Ein Ehepaar möchte in Deutschland ein Restaurant eröffnen. Was braucht es dazu unbedingt?", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Erlaubnis der Polizei", "correct": false, "text_en": "a permit from the police"}, {"text_de": "eine Genehmigung einer Partei", "correct": false, "text_en": "authorisation from a political party"}, {"text_de": "eine Genehmigung des Einwohnermeldeamts", "correct": false, "text_en": "authorisation from the residents' registration office"}, {"text_de": "eine Gaststättenerlaubnis von der zuständigen Behörde", "correct": true, "text_en": "a restaurant/catering licence (Gaststättenerlaubnis) from the responsible authority"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-256.png"}, "question_en": "A married couple wants to open a restaurant in Germany. What do they absolutely need for this?", "asking_note": "Tests which permit is legally required to run a food-and-drink business. The distractors invoke authorities (police, a party, the registration office) that have nothing to do with licensing a restaurant.", "answer_explanation": "Running an establishment that serves food and drink for on-site consumption generally requires a Gaststättenerlaubnis under the Restaurant/Catering Act (Gaststättengesetz), issued by the competent local authority (often the Ordnungs- or Gewerbeamt). The licence checks matters such as reliability and hygiene, especially where alcohol is served.", "distractor_notes": ["The police do not issue business licences; this is not their function.", "Political parties have no role in authorising a business — Germany is not a one-party state.", "The Einwohnermeldeamt registers residents' addresses, not businesses.", ""]}, {"id": 257, "id_str": "257", "category": "general", "exam_pool": "general", "question_de": "Eine erwachsene Frau möchte in Deutschland das Abitur nachholen. Das kann sie an …", "question_image": null, "image_kind": null, "options": [{"text_de": "einer Hochschule.", "correct": false, "text_en": "a university (Hochschule)."}, {"text_de": "einem Abendgymnasium.", "correct": true, "text_en": "an evening secondary school (Abendgymnasium)."}, {"text_de": "einer Hauptschule.", "correct": false, "text_en": "a lower secondary school (Hauptschule)."}, {"text_de": "einer Privatuniversität.", "correct": false, "text_en": "a private university."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-257.png"}, "question_en": "An adult woman wants to obtain her Abitur (higher-education entrance qualification) later in life. She can do this at …", "asking_note": "Tests knowledge of the 'second education pathway' (zweiter Bildungsweg) for adults. The trap is that a university or Hauptschule cannot award the Abitur; the Abendgymnasium is designed exactly for working adults.", "answer_explanation": "The Abendgymnasium is part of Germany's 'second-chance' education route: it lets adults, typically alongside work, catch up on the Abitur (the qualification for university entrance). Universities require the Abitur for admission, so they cannot award it, and a Hauptschule leads only to a lower school-leaving certificate.", "distractor_notes": ["A Hochschule (university) requires the Abitur to enter; it does not award it.", "", "A Hauptschule leads to a basic lower-secondary certificate, not the Abitur.", "A private university, like any university, presupposes the Abitur rather than granting it."]}, {"id": 258, "id_str": "258", "category": "general", "exam_pool": "general", "question_de": "Was darf das Jugendamt in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Es entscheidet, welche Schule das Kind besucht.", "correct": false, "text_en": "It decides which school the child attends."}, {"text_de": "Es kann ein Kind, das geschlagen wird oder hungern muss, aus der Familie nehmen.", "correct": true, "text_en": "It can remove a child who is being beaten or made to go hungry from the family."}, {"text_de": "Es bezahlt das Kindergeld an die Eltern.", "correct": false, "text_en": "It pays the child benefit to the parents."}, {"text_de": "Es kontrolliert, ob das Kind einen Kindergarten besucht.", "correct": false, "text_en": "It checks whether the child attends a kindergarten."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-258.png"}, "question_en": "What is the youth welfare office (Jugendamt) allowed to do in Germany?", "asking_note": "Tests the Jugendamt's core protective power. The distractors describe things it does NOT do (choosing the school, paying child benefit, checking kindergarten attendance) — the point is its role in protecting endangered children.", "answer_explanation": "When a child's welfare is endangered (Kindeswohlgefährdung), § 8a SGB VIII and § 42 SGB VIII empower the Jugendamt to intervene and, if necessary, take the child into care (Inobhutnahme) — for example where a child is being beaten or neglected. Its central mandate is protecting the child's well-being.", "distractor_notes": ["Wrong — school choice is a matter for parents and the school authorities, not the Jugendamt.", "", "Wrong — child benefit (Kindergeld) is paid by the Familienkasse of the Federal Employment Agency, not the Jugendamt.", "Wrong — kindergarten attendance is voluntary; the Jugendamt does not police it."]}, {"id": 259, "id_str": "259", "category": "general", "exam_pool": "general", "question_de": "Das Berufsinformationszentrum BIZ bei der Bundesagentur für Arbeit in Deutschland hilft bei der …", "question_image": null, "image_kind": null, "options": [{"text_de": "Rentenberechnung.", "correct": false, "text_en": "calculating pensions."}, {"text_de": "Lehrstellensuche.", "correct": true, "text_en": "finding an apprenticeship/training place (Lehrstelle)."}, {"text_de": "Steuererklärung.", "correct": false, "text_en": "the tax return."}, {"text_de": "Krankenversicherung.", "correct": false, "text_en": "health insurance."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-259.png"}, "question_en": "The Career Information Centre (BIZ) at the Federal Employment Agency (Bundesagentur für Arbeit) in Germany helps with …", "asking_note": "Tests what the Federal Employment Agency's BIZ is for. The distractors name services handled by other bodies (pension office, tax office, health insurers) — the BIZ is about careers and training.", "answer_explanation": "The Berufsinformationszentrum (BIZ), run by the Federal Employment Agency, provides free information and guidance on careers, training and study. It supports people looking for an apprenticeship (Lehrstelle) or planning their career path.", "distractor_notes": ["Pension calculations are handled by the Deutsche Rentenversicherung, not the BIZ.", "", "Tax returns are dealt with by the Finanzamt (tax office), not the BIZ.", "Health insurance is handled by the statutory health insurers (Krankenkassen), not the BIZ."]}, {"id": 260, "id_str": "260", "category": "general", "exam_pool": "general", "question_de": "In Deutschland hat ein Kind in der Schule …", "question_image": null, "image_kind": null, "options": [{"text_de": "Recht auf unbegrenzte Freizeit.", "correct": false, "text_en": "a right to unlimited free time."}, {"text_de": "Wahlfreiheit für alle Fächer.", "correct": false, "text_en": "free choice of all subjects."}, {"text_de": "Anspruch auf Schulgeld.", "correct": false, "text_en": "an entitlement to be paid school money."}, {"text_de": "Anwesenheitspflicht.", "correct": true, "text_en": "a duty of attendance (compulsory schooling)."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-260.png"}, "question_en": "In Germany, a child in school has …", "asking_note": "Tests knowledge of compulsory schooling (Schulpflicht). The distractors describe invented 'rights' (unlimited free time, free choice of all subjects, a right to be paid for school); the real obligation is to attend.", "answer_explanation": "Germany has compulsory schooling (Schulpflicht), regulated by the individual federal states. Children must attend school regularly; attendance is a legal obligation, not optional, which is why unexcused absence can be penalised.", "distractor_notes": ["Wrong — school involves an attendance duty, not unlimited free time.", "Wrong — the curriculum is largely fixed; pupils cannot freely choose all subjects.", "Wrong — pupils are not paid to attend school; there is no such entitlement.", ""]}, {"id": 261, "id_str": "261", "category": "general", "exam_pool": "general", "question_de": "Ein Mann möchte mit 30 Jahren in Deutschland sein Abitur nachholen. Wo kann er das tun? An …", "question_image": null, "image_kind": null, "options": [{"text_de": "einer Hochschule.", "correct": false, "text_en": "a university (Hochschule)."}, {"text_de": "einem Abendgymnasium.", "correct": true, "text_en": "an evening secondary school (Abendgymnasium)."}, {"text_de": "einer Hauptschule.", "correct": false, "text_en": "a lower secondary school (Hauptschule)."}, {"text_de": "einer Privatuniversität.", "correct": false, "text_en": "a private university."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-261.png"}, "question_en": "A man wants to obtain his Abitur later, at the age of 30. Where can he do this? At …", "asking_note": "Same concept as question 257, worded for a 30-year-old man: the adult 'second education pathway.' The trap remains that only the Abendgymnasium awards the Abitur, not a university or Hauptschule.", "answer_explanation": "The Abendgymnasium exists precisely so that adults can obtain the Abitur later in life, usually while working. Universities require the Abitur for entry and therefore do not award it, and a Hauptschule offers only a basic lower-secondary qualification.", "distractor_notes": ["A Hochschule requires the Abitur for admission; it does not grant it.", "", "A Hauptschule leads to a basic school-leaving certificate, not the Abitur.", "A private university also presupposes the Abitur rather than awarding it."]}, {"id": 262, "id_str": "262", "category": "general", "exam_pool": "general", "question_de": "Was bedeutet in Deutschland der Grundsatz der Gleichbehandlung?", "question_image": null, "image_kind": null, "options": [{"text_de": "Niemand darf z.B. wegen einer Behinderung benachteiligt werden.", "correct": true, "text_en": "No one may be disadvantaged, for example because of a disability."}, {"text_de": "Man darf andere Personen benachteiligen, wenn ausreichende persönliche Gründe hierfür vorliegen.", "correct": false, "text_en": "You may disadvantage other people if there are sufficient personal reasons for it."}, {"text_de": "Niemand darf gegen Personen klagen, wenn sie benachteiligt wurden.", "correct": false, "text_en": "No one may sue people if they have been disadvantaged."}, {"text_de": "Es ist für alle Gesetz, benachteiligten Gruppen jährlich Geld zu spenden.", "correct": false, "text_en": "It is the law for everyone to donate money to disadvantaged groups every year."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-262.png"}, "question_en": "What does the principle of equal treatment mean in Germany?", "asking_note": "Tests understanding of equality/non-discrimination. Read the options carefully — the wrong ones subtly invert the principle (allowing discrimination 'for good reasons', banning lawsuits, or mandating annual donations).", "answer_explanation": "Article 3 of the Grundgesetz guarantees equality before the law and forbids disadvantaging anyone on grounds such as sex, descent, race, language, faith or disability. The General Equal Treatment Act (AGG) puts this into practice in areas like work and everyday transactions — so no one may be disadvantaged, for instance, because of a disability.", "distractor_notes": ["", "Wrong — the principle forbids disadvantaging people; 'personal reasons' do not justify discrimination.", "Wrong — people who are discriminated against can in fact take legal action; the right to sue is protected.", "Wrong — there is no legal duty for everyone to donate money to disadvantaged groups."]}, {"id": 263, "id_str": "263", "category": "general", "exam_pool": "general", "question_de": "In Deutschland sind Jugendliche ab 14 Jahren strafmündig. Das bedeutet: Jugendliche, die 14 Jahre und älter sind und gegen Strafgesetze verstoßen, …", "question_image": null, "image_kind": null, "options": [{"text_de": "werden bestraft.", "correct": true, "text_en": "are punished."}, {"text_de": "werden wie Erwachsene behandelt.", "correct": false, "text_en": "are treated like adults."}, {"text_de": "teilen die Strafe mit ihren Eltern.", "correct": false, "text_en": "share the punishment with their parents."}, {"text_de": "werden nicht bestraft.", "correct": false, "text_en": "are not punished."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-263.png"}, "question_en": "In Germany, young people are criminally responsible from the age of 14 (strafmündig). This means: young people aged 14 and older who break the criminal law …", "asking_note": "Tests the concept of criminal responsibility age. The trap is option [1] — being punishable does NOT mean being treated like an adult; juveniles are judged under special youth criminal law.", "answer_explanation": "From age 14, minors are criminally responsible and can be prosecuted, but they are tried under the special Juvenile Courts Act (Jugendgerichtsgesetz), which emphasises education over retribution. So they are punished — but not in the same way as adults, and the punishment is personal, not shared with parents.", "distractor_notes": ["", "Wrong — juveniles are judged under youth criminal law (JGG), not treated like adults.", "Wrong — criminal responsibility is personal; parents do not serve or share the punishment.", "Wrong — from age 14 they can indeed be punished; below 14 there is no criminal responsibility."]}, {"id": 264, "id_str": "264", "category": "general", "exam_pool": "general", "question_de": "Zu welchem Fest tragen Menschen in Deutschland bunte Kostüme und Masken?", "question_image": null, "image_kind": null, "options": [{"text_de": "am Rosenmontag", "correct": true, "text_en": "on Rose Monday (Rosenmontag)"}, {"text_de": "am Maifeiertag", "correct": false, "text_en": "on May Day (Maifeiertag)"}, {"text_de": "beim Oktoberfest", "correct": false, "text_en": "at the Oktoberfest"}, {"text_de": "an Pfingsten", "correct": false, "text_en": "at Whitsun (Pfingsten)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-264.png"}, "question_en": "At which festival do people in Germany wear colourful costumes and masks?", "asking_note": "Tests recognition of German festival customs. The trap is matching the specific custom (costumes and masks) to the right festival — the other options are real German holidays but with different traditions.", "answer_explanation": "Rosenmontag is the high point of the Carnival season (Karneval/Fasching/Fastnacht), especially in the Rhineland, when people dress in colourful costumes and masks and hold parades. It falls on the Monday before Ash Wednesday.", "distractor_notes": ["", "May Day (1 May) is a public holiday marked by labour rallies and maypole customs, not costume-wearing.", "The Oktoberfest is Munich's beer festival, associated with traditional dress (Dirndl/Lederhosen), not masks and costumes.", "Whitsun (Pentecost) is a Christian holiday without a costume-and-mask tradition."]}, {"id": 265, "id_str": "265", "category": "general", "exam_pool": "general", "question_de": "Wohin muss man in Deutschland zuerst gehen, wenn man heiraten möchte?", "question_image": null, "image_kind": null, "options": [{"text_de": "zum Einwohnermeldeamt", "correct": false, "text_en": "to the residents' registration office (Einwohnermeldeamt)"}, {"text_de": "zum Ordnungsamt", "correct": false, "text_en": "to the public order office (Ordnungsamt)"}, {"text_de": "zur Agentur für Arbeit", "correct": false, "text_en": "to the Employment Agency (Agentur für Arbeit)"}, {"text_de": "zum Standesamt", "correct": true, "text_en": "to the civil registry office (Standesamt)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-265.png"}, "question_en": "Where must you go first in Germany if you want to get married?", "asking_note": "Tests which office handles marriage. The distractors are other local authorities; note that a legally valid marriage in Germany requires the civil registry office, regardless of any religious ceremony.", "answer_explanation": "In Germany only a civil marriage before the Standesamt (civil registry office) is legally binding. Couples must register their intention to marry there, and the registrar conducts the legally valid ceremony; any religious wedding is optional and has no civil legal effect.", "distractor_notes": ["The Einwohnermeldeamt handles address registration, not marriages.", "The Ordnungsamt deals with public order, not marriage.", "The Agentur für Arbeit handles employment and benefits, not marriage.", ""]}, {"id": 266, "id_str": "266", "category": "general", "exam_pool": "general", "question_de": "Wann beginnt die gesetzliche Nachtruhe in Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "wenn die Sonne untergeht", "correct": false, "text_en": "when the sun goes down"}, {"text_de": "wenn die Nachbarn schlafen gehen", "correct": false, "text_en": "when the neighbours go to sleep"}, {"text_de": "um 0 Uhr, Mitternacht", "correct": false, "text_en": "at 12 o'clock, midnight"}, {"text_de": "um 22 Uhr", "correct": true, "text_en": "at 10 p.m. (22:00)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-266.png"}, "question_en": "When does the legally protected night-time quiet period (Nachtruhe) begin in Germany?", "asking_note": "Tests the standard start of the quiet hours. The distractors offer vague or wrong times (sunset, when neighbours sleep, midnight); the widely applied rule is a fixed clock time.", "answer_explanation": "Across Germany the general night-time quiet period (Nachtruhe) runs from 22:00 to 06:00. During these hours noise that disturbs others must be avoided; the rule is set out in state immission-control rules and house rules, with 10 p.m. the customary starting point.", "distractor_notes": ["Wrong — the quiet period is tied to a fixed clock time, not to sunset, which varies through the year.", "Wrong — it does not depend on when individual neighbours happen to go to bed.", "Wrong — the Nachtruhe begins at 22:00, not at midnight.", ""]}, {"id": 267, "id_str": "267", "category": "general", "exam_pool": "general", "question_de": "Eine junge Frau in Deutschland, 22 Jahre alt, lebt mit ihrem Freund zusammen. Die Eltern der Frau finden das nicht gut, weil ihnen der Freund nicht gefällt. Was können die Eltern tun?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sie müssen die Entscheidung der volljährigen Tochter respektieren.", "correct": true, "text_en": "They must respect the decision of their adult daughter."}, {"text_de": "Sie haben das Recht, die Tochter in die elterliche Wohnung zurückzuholen.", "correct": false, "text_en": "They have the right to bring the daughter back to the parental home."}, {"text_de": "Sie können zur Polizei gehen und die Tochter anzeigen.", "correct": false, "text_en": "They can go to the police and report the daughter."}, {"text_de": "Sie suchen einen anderen Mann für die Tochter.", "correct": false, "text_en": "They look for another man for the daughter."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-267.png"}, "question_en": "A young woman in Germany, 22 years old, lives with her boyfriend. The woman's parents do not like this because they dislike the boyfriend. What can the parents do?", "asking_note": "Tests the rights of adults (Volljährigkeit) over their own lives. The wrong options describe coercive actions parents have no right to take once a child is of legal age.", "answer_explanation": "In Germany a person becomes an adult (volljährig) at 18 and can decide freely how and with whom to live; this is part of the general freedom to act protected by Article 2 of the Grundgesetz. Parents have no authority over an adult child's choice of partner or residence and must respect her decision.", "distractor_notes": ["", "Wrong — parents have no right to force an adult daughter back home; she decides where she lives.", "Wrong — living with a partner is not an offence, so there is nothing to report to the police.", "Wrong — arranging a partner against her will violates her right to self-determination."]}, {"id": 268, "id_str": "268", "category": "general", "exam_pool": "general", "question_de": "Eine junge Frau will den Führerschein machen. Sie hat Angst vor der Prüfung, weil ihre Muttersprache nicht Deutsch ist. Was ist richtig?", "question_image": null, "image_kind": null, "options": [{"text_de": "Sie muss mindestens zehn Jahre in Deutschland leben, bevor sie den Führerschein machen kann.", "correct": false, "text_en": "She must live in Germany for at least ten years before she can get a driving licence."}, {"text_de": "Wenn sie kein Deutsch kann, darf sie keinen Führerschein haben.", "correct": false, "text_en": "If she cannot speak German, she is not allowed to have a driving licence."}, {"text_de": "Sie muss den Führerschein in dem Land machen, in dem man ihre Sprache spricht.", "correct": false, "text_en": "She must take the driving licence in the country where her language is spoken."}, {"text_de": "Sie kann die Theorie-Prüfung vielleicht in ihrer Muttersprache machen. Es gibt mehr als zehn Sprachen zur Auswahl.", "correct": true, "text_en": "She may be able to take the theory test in her mother tongue. There are more than ten languages to choose from."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-268.png"}, "question_en": "A young woman wants to get her driving licence. She is afraid of the exam because her mother tongue is not German. What is correct?", "asking_note": "Tests knowledge that the driving-theory test is offered in multiple languages. The distractors invent barriers (residence minimum, German-language requirement, having to test abroad) that do not exist.", "answer_explanation": "The official German driving-theory examination can be taken in a number of foreign languages in addition to German — commonly including English, French, Arabic, Turkish, Russian and others (well over ten options). So limited German is not a barrier to sitting the theory test.", "distractor_notes": ["Wrong — there is no ten-year residence requirement for obtaining a driving licence.", "Wrong — you do not need to speak German to get a driving licence; the theory test is offered in several languages.", "Wrong — she can take the test in Germany; there is no need to go abroad.", ""]}, {"id": 269, "id_str": "269", "category": "general", "exam_pool": "general", "question_de": "In Deutschland haben Kinder ab dem Alter von drei Jahren bis zur Ersteinschulung einen Anspruch auf …", "question_image": null, "image_kind": null, "options": [{"text_de": "monatliches Taschengeld.", "correct": false, "text_en": "monthly pocket money."}, {"text_de": "einen Platz in einem Sportverein.", "correct": false, "text_en": "a place in a sports club."}, {"text_de": "einen Kindergartenplatz.", "correct": true, "text_en": "a kindergarten place."}, {"text_de": "einen Ferienpass.", "correct": false, "text_en": "a holiday pass."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-269.png"}, "question_en": "In Germany, children from the age of three until they first start school are entitled to …", "asking_note": "Tests the legal entitlement to childcare. The distractors offer invented entitlements (pocket money, a sports-club place, a holiday pass); the real statutory right is to a kindergarten place.", "answer_explanation": "Under § 24 of Book VIII of the Social Code (SGB VIII), every child has a legal right to a place in a day-care facility (Kindergarten) from their third birthday until they start school (and, since 2013, even from age one). This entitlement is meant to support early education and help parents combine work and family.", "distractor_notes": ["Wrong — there is no legal entitlement to pocket money from the state.", "Wrong — there is no statutory right to a sports-club place.", "", "Wrong — a 'holiday pass' is not a legal entitlement of this kind."]}, {"id": 270, "id_str": "270", "category": "general", "exam_pool": "general", "question_de": "Die Volkshochschule in Deutschland ist eine Einrichtung …", "question_image": null, "image_kind": null, "options": [{"text_de": "für den Religionsunterricht.", "correct": false, "text_en": "religious instruction."}, {"text_de": "nur für Jugendliche.", "correct": false, "text_en": "only for young people."}, {"text_de": "zur Weiterbildung.", "correct": true, "text_en": "continuing education (Weiterbildung)."}, {"text_de": "nur für Rentnerinnen und Rentner.", "correct": false, "text_en": "only for pensioners."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-270.png"}, "question_en": "The adult education centre (Volkshochschule) in Germany is an institution for …", "asking_note": "Tests what a Volkshochschule is. The distractors wrongly narrow it to religion, only young people, or only pensioners — in fact it is open, general adult continuing education.", "answer_explanation": "The Volkshochschule (VHS) is Germany's main public provider of adult and continuing education (Weiterbildung). It offers affordable courses — languages, integration and citizenship courses, IT, culture, health and more — open to adults of all ages and backgrounds.", "distractor_notes": ["Wrong — the VHS is not a religious institution; it offers broad, secular adult education.", "Wrong — it is not only for young people; it serves adults of all ages.", "", "Wrong — it is not only for pensioners; anyone can attend."]}, {"id": 271, "id_str": "271", "category": "general", "exam_pool": "general", "question_de": "Was ist in Deutschland ein Brauch zu Weihnachten?", "question_image": null, "image_kind": null, "options": [{"text_de": "bunte Eier verstecken", "correct": false, "text_en": "hiding coloured eggs"}, {"text_de": "einen Tannenbaum schmücken", "correct": true, "text_en": "decorating a fir tree (Christmas tree)"}, {"text_de": "sich mit Masken und Kostümen verkleiden", "correct": false, "text_en": "dressing up with masks and costumes"}, {"text_de": "Kürbisse vor die Tür stellen", "correct": false, "text_en": "putting pumpkins outside the door"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-271.png"}, "question_en": "What is a Christmas custom in Germany?", "asking_note": "Tests matching a custom to the right festival. Each distractor is a genuine custom but belongs to a different occasion (Easter, Carnival, Halloween) — don't be pulled to the wrong holiday.", "answer_explanation": "Decorating a fir tree — the Christmas tree (Weihnachtsbaum/Tannenbaum) — is a central German Christmas custom, along with gift-giving on Christmas Eve (Heiligabend, 24 December). The decorated tree is a tradition that spread from Germany around the world.", "distractor_notes": ["Hiding coloured eggs is an Easter custom, not Christmas.", "", "Dressing up with masks and costumes belongs to Carnival (Karneval/Fasching).", "Putting out pumpkins is associated with Halloween, not Christmas."]}, {"id": 272, "id_str": "272", "category": "general", "exam_pool": "general", "question_de": "Welche Lebensform ist in Deutschland nicht erlaubt?", "question_image": null, "image_kind": null, "options": [{"text_de": "Mann und Frau sind geschieden und leben mit neuen Partnern zusammen.", "correct": false, "text_en": "A man and woman are divorced and live with new partners."}, {"text_de": "Zwei Frauen leben zusammen.", "correct": false, "text_en": "Two women live together."}, {"text_de": "Ein alleinerziehender Vater lebt mit seinen zwei Kindern zusammen.", "correct": false, "text_en": "A single father lives with his two children."}, {"text_de": "Ein Mann ist mit zwei Frauen zur selben Zeit verheiratet.", "correct": true, "text_en": "A man is married to two women at the same time."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-272.png"}, "question_en": "Which form of living together is NOT permitted in Germany?", "asking_note": "NEGATIVE framing — you must pick the ONE arrangement that is illegal, not an allowed one. Three options describe perfectly legal living arrangements; only being married to two people at once is forbidden.", "answer_explanation": "German law permits monogamous marriage only; being married to two people simultaneously (bigamy/polygamy) is a criminal offence under § 172 StGB. The other arrangements — living with a new partner after divorce, a same-sex couple, or a single parent with children — are all legal and protected.", "distractor_notes": ["Allowed — people may live with new partners after divorce.", "Allowed — same-sex couples may live together and even marry (Ehe für alle, since 2017).", "Allowed — single-parent families are legal and common.", ""]}, {"id": 273, "id_str": "273", "category": "general", "exam_pool": "general", "question_de": "Bei Erziehungsproblemen gehen Sie in Deutschland …", "question_image": null, "image_kind": null, "options": [{"text_de": "zur Ärztin/zum Arzt.", "correct": false, "text_en": "to the doctor."}, {"text_de": "zum Gesundheitsamt.", "correct": false, "text_en": "to the health department (Gesundheitsamt)."}, {"text_de": "zum Einwohnermeldeamt.", "correct": false, "text_en": "to the residents' registration office (Einwohnermeldeamt)."}, {"text_de": "zum Jugendamt.", "correct": true, "text_en": "to the youth welfare office (Jugendamt)."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-273.png"}, "question_en": "In Germany, for parenting problems you go to …", "asking_note": "Same core fact as question 255: the youth welfare office is the go-to for child-rearing difficulties. The distractors are medical or administrative offices with unrelated roles.", "answer_explanation": "The Jugendamt (youth welfare office) is the responsible body for supporting families with child-rearing questions and difficulties, under Book VIII of the Social Code (SGB VIII). It offers advice, family counselling and assistance with upbringing.", "distractor_notes": ["A doctor treats health problems, not general parenting difficulties.", "The Gesundheitsamt handles public health, not child-rearing support.", "The Einwohnermeldeamt registers addresses, not family support.", ""]}, {"id": 274, "id_str": "274", "category": "general", "exam_pool": "general", "question_de": "Sie haben in Deutschland absichtlich einen Brief geöffnet, der an eine andere Person adressiert ist. Was haben Sie nicht beachtet?", "question_image": null, "image_kind": null, "options": [{"text_de": "das Schweigerecht", "correct": false, "text_en": "the right to remain silent"}, {"text_de": "das Briefgeheimnis", "correct": true, "text_en": "the secrecy of correspondence (Briefgeheimnis)"}, {"text_de": "die Schweigepflicht", "correct": false, "text_en": "the duty of confidentiality (Schweigepflicht)"}, {"text_de": "die Meinungsfreiheit", "correct": false, "text_en": "freedom of opinion"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-274.png"}, "question_en": "In Germany, you deliberately opened a letter addressed to another person. What did you fail to observe (i.e. which right/rule did you violate)?", "asking_note": "NEGATIVE framing ('what did you NOT observe') — you must name the protection that was violated. The trap is telling apart similar-sounding legal terms: secrecy of correspondence vs. professional confidentiality vs. freedom of opinion.", "answer_explanation": "Article 10 of the Grundgesetz protects the privacy of correspondence, posts and telecommunications (the Briefgeheimnis). Deliberately opening someone else's letter violates this secrecy of correspondence and can also be a criminal offence under § 202 StGB (Verletzung des Briefgeheimnisses).", "distractor_notes": ["The 'right to remain silent' concerns not incriminating oneself in legal proceedings — unrelated to opening mail.", "", "The Schweigepflicht is a professional duty of confidentiality (e.g. for doctors, lawyers) — not what opening a letter breaches.", "Freedom of opinion (Art. 5 GG) protects expressing views — nothing to do with reading another's mail."]}, {"id": 275, "id_str": "275", "category": "general", "exam_pool": "general", "question_de": "Was braucht man in Deutschland für eine Ehescheidung?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Einwilligung der Eltern", "correct": false, "text_en": "the consent of the parents"}, {"text_de": "ein Attest einer Ärztin/eines Arztes", "correct": false, "text_en": "a certificate from a doctor"}, {"text_de": "die Einwilligung der Kinder", "correct": false, "text_en": "the consent of the children"}, {"text_de": "die Unterstützung einer Anwältin/eines Anwalts", "correct": true, "text_en": "the support of a lawyer"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-275.png"}, "question_en": "What do you need in Germany for a divorce?", "asking_note": "Tests the procedural requirement of a divorce. The distractors invent consents (parents', children') or a medical certificate; the real requirement is legal representation, because divorces are decided in court.", "answer_explanation": "Divorce in Germany is decided by the family court (Familiengericht), and there is a lawyer requirement (Anwaltszwang): at least the spouse filing the petition must be represented by a lawyer. Neither parents nor children need to consent, and no medical certificate is involved.", "distractor_notes": ["Wrong — adults do not need their parents' consent to divorce.", "Wrong — no doctor's certificate is required for a divorce.", "Wrong — children's consent is not required for their parents to divorce.", ""]}, {"id": 276, "id_str": "276", "category": "general", "exam_pool": "general", "question_de": "Was sollten Sie tun, wenn Sie von Ihrer Ansprechpartnerin/Ihrem Ansprechpartner in einer deutschen Behörde schlecht behandelt werden?", "question_image": null, "image_kind": null, "options": [{"text_de": "Ich kann nichts tun.", "correct": false, "text_en": "I can't do anything."}, {"text_de": "Ich muss mir diese Behandlung gefallen lassen.", "correct": false, "text_en": "I have to put up with this treatment."}, {"text_de": "Ich drohe der Person.", "correct": false, "text_en": "I threaten the person."}, {"text_de": "Ich kann mich bei der Behördenleiterin/beim Behördenleiter beschweren.", "correct": true, "text_en": "I can complain to the head of the authority."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-276.png"}, "question_en": "What should you do if you are treated badly by your contact person at a German public authority?", "asking_note": "Tests knowledge of the legitimate way to respond to poor treatment by officials. The wrong options are resignation ('nothing I can do') or an illegal reaction (threatening the person); the right path is a formal complaint.", "answer_explanation": "In a state governed by the rule of law, citizens are entitled to be treated properly by public officials and can lodge a complaint (Beschwerde) with that official's superior — the head of the authority (Behördenleitung). This right of complaint follows from the right to petition in Article 17 of the Grundgesetz.", "distractor_notes": ["Wrong — you do have options; you can complain to the official's superior.", "Wrong — you do not have to tolerate poor treatment; you can complain.", "Wrong — threatening someone is itself a criminal offence and never the correct course.", ""]}, {"id": 277, "id_str": "277", "category": "general", "exam_pool": "general", "question_de": "Eine Frau, die ein zweijähriges Kind hat, bewirbt sich in Deutschland um eine Stelle. Was ist ein Beispiel für Diskriminierung? Sie bekommt die Stelle nur deshalb nicht, weil sie …", "question_image": null, "image_kind": null, "options": [{"text_de": "kein Englisch spricht.", "correct": false, "text_en": "does not speak English."}, {"text_de": "zu hohe Gehaltsvorstellungen hat.", "correct": false, "text_en": "has salary expectations that are too high."}, {"text_de": "keine Erfahrungen in diesem Beruf hat.", "correct": false, "text_en": "has no experience in this profession."}, {"text_de": "Mutter ist.", "correct": true, "text_en": "is a mother."}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-277.png"}, "question_en": "A woman who has a two-year-old child applies for a job in Germany. Which is an example of discrimination? She does not get the job solely because she …", "asking_note": "Tests recognising unlawful discrimination versus a legitimate hiring reason. The trap: options [0]-[2] are lawful job-related reasons for rejection; only rejecting her because she is a mother is discrimination.", "answer_explanation": "Rejecting an applicant because she is a mother is discrimination on the grounds of sex/parental status, prohibited by the General Equal Treatment Act (AGG) and the equality guarantee in Article 3 of the Grundgesetz. By contrast, missing job-relevant skills, lack of experience or excessive salary demands are legitimate, non-discriminatory reasons.", "distractor_notes": ["Not discrimination — a genuine language requirement for the job is a legitimate criterion.", "Not discrimination — salary expectations that exceed the budget are a lawful reason to decline.", "Not discrimination — lack of relevant professional experience is a legitimate hiring consideration.", ""]}, {"id": 278, "id_str": "278", "category": "general", "exam_pool": "general", "question_de": "Ein Mann im Rollstuhl hat sich auf eine Stelle als Buchhalter beworben. Was ist ein Beispiel für Diskriminierung? Er bekommt die Stelle nur deshalb nicht, weil er …", "question_image": null, "image_kind": null, "options": [{"text_de": "im Rollstuhl sitzt.", "correct": true, "text_en": "uses a wheelchair."}, {"text_de": "keine Erfahrung hat.", "correct": false, "text_en": "has no experience."}, {"text_de": "zu hohe Gehaltsvorstellungen hat.", "correct": false, "text_en": "has salary expectations that are too high."}, {"text_de": "kein Englisch spricht.", "correct": false, "text_en": "does not speak English."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-278.png"}, "question_en": "A man in a wheelchair has applied for a job as an accountant. Which is an example of discrimination? He does not get the job solely because he …", "asking_note": "Tests recognising disability discrimination versus legitimate reasons. The trap: options [1]-[3] are lawful job-related reasons; only rejecting him because he uses a wheelchair is discrimination.", "answer_explanation": "Refusing to hire someone solely because he uses a wheelchair is discrimination on grounds of disability, forbidden by the General Equal Treatment Act (AGG) and Article 3(3) of the Grundgesetz, which states that no one may be disadvantaged because of a disability. A desk-based accounting job does not require walking, so the wheelchair is irrelevant to competence. Lack of experience, excessive pay demands or missing language skills would be legitimate reasons.", "distractor_notes": ["", "Not discrimination — lack of experience is a legitimate, job-related reason to decline.", "Not discrimination — salary demands above budget are a lawful reason to reject an applicant.", "Not discrimination — a genuine language requirement for the role is a legitimate criterion."]}, {"id": 279, "id_str": "279", "category": "general", "exam_pool": "general", "question_de": "In den meisten Mietshäusern in Deutschland gibt es eine \"Hausordnung\". Was steht in einer solchen \"Hausordnung\"? Sie nennt …", "question_image": null, "image_kind": null, "options": [{"text_de": "Regeln für die Benutzung öffentlicher Verkehrsmittel.", "correct": false, "text_en": "rules for using public transport."}, {"text_de": "alle Mieterinnen und Mieter im Haus.", "correct": false, "text_en": "all the tenants in the building."}, {"text_de": "Regeln, an die sich alle Bewohnerinnen und Bewohner halten müssen.", "correct": true, "text_en": "rules that all residents must follow."}, {"text_de": "die Adresse des nächsten Ordnungsamtes.", "correct": false, "text_en": "the address of the nearest public order office."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-279.png"}, "question_en": "Most rented apartment buildings in Germany have a set of 'house rules' (Hausordnung). What does such a 'Hausordnung' contain? It states …", "asking_note": "Tests what a Hausordnung is. The distractors misdirect to unrelated content (public transport rules, a list of all tenants, the address of an office); the point is that it sets binding rules of conduct for everyone in the building.", "answer_explanation": "A Hausordnung is a set of house rules for a residential building that all residents must observe — covering matters such as quiet hours, use of shared areas, cleaning duties and refuse disposal. It is meant to ensure orderly, considerate coexistence among the occupants and is often part of the tenancy agreement.", "distractor_notes": ["Wrong — a Hausordnung governs conduct in the building, not the use of public transport.", "Wrong — it is a set of rules, not a directory listing the tenants.", "", "Wrong — it does not provide the address of any authority; it lays down rules for the residents."]}, {"id": 280, "id_str": "280", "category": "general", "exam_pool": "general", "question_de": "Wenn Sie sich in Deutschland gegen einen falschen Steuerbescheid wehren wollen, müssen Sie …", "question_image": null, "image_kind": null, "options": [{"text_de": "nichts machen.", "correct": false, "text_en": "do nothing."}, {"text_de": "den Bescheid wegwerfen.", "correct": false, "text_en": "throw the notice away."}, {"text_de": "Einspruch einlegen.", "correct": true, "text_en": "file an objection (Einspruch)."}, {"text_de": "warten, bis ein anderer Bescheid kommt.", "correct": false, "text_en": "wait until a different notice arrives."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-280.png"}, "question_en": "If you want to challenge an incorrect tax assessment (Steuerbescheid) in Germany, you must …", "asking_note": "Tests whether you know the formal remedy against a tax decision. Note the specific term: for a tax assessment from the Finanzamt the correct action is 'Einspruch' (objection), which must be filed within one month. Doing nothing or discarding the notice lets it become final.", "answer_explanation": "German tax law gives you the right to contest a Steuerbescheid you believe is wrong by lodging a formal 'Einspruch' (objection) with the tax office (Finanzamt), normally within one month of receiving the notice. The tax office then re-examines the case. This is the legally recognized way to defend yourself against an incorrect official decision rather than simply accepting or ignoring it.", "distractor_notes": ["Doing nothing means the assessment becomes legally binding after the deadline and you lose the right to challenge it.", "Discarding the notice changes nothing legally; the assessment still stands and becomes final.", "", "There is no automatic 'other notice' — you must actively act within the deadline, or the decision stands."]}, {"id": 281, "id_str": "281", "category": "general", "exam_pool": "general", "question_de": "Zwei Freunde wollen in ein öffentliches Schwimmbad in Deutschland. Beide haben eine dunkle Hautfarbe und werden deshalb nicht hineingelassen. Welches Recht wird in dieser Situation verletzt? Das Recht auf …", "question_image": null, "image_kind": null, "options": [{"text_de": "Meinungsfreiheit", "correct": false, "text_en": "freedom of expression"}, {"text_de": "Gleichbehandlung", "correct": true, "text_en": "equal treatment"}, {"text_de": "Versammlungsfreiheit", "correct": false, "text_en": "freedom of assembly"}, {"text_de": "Freizügigkeit", "correct": false, "text_en": "freedom of movement"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-281.png"}, "question_en": "Two friends want to enter a public swimming pool in Germany. Both have dark skin and are refused entry for that reason. Which right is being violated in this situation? The right to …", "asking_note": "A scenario testing which basic right protects against being treated worse because of skin colour. The trap is that all four options are real freedoms; you must pick the one about being treated the same as everyone else (equality), not about speech, assembly or movement.", "answer_explanation": "Refusing people entry because of their skin colour violates the right to equal treatment. Article 3 of the Grundgesetz states that all people are equal before the law and that no one may be disadvantaged because of, among other things, their race, origin or beliefs. Denying access based on skin colour is exactly the kind of discrimination this equality guarantee forbids.", "distractor_notes": ["Freedom of expression (Art. 5 GG) protects saying and publishing opinions, not access to a pool.", "", "Freedom of assembly (Art. 8 GG) protects gathering and demonstrating peacefully, which is not the issue here.", "Freedom of movement (Art. 11 GG) is the right to move and reside anywhere in Germany, not the right to be admitted somewhere without discrimination."]}, {"id": 282, "id_str": "282", "category": "general", "exam_pool": "general", "question_de": "Welches Ehrenamt müssen deutsche Staatsbürgerinnen und Staatsbürger übernehmen, wenn sie dazu aufgefordert werden?", "question_image": null, "image_kind": null, "options": [{"text_de": "Vereinstrainerin/Vereinstrainer", "correct": false, "text_en": "club coach"}, {"text_de": "Wahlhelferin/Wahlhelfer", "correct": true, "text_en": "election helper (Wahlhelfer)"}, {"text_de": "Bibliotheksaufsicht", "correct": false, "text_en": "library supervisor"}, {"text_de": "Lehrerin/Lehrer", "correct": false, "text_en": "teacher"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-282.png"}, "question_en": "Which honorary duty (Ehrenamt) must German citizens take on when they are called upon to do so?", "asking_note": "Tests which volunteer role is actually a compulsory civic duty, not just an optional activity. The trap: three options are genuine voluntary roles you can freely decline; only one is a legal obligation citizens can be required to perform.", "answer_explanation": "Serving as an election helper (Wahlhelfer) is an honorary office that eligible citizens are legally obliged to accept if appointed, so that elections can be staffed and run properly. It is one of the few civic duties that can be imposed on citizens. The role involves tasks such as staffing polling stations and counting votes.", "distractor_notes": ["Coaching a sports club is purely voluntary; no one can be compelled to do it.", "", "Supervising a library is a job or voluntary activity, not a compulsory civic duty.", "Teaching is a paid profession requiring qualifications, not an honorary duty citizens can be forced to take on."]}, {"id": 283, "id_str": "283", "category": "general", "exam_pool": "general", "question_de": "Was tun Sie, wenn Sie eine falsche Rechnung von einer deutschen Behörde bekommen?", "question_image": null, "image_kind": null, "options": [{"text_de": "Ich lasse die Rechnung liegen.", "correct": false, "text_en": "I leave the bill lying around."}, {"text_de": "Ich lege Widerspruch bei der Behörde ein.", "correct": true, "text_en": "I file an objection (Widerspruch) with the authority."}, {"text_de": "Ich schicke die Rechnung an die Behörde zurück.", "correct": false, "text_en": "I send the bill back to the authority."}, {"text_de": "Ich gehe mit der Rechnung zum Finanzamt.", "correct": false, "text_en": "I go to the tax office with the bill."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-283.png"}, "question_en": "What do you do if you receive an incorrect bill (Rechnung) from a German public authority?", "asking_note": "Tests the correct remedy against a wrong decision by an administrative authority. Note the term 'Widerspruch' (formal objection) — the general administrative remedy, as opposed to 'Einspruch' used specifically for tax assessments. The trap distractor sends you to the Finanzamt, which only handles tax matters.", "answer_explanation": "If a public authority sends you an incorrect bill or decision, the proper step is to lodge a formal objection (Widerspruch) with that authority, usually within one month. This forces the authority to review its decision. It is the standard legal remedy against administrative acts and preserves your right to take the matter further if needed.", "distractor_notes": ["Ignoring the bill risks the demand becoming final and enforceable; the error will not correct itself.", "", "Merely returning the bill without a formal objection does not trigger any legal review of the decision.", "The Finanzamt (tax office) only deals with tax matters, not with bills from other authorities, so this is the wrong address."]}, {"id": 284, "id_str": "284", "category": "general", "exam_pool": "general", "question_de": "Was man für die Arbeit können muss, ändert sich in Zukunft sehr schnell. Was kann man tun?", "question_image": null, "image_kind": null, "options": [{"text_de": "Es ist egal, was man lernt.", "correct": false, "text_en": "It doesn't matter what you learn."}, {"text_de": "Erwachsene müssen auch nach der Ausbildung immer weiter lernen.", "correct": true, "text_en": "Adults must keep learning even after their training/education."}, {"text_de": "Kinder lernen in der Schule alles, was im Beruf wichtig ist. Nach der Schule muss man nicht weiter lernen.", "correct": false, "text_en": "Children learn everything important for their job at school. After school you don't need to keep learning."}, {"text_de": "Alle müssen früher aufhören zu arbeiten, weil sich alles ändert.", "correct": false, "text_en": "Everyone has to stop working earlier because everything changes."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-284.png"}, "question_en": "What you need to be able to do for work changes very quickly in the future. What can one do?", "asking_note": "Tests understanding of lifelong learning in a changing labour market. Straightforward: pick the sensible, forward-looking answer; the distractors are deliberately fatalistic or dismissive of continued education.", "answer_explanation": "Because job requirements change rapidly, continuing education and lifelong learning (Weiterbildung) are essential; adults are expected to keep updating their skills throughout their working lives. Germany actively supports this through further-training courses and adult education institutions such as the Volkshochschulen. Staying qualified is how workers adapt to new technologies and demands.", "distractor_notes": ["It clearly does matter what you learn — relevant, up-to-date skills are what keep you employable.", "", "School cannot teach everything a career will later require, especially as jobs change; ongoing learning is needed.", "Rapid change is a reason to keep learning, not to retire early; this conclusion does not follow."]}, {"id": 285, "id_str": "285", "category": "general", "exam_pool": "general", "question_de": "Frau Frost arbeitet als fest angestellte Mitarbeiterin in einem Büro. Was muss sie nicht von ihrem Gehalt bezahlen?", "question_image": null, "image_kind": null, "options": [{"text_de": "Lohnsteuer", "correct": false, "text_en": "wage tax (Lohnsteuer)"}, {"text_de": "Beiträge zur Arbeitslosenversicherung", "correct": false, "text_en": "unemployment insurance contributions"}, {"text_de": "Beiträge zur Renten- und Krankenversicherung", "correct": false, "text_en": "pension and health insurance contributions"}, {"text_de": "Umsatzsteuer", "correct": true, "text_en": "value-added tax (Umsatzsteuer)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-285.png"}, "question_en": "Ms Frost works as a permanently employed staff member in an office. Which of these does she NOT have to pay out of her salary?", "asking_note": "Negative framing — you must find the item that is NOT deducted from an employee's wages. The trap: three options are genuine payroll deductions for an employee; the odd one out is a consumption tax charged on goods and services, unrelated to salary.", "answer_explanation": "Value-added tax (Umsatzsteuer/VAT) is a tax on the sale of goods and services, paid when you buy things — it is not deducted from wages. An employee's salary does have wage tax and social-insurance contributions (unemployment, pension, health) withheld directly. Because Umsatzsteuer has nothing to do with earning a wage, it is the item Ms Frost does not pay from her salary.", "distractor_notes": ["Lohnsteuer (wage tax) is withheld directly from an employee's gross salary, so she does pay it.", "Unemployment insurance contributions are a mandatory payroll deduction for employees, so she does pay them.", "Pension and health insurance contributions are mandatory social-insurance deductions from salary, so she does pay them.", ""]}, {"id": 286, "id_str": "286", "category": "general", "exam_pool": "general", "question_de": "Welche Organisation in einer Firma hilft den Arbeitnehmerinnen und Arbeitnehmern bei Problemen mit der Arbeitgeberin/dem Arbeitgeber?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Betriebsrat", "correct": true, "text_en": "the works council (Betriebsrat)"}, {"text_de": "die Betriebsprüferin/der Betriebsprüfer", "correct": false, "text_en": "the tax/company auditor (Betriebsprüfer)"}, {"text_de": "die Betriebsgruppe", "correct": false, "text_en": "the company group (Betriebsgruppe)"}, {"text_de": "das Betriebsmanagement", "correct": false, "text_en": "the company management (Betriebsmanagement)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-286.png"}, "question_en": "Which organization within a company helps employees with problems involving their employer?", "asking_note": "Tests knowledge of the works council. The trap is that all four options start with 'Betrieb-' and sound plausible; only one is the elected body that represents employees' interests to management.", "answer_explanation": "The Betriebsrat (works council) is the body elected by a company's employees to represent their interests toward the employer and to help resolve workplace problems. Its rights are set out in the Works Constitution Act (Betriebsverfassungsgesetz), and it has co-determination rights on matters like working hours and dismissals. It exists specifically to give workers a collective voice.", "distractor_notes": ["", "A Betriebsprüfer is an auditor (often a tax auditor) who inspects the company's books — not a body that helps employees.", "'Betriebsgruppe' is not an established employee-representation body in German labour law.", "Company management represents the employer's side, so it is not the body that advocates for employees against the employer."]}, {"id": 287, "id_str": "287", "category": "general", "exam_pool": "general", "question_de": "Sie möchten bei einer Firma in Deutschland ihr Arbeitsverhältnis beenden. Was müssen Sie beachten?", "question_image": null, "image_kind": null, "options": [{"text_de": "die Gehaltszahlungen", "correct": false, "text_en": "the salary payments"}, {"text_de": "die Arbeitszeit", "correct": false, "text_en": "the working hours"}, {"text_de": "die Kündigungsfrist", "correct": true, "text_en": "the notice period (Kündigungsfrist)"}, {"text_de": "die Versicherungspflicht", "correct": false, "text_en": "the compulsory insurance"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-287.png"}, "question_en": "You want to end your employment relationship with a company in Germany. What must you observe/take into account?", "asking_note": "Tests what an employee must respect when quitting a job. The answer is the notice period; the distractors are real employment concepts but not what governs when you may leave.", "answer_explanation": "When resigning, you must observe the notice period (Kündigungsfrist) — the legally or contractually required amount of time between giving notice and the employment actually ending. The statutory basic period under the German Civil Code (BGB) is four weeks, though contracts or collective agreements can set longer periods. Respecting it makes the termination valid and effective.", "distractor_notes": ["Salary payments are the employer's obligation and are not what you must observe in order to quit.", "Working hours govern the daily job, not the process of ending the contract.", "", "Compulsory insurance is about social-security coverage, not about how or when you may terminate the contract."]}, {"id": 288, "id_str": "288", "category": "general", "exam_pool": "general", "question_de": "Woraus begründet sich Deutschlands besondere Verantwortung für Israel?", "question_image": null, "image_kind": null, "options": [{"text_de": "aus der Mitgliedschaft in der Europäischen Union (EU)", "correct": false, "text_en": "its membership in the European Union (EU)"}, {"text_de": "aus den nationalsozialistischen Verbrechen gegen Juden", "correct": true, "text_en": "the National Socialist crimes against Jews"}, {"text_de": "aus dem Grundgesetz der Bundesrepublik Deutschland", "correct": false, "text_en": "the Basic Law (Grundgesetz) of the Federal Republic of Germany"}, {"text_de": "aus der christlichen Tradition", "correct": false, "text_en": "the Christian tradition"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-288.png"}, "question_en": "What is the basis of Germany's special responsibility toward Israel?", "asking_note": "Tests knowledge of the historical reason behind Germany's special relationship with Israel. The trap distractors offer institutional or cultural sources; the correct answer is specifically the historical guilt for Nazi crimes against Jews.", "answer_explanation": "Germany's special responsibility for Israel arises from the crimes committed under National Socialism against Jews — above all the systematic murder of some six million Jews in the Holocaust (Shoah). Out of this historical guilt, the Federal Republic recognizes a lasting moral and political obligation toward Israel and Jewish life. This is why standing up for Israel's security is treated as part of Germany's national responsibility.", "distractor_notes": ["EU membership concerns European integration and has nothing to do with the historical roots of this relationship.", "", "The Grundgesetz sets out Germany's constitutional order but is not the source of this specific responsibility, which is historical.", "Christian tradition is unrelated; the responsibility stems from the persecution and murder of Jews, not from religion."]}, {"id": 289, "id_str": "289", "category": "general", "exam_pool": "general", "question_de": "Ein Mann mit dunkler Hautfarbe bewirbt sich um eine Stelle als Kellner in einem Restaurant in Deutschland. Was ist ein Beispiel für Diskriminierung? Er bekommt die Stelle nur deshalb nicht, weil …", "question_image": null, "image_kind": null, "options": [{"text_de": "seine Deutschkenntnisse zu gering sind.", "correct": false, "text_en": "his German-language skills are too weak."}, {"text_de": "er zu hohe Gehaltsvorstellungen hat.", "correct": false, "text_en": "he has salary expectations that are too high."}, {"text_de": "er eine dunkle Haut hat.", "correct": true, "text_en": "he has dark skin."}, {"text_de": "er keine Erfahrungen im Beruf hat.", "correct": false, "text_en": "he has no experience in the profession."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-289.png"}, "question_en": "A man with dark skin applies for a job as a waiter in a restaurant in Germany. What is an example of discrimination? He fails to get the job only because …", "asking_note": "Tests recognizing discrimination — being rejected for a reason that has nothing to do with ability to do the job. The trap: three options are legitimate, job-related reasons for rejection; only rejection because of skin colour is unlawful discrimination.", "answer_explanation": "Refusing to hire someone solely because of their skin colour is discrimination, because it judges the person by an inherent characteristic rather than their suitability for the work. This is prohibited under the equality guarantee of Article 3 of the Grundgesetz and by the General Equal Treatment Act (AGG), which bans disadvantage based on race or ethnic origin. The other reasons relate to actual job requirements; skin colour does not.", "distractor_notes": ["Insufficient German for a customer-facing job is a job-related reason, not discrimination.", "Salary expectations that are too high are a legitimate business reason to reject a candidate.", "", "Lack of relevant professional experience is a fair, job-related reason for not hiring someone."]}, {"id": 290, "id_str": "290", "category": "general", "exam_pool": "general", "question_de": "Sie haben in Deutschland einen Fernseher gekauft. Zu Hause packen Sie den Fernseher aus, doch er funktioniert nicht. Der Fernseher ist kaputt. Was können Sie machen?", "question_image": null, "image_kind": null, "options": [{"text_de": "eine Anzeige schreiben", "correct": false, "text_en": "write a police report / criminal complaint (Anzeige)"}, {"text_de": "den Fernseher reklamieren", "correct": true, "text_en": "make a complaint about the TV (reklamieren)"}, {"text_de": "das Gerät ungefragt austauschen", "correct": false, "text_en": "swap the device yourself without asking"}, {"text_de": "die Garantie verlängern", "correct": false, "text_en": "extend the guarantee"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-290.png"}, "question_en": "You have bought a television in Germany. At home you unpack it, but it does not work — the TV is broken. What can you do?", "asking_note": "Tests the consumer's remedy for a defective purchase. The correct action is to make a complaint/return under warranty (reklamieren). The distractors confuse this with a police report, unauthorized self-help, or extending a guarantee.", "answer_explanation": "When goods are defective, the consumer's remedy is to complain to the seller (reklamieren) and demand repair, replacement, a refund or a price reduction. German law gives buyers a statutory warranty (Gewährleistung) of two years on new goods, so a TV that is broken on arrival can be returned to the shop. This is the correct, lawful way to deal with a faulty product.", "distractor_notes": ["An 'Anzeige' is a report of a crime to the police; buying a faulty appliance is a consumer-law matter, not a crime.", "", "You cannot simply swap the device on your own; you must go through the seller, who decides on repair or replacement.", "Extending a guarantee does not fix or replace a device that is already broken now."]}, {"id": 291, "id_str": "291", "category": "general", "exam_pool": "general", "question_de": "Warum muss man in Deutschland bei der Steuererklärung aufschreiben, ob man zu einer Kirche gehört oder nicht? Weil …", "question_image": null, "image_kind": null, "options": [{"text_de": "es eine Kirchensteuer gibt, die an die Einkommen- und Lohnsteuer geknüpft ist.", "correct": true, "text_en": "there is a church tax that is linked to income tax and wage tax."}, {"text_de": "das für die Statistik in Deutschland wichtig ist.", "correct": false, "text_en": "it is important for statistics in Germany."}, {"text_de": "man mehr Steuern zahlen muss, wenn man nicht zu einer Kirche gehört.", "correct": false, "text_en": "you have to pay more taxes if you do not belong to a church."}, {"text_de": "die Kirche für die Steuererklärung verantwortlich ist.", "correct": false, "text_en": "the church is responsible for the tax return."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-291.png"}, "question_en": "Why must you state on your tax return in Germany whether or not you belong to a church? Because …", "asking_note": "Tests why religious affiliation is asked on tax forms — it determines liability for church tax. The distractors offer statistics, a penalty for non-members, or church control of taxes; only the church-tax explanation is correct.", "answer_explanation": "Members of recognized religious communities pay a church tax (Kirchensteuer), which is levied as a surcharge (8 or 9% depending on the federal state) on income and wage tax and collected by the state's tax authorities on the churches' behalf. Your tax return therefore has to record your church membership so the correct amount can be assessed. People who do not belong to a tax-collecting church simply do not pay it.", "distractor_notes": ["", "The purpose is to levy the church tax, not to gather statistics.", "The opposite is true: non-members pay no church tax, so they do not pay more — they pay less.", "The state tax authorities, not the church, are responsible for processing tax returns."]}, {"id": 292, "id_str": "292", "category": "general", "exam_pool": "general", "question_de": "Die Menschen in Deutschland leben nach dem Grundsatz der religiösen Toleranz. Was bedeutet das?", "question_image": null, "image_kind": null, "options": [{"text_de": "Es dürfen keine Moscheen gebaut werden.", "correct": false, "text_en": "No mosques may be built."}, {"text_de": "Alle Menschen glauben an Gott.", "correct": false, "text_en": "All people believe in God."}, {"text_de": "Jeder kann glauben, was er möchte.", "correct": true, "text_en": "Everyone may believe whatever they wish."}, {"text_de": "Der Staat entscheidet, an welchen Gott die Menschen glauben.", "correct": false, "text_en": "The state decides which God people believe in."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-292.png"}, "question_en": "People in Germany live by the principle of religious tolerance. What does that mean?", "asking_note": "Tests the meaning of religious tolerance / freedom of belief. The trap distractors describe intolerance (banning mosques), a false universal (everyone believes in God), or state control of religion — the opposite of tolerance.", "answer_explanation": "Religious tolerance means everyone is free to hold their own beliefs — or none at all — and to practise their religion. This is guaranteed by the freedom of faith and conscience in Article 4 of the Grundgesetz, and Germany is religiously and ideologically neutral. No one may be forced into or barred from a belief by the state.", "distractor_notes": ["Banning mosques would violate religious freedom; tolerance means all faiths may build places of worship.", "Not everyone believes in God — atheists and agnostics are equally free, which is part of tolerance.", "", "In Germany the state does not dictate anyone's beliefs; that would contradict religious freedom."]}, {"id": 293, "id_str": "293", "category": "general", "exam_pool": "general", "question_de": "Was ist in Deutschland ein Brauch zu Ostern?", "question_image": null, "image_kind": null, "options": [{"text_de": "Kürbisse vor die Tür stellen", "correct": false, "text_en": "putting pumpkins outside the door"}, {"text_de": "einen Tannenbaum schmücken", "correct": false, "text_en": "decorating a fir tree"}, {"text_de": "Eier bemalen", "correct": true, "text_en": "painting eggs"}, {"text_de": "Raketen in die Luft schießen", "correct": false, "text_en": "shooting fireworks/rockets into the air"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-293.png"}, "question_en": "What is a custom (Brauch) at Easter in Germany?", "asking_note": "Tests recognizing which custom belongs to Easter. The trap: each distractor is a real German custom, but tied to a different occasion (Halloween, Christmas, New Year's Eve).", "answer_explanation": "Painting eggs is a traditional Easter custom in Germany; decorated eggs (and the Easter bunny hiding them) are central to the festival, which celebrates the resurrection of Jesus. The other options are customs of other holidays. Easter eggs are among the most recognizable springtime traditions in German culture.", "distractor_notes": ["Pumpkins at the door belong to Halloween (31 October), not Easter.", "Decorating a fir tree is a Christmas custom.", "", "Fireworks are set off at New Year's Eve (Silvester), not at Easter."]}, {"id": 294, "id_str": "294", "category": "general", "exam_pool": "general", "question_de": "Pfingsten ist ein …", "question_image": null, "image_kind": null, "options": [{"text_de": "christlicher Feiertag.", "correct": true, "text_en": "Christian holiday."}, {"text_de": "deutscher Gedenktag.", "correct": false, "text_en": "German day of remembrance."}, {"text_de": "internationaler Trauertag.", "correct": false, "text_en": "international day of mourning."}, {"text_de": "bayerischer Brauch.", "correct": false, "text_en": "Bavarian custom."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-294.png"}, "question_en": "Pentecost (Pfingsten) is a …", "asking_note": "Tests classifying Pentecost correctly. The trap distractors reframe it as a secular day of remembrance, an international day of mourning, or a purely regional custom — but it is a Christian religious holiday.", "answer_explanation": "Pentecost (Pfingsten) is a Christian holy day celebrated 50 days after Easter, commemorating the descent of the Holy Spirit upon Jesus's disciples. It is a public holiday across Germany (Pentecost Monday), rooted in the Christian calendar. It is neither a secular commemoration nor a purely regional custom.", "distractor_notes": ["", "It is a religious feast, not a state day of remembrance for a historical event.", "It is not a day of mourning at all — it is a joyful Christian festival.", "It is celebrated throughout Germany and the Christian world, not only in Bavaria."]}, {"id": 295, "id_str": "295", "category": "general", "exam_pool": "general", "question_de": "Welche Religion hat die europäische und deutsche Kultur geprägt?", "question_image": null, "image_kind": null, "options": [{"text_de": "der Hinduismus", "correct": false, "text_en": "Hinduism"}, {"text_de": "das Christentum", "correct": true, "text_en": "Christianity"}, {"text_de": "der Buddhismus", "correct": false, "text_en": "Buddhism"}, {"text_de": "der Islam", "correct": false, "text_en": "Islam"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-295.png"}, "question_en": "Which religion has shaped European and German culture?", "asking_note": "Tests which religion historically shaped German and European culture. Straightforward factual recall; the distractors are other world religions.", "answer_explanation": "Christianity has shaped European and German culture over roughly two thousand years, influencing values, law, art, architecture, holidays and the calendar. Most public holidays in Germany, such as Christmas, Easter and Pentecost, have Christian origins. This deep historical imprint is why Christianity is the correct answer.", "distractor_notes": ["Hinduism originated in South Asia and has not been a shaping force in German or European culture.", "", "Buddhism originated in Asia and did not shape the historical development of European culture.", "Islam has a presence in Germany today, especially through migration, but it did not historically shape German and European culture the way Christianity did."]}, {"id": 296, "id_str": "296", "category": "general", "exam_pool": "general", "question_de": "In Deutschland nennt man die letzten vier Wochen vor Weihnachten …", "question_image": null, "image_kind": null, "options": [{"text_de": "den Buß- und Bettag.", "correct": false, "text_en": "the Day of Repentance and Prayer (Buß- und Bettag)."}, {"text_de": "das Erntedankfest.", "correct": false, "text_en": "the Harvest Thanksgiving festival (Erntedankfest)."}, {"text_de": "die Adventszeit.", "correct": true, "text_en": "the Advent season (Adventszeit)."}, {"text_de": "Allerheiligen.", "correct": false, "text_en": "All Saints' Day (Allerheiligen)."}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-296.png"}, "question_en": "In Germany, the last four weeks before Christmas are called …", "asking_note": "Tests the name of the pre-Christmas season. The trap: all distractors are genuine Christian/German observances, but each falls on a single day or a different time of year, not the four-week run-up to Christmas.", "answer_explanation": "The four weeks leading up to Christmas are called Advent (Adventszeit), a period of preparation in the Christian calendar marked by the four Sundays of Advent and customs like the Advent wreath and Advent calendar. The word comes from the Latin for 'arrival', referring to the coming of Christ. It begins on the fourth Sunday before Christmas.", "distractor_notes": ["Buß- und Bettag is a single Protestant day of repentance in November, not a four-week season.", "Erntedankfest (harvest thanksgiving) is celebrated in autumn, typically early October, not before Christmas.", "", "Allerheiligen (All Saints' Day) is a single day on 1 November, not the pre-Christmas period."]}, {"id": 297, "id_str": "297", "category": "general", "exam_pool": "general", "question_de": "Aus welchem Land sind die meisten Migrantinnen und Migranten nach Deutschland gekommen?", "question_image": null, "image_kind": null, "options": [{"text_de": "Italien", "correct": false, "text_en": "Italy"}, {"text_de": "Polen", "correct": false, "text_en": "Poland"}, {"text_de": "Marokko", "correct": false, "text_en": "Morocco"}, {"text_de": "Türkei", "correct": true, "text_en": "Turkey"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-297.png"}, "question_en": "From which country have the most migrants come to Germany?", "asking_note": "Tests knowledge of the largest group of migrants in Germany by country of origin. The trap: all options are real sources of migration, but one stands out as the largest immigrant group.", "answer_explanation": "The largest group of migrants in Germany has come from Turkey, a legacy of the guest-worker recruitment agreement signed in 1961 and the family members who followed. People of Turkish origin form the biggest community with a migration background in the country. This makes Turkey the correct answer.", "distractor_notes": ["Italians are a large migrant group (early guest workers), but not the largest.", "Poles are a significant migrant group, but fewer than those from Turkey.", "Migration from Morocco to Germany is comparatively small.", ""]}, {"id": 298, "id_str": "298", "category": "general", "exam_pool": "general", "question_de": "In der DDR lebten vor allem Migrantinnen und Migranten aus …", "question_image": null, "image_kind": null, "options": [{"text_de": "Vietnam, Polen, Mosambik.", "correct": true, "text_en": "Vietnam, Poland, Mozambique."}, {"text_de": "Frankreich, Rumänien, Somalia.", "correct": false, "text_en": "France, Romania, Somalia."}, {"text_de": "Chile, Ungarn, Simbabwe.", "correct": false, "text_en": "Chile, Hungary, Zimbabwe."}, {"text_de": "Nordkorea, Mexiko, Ägypten.", "correct": false, "text_en": "North Korea, Mexico, Egypt."}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-298.png"}, "question_en": "In the GDR (East Germany), migrants lived mainly from …", "asking_note": "Tests where the GDR's 'contract workers' (Vertragsarbeiter) came from — socialist allied states. The trap: only one grouping lists countries that were actually partners of the GDR; the others mix in Western or unrelated countries.", "answer_explanation": "The GDR recruited 'contract workers' (Vertragsarbeiter) mainly from fellow socialist and allied states, above all Vietnam, Poland and Mozambique (as well as Cuba and Angola). These workers came under state agreements between the GDR and those countries. That is why the Vietnam/Poland/Mozambique grouping is correct.", "distractor_notes": ["", "France was a Western country not allied with the GDR; this grouping does not match the GDR's contract-worker partners.", "This mix does not correspond to the main countries the GDR recruited workers from.", "This grouping likewise does not reflect the GDR's actual contract-worker source countries."]}, {"id": 299, "id_str": "299", "category": "general", "exam_pool": "general", "question_de": "Ausländische Arbeitnehmerinnen und Arbeitnehmer, die in den 50er und 60er Jahren von der Bundesrepublik Deutschland angeworben wurden, nannte man …", "question_image": null, "image_kind": null, "options": [{"text_de": "Schwarzarbeiterinnen/Schwarzarbeiter.", "correct": false, "text_en": "illegal/undeclared workers (Schwarzarbeiter)."}, {"text_de": "Gastarbeiterinnen/Gastarbeiter.", "correct": true, "text_en": "guest workers (Gastarbeiter)."}, {"text_de": "Zeitarbeiterinnen/Zeitarbeiter.", "correct": false, "text_en": "temporary agency workers (Zeitarbeiter)."}, {"text_de": "Schichtarbeiterinnen/Schichtarbeiter.", "correct": false, "text_en": "shift workers (Schichtarbeiter)."}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-299.png"}, "question_en": "Foreign workers recruited by the Federal Republic of Germany in the 1950s and 1960s were called …", "asking_note": "Tests the historical term for recruited foreign workers in West Germany. The trap: all options are 'worker' compounds, but only one is the specific historical label.", "answer_explanation": "The foreign workers whom West Germany actively recruited in the 1950s and 1960s to meet labour shortages during the economic boom were called 'Gastarbeiter' (guest workers). They came through recruitment agreements with countries such as Italy, Spain, Greece, Turkey and Yugoslavia. The term reflects the original assumption that their stay would be temporary.", "distractor_notes": ["'Schwarzarbeit' means undeclared or illegal work; these workers were recruited legally under state agreements.", "", "Zeitarbeiter (agency/temp workers) describes a modern employment form, not the recruited foreign workers of that era.", "Schichtarbeiter simply means people who work in shifts, unrelated to the recruitment of foreign labour."]}, {"id": 300, "id_str": "300", "category": "general", "exam_pool": "general", "question_de": "Aus welchem Land kamen die ersten Gastarbeiterinnen und Gastarbeiter in die Bundesrepublik Deutschland?", "question_image": null, "image_kind": null, "options": [{"text_de": "Italien", "correct": true, "text_en": "Italy"}, {"text_de": "Spanien", "correct": false, "text_en": "Spain"}, {"text_de": "Portugal", "correct": false, "text_en": "Portugal"}, {"text_de": "Türkei", "correct": false, "text_en": "Turkey"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-300.png"}, "question_en": "From which country did the first guest workers (Gastarbeiter) come to the Federal Republic of Germany?", "asking_note": "Tests which country signed the first guest-worker recruitment agreement with West Germany. The trap: all four are countries Germany later recruited from; you need the first one.", "answer_explanation": "The first guest workers came from Italy, following the recruitment agreement (Anwerbeabkommen) signed between the Federal Republic and Italy in 1955 — the earliest such agreement. Later agreements followed with Spain and Greece (1960), Turkey (1961), Portugal (1964) and others. Italy therefore marks the start of the guest-worker era.", "distractor_notes": ["", "Germany's recruitment agreement with Spain came in 1960, after Italy.", "The agreement with Portugal was signed in 1964, well after Italy.", "The agreement with Turkey dates from 1961; Turkey became the largest group later, but was not first."]}, {"id": 301, "id_str": "BE-1", "category": "berlin", "exam_pool": "berlin", "question_de": "Welches Wappen gehört zum Bundesland Berlin?", "question_image": null, "image_kind": "options", "options": [{"text_de": "Bild 1", "correct": false, "image": "assets/img/q301-opt1.png", "text_en": "Picture 1"}, {"text_de": "Bild 2", "correct": false, "image": "assets/img/q301-opt2.png", "text_en": "Picture 2"}, {"text_de": "Bild 3", "correct": false, "image": "assets/img/q301-opt3.png", "text_en": "Picture 3"}, {"text_de": "Bild 4", "correct": true, "image": "assets/img/q301-opt4.png", "text_en": "Picture 4"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "numeric", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-301.png"}, "question_en": "Which coat of arms belongs to the federal state of Berlin?", "asking_note": "This is an image-answer question: the four options are pictures (Bild 1-4) of coats of arms, and you must pick Berlin's. Berlin's coat of arms shows a black bear on a white (silver) shield, topped by a golden mural crown. The correct picture is Bild 4.", "answer_explanation": "Berlin's coat of arms depicts a standing black bear with red claws and tongue on a white (silver) shield, crowned by a golden mural crown (a five-leaved crown symbolizing the city). The bear (the 'Berliner Bär') is the city's long-standing heraldic symbol. Among the four images, this is the one marked correct (Bild 4).", "distractor_notes": ["A different state's coat of arms, not Berlin's bear.", "A different state's coat of arms, not Berlin's bear.", "A different state's coat of arms, not Berlin's bear.", ""]}, {"id": 302, "id_str": "BE-2", "category": "berlin", "exam_pool": "berlin", "question_de": "Welches ist ein Bezirk von Berlin?", "question_image": null, "image_kind": null, "options": [{"text_de": "Altona", "correct": false, "text_en": "Altona"}, {"text_de": "Prignitz", "correct": false, "text_en": "Prignitz"}, {"text_de": "Pankow", "correct": true, "text_en": "Pankow"}, {"text_de": "Mecklenburgische Seenplatte", "correct": false, "text_en": "Mecklenburg Lake District (Mecklenburgische Seenplatte)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-302.png"}, "question_en": "Which of these is a district (Bezirk) of Berlin?", "asking_note": "Tests recognizing a Berlin borough. The trap: the distractors are real German places, but each belongs to a different city or state (Hamburg, Brandenburg, Mecklenburg-Vorpommern).", "answer_explanation": "Pankow is one of Berlin's twelve boroughs (Bezirke), located in the north-east of the city. Berlin is divided into these twelve administrative districts, each with its own local council (Bezirksverordnetenversammlung). Pankow is the only option that is actually part of Berlin.", "distractor_notes": ["Altona is a district of Hamburg, not Berlin.", "Prignitz is a rural district (Landkreis) in the state of Brandenburg.", "", "The Mecklenburgische Seenplatte is a district in the state of Mecklenburg-Vorpommern."]}, {"id": 303, "id_str": "BE-3", "category": "berlin", "exam_pool": "berlin", "question_de": "Für wie viele Jahre wird das Landesparlament in Berlin gewählt?", "question_image": null, "image_kind": null, "options": [{"text_de": "3", "correct": false, "text_en": "3"}, {"text_de": "4", "correct": false, "text_en": "4"}, {"text_de": "5", "correct": true, "text_en": "5"}, {"text_de": "6", "correct": false, "text_en": "6"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-303.png"}, "question_en": "For how many years is the state parliament (Landesparlament) in Berlin elected?", "asking_note": "Tests the length of the electoral term for Berlin's state parliament (the Abgeordnetenhaus). A specific-number question; the distractors are nearby figures.", "answer_explanation": "Berlin's state parliament, the Abgeordnetenhaus, is elected for a term of five years. This is set in the Constitution of Berlin. A five-year legislative period is the common standard among the German federal states.", "distractor_notes": ["Three years is too short; Berlin's parliament serves five-year terms.", "Four years is not correct for Berlin's Abgeordnetenhaus.", "", "Six years is too long; the term is five years."]}, {"id": 304, "id_str": "BE-4", "category": "berlin", "exam_pool": "berlin", "question_de": "Ab welchem Alter darf man in Berlin bei Kommunalwahlen (Wahl der Bezirksverordnetenversammlung) wählen?", "question_image": null, "image_kind": null, "options": [{"text_de": "14", "correct": false, "text_en": "14"}, {"text_de": "16", "correct": true, "text_en": "16"}, {"text_de": "18", "correct": false, "text_en": "18"}, {"text_de": "20", "correct": false, "text_en": "20"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-304.png"}, "question_en": "From what age may you vote in local elections in Berlin (election of the district council, Bezirksverordnetenversammlung)?", "asking_note": "Tests the minimum voting age for Berlin's local (borough) elections, which is lower than for state or federal elections. The trap: 18 is the age for state/federal elections, but local elections in Berlin allow voting from 16.", "answer_explanation": "In Berlin you may vote in local elections for the district councils (Bezirksverordnetenversammlung) from the age of 16. This lowered voting age applies at the local/borough level, whereas elections to the Abgeordnetenhaus (and federal elections) require you to be 18. The correct answer is therefore 16.", "distractor_notes": ["14 is too young; the local voting age in Berlin is 16.", "", "18 is the age for state and federal elections, not for Berlin's local district-council elections.", "20 is not a voting-age threshold in Germany."]}, {"id": 305, "id_str": "BE-5", "category": "berlin", "exam_pool": "berlin", "question_de": "Welche Farben hat die Landesflagge von Berlin?", "question_image": null, "image_kind": null, "options": [{"text_de": "blau-weiß-rot", "correct": false, "text_en": "blue-white-red"}, {"text_de": "weiß-rot", "correct": true, "text_en": "white-red"}, {"text_de": "grün-weiß-rot", "correct": false, "text_en": "green-white-red"}, {"text_de": "schwarz-gold", "correct": false, "text_en": "black-gold"}], "correct_index": 1, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-305.png"}, "question_en": "What colours does the state flag of Berlin have?", "asking_note": "Tests the colours of Berlin's flag. The trap: the distractors are colour combinations of other flags (e.g. blue-white-red, or Germany's black-gold); Berlin's flag is white and red with the bear.", "answer_explanation": "Berlin's state flag is white and red, with a white central stripe bearing the Berlin bear between two narrower red stripes (top and bottom). White and red are the traditional colours of the city. This makes 'white-red' the correct answer.", "distractor_notes": ["Blue-white-red is not Berlin's flag (those are, for instance, the French or Dutch national colours).", "", "Green-white-red is not the Berlin flag.", "Black-gold does not match Berlin's flag (black and gold appear in some other German symbols)."]}, {"id": 306, "id_str": "BE-6", "category": "berlin", "exam_pool": "berlin", "question_de": "Wo können Sie sich in Berlin über politische Themen informieren?", "question_image": null, "image_kind": null, "options": [{"text_de": "beim Ordnungsamt der Gemeinde", "correct": false, "text_en": "at the municipality's public order office (Ordnungsamt)"}, {"text_de": "bei den Kirchen", "correct": false, "text_en": "at the churches"}, {"text_de": "bei der Verbraucherzentrale", "correct": false, "text_en": "at the consumer advice centre (Verbraucherzentrale)"}, {"text_de": "bei der Landeszentrale für politische Bildung", "correct": true, "text_en": "at the State Agency for Civic Education (Landeszentrale für politische Bildung)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-306.png"}, "question_en": "Where can you inform yourself about political topics in Berlin?", "asking_note": "Tests which public body provides civic/political education. The distractors are real institutions with other purposes (public order office, churches, consumer advice centre); only the state agency for civic education fits.", "answer_explanation": "The Landeszentrale für politische Bildung is a state institution whose specific task is to provide citizens with balanced information and education about political topics. Every federal state has one (alongside the federal Bundeszentrale für politische Bildung). It offers materials, events and publications on politics and democracy, making it the right place to learn about political matters.", "distractor_notes": ["The Ordnungsamt handles public order and administrative matters (permits, enforcement), not political education.", "Churches are religious institutions, not the state body for political information.", "The Verbraucherzentrale advises on consumer issues (contracts, products), not political topics.", ""]}, {"id": 307, "id_str": "BE-7", "category": "berlin", "exam_pool": "berlin", "question_de": "Welches Bundesland ist ein Stadtstaat?", "question_image": null, "image_kind": null, "options": [{"text_de": "Berlin", "correct": true, "text_en": "Berlin"}, {"text_de": "Saarland", "correct": false, "text_en": "Saarland"}, {"text_de": "Brandenburg", "correct": false, "text_en": "Brandenburg"}, {"text_de": "Hessen", "correct": false, "text_en": "Hesse (Hessen)"}], "correct_index": 0, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-307.png"}, "question_en": "Which federal state (Bundesland) is a city-state (Stadtstaat)?", "asking_note": "Tests which of the listed states is a city-state rather than an area state (Flächenland). Germany has three city-states — Berlin, Hamburg and Bremen; only one appears among the options.", "answer_explanation": "Berlin is a city-state (Stadtstaat): a city that is simultaneously a federal state of its own. Germany has three such city-states — Berlin, Hamburg and Bremen — while the other 13 states are area states (Flächenländer). The others listed are all territorial states, so Berlin is the answer.", "distractor_notes": ["", "Saarland is a small area state (Flächenland) in the west, not a city-state.", "Brandenburg is an area state that surrounds Berlin, not a city-state.", "Hesse is an area state, not a city-state."]}, {"id": 308, "id_str": "BE-8", "category": "berlin", "exam_pool": "berlin", "question_de": "Welches Bundesland ist Berlin?", "question_image": "assets/img/q308-stem.png", "image_kind": "stem", "options": [{"text_de": "1", "correct": false, "text_en": "1"}, {"text_de": "2", "correct": false, "text_en": "2"}, {"text_de": "3", "correct": false, "text_en": "3"}, {"text_de": "4", "correct": true, "text_en": "4"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "numeric", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-308.png"}, "question_en": "Which federal state (numbered area on the map) is Berlin?", "asking_note": "This question refers to an image: a map of Germany with numbered areas, and the answer is a picture/number choice. You must identify which highlighted area is Berlin — a small city-state in the north-east, enclosed by Brandenburg. The correct choice is number 4.", "answer_explanation": "On the map, Berlin is the small city-state located in the north-east of Germany, completely surrounded by the state of Brandenburg. Identifying it means picking that small enclosed area rather than a large territorial state. The area marked correct here is number 4.", "distractor_notes": ["A different numbered area on the map, not Berlin.", "A different numbered area on the map, not Berlin.", "A different numbered area on the map, not Berlin.", ""]}, {"id": 309, "id_str": "BE-9", "category": "berlin", "exam_pool": "berlin", "question_de": "Wie nennt man die Regierungschefin/den Regierungschef des Stadtstaates Berlin?", "question_image": null, "image_kind": null, "options": [{"text_de": "Ministerpräsidentin/Ministerpräsident", "correct": false, "text_en": "Minister-President (Ministerpräsident)"}, {"text_de": "Oberbürgermeisterin/Oberbürgermeister", "correct": false, "text_en": "Lord Mayor (Oberbürgermeister)"}, {"text_de": "Präsidentin/Präsident des Senates", "correct": false, "text_en": "President of the Senate (Präsident des Senates)"}, {"text_de": "Regierende Bürgermeisterin/Regierender Bürgermeister", "correct": true, "text_en": "Governing Mayor (Regierende Bürgermeisterin/Regierender Bürgermeister)"}], "correct_index": 3, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-309.png"}, "question_en": "What is the head of government of the city-state of Berlin called?", "asking_note": "Tests the specific title of Berlin's head of government, which differs from the titles used in area states or ordinary cities. The trap: distractors use titles that apply elsewhere (Ministerpräsident for area states, Oberbürgermeister for cities within states).", "answer_explanation": "The head of government of the city-state of Berlin is called the Governing Mayor (Regierende(r) Bürgermeister(in)). Because Berlin is both a city and a federal state, its leader carries this special title and heads the Berlin Senate (the state government). Hamburg uses 'Erster Bürgermeister' and Bremen 'Bürgermeister/Präsident des Senats', while the area states have a Ministerpräsident.", "distractor_notes": ["Ministerpräsident is the title of the head of government in the area states (Flächenländer), not in Berlin.", "Oberbürgermeister is the title for the mayor of a large city that lies within a state, not for Berlin's head of government.", "'Präsident des Senates' is not the title of Berlin's head of government (this describes Bremen's usage more closely).", ""]}, {"id": 310, "id_str": "BE-10", "category": "berlin", "exam_pool": "berlin", "question_de": "Welche Senatorin/welchen Senator hat Berlin nicht?", "question_image": null, "image_kind": null, "options": [{"text_de": "Finanzsenatorin/Finanzsenator", "correct": false, "text_en": "Senator for Finance (Finanzsenator)"}, {"text_de": "Innensenatorin/Innensenator", "correct": false, "text_en": "Senator for the Interior (Innensenator)"}, {"text_de": "Senatorin/Senator für Außenbeziehungen", "correct": true, "text_en": "Senator for Foreign Relations (Senator für Außenbeziehungen)"}, {"text_de": "Justizsenatorin/Justizsenator", "correct": false, "text_en": "Senator for Justice (Justizsenator)"}], "correct_index": 2, "verification": {"text_source": "pdf", "answer_source": "oet", "agreement": ["pdf", "oet"], "match_kind": "text", "match_confidence": 1.0, "flags": []}, "assets": {"oet_screenshot": "assets/screenshots/oet/aufgabe-310.png"}, "question_en": "Which senator does Berlin NOT have?", "asking_note": "Negative framing — pick the senator post that does NOT exist in Berlin's government. The trap: three are genuine Berlin Senate portfolios; the odd one out concerns foreign affairs, which is a federal matter, so no state senator exists for it.", "answer_explanation": "Berlin has no Senator for Foreign Relations because foreign policy is exclusively a matter for the federal government (the Foreign Office in Berlin), not for the individual states. Berlin's Senate does have senators for areas within state competence such as finance, the interior and justice. Since foreign affairs lie outside a state's remit, this portfolio does not exist at the state level.", "distractor_notes": ["Berlin does have a Senator for Finance, responsible for the state budget.", "Berlin does have a Senator for the Interior, responsible for police and public security.", "", "Berlin does have a Senator for Justice, responsible for the courts and justice administration."]}]};
